/// <summary>
/// Contesto ambiente per il codice IL generato: il metodo Main sintetizzato
/// legge <see cref="Current"/> per raggiungere IRuntimeHost/BRT, invece di
/// riceverlo come parametro esplicito su ogni singolo metodo generato.
///
/// Scelta provvisoria (vedi TODO Obsidian, Filone B, "Domande aperte" #2):
/// più semplice da emettere in IL (nessun parametro extra su ogni chiamata),
/// ma non rientrante se in futuro serviranno più IRuntimeHost concorrenti
/// nello stesso processo (es. più goroutine BASIC con host diversi). Se
/// quel caso si presenta, questo campo dovrà diventare per-task invece che
/// per-thread, coordinandosi con lo scheduler di BRT (Filone A).
/// </summary>
public static partial class IlRuntime
{
    static IlRuntime()
    {
        // AI.CACHESTATS(name) → resolver unificato: oggi il contesto KV e' la sessione
        // dell'agente (AgentServer → IKvCacheManager). Hook per evitare dipendenza statica
        // AI→Agents nel resolver (IKvCacheContext.cs).
        Basic.AI.Rag.AgentContext.ResolverHook = name =>
        {
            var pair = Basic.Agents.AgentServer.Instance.GetAgentCacheManager(name);
            if (pair is null) return null;
            var (mgr, sid) = pair.Value;
            return new Basic.AI.Rag.AgentContext(name,
                stats: () => mgr.GetCacheStats(sid),
                clear: () => mgr.ClearCache(sid),
                trim: drop => mgr.TrimCache(sid, drop));
        };

        // AI.PLUGINCALL → PluginRegistry.Call → CallHandler → invoca la procedura BASIC
        // del plugin per nome, passando il primo argomento come primo parametro (json).
        Basic.AI.PluginRegistry.CallHandler = (name, args) =>
        {
            if (!_basicProcedures.TryGetValue(name, out var info)) return null;
            var arg = args is { Length: > 0 } ? args[0] : null;
            string? json = null;
            if (arg != null && info.ParamNames.Length > 0)
            {
                var name0 = info.ParamNames[0];
                var v = arg is string s
                    ? "\"" + s.Replace("\\", "\\\\").Replace("\"", "\\\"") + "\""
                    : Convert.ToString(arg, System.Globalization.CultureInfo.InvariantCulture);
                json = "{\"" + name0 + "\":" + v + "}";
            }
            try { return InvokeBasicProcedureGpm(name, json ?? ""); }
            catch { return null; }
        };
    }

    [ThreadStatic]
    private static IRuntimeHost? _current;

    /// <summary>
    /// Fallback a livello di PROCESSO (l'ultimo host impostato da SetCurrent, da
    /// qualunque thread): serve al codice generato che gira su thread DIVERSI da quello
    /// che ha chiamato SetCurrent — in particolare i FINALIZER (DELETE...END DELETE →
    /// ~ClassName), eseguiti dal thread finalizzatore del GC, che non vede mai il
    /// thread-static del thread principale. Scoperto testando DELETE: il finalizer
    /// falliva con "IlRuntime.Current non è stato impostato" pur con l'host impostato.
    /// </summary>
    private static volatile IRuntimeHost? _processWideFallback;

    // Il pool DATA appartiene a una singola esecuzione del programma generato. Tenerlo
    // thread-local evita che due esecuzioni IL indipendenti nel medesimo processo si
    // consumino reciprocamente i dati; BeginData lo reinizializza sempre prima di Main.
    [ThreadStatic] private static object?[]? _data;
    [ThreadStatic] private static int _dataPointer;
    private static long _nextCryptoHandle;
    private static readonly System.Collections.Concurrent.ConcurrentDictionary<long, AsymmetricKeyParameter> CryptoKeys = new();
    private static long _nextFileHandle;
    private static readonly System.Collections.Concurrent.ConcurrentDictionary<long, FileStream> OpenFiles = new();
    // Reader di riga PERSISTENTE per handle (2026-10-01, fix AiWiki Bugs/(solved) - PRINTFile-
    // Argomenti-Stringa-PCode-IL-Divergenza.md): FileReadLineNumber creava PRIMA un nuovo
    // StreamReader AD OGNI CHIAMATA — un reader bufferizza internamente (default 1KB) più byte
    // di quanti ReadLine() ne restituisca, e avanza lo STREAM sottostante di quanto ha
    // BUFFERIZZATO (non di quanto ha restituito). Scartando il reader a ogni chiamata (era
    // `using`), la chiamata successiva su un NUOVO reader partiva dalla posizione già avanzata
    // dal buffering del reader precedente — la SECONDA riga (e successive) andava persa (il
    // buffer del primo reader l'aveva già consumata ma mai restituita). Un reader persistente
    // per handle, creato alla prima lettura e riusato, risolve il problema senza toccare
    // Write/Seek (che operano ancora direttamente su OpenFiles[handle], invariati).
    private static readonly System.Collections.Concurrent.ConcurrentDictionary<long, StreamReader> OpenLineReaders = new();
    // Mapping file-number BASIC (#1, #2, ...) → handle IlRuntime (auto-incrementato).
    // Popolato da FileOpenNumber/FileCloseNumber, usato da FWrite/FRead/FClose via numero.
    private static readonly System.Collections.Concurrent.ConcurrentDictionary<long, long> FileNumberToHandle = new();
    // LINALG standalone: gli handle appartengono al runtime IL, non ai pool dell'Executor/P-Code.
    // Un contatore unico evita collisioni fra matrici e vettori; i valori sono puri double CLR,
    // quindi restano compatibili con Native AOT e non richiedono un bridge VM.
    private static long _nextLinAlgHandle;
    // Handle delle DECOMPOSIZIONI (LU/QR/SVD/… e spline di SPLREP): spazio SEPARATO da
    // matrici/vettori, come nel mondo C (PCode `_nextLinearDecompositionId`, VM/C e C99Native).
    // Prima condivideva `_nextLinAlgHandle` → SPLREP consumava un id matrice e SOLVEIVP
    // otteneva un handle diverso da PCode/VM-C/C99Native (bug NUMERICAL.SolveIvp: IL 3 vs 2).
    private static long _nextDecompHandle;
    private static readonly System.Collections.Concurrent.ConcurrentDictionary<long, double[,]> LinAlgMatrices = new();
    private static readonly System.Collections.Concurrent.ConcurrentDictionary<long, double[]> LinAlgVectors = new();
    private static readonly System.Collections.Concurrent.ConcurrentDictionary<long, Stack<double[,]>> LinAlgMatrixStacks = new();
    // Decomposizioni standalone: lo stesso handle LONG punta a un fattore opaco
    // qui sotto. La decomposizione è conservata come oggetto di decomposizione MathNet,
    // la stessa libreria usata dal runtime Executor/P-Code (CoreLu/CoreQr/...), così i
    // fattori estratti da DECOMP.GETFACTOR sono numericamente identici alla reference.
    private static readonly System.Collections.Concurrent.ConcurrentDictionary<long, object> LinAlgDecompositions = new();

    public static IRuntimeHost Current =>
        _current ?? _processWideFallback ?? throw new InvalidOperationException(
            "IlRuntime.Current non è stato impostato: chiamare IlRuntime.SetCurrent(host) prima di eseguire codice IL generato.");

    /// <summary>Imposta l'host SOLO sul thread corrente (ThreadStatic), senza toccare
    /// <see cref="_processWideFallback"/> né gli hook tastiera/AI di <see cref="SetCurrent"/>.
    /// Per i thread in background creati da UN'esecuzione già avviata (worker GPM v2, loop di
    /// ricezione WebSocket): senza questo, quei thread non hanno un _current proprio e
    /// ricadono su _processWideFallback — l'ultimo SetCurrent chiamato da QUALUNQUE thread nel
    /// processo, che sotto un gate xUnit a piena concorrenza appartiene quasi certamente a un
    /// ALTRO test/programma in esecuzione. Sintomo osservato: PRINT di una SUB invocata dal
    /// thread WS finiva nello StringWriter di un test diverso (IlHttpWebSocketParityTests.
    /// WsClient_RealHandshake_Send_OnMessage, flake solo sotto il gate pieno).</summary>
    public static void SetCurrentForThread(IRuntimeHost host) => _current = host;

    private static Action? _keyboardBreakHook;

    /// <summary>
    /// True dopo X della finestra o Ctrl+C non agganciato.
    /// Il loop UI deve uscirne e chiudere SDL subito: su macOS SIGINT non alza
    /// <c>Console.CancelKeyPress</c> (vedi docs/IL-Graphics-Input.md).
    /// </summary>
    public static bool AbortRequested { get; private set; }

    /// <summary>
    /// Interrompe il programma IL (chiusura finestra o Ctrl+C non agganciato).
    /// Ferma lo stepper GPM senza epilogo BASIC («premi un tasto»). Il loop UI
    /// deve comunque chiamare <c>SdlManager.Quit</c> sul thread principale.
    /// </summary>
    public static void RequestAbort()
    {
        AbortRequested = true;
        lock (InkeyQueueLock) InkeyQueue.Enqueue("\x1b");
        Aborted?.Invoke();
    }

    /// <summary>X/Ctrl+C: il programma si ferma subito, senza epilogo BASIC (es. «premi un tasto»).</summary>
    public sealed class ProgramAbortedException : Exception
    {
        public ProgramAbortedException() : base("Programma IL interrotto (finestra o Ctrl+C).") { }
    }

    private static void ThrowIfAborted()
    {
        if (AbortRequested) throw new ProgramAbortedException();
    }

    /// <summary>Il driver GPM si iscrive per svegliare i task parcheggiati.</summary>
    public static event Action? Aborted;

    /// <summary>True se ON KEY / hook ha intercettato Ctrl+C: non si abortisce.</summary>
    public static bool IsCtrlCIntercepted()
    {
        var combo = new CommonLib.Keyboard.KeyCombination(ConsoleKey.C, ConsoleModifiers.Control);
        try
        {
            if (Current.Keyboard.IsHookRegistered(combo)) return true;
        }
        catch { /* host non ancora installato */ }
        try { return CommonLib.App.EventDispatcher.Instance.HasKeyHandler(combo); }
        catch { return false; }
    }

    private static void OnKeyboardBreak()
    {
        var combo = new CommonLib.Keyboard.KeyCombination(ConsoleKey.C, ConsoleModifiers.Control);
        try
        {
            if (CommonLib.App.EventDispatcher.Instance.DispatchKey(combo)) return;
        }
        catch { /* dispatcher assente */ }
        if (IsCtrlCIntercepted()) return;
        RequestAbort();
    }

    public static void SetCurrent(IRuntimeHost host)
    {
        ArgumentNullException.ThrowIfNull(host);
        if (_keyboardBreakHook is not null && _processWideFallback is not null)
            _processWideFallback.Keyboard.BreakRequested -= _keyboardBreakHook;
        _current = host;
        _processWideFallback = host;
        _keyboardBreakHook = OnKeyboardBreak;
        host.Keyboard.BreakRequested += OnKeyboardBreak;
        // AIVECTOR risolve gli alias SQL attraverso un DataSession statico. La VM lo
        // sincronizza nel costruttore di PCodeProcessor; il backend IL deve farlo nel
        // punto equivalente in cui viene installato l'host dell'esecuzione.
        Basic.AI.Rag.AiVectorRuntime.SqlDataSession = host.SqlDataSession;
        // P0a2 (decisione utente 2026-09-12): il backend IL risolve il provider attivo a OGNI
        // avvio (prima: solo `if (Default is null)` — ramo morto dopo che il costruttore di
        // PCodeVm installava il fixture). Il fixture NON è una risoluzione accettabile (è la
        // pseudo-semantica che la decisione vieta): se l'attivo è il fixture, Default resta null
        // e le superfici AI RAG falliscono con errore esplicito che nomina il rimedio.
        {
            var providers = Basic.Providers.ProviderServer.Instance;
            var name = providers.GetActiveName(Basic.Providers.ProviderRole.Embedding);
            // MiniTest/selfcheck: `GMBASIC_TEST_FIXTURE_EMBEDDING=1` attiva il fixture SEMPRE
            // esplicitamente (bench test, mai produzione: i programmi BASIC che si affidano a un
            // default invisibile restano coperti dalla guardia null). Decisione P0a coperta per
            // costruzione — il contenuto continua a NON essere semantico, ma ora è una scelta
            // documentata di chi esegue il test, identica sui 4 backend.
            var testFixture = Environment.GetEnvironmentVariable("GMBASIC_TEST_FIXTURE_EMBEDDING") == "1";
            var isReal = name is not null
                         && (testFixture
                             || !name.StartsWith("fixture", StringComparison.OrdinalIgnoreCase))
                         && providers.GetStatus(name) == Basic.Providers.ProviderStatus.Available;
            Basic.SQLite.Vector.EmbeddingProviderResolver.Default =
                isReal ? providers.TryGetActiveEmbedding() : null;   // P0a2: configurato ma non caricabile = assente (null), mai throw nel bootstrap
            Basic.SQLite.Vector.EmbeddingProviderResolver.ActiveDimensions = providers.ActiveDimensions;
        }
        // Solo per host con grafica SDL reale: sotto NullGraphicsService (harness/test_ilrun
        // headless) questi due metodi toccavano comunque CommonGraphics.Graphics.GraphicsManager
        // .Instance/CommonGraphics.Consoles.SdlManager.Instance — singleton DI PROCESSO separati
        // da host.Graphics, che inizializzano SDL per davvero (SDL_Init) anche quando il
        // programma non usa mai SCREEN/MOUSE. Su una macchina con un display reale attaccato,
        // questo lasciava SDL "vivo" senza che nessuno pompasse mai gli eventi (l'host headless
        // non ha un loop finestra) — un programma con ON KEY/ON MOUSE GOSUB (che richiede la
        // rientranza dell'evento) restava in attesa per sempre, CPU al 900%+ (visto dal vivo:
        // test_ilrun su samples/Mouse/MouseGraphicState.bas, 29 minuti prima del kill).
        // ATTENZIONE: leggere `host.Graphics` CREA il servizio (proprietà pigra → factory →
        // dlopen di libgmb_gfx + SDL, ~8 MB) solo per controllarne il tipo: era questo a
        // caricare il motore grafico all'avvio di OGNI programma, anche un `PRINT`.
        // Si guarda solo un servizio GIÀ creato (esplicito dal costruttore o da un comando grafico).
        var createdGraphics = (host as Runtime.HeadlessRuntimeHost)?.CreatedGraphics;
        if (createdGraphics is not null and not NullGraphicsService)
        {
            SubscribeGuiWindowEvents();
            SubscribeGuiMouseEvents();
        }
    }

    /// <summary>Cabla i servizi SDL reali PRIMA che un HeadlessRuntimeHost venga costruito.
    /// IRuntimeHost.Graphics/Audio sono proprietà get-only, impostate UNA VOLTA SOLA nel
    /// costruttore da HeadlessRuntimeHost.DefaultGraphics/DefaultAudio: senza chiamare
    /// questo PRIMA di "new HeadlessRuntimeHost(...)" (come faceva solo il runner di test
    /// grafico test_graphics_headless), l'eseguibile standalone compilato (Executor -m)
    /// aveva Graphics permanentemente NullGraphicsService — SCREEN e ogni comando grafico
    /// erano no-op silenziosi, NESSUNA finestra appariva mai, indipendentemente da qualunque
    /// altro fix (orientamento, COLOR, ecc.).</summary>
    public static void PrepareGraphicsHost()
    {
        // Motore grafico unico C di DEFAULT (GMB_GFX_C=0 per il vecchio motore C#).
        // Factory, non istanze: la creazione avviene al PRIMO comando grafico/audio.
        if (Basic.Runtime.CGfxGraphicsService.UseCGraphics)
        {
            HeadlessRuntimeHost.GraphicsFactory ??= static () => new Basic.Runtime.CGfxGraphicsService();
            HeadlessRuntimeHost.ClipboardFactory ??= static () => new Basic.Runtime.CGfxClipboardService();
            HeadlessRuntimeHost.AudioFactory ??= static () => new Basic.Runtime.CGfxAudioService();
        }
        else
        {
            HeadlessRuntimeHost.GraphicsFactory ??= static () => new CommonGraphics.Graphics.SdlGraphicsService();
            HeadlessRuntimeHost.AudioFactory ??= static () => new CommonGraphics.SdlAudioService();
        }

        // Bridge grafico C: le matrici (handle MATRIX) vivono qui; il servizio C le risolve
        // via hook (BRT non può referenziare IlBackendRuntime).
        CGfxGraphicsService.MatrixResolver = GetMatrix2x3;
        // Eventi GUI (ON KEY/ON MOUSE) cablati QUANDO nasce la finestra, non all'avvio:
        // creare il servizio per controllarne il tipo costava dlopen di gfx+SDL in ogni run.
        HeadlessRuntimeHost.GraphicsCreated = static g =>
        {
            if (g is NullGraphicsService) return;
            SubscribeGuiWindowEvents();
            SubscribeGuiMouseEvents();
        };
    }

    /// <summary>Esegue il driver GPM su un thread in background mentre QUESTO thread (quello
    /// che ha chiamato Main, quindi l'OS main thread per l'eseguibile compilato) pompa SDL
    /// (PollEvents + Present) fino al termine. IlGpmDriver.Run() da solo blocca il thread
    /// chiamante con un semplice busy-wait (Thread.Sleep) SENZA mai chiamare PollEvents/
    /// Present: i comandi grafici accodati (EnqueueGpmOperation, incl. SCREEN stesso) non
    /// venivano MAI processati nell'eseguibile standalone, perché nessuno pompava la coda
    /// sul main thread — unico motivo per cui funzionava nei runner di test (che pompano
    /// loro stessi in un game loop esterno dedicato).</summary>

    /// <summary>Sottoscrive UNA volta gli eventi finestra GUI (SDL) e li inoltra al
    /// EventDispatcher unificato (ON WINDOW). Il backend IL referenzia CommonGraphics
    /// (a differenza di BRT), quindi può sottoscrivere GraphicsManager direttamente.
    /// Kind (WindowEventKind): Close=0, Resize=1, Quit=2, Move=3, Focus=4, Minimize=5,
    /// Restore=6, Open=7, Paste=8.</summary>
    private static bool _guiWindowEventsSubscribed;
    private static void SubscribeGuiWindowEvents()
    {
        if (_guiWindowEventsSubscribed) return;
        _guiWindowEventsSubscribed = true;
        try
        {
            var g = CommonGraphics.Graphics.GraphicsManager.Instance;
            // Handle 0 = finestra SDL (le finestre virtuali hanno id 1..N): `ON WINDOW ... OF 0`
            // intercetta gli eventi dello schermo grafico.
            g.WindowCloseRequested += () =>
            {
                try { CommonLib.App.EventDispatcher.Instance.DispatchWindow(0, 0); } catch { }
            };
            g.WindowResized += () =>
            {
                try { CommonLib.App.EventDispatcher.Instance.DispatchWindow(1, 0); } catch { }
            };
        }
        catch { }
    }

    public static void BeginData(object?[] values)
    {
        _data = values ?? throw new ArgumentNullException(nameof(values));
        _dataPointer = 0;
    }

    public static void RestoreData(int position = 0)
    {
        var data = _data ?? [];
        if ((uint)position > (uint)data.Length)
            throw new ArgumentOutOfRangeException(nameof(position));
        _dataPointer = position;
    }

    private static object? TakeData()
    {
        var data = _data ?? [];
        if ((uint)_dataPointer >= (uint)data.Length)
            throw new InvalidOperationException("OUT OF DATA");
        return data[_dataPointer++];
    }

    public static double ReadDataDouble() => Convert.ToDouble(TakeData(), CultureInfo.InvariantCulture);
    public static float ReadDataSingle() => Convert.ToSingle(TakeData(), CultureInfo.InvariantCulture);
    public static long ReadDataLong() => Convert.ToInt64(TakeData(), CultureInfo.InvariantCulture);
    public static ulong ReadDataULong() => Convert.ToUInt64(TakeData(), CultureInfo.InvariantCulture);
    // READ ... INTO una variabile INTEGER: INTEGER è a 64 bit (parità PCode/VM-C/C99Native,
    // dove non c'è troncamento a 16 bit), quindi la lettura non deve ridurre a short.
    public static long ReadDataInteger() => Convert.ToInt64(TakeData(), CultureInfo.InvariantCulture);
    public static ulong ReadDataUInteger() => Convert.ToUInt64(TakeData(), CultureInfo.InvariantCulture);
    public static byte ReadDataByte() => Convert.ToByte(TakeData(), CultureInfo.InvariantCulture);
    public static sbyte ReadDataSByte() => Convert.ToSByte(TakeData(), CultureInfo.InvariantCulture);
    public static bool ReadDataBit() => Convert.ToBoolean(TakeData(), CultureInfo.InvariantCulture);
    public static decimal ReadDataCurrency() => Convert.ToDecimal(TakeData(), CultureInfo.InvariantCulture);
    public static DateTime ReadDataDate() => Convert.ToDateTime(TakeData(), CultureInfo.InvariantCulture);
    public static string ReadDataString() => Convert.ToString(TakeData(), CultureInfo.InvariantCulture) ?? string.Empty;

    /// <summary>Applica la semantica STRING * N (padding a destra con spazi se più corta,
    /// troncamento se più lunga) — stessa logica di OP_ADJUST_STRING nella P-Code VM
    /// (PCodeVm/PCodeProcessor.cs). Porting da GMBasic (commit 24e8d24e): il backend IL non
    /// applicava MAI questa regola.</summary>
    public static string AdjustFixedString(string? value, int len)
    {
        var s = value ?? "";
        if (s.Length > len) return s.Substring(0, len);
        return s.Length < len ? s.PadRight(len) : s;
    }

    // RND/RANDOMIZE (2026-09): stesso xorshift64 del runtime C condiviso
    // (gmb_math.c gmb_rnd/gmb_rnd_seed) per la parità di sequenza dopo
    // RANDOMIZE <seed>. Senza RANDOMIZE il generatore usa lo STATO DI DEFAULT FISSO
    // (0x2545F4914F6CDD1D), esattamente come `gmb_rnd` del runtime C: il time-seed al
    // primo uso (com'era prima, "Random.Shared") rendeva RND NON deterministico e
    // DIVERGENTE tra le gambe — ogni backends è un processo separato, quindi un seed
    // basato su TickCount/clock produceva una sequenza diversa a ogni run (Sample
    // AnalysisTests, k-means: centoidi diversi su il/pcode/vmc/c99n/c99). Con lo stato
    // di default fisso tutte le gambe partono dalla STESSA sequenza (parità bit-exact).
    private static ulong _rndState = 0x2545F4914F6CDD1DUL;
    private static bool _rndSeeded;
    public static void Randomize()
    {
        _rndSeeded = true;
        _rndState = ((ulong)(Environment.TickCount64 & 0x7FFFFFFFFFFFFFFF)) | 1UL;
    }
    public static void RandomizeSeed(double seed)
    {
        _rndSeeded = true;
        _rndState = (ulong)seed != 0 ? (ulong)seed : 0x2545F4914F6CDD1DUL;
    }
    public static double Rnd()
    {
        // NB: NIENTE auto-time-seed — vedi commento sopra.
        _rndState ^= _rndState << 13;
        _rndState ^= _rndState >> 7;
        _rndState ^= _rndState << 17;
        return (double)(_rndState >> 11) / 9007199254740992.0;
    }

    /// <summary>Converte un valore object (boxed o stringa) in double — usato per le
    /// variabili con tipo RIDEFINITO (DIM S AS SINGLE poi DIM S$ AS STRING: stesso slot,
    /// local object boxed). Gestisce qualunque boxed numerico (Single/Double/Int...) e
    /// le stringhe numeriche.</summary>
    /// <summary>Legge l'elemento all'indice di un array (riga di matrice) con gestione
    /// dei mancanti: se index >= Length ritorna null (destructuring parziale, FOR EACH a,b,c
    /// su una riga più corta → i mancanti sono null).</summary>
    public static object? ArrayElementAt(object? row, int index)
    {
        if (row is Array arr && index >= 0 && index < arr.Length)
            return arr.GetValue(index);
        return null;
    }

    /// <summary>Numerico → bool: 0 = false, qualsiasi altro valore = true (semantica BASIC).</summary>
    public static bool ToBool(double value) => value != 0.0;

    public static DateTime ToDateTime(object? value)
    {
        if (value is DateTime dt) return dt;
        if (value is string s && DateTime.TryParse(s, CultureInfo.InvariantCulture, DateTimeStyles.None, out var ps))
            return ps;
        if (value is double d) return DateTime.FromOADate(d);
        if (value is long l) return new DateTime(l);
        if (value is int i) return DateTime.FromOADate(i);
        return DateTime.MinValue;
    }

    public static double ToDouble(object? value)    {
        if (value is null) return 0.0;
        if (value is double d) return d;
        if (value is float f) return f;
        if (value is decimal m) return (double)m;
        if (value is int i) return i;
        if (value is long l) return l;
        if (value is short s) return s;
        if (value is byte b) return b;
        // Convenzione VMBASIC: bool → -1 (vero) / 0 (falso), come PCode SafeDouble e VM/C.
        if (value is bool bb) return bb ? -1.0 : 0.0;
        if (value is string str)
            // Stringa numerica → parsed; stringa NON numerica → 0 (parità `atof`/gmb_string_to_double
            // del runtime C: STR$/builtin numerici su un campo/campo stringa nudo non devono lanciare).
            return double.TryParse(str, NumberStyles.Float, CultureInfo.InvariantCulture, out var parsed) ? parsed : 0.0;
        return Convert.ToDouble(value, CultureInfo.InvariantCulture);
    }
    /// <summary>Conversione di un valore DINAMICO (oggetto JSON/ANY) verso un target numerico:
    /// numeri via ToDouble; stringhe con prefisso numerico via parsing "atof" (es. "2023-01-06"
    /// → 2023, come il runtime C `atof`); qualunque altro caso → 0. Non lancia mai: un object
    /// boxed arriva da JsonFieldGet e va sempre risolto a un numero (l'alternativa era stloc di
    /// un reference in un campo numerico → garbage).</summary>
    public static double CoerceDynamicNumber(object? value)
    {
        if (value is null) return 0.0;
        if (value is string s)
        {
            if (double.TryParse(s, NumberStyles.Float, CultureInfo.InvariantCulture, out var p)) return p;
            var m = System.Text.RegularExpressions.Regex.Match(s.TrimStart(), @"^[+-]?(\d+\.?\d*|\.\d+)");
            if (m.Success && double.TryParse(m.Value, NumberStyles.Float, CultureInfo.InvariantCulture, out var q)) return q;
            return 0.0;
        }
        return ToDouble(value);
    }
    /// <summary>Conversione di un valore DINAMICO (oggetto JSON) verso un campo/var DATE
    /// (DateTime): DateTime già pronto; numero = seriale OADate; stringa ISO/parse-abile via
    /// CoreDateValue. Mai eccezione.</summary>
    public static DateTime CoerceDynamicDate(object? value)
    {
        if (value is DateTime dt) return dt;
        if (value is double d) { try { return DateTime.FromOADate(d); } catch { return DateTime.FromOADate(0); } }
        if (value is string s && !string.IsNullOrWhiteSpace(s))
        {
            try { return CommonLib.DateUtils.CoreDateValue(s).ToDateTime(TimeOnly.MinValue); } catch { }
        }
        return DateTime.FromOADate(0);
    }
    // Parità VM (CDBL su SINGLE → SafeDouble(float) → double.TryParse(float.ToString())):
    // il float viene convertito tramite la SUA RAPPRESENTAZIONE STRINGA ("1.234567" ->
    // 1.234567 pulito), NON esteso (1.234567f come double = 1.23456704616547). Golden
    // TypesConversions 'CDBL(S) = 1.234567'.
    public static double CDblSingle(float value)
        => double.TryParse(value.ToString(System.Globalization.CultureInfo.InvariantCulture),
            System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out var r) ? r : value;
    /// <summary>CDBL su un valore object (variabile RIDEFINITA, es. DIM S AS SINGLE poi DIM
    /// S$ AS STRING: il local è object con un float boxato). ToDouble(object) estende il
    /// float (1.234567f → 1.23456704616547); la VM usa la rappresentazione STRINGA del
    /// float (SafeDouble) → 1.234567 pulito. Golden TypesConversions 'CDBL(S) = 1.234567'.</summary>
    public static double CDblValue(object? value)
    {
        if (value is float f) return CDblSingle(f);
        return ToDouble(value);
    }

    private static long StoreMatrix(double[,] value)
    {
        var handle = Interlocked.Increment(ref _nextLinAlgHandle);
        LinAlgMatrices[handle] = value;
        return handle;
    }

    /// <summary>Registra una matrice reale (Double[,]) come handle — per le builtin linalg
    /// (DETERMINANT/SOLVE/LU/...) chiamate con un array invece di un handle.</summary>
    public static long LinAlgMatrixHandle(object matrix)
        => matrix is double[,] dm ? StoreMatrix(dm)
         : matrix is double[] v ? StoreMatrix(ToJaggedAsRect(v))
         : Convert.ToInt64(matrix);

    /// <summary>Registra un vettore reale (Double[]) come handle.</summary>
    public static long LinAlgVectorHandle(object vector)
    {
        return vector is double[] dv ? StoreVector(dv)
            : Convert.ToInt64(vector);
    }

    private static double[,] ToJaggedAsRect(double[] v)
    {
        var r = new double[v.Length, 1];
        for (var i = 0; i < v.Length; i++) r[i, 0] = v[i];
        return r;
    }

    private static long StoreVector(double[] value)
    {
        var handle = Interlocked.Increment(ref _nextLinAlgHandle);
        LinAlgVectors[handle] = value;
        return handle;
    }

    private static double[,] Matrix(long handle) => LinAlgMatrices.TryGetValue(handle, out var value)
        ? value
        : throw new ArgumentException("Handle matrice non valido.", nameof(handle));

    private static double[] Vector(long handle)
    {
                return LinAlgVectors.TryGetValue(handle, out var value)
            ? value
            : throw new ArgumentException("Handle vettore non valido.", nameof(handle));
    }

