    public static string TorchLibPath()
    {
        TorchEnsureLoaded();
        var buf = new byte[1024];
        var h = System.Runtime.InteropServices.Marshal.AllocHGlobal(1024);
        try
        {
            if (MlNativeEngine.gmb_ml_lib_path(h, 1024) != 0)
                return System.Runtime.InteropServices.Marshal.PtrToStringUTF8(h) ?? "";
            return "";
        }
        finally { System.Runtime.InteropServices.Marshal.FreeHGlobal(h); }
    }
