    public static double[] TorchToArray(long h)
    {
        TorchEnsureLoaded();
        var r = MlNativeEngine.gmb_ml_tensor_rows(h);
        var c = MlNativeEngine.gmb_ml_tensor_cols(h);
        if (r < 0 || c < 0) return Array.Empty<double>();
        var n = checked(r * c);
        var buf = new double[n];
        var got = MlNativeEngine.gmb_ml_tensor_toarray(h, buf, n);
        if (got < 0) return Array.Empty<double>();
        return got == n ? buf : buf[..got];
    }
