    /* L7 Training: BLEU-4 + ROUGE-L nella variante GMBasic — STESSA formula e STESSA
     * tokenizzazione del C (gmb_rag_eval.c: token [a-z0-9]+ lowercase, case-insensitive,
     * singolo riferimento, niente smoothing, beta=1). Parita' di comportamento per
     * costruzione; gli oracoli sono gli stessi del selfcheck C. */
    public static double TorchBleu(string reference, string hypothesis)
    {
        var r = TorchBleuRougeTokens(reference);
        var h = TorchBleuRougeTokens(hypothesis);
        if (r.Count == 0 || h.Count == 0) return 0.0;
        double logsum = 0.0;
        for (int n = 1; n <= 4; n++)
        {
            int total = (h.Count >= n) ? h.Count - n + 1 : 0;
            if (total == 0) return 0.0;
            int clip = TorchNgramClipped(h, r, n);
            if (clip == 0) return 0.0;
            logsum += Math.Log((double)clip / total);
        }
        double bp = (h.Count >= r.Count) ? 1.0 : Math.Exp(1.0 - (double)r.Count / h.Count);
        return bp * Math.Exp(logsum / 4.0);
    }
    public static double TorchRouge(string reference, string hypothesis)
    {
        var r = TorchBleuRougeTokens(reference);
        var h = TorchBleuRougeTokens(hypothesis);
        if (r.Count == 0 && h.Count == 0) return 1.0;
        if (r.Count == 0 || h.Count == 0) return 0.0;
        int lcs = TorchLcs(r, h);
        double rl = (double)lcs / r.Count, pl = (double)lcs / h.Count;
        return (rl + pl) > 0.0 ? 2.0 * rl * pl / (rl + pl) : 0.0;
    }
    private static List<string> TorchBleuRougeTokens(string? s)
    {
        // Identico a rge_is_word/rge_split_tokens in C: solo ASCII a-zA-Z0-9, lowercase.
        var toks = new List<string>();
        if (string.IsNullOrEmpty(s)) return toks;
        int start = -1;
        for (int i = 0; i <= s.Length; i++)
        {
            bool isWord = i < s.Length && ((s[i] >= 'a' && s[i] <= 'z') ||
                (s[i] >= 'A' && s[i] <= 'Z') || (s[i] >= '0' && s[i] <= '9'));
            if (isWord && start < 0) start = i;
            if (!isWord && start >= 0)
            {
                toks.Add(s.Substring(start, i - start).ToLowerInvariant());
                start = -1;
            }
        }
        return toks;
    }
    private static int TorchNgramClipped(List<string> hyp, List<string> rf, int n)
    {
        int th = (hyp.Count >= n) ? hyp.Count - n + 1 : 0;
        int tr = (rf.Count >= n) ? rf.Count - n + 1 : 0;
        if (th == 0 || tr == 0) return 0;
        var used = new bool[tr];
        int match = 0;
        for (int i = 0; i < th; i++)
            for (int r = 0; r < tr; r++)
            {
                if (used[r]) continue;
                bool eq = true;
                for (int k = 0; k < n; k++)
                    if (!string.Equals(hyp[i + k], rf[r + k], StringComparison.Ordinal)) { eq = false; break; }
                if (eq) { used[r] = true; match++; break; }
            }
        return match;
    }
    private static int TorchLcs(List<string> a, List<string> b)
    {
        var prev = new int[b.Count + 1];
        var cur = new int[b.Count + 1];
        for (int i = 1; i <= a.Count; i++)
        {
            for (int j = 1; j <= b.Count; j++)
                cur[j] = string.Equals(a[i - 1], b[j - 1], StringComparison.Ordinal)
                    ? prev[j - 1] + 1 : Math.Max(prev[j], cur[j - 1]);
            var tmp = prev; prev = cur; cur = tmp;
        }
        return prev[b.Count];
    }
