    /* L11: lettore imatrix → tensore [n_layer, 1] di energie medie per-layer. */
    public static long TorchImatrixLoad(string path)
    {
        TorchEnsureLoaded();
        const int Max = 4096;
        var buf = System.Runtime.InteropServices.Marshal.AllocHGlobal(Max * sizeof(double));
        try
        {
            int n = MlNativeEngine.gmb_ml_imatrix_layer_energy(path ?? "", buf, Max);
            if (n <= 0) return -1;
            var arr = new double[n];
            System.Runtime.InteropServices.Marshal.Copy(buf, arr, 0, n);
            return MlNativeEngine.gmb_ml_tensor_from(n, 1, arr, MlNativeEngine.gmb_ml_active_device());
        }
        finally { System.Runtime.InteropServices.Marshal.FreeHGlobal(buf); }
    }
    /* L11: mappa energia→rank per-layer → tensore [n_layer, 1] di rank. */
    public static long TorchImatrixRanks(string path, long minRank, long maxRank)
    {
        TorchEnsureLoaded();
        const int Max = 4096;
        var buf = System.Runtime.InteropServices.Marshal.AllocHGlobal(Max * sizeof(int));
        try
        {
            int n = MlNativeEngine.gmb_ml_imatrix_rank_map(path ?? "", (int)minRank, (int)maxRank, buf, Max);
            if (n <= 0) return -1;
            var arr = new double[n];
            var tmp = new int[n];
            System.Runtime.InteropServices.Marshal.Copy(buf, tmp, 0, n);
            for (int i = 0; i < n; i++) arr[i] = (double)tmp[i];
            return MlNativeEngine.gmb_ml_tensor_from(n, 1, arr, MlNativeEngine.gmb_ml_active_device());
        }
        finally { System.Runtime.InteropServices.Marshal.FreeHGlobal(buf); }
    }
