    /// <summary>Carica la lib ML (lazy) e, se non disponibile, solleva un errore BASIC
    /// chiaro (mai -1/0 muti). Idempotente: il loader cache l'esito.</summary>
    public static void TorchEnsureLoaded()
    {
        if (MlNativeEngine.gmb_ml_load_lib() != 0)
            throw new System.InvalidOperationException(
                "TORCH non caricato: esegui 'gmb setup TORCH' (CLI) o 'SETUP TORCH' (REPL) per scaricare le librerie ML (Resources/libs o libs-runtime/ml)");
    }

    /// <summary>Matrice 2x3 (a,b,c,d,e,f) da un handle MATRIX — usata dal bridge grafico C
    /// per SpriteSetTransform/SpriteSetMatrix (IlRuntime è l'unico proprietario del registry).</summary>
    public static double[]? GetMatrix2x3(long handle)
    {
        var m = Matrix(handle);
        if (m == null) return null;
        var rows = m.GetLength(0);
        var cols = m.GetLength(1);
        if (rows >= 2 && cols >= 2)
        {
            var e = rows >= 3 ? m[0, 2] : 0.0;
            var f = rows >= 3 ? m[1, 2] : 0.0;
            return new[] { m[0, 0], m[0, 1], m[1, 0], m[1, 1], e, f };
        }
        return null;
    }

    public static long MatrixCreate(long rows, long columns)
    {
        if (rows is <= 0 or > int.MaxValue || columns is <= 0 or > int.MaxValue)
            throw new ArgumentOutOfRangeException(nameof(rows), "Le dimensioni della matrice devono essere positive.");
        var matrix = new double[checked((int)rows), checked((int)columns)];
        for (var index = 0; index < Math.Min(rows, columns); index++) matrix[index, index] = 1d;
        return StoreMatrix(matrix);
    }

    public static long VectorCreate(double x, double y, double z, double w) => StoreVector([x, y, z, w]);

    public static long MatrixMultiply(long leftHandle, long rightHandle)
    {
        var left = Matrix(leftHandle);
        if (LinAlgMatrices.TryGetValue(rightHandle, out var right))
        {
            if (left.GetLength(1) != right.GetLength(0)) throw new ArgumentException("Dimensioni matrice incompatibili.");
            var result = new double[left.GetLength(0), right.GetLength(1)];
            for (var row = 0; row < result.GetLength(0); row++)
                for (var column = 0; column < result.GetLength(1); column++)
                    for (var index = 0; index < left.GetLength(1); index++) result[row, column] += left[row, index] * right[index, column];
            return StoreMatrix(result);
        }
        var vector = Vector(rightHandle);
        if (left.GetLength(1) != vector.Length) throw new ArgumentException("Dimensioni matrice/vettore incompatibili.");
        var vectorResult = new double[left.GetLength(0)];
        for (var row = 0; row < vectorResult.Length; row++)
            for (var index = 0; index < vector.Length; index++) vectorResult[row] += left[row, index] * vector[index];
        return StoreVector(vectorResult);
    }

    public static double MatrixDeterminant(long handle)
    {
        var matrix = (double[,])Matrix(handle).Clone();
        var size = matrix.GetLength(0);
        if (size != matrix.GetLength(1)) throw new ArgumentException("Il determinante richiede una matrice quadrata.");
        var sign = 1d;
        var determinant = 1d;
        for (var pivot = 0; pivot < size; pivot++)
        {
            var pivotRow = pivot;
            for (var row = pivot + 1; row < size; row++) if (Math.Abs(matrix[row, pivot]) > Math.Abs(matrix[pivotRow, pivot])) pivotRow = row;
            if (Math.Abs(matrix[pivotRow, pivot]) < 1e-14) return 0d;
            if (pivotRow != pivot) { SwapRows(matrix, pivotRow, pivot); sign = -sign; }
            var value = matrix[pivot, pivot];
            determinant *= value;
            for (var row = pivot + 1; row < size; row++)
            {
                var factor = matrix[row, pivot] / value;
                for (var column = pivot + 1; column < size; column++) matrix[row, column] -= factor * matrix[pivot, column];
            }
        }
        return sign * determinant;
    }

    // LINALG.PINVERSE(handle) - Pseudoinversa Moore-Penrose
    public static long MatrixPseudoInverse(long handle)
    {
        var matrix = Matrix(handle);
        var m = matrix.GetLength(0);
        var n = matrix.GetLength(1);
        
        // Conversione a MathNet per SVD
        var mat = MathNet.Numerics.LinearAlgebra.Double.DenseMatrix.OfArray(matrix);
        var svd = mat.Svd();
        var tolerance = Math.Max(m, n) * svd.S[0] * 1e-15;

        // Costruisci matrice inversa dei valori singolari
        var invertedS = MathNet.Numerics.LinearAlgebra.Matrix<double>.Build.Dense(n, m);
        for (var i = 0; i < svd.S.Count; i++)
        {
            if (svd.S[i] > tolerance)
                invertedS[i, i] = 1.0 / svd.S[i];
        }

        // A⁺ = V * S⁺ * Uᵀ
        var result = svd.VT.Transpose() * invertedS * svd.U.Transpose();

        return StoreMatrix(result.ToArray());
    }

    // LINALG.RANK(handle) - Rango matrice
    public static long MatrixRank(long handle)
    {
        var matrix = Matrix(handle);
        var m = matrix.GetLength(0);
        var n = matrix.GetLength(1);
        
        var mat = MathNet.Numerics.LinearAlgebra.Double.DenseMatrix.OfArray(matrix);
        var svd = mat.Svd();
        var tolerance = Math.Max(m, n) * svd.S[0] * 1e-15;

        int rank = 0;
        for (var i = 0; i < svd.S.Count; i++)
            if (svd.S[i] > tolerance) rank++;
        
        return rank;
    }

    // MATRIX.LSTSQ(handleA, handleB) - Minimi quadrati
    public static long MatrixLstsq(long handleA, long handleB)
    {
        var A = Matrix(handleA);
        var b = Matrix(handleB);
        
        var m = A.GetLength(0);
        var n = A.GetLength(1);
        var rowsB = b.GetLength(0);
        
        if (rowsB != m) throw new ArgumentException("Dimensioni incompatibili per LSTSQ");
        
        var matA = MathNet.Numerics.LinearAlgebra.Double.DenseMatrix.OfArray(A);
        var vecB = MathNet.Numerics.LinearAlgebra.Double.DenseVector.Create(m, i => b[i, 0]);

        var result = matA.Solve(vecB);
        
        return StoreVector(result.ToArray());
    }

    // MATRIX.TRACE(handle) - Traccia matrice
    public static double MatrixTrace(long handle)
    {
        var matrix = Matrix(handle);
        var m = matrix.GetLength(0);
        var n = matrix.GetLength(1);
        
        if (m != n) throw new ArgumentException("La traccia richiede una matrice quadrata");
        
        double trace = 0;
        for (var i = 0; i < m; i++)
            trace += matrix[i, i];
        
        return trace;
    }

    // LINALG.NORM(handle) - Norma L2 (valore singolare massimo)
    public static double MatrixNorm(long handle)
    {
        var matrix = Matrix(handle);
        var m = matrix.GetLength(0);
        var n = matrix.GetLength(1);
        
        var mat = MathNet.Numerics.LinearAlgebra.Double.DenseMatrix.OfArray(matrix);
        var svd = mat.Svd();

        return svd.S[0];
    }

    public static long MatrixTranspose(long handle)
    {
        var matrix = Matrix(handle);
        var result = new double[matrix.GetLength(1), matrix.GetLength(0)];
        for (var row = 0; row < matrix.GetLength(0); row++)
            for (var column = 0; column < matrix.GetLength(1); column++) result[column, row] = matrix[row, column];
        return StoreMatrix(result);
    }

    public static long MatrixInverse(long handle)
    {
        var matrix = Matrix(handle);
        var size = matrix.GetLength(0);
        if (size != matrix.GetLength(1)) throw new ArgumentException("L'inversa richiede una matrice quadrata.");
        var augmented = new double[size, size * 2];
        for (var row = 0; row < size; row++)
            for (var column = 0; column < size; column++) { augmented[row, column] = matrix[row, column]; augmented[row, size + column] = row == column ? 1d : 0d; }
        GaussJordan(augmented, size, size * 2);
        var inverse = new double[size, size];
        for (var row = 0; row < size; row++) for (var column = 0; column < size; column++) inverse[row, column] = augmented[row, size + column];
        return StoreMatrix(inverse);
    }

    public static double[] MatrixSolve(long matrixHandle, long vectorHandle)
    {
        var matrix = Matrix(matrixHandle);
        var vector = Vector(vectorHandle);
        var size = matrix.GetLength(0);
        if (size != matrix.GetLength(1) || vector.Length != size) throw new ArgumentException("SOLVE richiede matrice quadrata e vettore compatibile.");
        var augmented = new double[size, size + 1];
        for (var row = 0; row < size; row++) { for (var column = 0; column < size; column++) augmented[row, column] = matrix[row, column]; augmented[row, size] = vector[row]; }
        GaussJordan(augmented, size, size + 1);
        var solution = new double[size];
        for (var row = 0; row < size; row++) solution[row] = augmented[row, size];
        return solution;
    }

    // Decomposizioni standalone. Il calcolo delega a MathNet.Numerics (stessa
    // libreria della reference, vedi CoreLu/CoreQr/... in Interpreter/Numerics/
    // LinAlg.Functions.cs) così i fattori estratti da DECOMP.GETFACTOR sono
    // numericamente identici al percorso Executor/P-Code. La decomposizione è
    // conservata opaca nel registry; ogni GETFACTOR ne estrae un fattore e lo
    // registra come matrice o vettore CLR puro (double[,] / double[]).

    private static long StoreDecomposition(object value)
    {
        var handle = Interlocked.Increment(ref _nextDecompHandle);
        LinAlgDecompositions[handle] = value;
        return handle;
    }

    private static object Decomposition(long handle) => LinAlgDecompositions.TryGetValue(handle, out var value)
        ? value
        : throw new ArgumentException("Handle di decomposizione non valido.", nameof(handle));

    public static long MatrixLu(long handle)
    {
        var matrix = Matrix(handle);
        return StoreDecomposition(MathNet.Numerics.LinearAlgebra.Double.DenseMatrix.OfArray(matrix).LU());
    }

