    public static long DecompositionGetFactor(long decompHandle, string factorName)
    {
        var decomposition = Decomposition(decompHandle);
        MathNet.Numerics.LinearAlgebra.Matrix<double>? matrixFactor = null;
        MathNet.Numerics.LinearAlgebra.Vector<double>? vectorFactor = null;

        switch (decomposition)
        {
            case MathNet.Numerics.LinearAlgebra.Factorization.LU<double> lu:
                matrixFactor = factorName.ToUpperInvariant() switch
                {
                    "L" => lu.L,
                    "U" => lu.U,
                    _ => throw new ArgumentException($"Fattore '{factorName}' non valido per la decomposizione LU.")
                };
                break;
            case MathNet.Numerics.LinearAlgebra.Factorization.QR<double> qr:
                matrixFactor = factorName.ToUpperInvariant() switch
                {
                    "Q" => qr.Q,
                    "R" => qr.R,
                    _ => throw new ArgumentException($"Fattore '{factorName}' non valido per la decomposizione QR.")
                };
                break;
            case MathNet.Numerics.LinearAlgebra.Factorization.Svd<double> svd:
                switch (factorName.ToUpperInvariant())
                {
                    case "S": matrixFactor = svd.W; break;
                    case "SVECTOR": vectorFactor = svd.S; break;
                    case "U": matrixFactor = svd.U; break;
                    case "VT": matrixFactor = svd.VT; break;
                    default:
                        throw new ArgumentException($"Fattore '{factorName}' non valido per la decomposizione SVD.");
                }
                break;
            case MathNet.Numerics.LinearAlgebra.Factorization.Evd<double> evd:
                switch (factorName.ToUpperInvariant())
                {
                    case "D": matrixFactor = evd.D; break;
                    case "V": matrixFactor = evd.EigenVectors; break;
                    case "DREAL": vectorFactor = ExtractEigenvalueVector(evd.EigenValues, real: true); break;
                    case "DIMAG": vectorFactor = ExtractEigenvalueVector(evd.EigenValues, real: false); break;
                    default:
                        throw new ArgumentException($"Fattore '{factorName}' non valido per la decomposizione EVD.");
                }
                break;
             case MathNet.Numerics.LinearAlgebra.Factorization.Cholesky<double> cholesky:
                 if (factorName.ToUpperInvariant() == "L")
                     matrixFactor = cholesky.Factor;
                 else
                     throw new ArgumentException($"Fattore '{factorName}' non valido per la decomposizione Cholesky.");
                 break;
            case CommonLib.Numerics.GeneralEigenDecomposition eig:
                switch (factorName.ToUpperInvariant())
                {
                    case "T": matrixFactor = eig.RealSchurForm; break;
                    case "Z": matrixFactor = eig.SchurVectors; break;
                    case "VRREAL": matrixFactor = eig.EigenvectorsReal; break;
                    case "VRIMAG": matrixFactor = eig.EigenvectorsImag; break;
                    case "DREAL": matrixFactor = AsColumn(eig.EigenvaluesReal); break;
                    case "DIMAG": matrixFactor = AsColumn(eig.EigenvaluesImag); break;
                    default:
                        throw new ArgumentException($"Fattore '{factorName}' non valido per la decomposizione EIG.");
                }
                break;
            case CommonLib.Numerics.PolarDecomposition polar:
                matrixFactor = factorName.ToUpperInvariant() switch
                {
                    "U" => polar.U,
                    "P" => polar.P,
                    _ => throw new ArgumentException($"Fattore '{factorName}' non valido per la decomposizione POLAR.")
                };
                break;
             default:
                throw new ArgumentException("Tipo di decomposizione non supportato internamente.");
        }

        if (matrixFactor is not null)
            return StoreMatrix(matrixFactor.ToArray());

        if (vectorFactor is not null)
            return StoreVector(vectorFactor.ToArray());

        throw new ArgumentException("Nessun fattore valido estratto dalla decomposizione.");
    }

    // Estrarre parte reale/immaginaria di Vector<Complex> senza il metodo di
    // estensione MathNet Real()/Imaginary() (che richiederebbe un using dedicato
    // nel file): si costruisce il Vector<double> componente per componente.
    private static MathNet.Numerics.LinearAlgebra.Vector<double> ExtractEigenvalueVector(
        MathNet.Numerics.LinearAlgebra.Vector<System.Numerics.Complex> values, bool real)
    {
        var result = new double[values.Count];
        for (var index = 0; index < values.Count; index++)
            result[index] = real ? values[index].Real : values[index].Imaginary;
        return MathNet.Numerics.LinearAlgebra.Double.DenseVector.Create(result.Length, index => result[index]);
    }

    private static MathNet.Numerics.LinearAlgebra.Matrix<double> AsColumn(double[] values)
    {
        var col = new double[values.Length, 1];
        for (var i = 0; i < values.Length; i++) col[i, 0] = values[i];
        return MathNet.Numerics.LinearAlgebra.Double.DenseMatrix.OfArray(col);
    }

    public static double VectorDotProduct(long leftHandle, long rightHandle)
    {
        var left = Vector(leftHandle); var right = Vector(rightHandle);
        if (left.Length != right.Length) throw new ArgumentException("Dimensioni vettore incompatibili.");
        var result = 0d; for (var index = 0; index < left.Length; index++) result += left[index] * right[index];
        return result;
    }

    public static double VectorNorm(long handle)
    {
        return Math.Sqrt(Vector(handle).Sum(value => value * value));
    }

    public static double VGet(long h, long i) => Vector(h)[(int)i];
    public static double VAngle(long a, long b) => VectorAngleH(a, b);
    public static double VDist(long a, long b) => VectorDistanceH(a, b);
    public static long VAdd(long a, long b) => VectorOp(a, b, 0, 0, 0);
    public static long VSub(long a, long b) => VectorOp(a, b, 0, 0, 1);
    public static long VMul(long a, long b) => VectorOp(a, b, 0, 0, 2);
    public static long VDiv(long a, long b) => VectorOp(a, b, 0, 0, 3);
    public static long VScale(long a, double s) => VectorOp(a, -1, s, 0, 4);
    public static long VNormV(long a) => VectorOp(a, -1, 0, 0, 5);
    public static long VLerp(long a, long b, double t) => VectorOp(a, b, 0, t, 6);
    public static long VCross(long a, long b) => VectorOp(a, b, 0, 0, 7);
    public static long VMin(long a, long b) => VectorOp(a, b, 0, 0, 8);
    public static long VMax(long a, long b) => VectorOp(a, b, 0, 0, 9);
    public static long VectorOp(long ah, long bh, double s, double t, int op)
    {
        var a = Vector(ah);
        var b = bh >= 0 ? Vector(bh) : new double[4];
        var r = new double[4];
        for (var i = 0; i < 4; i++)
        {
            var x = a[i]; var y = i < b.Length ? b[i] : 0.0;
            r[i] = op switch
            {
                0 => x + y, 1 => x - y, 2 => x * y, 3 => y != 0.0 ? x / y : 0.0,
                4 => x * s, 6 => x + (y - x) * t, 8 => x < y ? x : y,
                9 => x > y ? x : y, 10 => Math.Abs(x), _ => x,
            };
        }
        if (op == 5)
        {
            var n = Math.Sqrt(a[0] * a[0] + a[1] * a[1] + a[2] * a[2] + a[3] * a[3]);
            for (var i = 0; i < 4; i++) r[i] = n > 0.0 ? a[i] / n : a[i];
        }
        if (op == 7)
        {
            r[0] = a[1] * b[2] - a[2] * b[1];
            r[1] = a[2] * b[0] - a[0] * b[2];
            r[2] = a[0] * b[1] - a[1] * b[0];
            r[3] = 0.0;
        }
        return StoreVector(r);
    }
    public static double VectorAngleH(long ah, long bh)
    {
        var a = Vector(ah); var b = Vector(bh);
        double dot = 0, na = 0, nb = 0;
        for (var i = 0; i < 4; i++) { dot += a[i] * b[i]; na += a[i] * a[i]; nb += b[i] * b[i]; }
        if (na <= 0.0 || nb <= 0.0) return double.NaN;
        var c = Math.Abs(dot) / Math.Sqrt(na * nb);
        if (c > 1.0) c = 1.0;
        return Math.Acos(c);
    }
    public static double VectorDistanceH(long ah, long bh)
    {
        var a = Vector(ah); var b = Vector(bh);
        double s = 0;
        for (var i = 0; i < 4; i++) { var d = a[i] - b[i]; s += d * d; }
        return Math.Sqrt(s);
    }

