    public static void MatrixIdentity(long handle)
    {
        var matrix = Matrix(handle);
        Array.Clear(matrix);
        for (var index = 0; index < Math.Min(matrix.GetLength(0), matrix.GetLength(1)); index++) matrix[index, index] = 1d;
    }

    public static void MatrixTranslate(long handle, double x, double y, double z) =>
        MatrixPostMultiply(handle, new double[,] {
            { 1d, 0d, 0d, x },
            { 0d, 1d, 0d, y },
            { 0d, 0d, 1d, z },
            { 0d, 0d, 0d, 1d }
        });

    public static void MatrixScale(long handle, double x, double y, double z) =>
        MatrixPostMultiply(handle, new double[,] {
            { x, 0d, 0d, 0d },
            { 0d, y, 0d, 0d },
            { 0d, 0d, z, 0d },
            { 0d, 0d, 0d, 1d }
        });

    public static void MatrixRotate(long handle, double xDegrees, double yDegrees, double zDegrees)
    {
        const double radiansPerDegree = Math.PI / 180d;
        var x = xDegrees * radiansPerDegree;
        var y = yDegrees * radiansPerDegree;
        var z = zDegrees * radiansPerDegree;
        MatrixPostMultiply(handle, new double[,] {
            { 1d, 0d, 0d, 0d },
            { 0d, Math.Cos(x), -Math.Sin(x), 0d },
            { 0d, Math.Sin(x), Math.Cos(x), 0d },
            { 0d, 0d, 0d, 1d }
        });
        MatrixPostMultiply(handle, new double[,] {
            { Math.Cos(y), 0d, Math.Sin(y), 0d },
            { 0d, 1d, 0d, 0d },
            { -Math.Sin(y), 0d, Math.Cos(y), 0d },
            { 0d, 0d, 0d, 1d }
        });
        MatrixPostMultiply(handle, new double[,] {
            { Math.Cos(z), -Math.Sin(z), 0d, 0d },
            { Math.Sin(z), Math.Cos(z), 0d, 0d },
            { 0d, 0d, 1d, 0d },
            { 0d, 0d, 0d, 1d }
        });
    }

    public static void MatrixMultiplyInto(long leftHandle, long rightHandle, long resultHandle)
    {
        var left = Matrix(leftHandle);
        var right = Matrix(rightHandle);
        var result = Matrix(resultHandle);
        if (left.GetLength(1) != right.GetLength(0) || result.GetLength(0) != left.GetLength(0) || result.GetLength(1) != right.GetLength(1))
            throw new ArgumentException("Dimensioni matrice incompatibili.");
        var product = new double[result.GetLength(0), result.GetLength(1)];
        for (var row = 0; row < product.GetLength(0); row++)
            for (var column = 0; column < product.GetLength(1); column++)
                for (var index = 0; index < left.GetLength(1); index++) product[row, column] += left[row, index] * right[index, column];
        Array.Copy(product, result, product.Length);
    }

    public static void MatrixPush(long handle)
    {
        var stack = LinAlgMatrixStacks.GetOrAdd(handle, _ => new Stack<double[,]>());
        lock (stack) stack.Push((double[,])Matrix(handle).Clone());
    }

    public static void MatrixPop(long handle)
    {
        var target = Matrix(handle);
        if (!LinAlgMatrixStacks.TryGetValue(handle, out var stack)) throw new InvalidOperationException("Stack matrice vuoto.");
        double[,] value;
        lock (stack)
        {
            if (stack.Count == 0) throw new InvalidOperationException("Stack matrice vuoto.");
            value = stack.Pop();
        }
        if (target.GetLength(0) != value.GetLength(0) || target.GetLength(1) != value.GetLength(1)) throw new InvalidOperationException("Dimensioni matrice nello stack non compatibili.");
        Array.Copy(value, target, value.Length);
    }

    public static void VectorAdd(long destinationHandle, object? source) => VectorMutate(destinationHandle, source, static (left, right) => left + right);
    public static void VectorSub(long destinationHandle, object? source) => VectorMutate(destinationHandle, source, static (left, right) => left - right);
    public static void VectorMul(long destinationHandle, object? source) => VectorMutate(destinationHandle, source, static (left, right) => left * right);
    public static void VectorDiv(long destinationHandle, object? source) => VectorMutate(destinationHandle, source, static (left, right) => left / right);

    // Overload ARRAY-DIRETTI (back-end IL): in IL un `DIM V(4) AS DOUBLE` è un vero
    // double[] CLR (mai un handle numerico come nel P-Code VM) — i comandi VECTOR
    // ricevono l'array come 1° argomento, quindi operano direttamente su di esso.
    public static void VectorAdd(double[] destination, object? source) => VectorMutateDirect(destination, source, static (left, right) => left + right);
    public static void VectorSub(double[] destination, object? source) => VectorMutateDirect(destination, source, static (left, right) => left - right);
    public static void VectorMul(double[] destination, object? source) => VectorMutateDirect(destination, source, static (left, right) => left * right);
    public static void VectorDiv(double[] destination, object? source) => VectorMutateDirect(destination, source, static (left, right) => left / right);

    public static void VectorSet(long handle, double value) => Array.Fill(Vector(handle), value);
    public static void VectorSet(double[] destination, double value) => Array.Fill(destination, value);

    public static void VectorFillRandom(long handle, double min, double max) => VectorFillRandom(Vector(handle), min, max);
    public static void VectorFillRandom(double[] destination, double min, double max)
    {
        if (min > max) throw new ArgumentException("Il valore min non può essere maggiore di max.", nameof(min));
        var range = max - min;
        for (var index = 0; index < destination.Length; index++) destination[index] = Rnd() * range + min;
    }

    public static void VectorWrap(long handle, double min, double max) => VectorWrap(Vector(handle), min, max);
    public static void VectorWrap(double[] destination, double min, double max)
    {
        var range = max - min;
        if (range <= 0d) return;
        for (var index = 0; index < destination.Length; index++) destination[index] = Wrap(destination[index], min, max);
    }

    public static void VectorAddWrap(long destinationHandle, object? source, double min, double max) => VectorAddWrap(Vector(destinationHandle), source, min, max);
    public static void VectorAddWrap(double[] destination, object? source, double min, double max)
    {
        var range = max - min;
        if (range <= 0d) return;
        VectorMutateDirect(destination, source, (left, right) => Wrap(left + right, min, max));
    }

    public static void VectorBounce2D(double[] pos, double[] vel, double width, double height)
    {
        var count = pos.Length;
        if (vel.Length != count) throw new ArgumentException("pos e vel devono avere la stessa dimensione.");
        for (var index = 0; index < count; index++)
        {
            var px = pos[index];
            var vx = vel[index];
            if (px < 0 && vx < 0) vel[index] = -vx;
            else if (px > width && vx > 0) vel[index] = -vx;
        }
    }

    public static void VectorBounce2D(long posHandle, long velHandle, double width, double height)
    {
        var pos = Vector(posHandle);
        var vel = Vector(velHandle);
        var count = pos.Length;
        if (vel.Length != count) throw new ArgumentException("pos e vel devono avere la stessa dimensione.");
        for (var index = 0; index < count; index++)
        {
            var px = pos[index];
            var vx = vel[index];
            if (px < 0 && vx < 0) vel[index] = -vx;
            else if (px > width && vx > 0) vel[index] = -vx;
        }
    }

    public static void VectorBounce2D(long xPosHandle, long yPosHandle, long xVelHandle, long yVelHandle, double xMin, double yMin, double xMax, double yMax)
    {
        var xPos = Vector(xPosHandle);
        var yPos = Vector(yPosHandle);
        var xVel = Vector(xVelHandle);
        var yVel = Vector(yVelHandle);
        var count = xPos.Length;
        if (yPos.Length != count || xVel.Length != count || yVel.Length != count)
            throw new ArgumentException("Tutti gli array per BOUNCE2D devono avere la stessa dimensione.");
        for (var index = 0; index < count; index++)
        {
            var xPosValue = xPos[index];
            var yPosValue = yPos[index];
            var xVelValue = xVel[index];
            var yVelValue = yVel[index];
            if (xPosValue < xMin && xVelValue < 0) xVelValue = -xVelValue;
            else if (xPosValue > xMax && xVelValue > 0) xVelValue = -xVelValue;
            if (yPosValue < yMin && yVelValue < 0) yVelValue = -yVelValue;
            else if (yPosValue > yMax && yVelValue > 0) yVelValue = -yVelValue;
            xVel[index] = xVelValue;
            yVel[index] = yVelValue;
        }
    }

    /// <summary>BOUNCE2D 8-arg con VETTORI DIRETTI (DIM X#(MAX), ...): nessun handle —
    /// stessa logica dell'overload a handle, ma gli array vengono passati come double[]
    /// (GraphicsTexturesBenchmark: VECTOR BOUNCE2D X, Y, DX, DY, 0, 0, 640, 480).</summary>
    public static void VectorBounce2D(double[] xPos, double[] yPos, double[] xVel, double[] yVel, double xMin, double yMin, double xMax, double yMax)
    {
        var count = xPos.Length;
        if (yPos.Length != count || xVel.Length != count || yVel.Length != count)
            throw new ArgumentException("Tutti gli array per BOUNCE2D devono avere la stessa dimensione.");
        for (var index = 0; index < count; index++)
        {
            var xPosValue = xPos[index];
            var yPosValue = yPos[index];
            var xVelValue = xVel[index];
            var yVelValue = yVel[index];
            if (xPosValue < xMin && xVelValue < 0) xVelValue = -xVelValue;
            else if (xPosValue > xMax && xVelValue > 0) xVelValue = -xVelValue;
            if (yPosValue < yMin && yVelValue < 0) yVelValue = -yVelValue;
            else if (yPosValue > yMax && yVelValue > 0) yVelValue = -yVelValue;
            xVel[index] = xVelValue;
            yVel[index] = yVelValue;
        }
    }

    private static void MatrixPostMultiply(long handle, double[,] transform)
    {
        var matrix = Matrix(handle);
        if (matrix.GetLength(0) != 4 || matrix.GetLength(1) != 4) throw new ArgumentException("Le trasformazioni MATRIX richiedono una matrice 4x4.", nameof(handle));
        var product = new double[4, 4];
        for (var row = 0; row < 4; row++)
            for (var column = 0; column < 4; column++)
                for (var index = 0; index < 4; index++) product[row, column] += matrix[row, index] * transform[index, column];
        Array.Copy(product, matrix, product.Length);
    }

    private static void VectorMutate(long destinationHandle, object? source, Func<double, double, double> operation)
    {
        var destination = Vector(destinationHandle);
        if (source is long sourceHandle && LinAlgVectors.TryGetValue(sourceHandle, out var sourceVector))
        {
            if (destination.Length != sourceVector.Length) throw new ArgumentException("Dimensioni vettore incompatibili.");
            for (var index = 0; index < destination.Length; index++) destination[index] = operation(destination[index], sourceVector[index]);
            return;
        }
        var scalar = Convert.ToDouble(source, CultureInfo.InvariantCulture);
        for (var index = 0; index < destination.Length; index++) destination[index] = operation(destination[index], scalar);
    }

    // Variante ARRAY-DIRETTA (back-end IL): il 1° argomento è il double[] stesso, non un
    // handle — il source può essere un altro double[] o uno scalare.
    private static void VectorMutateDirect(double[] destination, object? source, Func<double, double, double> operation)
    {
        if (source is double[] sourceVector)
        {
            if (destination.Length != sourceVector.Length) throw new ArgumentException("Dimensioni vettore incompatibili.");
            for (var index = 0; index < destination.Length; index++) destination[index] = operation(destination[index], sourceVector[index]);
            return;
        }
        var scalar = Convert.ToDouble(source, CultureInfo.InvariantCulture);
        for (var index = 0; index < destination.Length; index++) destination[index] = operation(destination[index], scalar);
    }

    private static double Wrap(double value, double min, double max)
    {
        var range = max - min;
        if (value < min) return max - (min - value) % range;
        return value > max ? min + (value - max) % range : value;
    }

    private static void GaussJordan(double[,] augmented, int pivotCount, int columnCount)
    {
        for (var pivot = 0; pivot < pivotCount; pivot++)
        {
            var pivotRow = pivot;
            for (var row = pivot + 1; row < pivotCount; row++) if (Math.Abs(augmented[row, pivot]) > Math.Abs(augmented[pivotRow, pivot])) pivotRow = row;
            if (Math.Abs(augmented[pivotRow, pivot]) < 1e-14) throw new InvalidOperationException("Matrice singolare.");
            if (pivotRow != pivot) SwapRows(augmented, pivotRow, pivot);
            var value = augmented[pivot, pivot];
            for (var column = 0; column < columnCount; column++) augmented[pivot, column] /= value;
            for (var row = 0; row < pivotCount; row++)
            {
                if (row == pivot) continue;
                var factor = augmented[row, pivot];
                for (var column = 0; column < columnCount; column++) augmented[row, column] -= factor * augmented[pivot, column];
            }
        }
    }

    private static void SwapRows(double[,] matrix, int left, int right)
    {
        for (var column = 0; column < matrix.GetLength(1); column++) (matrix[left, column], matrix[right, column]) = (matrix[right, column], matrix[left, column]);
    }


