    private static CommonLib.SimdMatrix SimdMatrix(long handle)
    {
        var matrix = Matrix(handle);
        var rows = matrix.GetLength(0);
        var columns = matrix.GetLength(1);
        var flat = new double[rows * columns];
        for (var row = 0; row < rows; row++)
            for (var column = 0; column < columns; column++) flat[row * columns + column] = matrix[row, column];
        return new CommonLib.SimdMatrix(flat, rows, columns);
    }
    public static double[] MatrixRowSums(long data) => SimdMatrix(data).RowSums();
    public static double[] MatrixColSums(long data) => SimdMatrix(data).ColSums();
    public static double[] MatrixRowMeans(long data) => SimdMatrix(data).RowMeans();
