    public static double MatrixOneNorm(long data) => SimdMatrix(data).OneNorm();
    public static double MatrixInfinityNorm(long data) => SimdMatrix(data).InfinityNorm();
    public static bool MatrixIsSymmetric(long data) => SimdMatrix(data).IsSymmetric();
    public static bool MatrixIsOrthogonal(long data) => SimdMatrix(data).IsOrthogonal();
    public static bool MatrixIsUpperTriangular(long data) => SimdMatrix(data).IsUpperTriangular();
    public static bool MatrixIsLowerTriangular(long data) => SimdMatrix(data).IsLowerTriangular();
    public static long[] MatrixArgMax(long data) { var (row, column) = SimdMatrix(data).ArgMax(); return [row, column]; }
    public static long[] MatrixArgMin(long data) { var (row, column) = SimdMatrix(data).ArgMin(); return [row, column]; }
    private static long StoreSimdMatrix(CommonLib.SimdMatrix matrix)
    {
        var result = new double[matrix.Rows, matrix.Cols];
        for (var row = 0; row < matrix.Rows; row++)
            for (var column = 0; column < matrix.Cols; column++) result[row, column] = matrix[row, column];
        return StoreMatrix(result);
    }
    public static long MatrixSlice(long handle, long rowStart, long rowEnd, long colStart, long colEnd) =>
        StoreSimdMatrix(SimdMatrix(handle).Slice(checked((int)rowStart), checked((int)rowEnd), checked((int)colStart), checked((int)colEnd)));
    public static long MatrixReshape(long handle, long rows, long columns) =>
        StoreSimdMatrix(SimdMatrix(handle).Reshape(checked((int)rows), checked((int)columns)));
    public static long MatrixConcatRows(long first, long second) =>
        StoreSimdMatrix(CommonLib.SimdMatrix.ConcatRows(SimdMatrix(first), SimdMatrix(second)));
    public static long MatrixConcatCols(long first, long second) =>
        StoreSimdMatrix(CommonLib.SimdMatrix.ConcatCols(SimdMatrix(first), SimdMatrix(second)));
    public static long MatrixAddRowVector(long handle, double[] values) => StoreSimdMatrix(SimdMatrix(handle).AddRowVector(values));
    public static long MatrixAddColVector(long handle, double[] values) => StoreSimdMatrix(SimdMatrix(handle).AddColVector(values));
    public static double MatrixMaxValue(long handle) => SimdMatrix(handle).Max();
    public static double MatrixMinValue(long handle) => SimdMatrix(handle).Min();
    public static bool[] MatrixAboveMask(long handle, double threshold) => SimdMatrix(handle).Mask(threshold);
    public static bool[] MatrixAboveMatrix(long handle, double threshold)
    {
        var mask = SimdMatrix(handle).GreaterThan(threshold);
        var flat = new bool[mask.GetLength(0) * mask.GetLength(1)];
        for (var row = 0; row < mask.GetLength(0); row++)
            for (var column = 0; column < mask.GetLength(1); column++)
                flat[row * mask.GetLength(1) + column] = mask[row, column];
        return flat;
    }
