    // SYSTEM: query e utility senza stato della VM.
    public static string Sys(string property) => property.Trim().ToUpperInvariant() switch
    {
        "UI" => "STANDARD",
        "OS" => OperatingSystem.IsWindows() ? "WINDOWS" : OperatingSystem.IsMacOS() ? "MACOS" : OperatingSystem.IsLinux() ? "LINUX" : Environment.OSVersion.Platform.ToString().ToUpperInvariant(),
        "ARCH" => System.Runtime.InteropServices.RuntimeInformation.ProcessArchitecture.ToString().ToUpperInvariant(),
        "VERSION" => "GMBASICAI",
        "RUNTIME" => System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription,
        "CPUCOUNT" => Environment.ProcessorCount.ToString(CultureInfo.InvariantCulture),
        "MACHINE" => Environment.MachineName,
        "USER" => Environment.UserName,
        // Memoria di sistema (API native, attendibile): disponibile+reclamabile / totale / usata.
        "MEMAVAILABLE" => CommonLib.SystemMemory.AvailableReclaimableBytes().ToString(CultureInfo.InvariantCulture),
        "MEMFREE" => CommonLib.SystemMemory.AvailableReclaimableBytes().ToString(CultureInfo.InvariantCulture),
        "MEMRECLAIMABLE" => CommonLib.SystemMemory.AvailableReclaimableBytes().ToString(CultureInfo.InvariantCulture),
        "MEMTOTAL" => CommonLib.SystemMemory.TotalBytes().ToString(CultureInfo.InvariantCulture),
        "MEMUSED" => MemUsed(),
        "MEMAVAILABLEMB" => (CommonLib.SystemMemory.AvailableReclaimableBytes() / (1024UL * 1024UL)).ToString(CultureInfo.InvariantCulture),
        "MEMTOTALMB" => (CommonLib.SystemMemory.TotalBytes() / (1024UL * 1024UL)).ToString(CultureInfo.InvariantCulture),
        "CWD" => Directory.GetCurrentDirectory(),
        "SETTINGSPATH" => CommonLib.GmbiPaths.SettingsFile,
        _ => string.Empty
    };

    /// <summary>MEMUSED = totale - disponibile/reclamabile (byte).</summary>
    private static string MemUsed()
    {
        ulong total = CommonLib.SystemMemory.TotalBytes();
        ulong avail = CommonLib.SystemMemory.AvailableReclaimableBytes();
        return ((total > avail ? total - avail : 0)).ToString(CultureInfo.InvariantCulture);
    }

    // ============================================================
    // SHELL / EXEC — esecuzione di comandi di sistema (opt-in via SET SHELL ON)
    // ============================================================
    // Il flag globale è condiviso tra i backend (IL e PCodeVM leggono lo stesso valore).
    private static volatile bool _shellEnabled = false;

    /// <summary>SET SHELL ON|OFF: abilita/disabilita SYSTEM.SHELL/EXEC/EXECCODE (opt-in).</summary>
    public static void SetShellEnabled(bool enabled) => _shellEnabled = enabled;

    /// <summary>True se SHELL/EXEC è abilitato (SET SHELL ON). Di default OFF.</summary>
    public static bool IsShellEnabled() => _shellEnabled;

    private static (int ExitCode, string Output) RunSystemCommand(string command)
    {
        if (!_shellEnabled)
            throw new BasicException(ErrorCode.PermissionDenied, SourcePosition.Unknown,
                "SYSTEM.SHELL/EXEC non abilitato: serve 'SET SHELL ON' (opt-in).");
        if (string.IsNullOrWhiteSpace(command))
            throw new BasicException(ErrorCode.InvalidParameter, SourcePosition.Unknown,
                "Comando vuoto per SYSTEM.SHELL/EXEC.");
        var psi = new System.Diagnostics.ProcessStartInfo
        {
            FileName = OperatingSystem.IsWindows() ? "cmd.exe" : "/bin/sh",
            UseShellExecute = false,
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            CreateNoWindow = true,
        };
        if (OperatingSystem.IsWindows())
        {
            psi.ArgumentList.Add("/c");
            psi.ArgumentList.Add(command);
        }
        else
        {
            psi.ArgumentList.Add("-c");
            psi.ArgumentList.Add(command);
        }
        using var proc = System.Diagnostics.Process.Start(psi)
            ?? throw new BasicException(ErrorCode.PermissionDenied, SourcePosition.Unknown, "Impossibile avviare il processo.");
        var stdout = proc.StandardOutput.ReadToEndAsync().GetAwaiter().GetResult();
        var stderr = proc.StandardError.ReadToEndAsync().GetAwaiter().GetResult();
        proc.WaitForExit();
        var outText = (stdout + stderr).TrimEnd('\r', '\n');
        return (proc.ExitCode, outText);
    }

    /// <summary>SYSTEM.SHELL "cmd": esegue e scarta l'output (fire-and-forget con attesa).</summary>
    public static double SystemShell(string command)
    {
        RunSystemCommand(command);
        return 0.0;
    }

    /// <summary>SYSTEM.EXEC("cmd"): esegue e ritorna stdout+stderr come stringa.</summary>
    public static string SystemExec(string command)
        => RunSystemCommand(command).Output;

    /// <summary>SYSTEM.EXECCODE("cmd"): esegue e ritorna l'exit code del processo.</summary>
    public static double SystemExecCode(string command)
        => RunSystemCommand(command).ExitCode;

    /// <summary>Parità Go `runtime.GOMAXPROCS(n)`: restituisce il valore precedente (o corrente,
    /// con 0 argomenti). Sul backend IL non esiste uno scheduler GPM ridimensionabile come la
    /// PCodeVM (l'IL esegue sul thread host con la coda globale), quindi il valore riflette
    /// l'ambiente GMBASIC_GOMAXPROCS/ProcessorCount senza effetti collaterali. Sulla PCodeVM la
    /// stessa funzione ridimensiona davvero i P (vedi PCodeProcessor.Builtins GOMAXPROCS).</summary>
    private static int _goMaxProcs;
    public static double GoMaxProcs(double n = 0)
    {
        // Valore corrente = numero di CPU (come i worker di PCode/VM-C/C99); n > 0 lo imposta e la
        // funzione ritorna il PRECEDENTE (Go runtime.GOMAXPROCS). Prima ignorava n e leggeva la env
        // GMBASIC_GOMAXPROCS (vietata dalla direttiva sulle variabili d'ambiente).
        var previous = _goMaxProcs > 0 ? _goMaxProcs : Math.Max(1, Math.Min(8, Environment.ProcessorCount));
        if (n > 0) _goMaxProcs = (int)n;
        return previous;
    }
    /// <summary>SYSTEM.NUMGOROUTINE() nel path LINEARE: nessuna goroutine (non-GPM) → 0. Nel
    /// path v2 l'emitter legge direttamente task.Scheduler.TaskCount.</summary>
    public static double NumGoroutine() => 0;
    /// <summary>SYSTEM.NUMCPU() (parità Go runtime.NumCPU).</summary>
    public static double NumCpu() => Environment.ProcessorCount;
    public static bool Empty(object? value) => value switch
    {
        null => true, string text => string.IsNullOrWhiteSpace(text), bool bit => !bit,
        Array array => array.Length == 0, byte number => number == 0, sbyte number => number == 0,
        short number => number == 0, ushort number => number == 0, int number => number == 0,
        uint number => number == 0, long number => number == 0, ulong number => number == 0,
        float number => number == 0, double number => number == 0, decimal number => number == 0,
        _ => false
    };
    public static string TypeName(object? value)
    {
        switch (value)
        {
            case null: return "NIL";
            case string: return "STRING";
            case bool: return "BIT";
            case byte: return "BYTE";
            case sbyte: return "SBYTE";
            case short: return "INTEGER";
            case ushort: return "UINTEGER";
            case long: return "LONG";
            case ulong: return "ULONG";
            case float: return "SINGLE";
            case double: return "DOUBLE";
            case decimal: return "CURRENCY";
            case DateTime: return "DATETIME";
            case Array: return "ARRAY";
            // BAG<T> è materializzato come Dictionary<T,long> (BagMultiset). Le altre gambe
            // (PCode/VM-C/C99) vedono un DICTIONARY e riportano "DICTIONARY`2": il nome CLR
            // "BAGMULTISET`1" era una divergenza solo IL (minitest
            // collections/collection_typename_valtype).
            case IBagMultiset: return "DICTIONARY`2";
            // HLL: nome BASIC (parità C99/VM-C, gmb_collection_type_name(30)).
            case CommonLib.Collections.HyperLogLog: return "HLL";
            default:
                // UDT: nome BASIC dal registro (parità PCode/VM-C) invece del nome CLR "UDT_540".
                if (UdtTypeNames.TryGetValue(value.GetType().FullName ?? "", out var bn)) return bn;
                return value.GetType().Name.ToUpperInvariant();
        }
    }
    public static long SizeOf(object? value)
    {
        if (value is null or string) return -1;
        if (value is Array array) { try { return Buffer.ByteLength(array); } catch (ArgumentException) { return -1; } }
        return value switch { bool or byte or sbyte => 1, short or ushort => 2, int or uint or float => 4, long or ulong or double or DateTime => 8, decimal => 16, _ => -1 };
    }
    /* Argomenti del PROGRAMMA BASIC (non quelli dell'host). Un host embedded (test/REPL/
     * runner) li imposta esplicitamente; senza override si mantiene il fallback storico
     * su argv del processo. Indice 1-based: COMMAND(1) = primo argomento utente. */
    private static string[]? _commandArgs;
    public static void SetCommandArgs(string[]? args) => _commandArgs = args;
    public static long CommandCount() => _commandArgs is { } a
        ? a.Length
        : Math.Max(0, Environment.GetCommandLineArgs().Length - 1);
    public static string Command(long index)
    {
        if (_commandArgs is { } a)
            return index >= 1 && index <= a.Length ? a[(int)index - 1] : string.Empty;
        var args = Environment.GetCommandLineArgs();
        return index >= 1 && index < args.Length ? args[index] : string.Empty;
    }

    /// <summary>ENV$(nome): valore della variabile d'ambiente, "" se assente. Lettura
    /// ESPLICITA del programma utente; il motore continua a usare il registro opzioni.</summary>
    public static string EnvGet(string? name)
        => string.IsNullOrEmpty(name) ? string.Empty : (Environment.GetEnvironmentVariable(name) ?? string.Empty);

    /// <summary>ENV.HAS(nome): -1 se presente, 0 se assente (convenzione booleana BASIC).</summary>
    public static double EnvHas(string? name)
        => !string.IsNullOrEmpty(name) && Environment.GetEnvironmentVariable(name) is not null ? -1.0 : 0.0;

    // IO: handle file autonomi per il codice IL, separati dal registro della VM.
    private static long StoreFile(FileStream stream)
    {
        // Primo handle LIBERO (1-based), come il runtime C (gmb_file_open: primo slot libero
        // di gmb_file_handles[]). Prima si usava _nextFileHandle (Interlocked.Increment): il
        // numero NON veniva mai riusato, quindi cresceva senza limite e divergeva dal mondo C
        // — es. FREEFILE dopo la chiusura ritornava un numero alto invece del primo libero
        // (§ MiniTests/io/io_freefile.bas). TryAdd e' atomico: nessuna finestra fra il test
        // di libero e l'occupazione.
        for (long h = 1; h <= 4096; h++)
            if (OpenFiles.TryAdd(h, stream)) return h;
        throw new InvalidOperationException("Troppi file aperti (limite 4096).");
    }
    private static FileStream GetFile(long handle) => OpenFiles.TryGetValue(handle, out var stream) ? stream : throw new ArgumentException("Handle file non valido.", nameof(handle));
    public static bool Eof(long handle) { var stream = GetFile(handle); return stream.Position >= stream.Length; }
    /// <summary>EOF di un FILE NUMBER (stile legacy `OPEN ... AS #n` / `USING F = OPEN(...)`):
    /// mappa il file number all'handle via FileNumberToHandle (come FileWriteNumber), con
    /// fallback all'handle diretto (FOpen). Senza, `EOF(F)` passava F (file number) a
    /// Eof(handle) → GetFile(fileNumber) → "Handle file non valido".</summary>
    public static bool FileEofNumber(long fileNum)
    {
        long handle = FileNumberToHandle.TryGetValue(fileNum, out var h) ? h : fileNum;
        // Se FileReadLineNumber ha creato un StreamReader per l'handle, il suo buffer ha GIÀ
        // letto avanti l'INTERO file → il FileStream.Position è a fine file anche con righe
        // ancora da leggere → la Position darebbe EOF troppo presto (bug: `DO WHILE NOT EOF(F)`
        // leggeva solo la prima riga su IL/PCode). Usa reader.EndOfStream, non la Position.
        if (OpenLineReaders.TryGetValue(handle, out var reader)) return reader.EndOfStream;
        try { return Eof(handle); } catch { return true; }
    }
    public static long Lof(long handle) => GetFile(handle).Length;
    /// <summary>LOF di un FILE NUMBER (stile legacy / USING): mappa all'handle (come FileEofNumber).</summary>
    public static long FileLofNumber(long fileNum)
    {
        long handle = FileNumberToHandle.TryGetValue(fileNum, out var h) ? h : fileNum;
        try { return Lof(handle); } catch { return 0; }
    }
    public static long FreeFile()
    {
        // FREEFILE: primo numero di file LIBERO (1-based), stessa semantica di
        // gmb_file_free_file() del runtime C (§0bis: la numerazione dei file deve essere la
        // stessa su tutti i backend) e coerente con l'assegnazione degli handle in StoreFile.
        // Prima era `_nextFileHandle + 1`: un CONTATORE che cresce e non si resetta mai,
        // quindi dopo la chiusura dei file ritornava un numero alto invece del primo libero
        // (es. 5) e divergeva da C99/C99Native; il PCode ritornava la costante 1.
        // Trovato da MiniTests/io/io_freefile.bas.
        for (long h = 1; h <= 4096; h++)
            if (!OpenFiles.ContainsKey(h)) return h;
        return -1;
    }
    public static string FileInput(long count, long handle)
    {
        var bytes = new byte[checked((int)Math.Max(0, count))];
        var read = GetFile(handle).Read(bytes, 0, bytes.Length);
        return System.Text.Encoding.UTF8.GetString(bytes, 0, read);
    }
