    /// <summary>Cerca una cartella per NOME (es. "samples") con profondità di discesa di default.</summary>
    public static string GetFolderPath(string folder) => GetFolderPath(folder, 10);

    /// <summary>Cerca una cartella per NOME (es. "samples") salendo dalla cartella del programma
    /// entry-point fino alla root; se non trovata, scende in BFS fino a <paramref name="maxDepth"/>
    /// livelli (default 10). Ritorna il percorso assoluto o stringa vuota.</summary>
    public static string GetFolderPath(string folder, double maxDepth)
    {
        if (string.IsNullOrWhiteSpace(folder)) return "";
        var start = CurrentProgramFolder;
        if (string.IsNullOrEmpty(start)) return "";
        try
        {
            var root = new DirectoryInfo(start);
            for (var d = root; d != null; d = d.Parent)
            {
                var candidate = Path.Combine(d.FullName, folder);
                if (Directory.Exists(candidate)) return Path.GetFullPath(candidate);
            }
            var levels = Math.Max(0, (int)maxDepth);
            if (levels == 0) return "";
            var visited = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { root.FullName };
            var frontier = new Queue<DirectoryInfo>();
            frontier.Enqueue(root);
            for (var depth = 1; depth <= levels && frontier.Count > 0; depth++)
            {
                var next = new Queue<DirectoryInfo>();
                while (frontier.Count > 0)
                {
                    var d = frontier.Dequeue();
                    DirectoryInfo[] subs;
                    try { subs = d.GetDirectories(); } catch { continue; }
                    foreach (var sub in subs)
                    {
                        if (!visited.Add(sub.FullName)) continue;
                        if (string.Equals(sub.Name, folder, StringComparison.OrdinalIgnoreCase))
                            return sub.FullName;
                        next.Enqueue(sub);
                    }
                }
                frontier = next;
            }
        }
        catch { /* IO/diritti: nessun match */ }
        return "";
    }

    public static string NormalizePath(string path) => CommonLib.FileSystemUtils.CoreNormalizePath(path);
    /// <summary>Risolve un path FILE/DIR: assoluto → così com'è (se esiste); relativo → contro la
    /// cartella dell'ENTRY point e la lista SET PATH. Stringa vuota se non esiste da nessuna parte.</summary>
    public static string ResolveFilePath(string path)
    {
        if (string.IsNullOrWhiteSpace(path)) return "";
        if (Path.IsPathRooted(path))
            return (File.Exists(path) || Directory.Exists(path)) ? path : "";
        var candidates = new List<string> { Path.Combine(CurrentProgramFolder, path) };
        foreach (var sp in _searchPaths) candidates.Add(Path.Combine(sp, path));
        foreach (var c in candidates)
        {
            if (File.Exists(c) || Directory.Exists(c))
            {
                try { return Path.GetFullPath(c); } catch { return c; }
            }
        }
        return "";
    }

    /// <summary>Ritorna la lista SET PATH separata da ';' (default: cartella del programma entry-point).</summary>
    // APPPATH() = cartella dell'applicazione (guida IO §2). Con _searchPaths vuoto (nessun
    // path di ricerca registrato) il C runtime ritorna gmb_path_app_dir(): stesso fallback qui,
    // altrimenti l'IL dava "" mentre VM/C/C99 davano la cartella (§ FilesFullCoverage).
    public static string AppPath() => _searchPaths.Count > 0 ? string.Join(";", _searchPaths) : CommonLib.FileSystemUtils.CoreAppPath();

