    /// <summary>Array (string[]/double[]/...) -> List&lt;object&gt; per assegnarlo a una variabile `LIST` non tipizzata.</summary>
    public static System.Collections.Generic.List<object?> ArrayToObjectList(System.Collections.IEnumerable? src)
    {
        var l = new System.Collections.Generic.List<object?>();
        if (src != null) foreach (var x in src) l.Add(x);
        return l;
    }
    public static string[] Dir(string pathMask)
    {
        var mask = pathMask ?? "";
        if (string.IsNullOrWhiteSpace(mask)) return [];
        var dirPart = Path.GetDirectoryName(mask);
        var pattern = Path.GetFileName(mask);
        string directory;
        if (string.IsNullOrEmpty(dirPart))
            directory = CurrentProgramFolder;                 // "." o pattern nudo → cartella entry
        else
        {
            directory = ResolveFilePath(dirPart);             // contro la cartella entry + SET PATH
            if (string.IsNullOrEmpty(directory)) return [];   // dir inesistente → array vuoto
        }
        if (!Directory.Exists(directory)) return [];
        if (string.IsNullOrEmpty(pattern) || pattern is "." or "*" or "*.*") pattern = "*";
        try
        {
            return Directory.GetDirectories(directory, pattern).Concat(Directory.GetFiles(directory, pattern))
                .Select(Path.GetFileName).Where(n => n is not null).Cast<string>().ToArray();
        }
        catch { return []; }
    }
    /// <summary>FOPEN path — apre un file e ritorna l'handle (>=1) o -1 se fallisce,
    /// impostando FileReadWriteUtils.FileError (2 = file non trovato, 1 = altro errore).
    /// Non lancia: parità col PCode (BuiltInFunction.FOPEN → -1).</summary>
    public static long FOpen(string path)
    {
        try
        {
            if (!File.Exists(path)) { CommonLib.FileReadWriteUtils.FileError = 2; return -1; }
            var h = StoreFile(new FileStream(path, FileMode.Open, FileAccess.ReadWrite, FileShare.Read));
            CommonLib.FileReadWriteUtils.FileError = 0;
            return h;
        }
        catch { CommonLib.FileReadWriteUtils.FileError = 1; return -1; }
    }
    /// <summary>FCREATE path — crea/trunca un file e ritorna l'handle (>=1) o -1 se fallisce,
    /// impostando FileReadWriteUtils.FileError (1 = errore generico).</summary>
    public static long FCreate(string path)
    {
        try
        {
            var h = StoreFile(new FileStream(path, FileMode.Create, FileAccess.ReadWrite, FileShare.Read));
            CommonLib.FileReadWriteUtils.FileError = 0;
            return h;
        }
        catch { CommonLib.FileReadWriteUtils.FileError = 1; return -1; }
    }
    /// <summary>Usato da APPEND/BINARY: a differenza di FOpen (FileMode.Open) non richiede
    /// che il file esista già — crea un file vuoto se manca, altrimenti apre quello esistente
    /// senza troncarlo (a differenza di FCreate/FileMode.Create).</summary>
    public static long FOpenOrCreate(string path)
    {
        try
        {
            var h = StoreFile(new FileStream(path, FileMode.OpenOrCreate, FileAccess.ReadWrite, FileShare.Read));
            CommonLib.FileReadWriteUtils.FileError = 0;
            return h;
        }
        catch { CommonLib.FileReadWriteUtils.FileError = 1; return -1; }
    }
    public static long FClose(long handle) { if (OpenLineReaders.TryRemove(handle, out var rdr)) rdr.Dispose(); if (!OpenFiles.TryRemove(handle, out var stream)) return -1; stream.Dispose(); return 0; }

    /// <summary>OPEN con file number: crea/apre il file e registra handle per il file number.
    /// INPUT ("r") resta su FOpen — deve fallire se il file non esiste (comportamento
    /// corretto, ora anche catturabile da ON ERROR/TRY-CATCH via BasicException.
    /// FromClrException). APPEND ("a")/BINARY ("rb") vanno invece creati se mancanti,
    /// come OUTPUT — solo che non troncano un file già esistente; APPEND inoltre
    /// posiziona il cursore a fine file per le scritture successive.</summary>
    public static long FileOpenNumber(string path, string mode, long fileNum)
    {
        // Normalizza i mode BASIC (OUTPUT/INPUT/APPEND) ai mode interni ("w"/"r"/"a")
        // — la FUNZIONE OPEN del USING passa il mode testuale del campione.
        mode = mode.ToUpperInvariant() switch
        {
            "W" or "OUTPUT" => "w",
            "R" or "INPUT" => "r",
            "A" or "APPEND" => "a",
            _ => mode.ToLowerInvariant()
        };
        var handle = mode switch
        {
            "w" => FCreate(path),
            "a" or "rb" or "r+" => FOpenOrCreate(path),
            _ => FOpen(path)
        };
        if (mode == "a") GetFile(handle).Seek(0, SeekOrigin.End);
        FileNumberToHandle[fileNum] = handle;
        return handle;
    }
    /// <summary>CLOSE via file number: rilascia l'handle registrato.</summary>
    public static void FileCloseAll()
    {
        // CLOSE senza handle: chiude tutti i file aperti (parità VM — la pulizia finale).
        try
        {
            foreach (var kv in FileNumberToHandle.ToList())
                FClose(kv.Value);
            FileNumberToHandle.Clear();
        }
        catch { }
    }

    public static long FileCloseNumber(long fileNum)
    {
        if (FileNumberToHandle.TryRemove(fileNum, out var handle)) return FClose(handle);
        return -1;
    }
    /// <summary>Content type per file number (1 = JSON, come task.FileContentTypes del
    /// PCodeVM): serve al PRINT #h per serializzare un oggetto come JSON invece del
    /// ToString() del CLR (bug reale: `JSON OPEN` + `PRINT #h, obj` scriveva
    /// "System.Collections.Generic.Dictionary`2[...]" nel file).</summary>
    private static readonly System.Collections.Concurrent.ConcurrentDictionary<long, int> FileNumberContentType = new();

    /// <summary>true se il canale e' stato aperto come JSON (`JSON OPEN ... AS #n`, content type 1).</summary>
    public static bool FileIsJson(long fileNum)
        => FileNumberContentType.TryGetValue(fileNum, out var ct) && ct == 1;

    /// <summary>INPUT # su un canale JSON (parità PCode INPUT_FILE con FileContentTypes == 1): legge il resto del
    /// file come UN documento JSON e lo converte in dizionario/lista (JsonElementToObject: stessi tipi di JSON.LOAD).
    /// File vuoto o non valido = dizionario vuoto. Prima IL leggeva UNA riga CSV e la convertiva a double: la variabile
    /// JSON diventava 0 e `g["k"].campo` dava valori falsi.</summary>
    public static object? FileReadJsonNumber(long fileNum)
    {
        var text = "";
        if (FileNumberToHandle.TryGetValue(fileNum, out var handle))
        {
            var reader = OpenLineReaders.GetOrAdd(handle,
                h => new System.IO.StreamReader(GetFile(h), System.Text.Encoding.UTF8, false, 4096, true));
            text = reader.ReadToEnd();
        }
        try
        {
            using var doc = System.Text.Json.JsonDocument.Parse(string.IsNullOrWhiteSpace(text) ? "{}" : text);
            return JsonElementToObject(doc.RootElement);
        }
        catch { return new Dictionary<string, object?>(StringComparer.OrdinalIgnoreCase); }
    }

    /// <summary>OPEN con content type (parità PCode OPEN: typeCode 1 = JSON).</summary>
    public static long FileOpenNumber(string path, string mode, long fileNum, long contentType)
    {
        var h = FileOpenNumber(path, mode, fileNum);
        FileNumberContentType[fileNum] = (int)contentType;
        return h;
    }

    /// <summary>PRINT #h, v: se l'handle è JSON (content type 1) serializza v come JSON
    /// (parità PCode PRINT_FILE con FileContentTypes == 1), altrimenti Convert.ToString.</summary>
    public static long FileWriteNumberOrJson(long fileNum, object? v)
    {
        string text;
        if (FileNumberContentType.TryGetValue(fileNum, out var ct) && ct == 1)
        {
            try { text = System.Text.Json.JsonSerializer.Serialize(v) ?? "null"; }
            catch { text = Convert.ToString(v, System.Globalization.CultureInfo.InvariantCulture) ?? ""; }
        }
        else
        {
            text = Convert.ToString(v, System.Globalization.CultureInfo.InvariantCulture) ?? "";
        }
        return FileWriteNumber(fileNum, text);
    }

    /// <summary>WRITE via file number.</summary>
    public static long FileWriteNumber(long fileNum, string text)
    {
        if (!FileNumberToHandle.TryGetValue(fileNum, out var handle)) return -1;
        var bytes = System.Text.Encoding.UTF8.GetBytes(text ?? "");
        GetFile(handle).Write(bytes, 0, bytes.Length);
        return bytes.Length;
    }
    /// <summary>Formatta UN campo per WRITE # (stile BASIC, parità PCode WRITE_FILE):
    /// stringhe tra virgolette (doppie " escape come ""), double -1/0 → TRUE/FALSE,
    /// bool TRUE/FALSE, null → NULL, resto invariant. Campi separati da virgola e
    /// riga chiusa da newline a carico dell'emettitore.</summary>
    public static string WriteField(object? v) => v switch
    {
        null => "NULL",
        string s => "\"" + s.Replace("\"", "\"\"") + "\"",
        bool b => b ? "TRUE" : "FALSE",
        double dv => dv == -1.0 ? "TRUE" : dv == 0.0 ? "FALSE"
            : dv.ToString(System.Globalization.CultureInfo.InvariantCulture),
        float fv => fv == -1f ? "TRUE" : fv == 0f ? "FALSE"
            : ((double)fv).ToString(System.Globalization.CultureInfo.InvariantCulture),
        _ => Convert.ToString(v, System.Globalization.CultureInfo.InvariantCulture) ?? "",
    };
    /// <summary>READ LINE via file number. Ritorna null a EOF.</summary>
    public static string? FileReadLineNumber(long fileNum)
    {
        if (!FileNumberToHandle.TryGetValue(fileNum, out var handle)) return null;
        var reader = OpenLineReaders.GetOrAdd(handle,
            h => new System.IO.StreamReader(GetFile(h), System.Text.Encoding.UTF8, false, 4096, true));
        if (reader.EndOfStream) return null;
        return reader.ReadLine();
    }

    /// <summary>INPUT #: legge UNA riga e la divide nei campi CSV canonici (parità
    /// `gmb_file_read_csv_line` e WriteField): virgole dentro i doppi apici letterali,
    /// `""` → `"`, gli apici del campo rimossi. Null a EOF.</summary>
    public static string[]? FileReadCsvLineNumber(long fileNum)
    {
        var line = FileReadLineNumber(fileNum);
        if (line == null) return null;
        return ParseCsvFields(line);
    }

    /// <summary>Parser CSV condiviso (stessa semantica del runtime C).</summary>
    public static string[] ParseCsvFields(string line)
    {
        var fields = new List<string>();
        var sb = new System.Text.StringBuilder();
        var inQuotes = false;
        for (var i = 0; i < line.Length; i++)
        {
            var ch = line[i];
            if (ch == '"')
            {
                if (inQuotes && i + 1 < line.Length && line[i + 1] == '"') { sb.Append('"'); i++; }
                else inQuotes = !inQuotes;
                continue;
            }
            if (ch == ',' && !inQuotes)
            {
                fields.Add(sb.ToString());
                sb.Clear();
                continue;
            }
            sb.Append(ch);
        }
        fields.Add(sb.ToString());
        return fields.ToArray();
    }

    /// <summary>Campo i-esimo come stringa ("" se mancante/EOF).</summary>
    public static string CsvFieldToString(string[]? fields, int i)
        => fields != null && i >= 0 && i < fields.Length ? fields[i] : "";

    /// <summary>Campo i-esimo come double: TRUE/FALSE → -1/0, numero invariant, altrimenti 0
    /// (parità del contratto WRITE#/INPUT# C# ↔ runtime C).</summary>
    public static double CsvFieldToDouble(string[]? fields, int i)
    {
        if (fields == null || i < 0 || i >= fields.Length) return 0.0;
        var f = fields[i];
        if (f.Equals("TRUE", StringComparison.OrdinalIgnoreCase)) return -1.0;
        if (f.Equals("FALSE", StringComparison.OrdinalIgnoreCase)) return 0.0;
        return double.TryParse(f, System.Globalization.NumberStyles.Float,
            System.Globalization.CultureInfo.InvariantCulture, out var d) ? d : 0.0;
    }
    /// <summary>FREAD(handle [, count]) — FUNZIONE PURA (AGENTS §1/§3: le funzioni non scrivono
    /// mai): ritorna i dati letti (una riga se `count` e' omesso/&lt;=0, altrimenti `count` byte).
    /// La scrittura in un buffer e' il COMANDO `FREAD handle [, count] INTO buffer`, che il
    /// parser desugara in un'assegnazione. Prima era `FRead(handle, byte[])` con ritorno lungo:
    /// una funzione che scriveva (e con una STRING lanciava ArgumentException).</summary>
    public static string FRead(long handle, long count = 0)
    {
        if (count <= 0) return FReadLine(handle);
        var fs = GetFile(handle);
        var buf = new byte[count];
        int n = fs.Read(buf, 0, buf.Length);
        return System.Text.Encoding.UTF8.GetString(buf, 0, n);
    }

    /// <summary>Una riga dall'handle (usata da FREAD senza count).</summary>
    public static string FReadLine(long handle)
    {
        var fs = GetFile(handle);
        var sb = new System.Text.StringBuilder();
        int b;
        while ((b = fs.ReadByte()) >= 0)
        {
            if (b == '\n') break;
            if (b == '\r') { if (fs.Position < fs.Length && fs.ReadByte() != '\n') fs.Position--; break; }
            sb.Append((char)b);
        }
        return sb.ToString();
    }
    public static long FWrite(long handle, object? data) { var bytes = CryptoBytes(data); GetFile(handle).Write(bytes, 0, bytes.Length); return bytes.Length; }
    public static long Seek(long handle) => GetFile(handle).Position;
    public static long FSeek(long handle, long position) { var stream = GetFile(handle); stream.Position = position; return stream.Position; }
    /// <summary>SEEK via NUMERO DI FILE legacy (`OPEN ... AS #n`). La funzione IO.SEEK(fileNumber)
    /// della StdLib prende un numero di file, non un handle di FOpen: prima il codegen la mandava
    /// su Seek(handle) e con un numero legacy lanciava ArgumentException "Handle file non valido"
    /// (§ trovato da MiniTests/io/io_misc.bas, dove PCode e VMC funzionavano). Se il numero non e'
    /// un file legacy resta interpretato come handle di FOpen (retro-compatibile).</summary>
    public static long FileSeekNumber(long fileNum)
        => FileNumberToHandle.TryGetValue(fileNum, out var handle) ? Seek(handle) : Seek(fileNum);

    /// <summary>SEEK n, pos — COMANDO legacy (pos 1-based: `SEEK 1, 1` torna all'inizio).
    /// Risolve il NUMERO di file legacy (`OPEN ... AS #n`) tramite FileNumberToHandle e sposta
    /// il cursore. Prima lo statement passava il numero di file direttamente a
    /// IFileService.Seek come se fosse un HANDLE di FOpen: il seek finiva su un altro stream
    /// (o su nessuno) e non aveva effetto — trovato da MiniTests/io/io_misc.bas (dopo
    /// `SEEK 1, 3` il PCode leggeva 3, IL e VMC restavano a 0).</summary>
    public static long FileSetPosNumber(long fileNum, long position1Based)
    {
        var handle = FileNumberToHandle.TryGetValue(fileNum, out var h) ? h : fileNum;
        var stream = GetFile(handle);
        stream.Position = position1Based > 1 ? position1Based - 1 : 0;
        return stream.Position;
    }
    /// <summary>FERROR() — ultimo codice di errore file (Clipper): 0 = ok, 1 = errore
    /// generico, 2 = file non trovato. Stato condiviso con CommonLib.FileReadWriteUtils
    /// (parità col PCode BuiltInFunction.FERROR).</summary>
    public static long FError() => CommonLib.FileReadWriteUtils.FileError;

    public static void RemoveDirectory(string path, bool recursive)
