        if (Directory.Exists(path)) Directory.Delete(path, recursive);
    }

    public static void CopyDirectory(string source, string destination, bool recursive, bool overwrite)
        => CommonLib.FileSystemUtils.CoreDirectoryCopy(source, destination, recursive, overwrite);

    /* NOW() in UTC (canone data/ora, TIME-TimeType): le gambe C (gmb_dt_now) sono UTC -> parità
     * di fuso. Prima DateTime.Now (locale) -> HttpSession timestamp 13:48 vs 11:48 sulle gambe C. */
    public static DateTime Now() => DateTime.UtcNow;
    public static DateTime Today() => DateTime.Today;
    public static DateTime DateValue(string value) => CommonLib.DateUtils.CoreDateValue(value).ToDateTime(TimeOnly.MinValue);
    public static DateTime DateSerial(short year, short month, short day) => CommonLib.DateUtils.CoreDateSerial(year, month, day).ToDateTime(TimeOnly.MinValue);
    // TIMESERIAL: solo ORA del giorno (data = OADate 0 = 30/12/1899, canone VB), cosi' il serial e' la frazione di giorno come nel runtime C.
    public static DateTime TimeSerial(short hour, short minute, short second) => DateTime.FromOADate(0).Add(new TimeSpan(hour, minute, second));
    public static string Dtos(DateTime value) => CommonLib.DateUtils.CoreDtos(value);
    public static DateTime Stod(string value) => CommonLib.DateUtils.CoreStod(value).ToDateTime(TimeOnly.MinValue);

    /// <summary>CTOD con SET EPOCH: anno a 2 cifre → 19xx/20xx col cutoff di SetEpoch.
    /// Restituisce il serial OADate (il tipo dichiarato della nativa CTOD è DoubleType).</summary>
    /// <summary>CTOD in forma data (DateTime) come DateValue: IL interno usa DateTime.</summary>
    public static DateTime CtODDate(string value)
    {
        try { return DateTime.FromOADate(CtOD(value ?? "")); }
        catch { return DateTime.FromOADate(0); }
    }

    public static double CtOD(string value)
    {
        try
        {
            var m = System.Text.RegularExpressions.Regex.Match(value ?? "", @"^(\d{1,2})[/-](\d{1,2})[/-](\d{2})$");
            if (m.Success)
            {
                var yy = int.Parse(m.Groups[3].Value);
                var ec = Current.Graphics.ClipperEpoch();
                int fy = ec >= 2000 ? 2000 + yy
                    : ec <= 1900 ? 1900 + yy
                    : yy >= (ec % 100) ? 1900 + yy : 2000 + yy;
                return new DateTime(fy, int.Parse(m.Groups[1].Value), int.Parse(m.Groups[2].Value)).ToOADate();
            }
            var mi = System.Text.RegularExpressions.Regex.Match(value ?? "", @"^(\d{4})-(\d{1,2})-(\d{1,2})$");
            if (mi.Success)
                return new DateTime(int.Parse(mi.Groups[1].Value), int.Parse(mi.Groups[2].Value),
                                    int.Parse(mi.Groups[3].Value)).ToOADate();
            return CommonLib.DateUtils.CoreCtod(value ?? "");
        }
        catch { return 0; }
    }
