    /// <summary>Canone data/ora (UTC): TIME() = seriale data+ora, DATE() = seriale giorno (numerici).</summary>
    public static double Time() => CommonLib.DateUtils.CoreTimeSerial();
    public static double DaySerial() => CommonLib.DateUtils.CoreDaySerial();
    public static string StrTime() => CommonLib.DateUtils.CoreTimeString();
    public static string StrDate() => CommonLib.DateUtils.CoreDateString();
