    /// <summary>Operazioni binarie su date/ora/timespan: op (0=+, 1=-). "lKind"/"rKind"
    /// sono i tipi (0=Date/DateTime, 1=Time, 2=TimeSpan, 3=numero). r è boxed (DateTime
    /// o double). Date+Time→DateTime; Date+double→AddDays; Date-Date→TimeSpan; Date±TimeSpan.</summary>
    public static object? DateBinary(DateTime l, double op, double lKind, object? r, double rKind)
    {
        var left = l;
        try
        {
            var isSub = op != 0;
            var lk = (int)lKind;
            var rk = (int)rKind;
            DateTime? rDt = r is DateTime rd ? rd : null;
            // rNum solo per rk==3 (numero): Convert.ToDouble(DateTime) lancerebbe.
            double? rNum = rk == 3 ? (r is double rn ? rn : Convert.ToDouble(r, CultureInfo.InvariantCulture)) : null;
            TimeSpan? rSpan = rk switch
            {
                2 when rDt is { } dt => new TimeSpan(dt.Ticks),
                1 when rDt is { } dt => new TimeSpan(dt.Hour, dt.Minute, dt.Second),
                _ => null
            };

            if (lk == 2) // TimeSpan ± TimeSpan / double
            {
                var ls = new TimeSpan(l.Ticks);
                var rs = rSpan ?? TimeSpan.FromDays(rNum ?? 0);
                return isSub ? ls.Subtract(rs) : ls.Add(rs);
            }
            if (rSpan is { } span) // Date/DateTime ± TimeSpan
            {
                return isSub ? left.Subtract(span) : left.Add(span);
            }
            if (rk == 0 && isSub) // Date - Date → TimeSpan
                return left.Subtract(rDt ?? default);
            if (rk == 0) // Date + Date → DateTime (somma delle parti)
                return new DateTime(left.Ticks + (rDt ?? default).Ticks);
            // Date + numero → AddDays
            return isSub ? left.AddDays(-(rNum ?? 0)) : left.AddDays(rNum ?? 0);
        }
        catch { return null; }
    }

    /// <summary>Converte un valore generico in byte[] per operazioni di rete/file binari.</summary>
    public static byte[] ValueToBytes(object? value) => value switch
    {
        null => Array.Empty<byte>(),
        byte[] bytes => bytes,
        string text => System.Text.Encoding.UTF8.GetBytes(text),
        _ => System.Text.Encoding.UTF8.GetBytes(Convert.ToString(value, CultureInfo.InvariantCulture) ?? string.Empty)
    };

