        if (OperatingSystem.IsWindows()) stream.Unlock(position, length);
    }

    // ── Audio ────────────────────────────────────────────────────────


    // ── HTTP Server ───────────────────────────────────────────────────
    private static long _httpServerHandle = -1;
    /// <summary>Scheduler GPM catturato a <c>HTTP SERVER</c> (quando il programma gira sul GPM).
    /// I dispatch HTTP/WS dei thread di rete usano QUESTO scheduler (contesto esplicito, §0ter
    /// punto 4) invece di rileggere <see cref="IlGpmRuntime.CurrentScheduler"/> a ogni richiesta:
    /// quello statico viene azzerato a fine run e può essere null quando il servizio process-wide
    /// (HttpService) riceve una richiesta da un thread di pool → flaky/hang in-process. Parità
    /// PCodeVM, dove lo scheduler è legato alla VM (task.Scheduler = _scheduler).</summary>
    private static Basic.Runtime.Gpm.PCodeScheduler? _httpScheduler;
    private static readonly Dictionary<string, (string Method, string Path, int HandlerSymbolId)> _httpRoutes = new(StringComparer.OrdinalIgnoreCase);
    private static readonly List<(string? Path, int HandlerSymbolId)> _httpMiddleware = [];
    private static readonly List<(string Path, int HandlerSymbolId)> _httpWsRoutes = new();
    private static readonly List<(string Prefix, string Directory)> _httpStatics = new();
    /// <summary>Servizio HTTP che possiede <see cref="_httpServerHandle"/>. Ogni programma creato
    /// dal harness in-process ha un HeadlessRuntimeHost NUOVO (quindi un HttpService nuovo):
    /// fermare l'handle su `Current.Http` dopo un cambio di run è un no-op e lascia il listener
    /// VIVO (porta occupata → il run successivo non riesce a fare bind → richieste in TIMEOUT).
    /// Si ricorda quindi il servizio di avvio e lo si usa per lo stop.</summary>
    private static IHttpService? _httpServerService;

    /// <summary>
    /// Prima azzerava sempre i mount STATIC e
    /// <see cref="_httpRoutes"/> all'avvio — ma in TUTTI i sample reali (`HttpStatic.bas`,
    /// `PackageServer.bas`, ecc.) `HTTP STATIC`/`HTTP ROUTE` vengono scritti PRIMA di
    /// `HTTP SERVER` (ordine naturale: prima si dichiara cosa servire, poi si avvia il server) —
    /// con la guardia `_httpServerHandle &lt; 0` su <see cref="HttpAddStatic"/>/
    /// <see cref="HttpAddRoute"/>, quelle dichiarazioni precedenti non avevano mai effetto (no-op
    /// silenzioso) e qui il reset le cancellava comunque. Ora, se STATIC/ROUTE erano già stati
    /// dichiarati prima dell'avvio, vengono applicati subito dopo aver ottenuto un handle valido.
    /// </summary>
    public static long HttpServerStart(string port, string callbackName)
    {
        var portNum = int.TryParse(port, out var p) ? p : 8080;
        // Cattura lo scheduler GPM della run che emette HTTP SERVER: il dispatch dei thread di
        // rete (accettati più tardi) usa questo scheduler esplicito, MAI il CurrentScheduler
        // riletto a dispatch-time (azzerato a fine run → fallback a invocazione diretta).
        _httpScheduler = IlGpmRuntime.CurrentScheduler;
        long handle;
        if (_pendingHttpSettings is { CertificatePath.Length: > 0 } pendingTls)
            handle = Current.Http.HttpServerStartTls(portNum, pendingTls.CertificatePath, pendingTls.CertificatePassword);
        else
            handle = Current.Http.HttpServerStart(portNum);
        _httpServerHandle = handle;
        _httpServerService = Current.Http;   // chi possiede l'handle (serve a HttpServerStop)
        if (_httpServerHandle >= 0)
        {
            if (_pendingHttpSettings is not null)
                Current.Http.HttpConfigure(_httpServerHandle, _pendingHttpSettings);
            foreach (var (prefix, directory) in _httpStatics)
                Current.Http.HttpAddStatic(_httpServerHandle, prefix, directory);
            foreach (var (method, path, handlerSymbolId) in _httpRoutes.Values)
                RegisterRouteWithHost(_httpServerHandle, method, path, handlerSymbolId);
            foreach (var (path, handlerSymbolId) in _httpMiddleware)
                RegisterMiddlewareWithHost(_httpServerHandle, path, handlerSymbolId);
            foreach (var (path, handlerSymbolId) in _httpWsRoutes)
                RegisterWsRouteWithHost(_httpServerHandle, path, handlerSymbolId);
        }
        return _httpServerHandle;
    }

    public static void HttpServerStop()
    {
        if (_httpServerHandle < 0) return;
        // Il servizio di AVVIO, non `Current.Http`: dopo un cambio di run (harness in-process)
        // Current.Http è un HttpService nuovo che non conosce l'handle → stop no-op e listener
        // lasciato vivo (vedi il commento su _httpServerService).
        (_httpServerService ?? Current.Http).HttpServerStop(_httpServerHandle);
        _httpServerHandle = -1;
        _httpServerService = null;
    }

    /// <summary>
    /// Reset dello stato HTTP **dichiarativo** del programma: ferma un server eventualmente
    /// ancora attivo e svuota route/middleware/WebSocket/static/scheduler. Sono tutte
    /// collezioni STATICHE di processo: in un harness che esegue più programmi nello stesso
    /// processo (MiniTest xUnit, sweep) senza questo reset il programma successivo
    /// ri-registrava le route del precedente al proprio `HTTP SERVER` (handler symbolId di
    /// un'assembly già chiusa) e poteva restare un listener vivo sulla porta → risposte
    /// sbagliate/TIMEOUT dipendenti dall'ordine (bug MiniTest-HTTP-Server-Stesso-Processo).
    /// Chiamato da <see cref="ResetProgramState"/> a inizio di OGNI programma; non tocca le
    /// route già registrate nel servizio (un server in esecuzione continua a servirle).
    /// </summary>
    public static void HttpDeclarationReset()
    {
        HttpServerStop();
        _httpRoutes.Clear();
        _httpMiddleware.Clear();
        _httpWsRoutes.Clear();
        _httpStatics.Clear();
        _httpScheduler = null;
        // `HTTP CONFIG` (porta/TLS/middleware): impostazioni statiche che HttpServerStart
        // applica al PRIMO server avviato. Senza reset, il programma successivo nello stesso
        // processo (harness MiniTest) avviava il proprio server con la CONFIG del precedente
        // (porta sbagliata/TLS) → richieste verso il proprio URL senza risposta.
        _pendingHttpSettings = null;
    }

    /// <summary>
    /// Prima registrava solo `method+path+callbackName` in <see cref="_httpRoutes"/>, MAI letto
    /// da nessun altro punto del codice: `IHttpService.HttpAddRoute` (il vero
    /// `HttpService`/`HttpListener`, <c>common/BRT/Services/HttpService.cs</c>) non veniva mai
    /// chiamato. `HTTP ROUTE` era quindi un no-op silenzioso su OGNI sample esistente
    /// (`PackageServer.bas`, `HttpFullServer.bas`, ecc.) — le route dichiarate da BASIC non
    /// ricevevano mai traffico reale, esattamente come `HTTP STATIC` prima del suo fix gemello.
    /// `handlerSymbolId` (risolto a COMPILE TIME in `IlProgramCompiler.EmitHttpRouteStatement`,
    /// stesso pattern già usato per `AI AGENT ASK ... INTO`/<see cref="GetStringProcedureDelegate"/>)
    /// permette di trovare via reflection il metodo statico `Proc_&lt;symbolId&gt;` generato per
    /// la SUB callback e invocarlo per ogni richiesta reale — vedi <see cref="RegisterRouteWithHost"/>.
    /// </summary>
    public static void HttpAddRoute(string method, string path, int handlerSymbolId)
    {
        _httpRoutes[method + ":" + path] = (method, path, handlerSymbolId);
        if (_httpServerHandle >= 0)
            RegisterRouteWithHost(_httpServerHandle, method, path, handlerSymbolId);
    }

    /// <summary>Risolve la SUB callback e la collega al server HTTP reale. Con 2 parametri
    /// (req AS HTTPREQUEST, res AS HTTPRESPONSE) è una route HTTP normale; con 3 parametri
    /// (req, res, ws AS WEBSOCKET) è una route WebSocket (upgrade) — vedi <see cref="RegisterWsRouteWithHost"/>.
    /// Il "req" passato alla SUB è un <c>Dictionary&lt;string,object?&gt;</c> case-
    /// insensitive con le stesse chiavi già usate da BSP (Method/Path/Body/Headers/Query, vedi
    /// <c>BspDispatch.ConvertRequest</c>) più "Params" (parametri estratti dal path template,
    /// es. <c>{name}</c> — vedi <c>HttpService.RouteEntry.TryMatch</c>); "res" è un
    /// <see cref="Basic.IlBackend.PCode.Http.PCodeHttpResponse"/> — le chiamate BASIC
    /// <c>res.Send(...)</c>/<c>res.SendJSON(...)</c>/ecc. dentro la SUB sono già compilate come
    /// dispatch dinamico via reflection (<see cref="CollectionInvoke"/>, case-insensitive), quindi
    /// funzionano su QUALUNQUE oggetto CLR reale che esponga quei metodi — nessun codice nuovo
    /// necessario lato callback, la stessa classe già provata per BSP.
    /// </summary>
    private static void RegisterRouteWithHost(long handle, string method, string path, int handlerSymbolId)
    {
        var procMethod = FindProcedureMethod(handlerSymbolId, [typeof(object), typeof(object)]);
        if (procMethod is null)
        {
            // Fallback: handler a 3 parametri (req, res, ws) → route WebSocket.
            var wsProcMethod = FindProcedureMethod(handlerSymbolId, [typeof(object), typeof(object), typeof(object)]);
            if (wsProcMethod is null)
            {
                Console.Error.WriteLine($"[HTTP ROUTE] callback (symbolId {handlerSymbolId}) non trovata — route '{method} {path}' ignorata.");
                return;
            }
            RegisterWsRouteWithHost(handle, path, handlerSymbolId);
            return;
        }
        Current.Http.HttpAddRoute(handle, method, path, req => InvokeHttpRouteHandler(handlerSymbolId, req));
    }

    /// <summary>Route WebSocket (HTTP ROUTE con handler a 3 parametri req/res/ws): la registra sul
    /// server reale come route di UPGRADE. All'arrivo di una richiesta `Upgrade: websocket` sul
    /// path, HttpService fa l'handshake 101 e invoca <see cref="RunWebSocketSessionAsync"/> con il
    /// WebSocket accettato; il handler BASIC (chiamato una volta) registra OnMessage/OnClose e/o
    /// invia il benvenuto, poi il loop di ricezione guida la sessione (come la PCodeVM).</summary>
    public static void HttpAddWebSocketRoute(string path, int handlerSymbolId)
    {
        _httpWsRoutes.Add((path, handlerSymbolId));
        if (_httpServerHandle >= 0)
            RegisterWsRouteWithHost(_httpServerHandle, path, handlerSymbolId);
    }

    private static void RegisterWsRouteWithHost(long handle, string path, int handlerSymbolId)
    {
        var procMethod = FindProcedureMethod(handlerSymbolId, [typeof(object), typeof(object), typeof(object)]);
        if (procMethod is null)
        {
            Console.Error.WriteLine($"[HTTP ROUTE] callback WebSocket (symbolId {handlerSymbolId}) non trovata — route '{path}' ignorata.");
            return;
        }
        Current.Http.HttpAddWebSocketRoute(handle, path, (req, ws) => RunWebSocketSessionAsync(req, ws, handlerSymbolId));
    }

    /// <summary>Guida la sessione WebSocket lato server: avvolge il WebSocket accettato in un
    /// <see cref="IlWebSocketHandle"/>, invoca il handler BASIC (req, res, ws) una volta — è lì
    /// che la SUB registra ws.OnMessage e/o invia il benvenuto — poi avvia il loop di ricezione
    /// (che dispatca i messaggi alla SUB OnMessage e la chiusura a OnClose). Gira su un task in
    /// background, così l'accept loop del server non si blocca.</summary>
    private static async Task RunWebSocketSessionAsync(HttpRequest req, System.Net.WebSockets.WebSocket ws, int handlerSymbolId)
    {
        var wsHandle = new IlWebSocketHandle { Socket = ws, IsServerSide = true };
        var reqDict = HttpRequestToDict(req);
        var res = new Basic.IlBackend.PCode.Http.PCodeHttpResponse();
        // Il handler (req, res, ws) registra OnMessage/OnClose e/o invia il benvenuto: dispatch
        // come TASK GPM (in-context), mai sul thread del HttpListener.
        DispatchGpmHandler(handlerSymbolId, [reqDict, res, wsHandle], requestTimeoutMs: 30000, _httpScheduler);
        wsHandle.Scheduler = _httpScheduler;
        wsHandle.StartReceiveLoop();
    }

    /// <summary>Invoca l'handler BASIC della route HTTP come TASK GPM (la SUB gira in-context su
    /// un worker, MAI sul thread del HttpListener/pool — la GPM è l'unico esecutore). Attende il
    /// completamento (polling del task, come la PCodeVM) con timeout, poi converte la response
    /// condivisa scritta dall'handler. Fallback deterministico (invocazione diretta) solo senza
    /// GPM attivo.</summary>
    private static HttpResponse InvokeHttpRouteHandler(int handlerSymbolId, HttpRequest req)
    {
        var reqDict = HttpRequestToDict(req);
        var res = new Basic.IlBackend.PCode.Http.PCodeHttpResponse();
        // Range della richiesta → res.SendFile può servire una fetta (206) anche sulla gamba IL.
        res.AttachRequestInfo(req.Headers.TryGetValue("Range", out var reqRange) ? reqRange : null);
        var task = DispatchGpmHandler(handlerSymbolId, [reqDict, res], requestTimeoutMs: 30000, _httpScheduler, res);
        if (task?.PendingException is { } ex)
            return new HttpResponse { StatusCode = 500, ContentType = "text/plain", Body = $"500 Handler Error: {ex.Message}" };
        return PCodeResponseToHttpResponse(res);
    }

    /// <summary>Dispatch di un handler BASIC (HTTP/WS/middleware) come TASK GPM: SpawnGoSub su
    /// lo scheduler passato esplicitamente (<c>scheduler</c>, catturato a HTTP SERVER — contesto
    /// esplicito, §0ter punto 4) o, in mancanza, su IlGpmRuntime.CurrentScheduler; attesa del
    /// completamento (polling del task, parità PCodeVM). La SUB gira su un worker in-context; il
    /// thread di rete NON la esegue mai. Fallback deterministico (invocazione diretta) solo
    /// quando nessun GPM è attivo. Ritorna il task (per ispezionare PendingException) o null se
    /// il dispatch è fallito.</summary>
    private static PCodeTask? DispatchGpmHandler(int symbolId, object?[] args, int requestTimeoutMs, Basic.Runtime.Gpm.PCodeScheduler? scheduler = null, Basic.IlBackend.PCode.Http.PCodeHttpResponse? streamingWatch = null)
    {
        var activeScheduler = scheduler ?? IlGpmRuntime.CurrentScheduler;
        if (activeScheduler != null)
        {
            var task = IlGpmRuntime.SpawnGoSub(activeScheduler, symbolId, args, null);
            var deadline = Environment.TickCount64 + Math.Max(1000, requestTimeoutMs);
            while (task.State != PCodeTaskState.Finished && task.PendingException == null
                   && Environment.TickCount64 < deadline)
            {
                /* Streaming in corso: la durata della risposta è quella dello stream (SSE/minuti),
                 * non il timeout della richiesta — si sposta la scadenza avanti. */
                if (streamingWatch is { Streaming: true })
                    deadline = Environment.TickCount64 + 24 * 60 * 60 * 1000;
                System.Threading.Thread.Sleep(5);
            }
            return task;
        }
        var method = FindProcedureMethod(symbolId, null);
        var scope = IlRuntime.ProgramGlobalScope;
        if (scope != null) IlRuntime.BeginGlobalScope(scope);
        try { method?.Invoke(null, args); }
        catch (System.Reflection.TargetInvocationException tie) { var ex = tie.InnerException ?? tie; System.Console.Error.WriteLine($"[HTTP handler] {ex.Message}"); }
        finally { if (scope != null) IlRuntime.EndGlobalScope(); }
        return null;
    }

    private static HttpResponse PCodeResponseToHttpResponse(Basic.IlBackend.PCode.Http.PCodeHttpResponse res)
    {
        if (!res.Sent)
            return new HttpResponse { StatusCode = 204, ContentType = "text/plain", Body = "" };
        var headers = new Dictionary<string, string>(res.Headers, StringComparer.OrdinalIgnoreCase);
        if (res.RawSetCookieHeaders.Count > 0)
            headers["Set-Cookie"] = res.RawSetCookieHeaders[^1];
        return new HttpResponse
        {
            StatusCode = res.StatusCode,
            ContentType = headers.TryGetValue("Content-Type", out var ct) ? ct : "text/html",
            // I byte GREZI viaggiano in BodyBytes: convertire il corpo in stringa UTF-8 distrugge
            // ogni risposta binaria (res.SendFile: uno ZIP di 477 byte arrivava al client come 493
            // byte pieni di U+FFFD, e il PackageManager falliva con "Bad magic number for central
            // directory"). `Body` resta la vista testuale per chi legge la risposta come stringa.
            BodyBytes = res.Body,
            Body = System.Text.Encoding.UTF8.GetString(res.Body),
            Headers = headers,
        };
    }

    /// <summary>
    /// Prima non chiamava MAI <see cref="IHttpService.HttpAddStatic"/> — si limitava a salvare
    /// `urlPath`/`physicalPath` in campi statici mai letti da nessun altro punto del codice. `HTTP STATIC`
    /// era quindi un no-op silenzioso: nessuna directory veniva mai registrata in
    /// <c>HttpService._staticDirs</c>, quindi nessuna richiesta HTTP reale poteva mai raggiungere
    /// un file statico né, di conseguenza, una pagina <c>.bsp</c> (il dispatcher BSP dipende
    /// interamente dal branch "file statico" di <c>HttpService.Dispatch</c> per essere invocato —
    /// vedi <c>HttpService.cs</c> riga ~193). Scoperto verificando dal vivo con un server reale
    /// + curl se le pagine BSP fossero davvero servibili end-to-end (non solo compilabili).
    /// </summary>
    public static void HttpAddStatic(string urlPath, string physicalPath)
    {
        // Più mount STATIC nello stesso programma sono legittimi e necessari (tipico: le pagine
        // BSP su "/" e gli asset su "/static"). Prima si teneva UN SOLO (prefisso, cartella):
        // il secondo `HTTP STATIC` sovrascriveva il primo in silenzio, quindi il servizio
        // esponeva le pagine e non gli asset (o viceversa) — la dashboard si apriva senza JS.
        _httpStatics.Add((urlPath, physicalPath));
        // Se il server è già avviato (STATIC dopo SERVER, meno comune ma valido) applica subito;
        // altrimenti HttpServerStart li applica tutti non appena ottiene un handle valido.
        if (_httpServerHandle >= 0)
            Current.Http.HttpAddStatic(_httpServerHandle, urlPath, physicalPath);
    }

    /// <summary>
    /// Prima registrava solo `path+callbackName` in <see cref="_httpMiddleware"/>, mai letto da
    /// nessun altro punto del codice — stesso identico gap già risolto per `HTTP ROUTE`
    /// (`RegisterRouteWithHost`). `handlerSymbolId` risolto a COMPILE TIME
    /// (`IlProgramCompiler.EmitHttpUseStatement`), stesso pattern.
    /// </summary>
    public static void HttpAddMiddleware(string? path, int handlerSymbolId)
    {
        _httpMiddleware.Add((path, handlerSymbolId));
        if (_httpServerHandle >= 0)
            RegisterMiddlewareWithHost(_httpServerHandle, path, handlerSymbolId);
    }

    private static HttpServerSettings? _pendingHttpSettings;

    /// <summary>
    /// HTTP CONFIG configObject — applica le impostazioni di servizio (timeout per richiesta,
    /// dimensione massima del body, rate-limit, keep-alive). Prima era un no-op: leggeva nulla e
    /// non faceva nulla, mentre la PCodeVM applicava davvero la configurazione (Port/certificato/
    /// timeout/rate-limit) al suo PCodeHttpServer. L'oggetto config in IL è un
    /// Dictionary&lt;string,object?&gt; (NEW HTTPCONFIG → dict, campi via JsonFieldSet), stesso
    /// contenuto del dict P-CODE (OP_NEW typeCode). LIMITE documentato: la porta è decisa da
    /// HTTP SERVER (argomento esplicito, non dal config) e il TLS (CertificatePath/Password) non
    /// è supportato da HttpListener — quel percorso resta la PCodeVM/PCodeHttpServer.
    /// </summary>
    public static void HttpConfig(object? config)
    {
        var settings = new HttpServerSettings();
        if (config is System.Collections.IDictionary cd)
        {
            int GetInt(params string[] keys)
            {
                foreach (var k in keys)
                    if (cd.Contains(k) && cd[k] is not null)
                        return Convert.ToInt32(cd[k], System.Globalization.CultureInfo.InvariantCulture);
                return 0;
            }
            bool GetBool(string key, bool def) => cd.Contains(key) && cd[key] is bool b ? b : def;

            var timeoutMs = GetInt("RequestTimeoutMs", "DefaultRequestTimeout");
            if (timeoutMs > 0) settings.RequestTimeoutMs = timeoutMs;
            var maxBody = GetInt("MaxRequestBodySize");
            if (maxBody > 0) settings.MaxRequestBodySize = maxBody;
            settings.EnableKeepAlive = GetBool("EnableKeepAlive", true);
            var rlPerMin = GetInt("RateLimitRequestsPerMinute");
            if (rlPerMin > 0) settings.RateLimitRequestsPerMinute = rlPerMin;
            var rlBurst = GetInt("RateLimitBurstSize");
            if (rlBurst > 0) settings.RateLimitBurstSize = rlBurst;
            settings.SecurityHeaders = GetBool("SecurityHeaders", false);
            settings.AllowedIPs = GetString(cd, "AllowedIPs");
            settings.BlockedIPs = GetString(cd, "BlockedIPs");
            settings.CertificatePath = GetString(cd, "CertificatePath");
            settings.CertificatePassword = GetString(cd, "CertificatePassword");
            settings.Sessions = GetBool("Sessions", false);
            settings.SessionFile = GetString(cd, "SessionFile");
            // Memoizzazione della resa BSP (0 = disattivata): stessa chiave del backend P-Code
            // (HTTPCONFIG), così una app può configurarla senza cambiare codice.
            var bspTtl = GetInt("BspCacheMs");
            if (bspTtl > 0) settings.BspCacheMs = bspTtl;
            CommonLib.Http.BspRuntime.RenderCacheTtlMs = bspTtl;
            CommonLib.Http.BspRuntime.EnginePreference =
                string.Equals(GetString(cd, "BspEngine"), "c", StringComparison.OrdinalIgnoreCase)
                    ? CommonLib.Http.BspEngine.C : CommonLib.Http.BspEngine.Managed;
            CommonLib.Http.BspRuntime.SetEngineCPages(GetString(cd, "BspEnginePages"));
            CommonLib.Http.BspRuntime.ConcurrentPages = GetString(cd, "BspConcurrentPages") ?? "";
            CommonLib.Http.BspC.SetConcurrentPages(CommonLib.Http.BspRuntime.ConcurrentPages);
        }
        _pendingHttpSettings = settings;
        if (_httpServerHandle >= 0)
            Current.Http.HttpConfigure(_httpServerHandle, settings);
    }

    private static string GetString(System.Collections.IDictionary cd, string key)
        => cd.Contains(key) && cd[key] is not null ? Convert.ToString(cd[key], System.Globalization.CultureInfo.InvariantCulture) ?? "" : "";

    /// <summary>
    /// Prima era un no-op incondizionato ("nel modello IL, next() è gestito dal chain runtime
    /// P-Code" — falso per l'esecuzione IL reale, quel chain runtime esiste solo per i programmi
    /// eseguiti interamente via PCodeVm, vedi PCodeHttpRouter/PCodeHttpServer in
    /// common/IlBackend/PCode/Http/, un mondo diverso da questo). Qui il server HTTP reale
    /// (HttpService/HttpListener) processa le richieste in sequenza su un solo thread
    /// (ServerLoop), quindi un semplice flag statico basta a segnalare "il middleware ha chiamato
    /// NEXT, continua la catena" a <see cref="InvokeHttpMiddlewareHandler"/>/`HttpService.Dispatch`
    /// senza bisogno di un vero oggetto "next" continuabile. NON `[ThreadStatic]`: un campo
    /// thread-local su un assembly generato con `PersistedAssemblyBuilder` (il publish nativo,
    /// vedi IlProgramCompiler.Compile) causa un SIGSEGV nativo nel JIT stesso al primo accesso
    /// (`GetThreadLocalStaticBase`/`GetThreadStaticsByMethodTable` nello stack di crash — trovato
    /// dal vivo compilando ed eseguendo un test HTTP USE reale) — non necessario comunque, dato
    /// che ServerLoop è a singolo thread sequenziale, non serve isolamento per-thread.
    /// </summary>
    private static bool _httpUseNextCalled;
    public static void HttpUseNext() => _httpUseNextCalled = true;

    private static void RegisterMiddlewareWithHost(long handle, string? pathPrefix, int handlerSymbolId)
    {
        var procMethod = FindProcedureMethod(handlerSymbolId, [typeof(object), typeof(object), typeof(object)])
            ?? FindProcedureMethod(handlerSymbolId, [typeof(object), typeof(object)]);
        if (procMethod is null)
        {
            Console.Error.WriteLine($"[HTTP USE] callback (symbolId {handlerSymbolId}) non trovata — middleware ignorato.");
            return;
        }
        var takesNext = procMethod.GetParameters().Length == 3;
        Current.Http.HttpAddMiddleware(handle, pathPrefix ?? "*", req => InvokeHttpMiddlewareHandler(handlerSymbolId, takesNext, req));
    }

    /// <summary>
    /// (true, null) se il middleware ha chiamato `HTTP USE NEXT` (la catena continua), altrimenti
    /// (false, risposta) — ha risposto direttamente (short-circuit, es. un middleware di
    /// autenticazione che nega l'accesso senza mai chiamare NEXT). Ogni middleware riceve un
    /// `PCodeHttpResponse` FRESCO e isolato (non condiviso con gli altri passi della catena):
    /// limitazione nota accettata per una feature senza alcun sample esistente da verificare —
    /// se un middleware "continua" senza mai chiamare `res.Send`, l'oggetto è comunque vuoto e
    /// scartato senza perdita; se chiamasse `res.SetHeader(...)` e POI `HTTP USE NEXT` (imposta
    /// un header ma lascia decidere al passo successivo), quell'header andrebbe perso — nessun
    /// sample lo esercita, documentato qui per una futura estensione (stato condiviso via un
    /// singolo PCodeHttpResponse passato lungo l'intera catena, non solo al singolo middleware).
    /// </summary>
    private static (bool Continue, HttpResponse? Response) InvokeHttpMiddlewareHandler(
        int handlerSymbolId, bool takesNext, HttpRequest req)
    {
        var reqDict = HttpRequestToDict(req);
        var res = new Basic.IlBackend.PCode.Http.PCodeHttpResponse();
        _httpUseNextCalled = false;
        var task = DispatchGpmHandler(handlerSymbolId, takesNext ? [reqDict, res, new object()] : [reqDict, res], requestTimeoutMs: 30000, _httpScheduler);
        if (task?.PendingException is { } ex)
        {
            res.CompleteAsServerError($"500 Middleware Error: {ex.Message}");
            return (false, PCodeResponseToHttpResponse(res));
        }
        return _httpUseNextCalled ? (true, null) : (false, PCodeResponseToHttpResponse(res));
    }

    private static Dictionary<string, object?> HttpRequestToDict(HttpRequest req)
    {
        // Content-Type: i headers di HttpListener arrivano con la grafia del client → lookup
        // case-insensitive esplicito (req.Headers è un Dictionary<string,string> plain).
        string? contentType = null;
        foreach (var kv in req.Headers)
            if (string.Equals(kv.Key, "Content-Type", StringComparison.OrdinalIgnoreCase)) { contentType = kv.Value; break; }
        var headersDict = req.Headers.ToDictionary(kv => kv.Key, kv => (object?)kv.Value, StringComparer.OrdinalIgnoreCase);
        // Istanza reale CommonLib.Http.HttpRequest: permette i metodi BASIC della HTTPREQUEST
        // (req.ParseForm()/req.ParseMultipartForm()) — UNICA logica shared col PCode (che semina
        // la stessa chiave in BuildRequestDict; dispatch in PCodeHttpRequestDictInvoke, §0bis).
        // Il corpo binario arriva al BRT già come stringa: i byte multipart testuali round-trippano
        // via UTF-8; il parser condiviso legge "Content-Type" con la grafia esatta dell'header.
        var clHeaders = new System.Text.Json.Nodes.JsonObject();
        foreach (var kv in req.Headers) clHeaders[kv.Key] = kv.Value;
        if (contentType is not null && !clHeaders.ContainsKey("Content-Type"))
            clHeaders["Content-Type"] = contentType;
        var clQuery = new System.Text.Json.Nodes.JsonObject();
        foreach (var kv in req.Query) clQuery[kv.Key] = kv.Value;
        var clParams = new System.Text.Json.Nodes.JsonObject();
        foreach (var kv in req.Params) clParams[kv.Key] = kv.Value;
        var clHttpRequest = new CommonLib.Http.HttpRequest
        {
            Method = req.Method,
            Path = req.Path,
            Body = req.Body ?? "",
            BodyBytes = System.Text.Encoding.UTF8.GetBytes(req.Body ?? ""),
            Headers = clHeaders,
            Query = clQuery,
            Params = clParams,
            RemoteIpAddress = req.RemoteIpAddress,
        };
        return new(StringComparer.OrdinalIgnoreCase)
        {
            ["Method"] = req.Method,
            ["Path"] = req.Path,
            ["Body"] = req.Body,
            ["Headers"] = headersDict,
            ["Query"] = req.Query.ToDictionary(kv => kv.Key, kv => (object?)kv.Value),
            // Parità PCode (BuildRequestDict): senza questa chiave `req.QueryString` rendeva ""
            // sull'IL e un handler che ricostruisce un URL perdeva i parametri (bug reale sul
            // proxy /api/* della webapp: /api/memory?key=k arrivava senza query).
            ["QueryString"] = req.QueryString,
            ["Params"] = req.Params.ToDictionary(kv => kv.Key, kv => (object?)kv.Value),
            // req.RemoteIp (TokenKind RemoteIp, NON Ip): il dict request NON aveva la chiave →
            // il membro rendeva null su IL (divergenza HttpSession vs PCode, che la popola).
            // Stessa chiave "IP" mantenuta per req.Ip (compat).
            ["RemoteIp"] = req.RemoteIpAddress ?? "",
            ["IP"] = req.RemoteIpAddress ?? "",
            ["__httpRequest"] = clHttpRequest,
            // BodyJson canonico: UNICA logica shared con PCode (PCodeProcessor.ComputeBodyJson).
            ["BodyJson"] = Basic.IlBackend.PCode.PCodeProcessor.ComputeBodyJson(contentType, req.Body),
            // Sessione da cookie GM_BASIC_SESSION: UNICA logica shared con PCode
            // (PCodeProcessor.ParseSessionIdCookie) — senza la chiave req.SessionId era sempre
            // vuoto e ogni richiesta crearava una sessione nuova (divergenza IL, HttpFetchAdvanced).
            ["SessionId"] = Basic.IlBackend.PCode.PCodeProcessor.ParseSessionIdCookie(headersDict) ?? "",
            // Sessioni route HTTP (HTTP CONFIG .Sessions): REQ("Session") = JsonObject VIVO
            ["Session"] = req.SessionData!,
        };
    }

    // ── SQL ────────────────────────────────────────────────────────────
    private static readonly System.Collections.Concurrent.ConcurrentDictionary<long, Basic.Databases.Rdd.SqlDriver> IlSqlDrivers = new();
    private static long _nextIlSqlHandle;
    public static long SqlOpen(string path) => SqlOpen(path, null);
    public static long SqlOpen(string path, string? alias)
    {
        var handle = Current.Database.SqlOpen(path);
        if (!string.IsNullOrWhiteSpace(alias))
        {
            try
            {
                var session = Current.SqlDataSession;
                // Il path può essere un percorso FILE (es. "Work/app.db") o già una
                // connection string completa ("Data Source=...", "Host=localhost;...",
                // ":memory:"). Con "=" dentro è già una connection string → non toccare;
                // altrimenti è un percorso file → wrappa in "Data Source=".
                var connectionString = path.Equals(":memory:", StringComparison.OrdinalIgnoreCase)
                    ? "Data Source=:memory:"
                    : path.Contains('=')
                        ? path
                        : $"Data Source={path}";
                var driver = new Basic.Databases.Rdd.SqlDriver();
                driver.Open(new Basic.Databases.Rdd.DbOpenInfo
                {
                    FileName = connectionString,
                    // L'alias NON è il nome tabella: SQL OPEN "db" ALIAS AppDb deve aprire il
                    // database; la tabella/query arriva da EXEC/QUERY. Con Alias = alias,
                    // SqlDriver.LoadTableData faceva "SELECT * FROM AppDb" → "no such table".
                    Alias = "",
                    Driver = "SQLite"
                });
                // SQL OPEN con alias: registra il driver in un'area ALTA (>= 200) così NON
                // ruba le work area basse a RDD USE — i sample assumono area 1 = prima USE
                // (es. RDD_SQL_Demo: GETFIELD(1, ...) dopo SQL OPEN "..." ALIAS h).
                var sqlArea = 200;
                while (sqlArea < Basic.Databases.Rdd.DataSession.MaxWorkareas
                       && session.GetWorkArea(sqlArea)?.IsEmpty == false) sqlArea++;
                session.RegisterDirect(sqlArea, driver, alias);
                if (handle < 0) handle = System.Threading.Interlocked.Increment(ref _nextIlSqlHandle);
                IlSqlDrivers[handle] = driver;
            }
            catch { }
        }
        return handle;
    }
    public static void SqlBackup(object? dbOrAlias, string destination)
    {
        var driver = ResolveSqlDriver(dbOrAlias)
            ?? throw new InvalidOperationException("SQL database is not open.");
        // NON catturare: se il provider non supporta il backup (SqlDriver.Backup lancia
        // NotSupportedException) l'errore deve propagarsi al programma BASIC.
        driver.Backup(destination);
    }
    public static void SqlClose(object? dbOrAlias)
    {
        var driver = ResolveSqlDriver(dbOrAlias);
        if (driver is not null) try { driver.Close(); } catch { }
    }
    // Parità VM (SysCall.SQL_CLOSE usa ResolveSqlDriver(alias)): un riferimento DB negli
    // statement SQL può essere l'HANDLE numerico (variabile DIM AS LONG, es. `SQL CLOSE D`)
    // o l'ALIAS stringa (`SQL CLOSE "govdb"`). Il backend risolve entrambi.
    private static Basic.Databases.Rdd.SqlDriver? ResolveSqlDriver(object? dbOrAlias)
    {
        if (dbOrAlias is null) return null;
        if (dbOrAlias is string alias) { try { return Current.SqlDataSession.FindAlias(alias) as Basic.Databases.Rdd.SqlDriver; } catch { return null; } }
        long handle;
        try { handle = Convert.ToInt64(dbOrAlias, System.Globalization.CultureInfo.InvariantCulture); }
        catch { return null; }
        return IlSqlDrivers.TryGetValue(handle, out var driver) ? driver : null;
    }
    // Parità VM (SysCall.SQL_ATTACH): ATTACH/DETACH vanno sul driver SqlDriver via
    // il metodo dedicato (ATTACH DATABASE @path AS "schema" con parametro), NON come
    // query SQL concatata malformata. Il driver è risolto da handle numerico o alias.
    public static void SqlAttach(object? dbOrAlias, string path, string schema)
    { var driver = ResolveSqlDriver(dbOrAlias); if (driver is not null) try { driver.Attach(path, schema); } catch { } }
    public static void SqlDetach(object? dbOrAlias, string schema)
    { var driver = ResolveSqlDriver(dbOrAlias); if (driver is not null) try { driver.Detach(schema); } catch { } }
    public static void SqlExec(long h, string sql) => Current.Database.SqlExecute(h, sql);
    public static object?[][] SqlQuery(long h, string sql) => Current.Database.SqlQuery(h, sql);
    public static void SqlBegin(long h) => Current.Database.SqlBeginTransaction(h);
    public static void SqlCommit(long h) => Current.Database.SqlCommit(h);
    public static void SqlRollback(long h) => Current.Database.SqlRollback(h);
    // Transazioni sul SqlDriver (alias/handle) — STESSA connessione di EXEC/QUERY.
    // Il path precedente (Current.Database.Sql*Transaction sul handle base) apriva una
    // SECONDA connessione (SQLite) indipendente dal driver Npgsql → ROLLBACK/COMMIT
    // non toccavano i dati del driver.
    public static void SqlTransactionBegin(object? dbOrAlias) => SqlTransactionOp(dbOrAlias, d => d.BeginTransaction());
    public static void SqlTransactionCommit(object? dbOrAlias) => SqlTransactionOp(dbOrAlias, d => d.Commit());
    public static void SqlTransactionRollback(object? dbOrAlias) => SqlTransactionOp(dbOrAlias, d => d.Rollback());
    public static void SqlSavepoint(object? dbOrAlias, string name) => SqlTransactionOp(dbOrAlias, d => d.Savepoint(name));
    public static void SqlReleaseSavepoint(object? dbOrAlias, string name) => SqlTransactionOp(dbOrAlias, d => d.ReleaseSavepoint(name));
    public static void SqlRollbackToSavepoint(object? dbOrAlias, string name) => SqlTransactionOp(dbOrAlias, d => d.RollbackToSavepoint(name));
    private static void SqlTransactionOp(object? dbOrAlias, Action<Basic.Databases.Rdd.SqlDriver> op)
    {
        var driver = ResolveSqlDriver(dbOrAlias);
        if (driver is not null) try { op(driver); } catch { }
    }

    // ======================================================================================
    // DBF (RDD) — delega a IDatabaseService con modello area/alias (porting da
    // GMBasic/GMBasicAI IlBackend). Il backend IL non referenzia il motore RDD: ogni
    // operazione passa dall'handle dell'area corrente (come la PCodeVM con le aree xBase).
    // ======================================================================================
    private static readonly System.Collections.Generic.Dictionary<string, long> _dbfHandles =
        new(System.StringComparer.OrdinalIgnoreCase);
    private static string _dbfCurrentAlias = "dbf";
    private static string _dbfDefaultPath = "";
    // SET PATH per i motori DB (Clipper-style): lista dei percorsi di ricerca dei database.
    // Default = cartella del programma entry-point (SetEntrySourcePath). APPPATH() la espone
    // separata da ';'; i comandi DBF/ISAM/SPEED/LEDGER OPEN/USE risolvono contro questa lista.
    private static readonly List<string> _searchPaths = new();
    private static string _entrySourcePath = "";
    private static string _currentSourceFile = "";

    private static string CurrentProgramFolder
    {
        get
        {
            if (!string.IsNullOrEmpty(_entrySourcePath))
            {
                try
                {
                    var dir = Path.GetDirectoryName(Path.GetFullPath(_entrySourcePath));
                    if (!string.IsNullOrEmpty(dir)) return dir;
                }
                catch { }
            }
            return Directory.GetCurrentDirectory();
        }
    }

    public static string GetEntrySourceDir() => CurrentProgramFolder;

    /// <summary>Imposta il file entry-point e il default di SET PATH (= la sua cartella).</summary>
    public static void SetEntrySourcePath(string path)
    {
        _entrySourcePath = path ?? "";
        _searchPaths.Clear();
        try { var dir = Path.GetDirectoryName(Path.GetFullPath(_entrySourcePath)); if (!string.IsNullOrEmpty(dir)) _searchPaths.Add(dir); } catch { }
        _currentSourceFile = _entrySourcePath;
        try { CommonLib.EntrySource.Set(path); } catch { }
    }

    /// <summary>SET PATH TO: imposta la lista di ricerca aggiuntiva (separatori ';' o ','). Path relativi
    /// risolti contro la cartella del programma. null → default (cartella entry); "" → lista vuota
    /// (cerca solo nella DEFAULT, parità CA-Clipper).</summary>
    public static void SetSearchPaths(string? joined)
    {
        _searchPaths.Clear();
        // SET PATH TO / SET PATH "" / SET PATH (senza arg) → SVUOTA la lista (parità
        // CA-Clipper: si cerca solo nella DEFAULT). Il default (cartella entry) vale solo
        // se SET PATH non è MAI stato eseguito (impostato da SetEntrySourcePath).
        if (joined is null || string.IsNullOrWhiteSpace(joined)) return;
        foreach (var raw in joined.Split(';', ',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
        {
            var abs = raw;
            try { abs = Path.IsPathRooted(raw) ? raw : Path.GetFullPath(Path.Combine(CurrentProgramFolder, raw)); } catch { }
            if (!_searchPaths.Any(p => string.Equals(p, abs, StringComparison.OrdinalIgnoreCase)))
                _searchPaths.Add(abs);
        }
    }

    /// <summary>Traccia il file .bas correntemente in esecuzione (PROJECTFOLDER import-aware).</summary>
    public static void SetCurrentSourceFile(string path) { _currentSourceFile = path ?? ""; }

    /// <summary>Risolve un path di database (parità CA-Clipper): assoluto → DEFAULT dir (SET DEFAULT,
    /// default = cartella entry) → lista SET PATH. Fallback alla DEFAULT per la creazione.</summary>
    public static string ResolveDbPath(string path)
    {
        if (string.IsNullOrWhiteSpace(path) || Path.IsPathRooted(path)) return path;
        // `mem://nome` / `MEM:nome` = tabella ISAM IN MEMORIA: NON e' un percorso di file (PCode controlla IsMemPath prima di risolvere). Prima IL
        // lo combinava con la cartella del programma e creava un file REALE `mem:/nome` (+ .wal) accanto al .bas: la 2a esecuzione di
        // ISAM_InMem_Test falliva con "Violazione di unicita'" (dati persistiti).
        if (Basic.ISAM.IsamMemPath.IsMemPath(path)) return path;
        var primary = string.IsNullOrEmpty(_dbfDefaultPath) ? CurrentProgramFolder : _dbfDefaultPath;
        var full = Path.Combine(primary, path);
        if (File.Exists(full) || Directory.Exists(full)) return full;
        foreach (var sp in _searchPaths)
        {
            var candidate = Path.Combine(sp, path);
            if (File.Exists(candidate) || Directory.Exists(candidate)) return candidate;
        }
        return full;
    }

    /// <summary>Gli alias possono arrivare QUOTATI (`ALIAS "Nome"` → token con le virgolette):
    /// normalizza (spazi e apici esterni) così USE/SELECT/CLOSE usano la stessa chiave.</summary>
    private static string? UnquoteAlias(string? a)
        => a is null ? null : a.Trim().Trim('"', '\'').Trim();

    private static long DbfHandleFor(string? alias)
    {
        var a = UnquoteAlias(alias) ?? _dbfCurrentAlias;
        return _dbfHandles.TryGetValue(a, out var h) ? h : -1;
    }

    public static long DbfUse(string path, object?[] indexPaths, int locking, bool unsafeFlag,
        string? alias, object? typeId, string? typeName)
    {
        alias = UnquoteAlias(alias);
        path = ResolveDbPath(path);
        var handle = Current.Database.DbfUse(path, indexPaths, locking, unsafeFlag, alias, typeId, typeName);
        var key = alias ?? "dbf";
        _dbfHandles[key] = handle;
        _dbfCurrentAlias = key;
        return handle;
    }

    /// <summary>RDD USE &lt;path&gt; [VIA &lt;driver&gt;] [ALIAS &lt;a&gt;]: per il driver SQL apre via
    /// SqlDataSession (come SqlOpen) e registra l'area RDD; per gli altri driver delega a DbfUse
    /// (comportamento storico). Evita che `RDD USE ... VIA "SQL"` finisse nel layer DBF (area non
    /// lockabile, GETFIELD vuoto, FLOCK 0 — gap IL RDD USE→DbfUse; RDD_SQL_CRUD/Demo).</summary>
    public static long RddUse(string path, object?[] indexPaths, int locking, bool unsafeFlag,
        string? alias, object? typeId, string? typeName)
    {
        if (!string.IsNullOrEmpty(typeName) && typeName.Equals("SQL", StringComparison.OrdinalIgnoreCase))
        {
            try
            {
                var session = Current.SqlDataSession;
                var connectionString = path.Contains('=') ? path : $"Data Source={path}";
                var d = new Basic.Databases.Rdd.SqlDriver();
                d.Open(new Basic.Databases.Rdd.DbOpenInfo { FileName = connectionString, Alias = alias ?? "", Driver = "SQL" });
                var area = session.AllocateArea();
                session.RegisterDirect(area, d, alias ?? "");
                return area;
            }
            catch { }
        }
        return DbfUse(path, indexPaths, locking, unsafeFlag, alias, typeId, typeName);
    }
    public static void DbfSelectWorkArea(object? workArea)
    {
        // DBF SELECT alias (stringa) → l'area corrente è l'alias; SELECT n → area numerica.
        if (workArea is string alias)
        {
            alias = UnquoteAlias(alias)!;
            if (_dbfHandles.TryGetValue(alias, out var aliasHandle))
            {
                _dbfCurrentAlias = alias;
                // Aggiorna anche session.CurrentArea (DataSession) — senza, RLOCK()/FLOCK()
                // generici (RddRLock/RddFLock, che leggono session.CurrentArea, non
                // _dbfCurrentAlias) restavano ancorati all'ultima area aperta invece di
                // seguire la SELECT (stesso bug/causa risolto per ISAM in IsamSelect).
                try { Current.Database.DbfSelectHandle(aliasHandle); } catch { }
            }
            return;
        }
        var area = (long)System.Convert.ToDouble(workArea, System.Globalization.CultureInfo.InvariantCulture);
        Current.Database.DbfSelectWorkArea(area);
        _dbfCurrentAlias = area.ToString(System.Globalization.CultureInfo.InvariantCulture);
    }
    public static void DbfClose(string? alias = null)
    {
        var raw = UnquoteAlias(alias);
        string key;
        long h;
        // DBF CLOSE <area>: un numero è il numero d'area 1-based, non un alias (parità
        // C99/VM-C/PCode). Prima `DBF CLOSE 2` non trovava l'alias "2" e non chiudeva nulla.
        if (raw != null && int.TryParse(raw, out var areaNum) && areaNum > 0)
        {
            var areaAlias = Current.SqlDataSession.GetWorkArea(areaNum)?.Alias;
            key = string.IsNullOrEmpty(areaAlias) ? raw : areaAlias!;
            if (areaAlias == null || !_dbfHandles.TryGetValue(key, out h)) h = -1;
            if (h < 0) return;
        }
        else
        {
            key = raw ?? _dbfCurrentAlias;
            h = DbfHandleFor(alias);
        }
        if (h >= 0) { try { Current.Database.DbfClose(h); } catch { } }
        _dbfHandles.Remove(key);
        // Chiusa l'area CORRENTE: _dbfCurrentAlias resterebbe sull'alias chiuso e
        // DbfHandleFor(null) darebbe -1 (i comandi area-correnti successivi falliscono).
        // DataSession.Unregister ha già revertito l'area corrente a un'altra aperta → allinea
        // l'alias (primo ancora registrato, o "dbf").
        if (_dbfCurrentAlias == key)
        {
            _dbfCurrentAlias = "dbf";
            foreach (var k in _dbfHandles.Keys) { _dbfCurrentAlias = k; break; }
        }
    }
    public static void DbfCloseAll()
    {
        Current.Database.DbfCloseAll();
        // Le aree sono chiuse: gli alias in _dbfHandles puntano a handle morti. Rimasti, un alias
        // riusato (es. `C` in ISAM OPEN … ALIAS C) veniva risolto PRIMA come DBF (DbfBof/DbfEof/
        // DbfFound provano _dbfHandles prima di _isamHandles) → ISAM.EOF(C)/FOUND(C) sbagliati.
        _dbfHandles.Clear();
        _dbfCurrentAlias = "dbf";
    }
    public static double DbfBof(string? alias = null)
    {
        var h = DbfHandleFor(alias);
        if (h >= 0) return Current.Database.DbfBof(h) ? -1.0 : 0.0;
        // ISAM.BOF(x) è mappato su DbfBof: fallback alle aree ISAM (come DbfFound).
        var ih = IsamHandleFor(alias);
        return ih >= 0 && Current.Database.IsamBof(ih) ? -1.0 : 0.0;
    }
    public static double DbfEof(string? alias = null)
    {
        var h = DbfHandleFor(alias);
        if (h >= 0) return Current.Database.DbfEof(h) ? -1.0 : 0.0;
        // ISAM.EOF(x) è mappato su DbfEof: fallback alle aree ISAM (come DbfFound).
        var ih = IsamHandleFor(alias);
        return ih >= 0 && Current.Database.IsamEof(ih) ? -1.0 : 0.0;
    }
    // Numerici DBF: convenzione BASIC = double (mai long/bool — il box Int64/Int32 su un
    // double è IL invalido).
    public static double DbfRecno(string? alias = null)
    {
        var h = DbfHandleFor(alias);
        // PCode: DBF CREATE registra l'handle ma DBF CLOSE non lo rimuove da _dbfHandles, quindi
        // un handle STALE puo' restituire 0 mentre l'area RDD corrente e' posizionata (RECNO()=1).
        if (h >= 0)
        {
            var v = Current.Database.DbfRecno(h);
            if (v > 0) return v;
        }
        // RECNO su area ISAM (mappato su DbfRecno): fallback al driver via sessione.
        try
        {
            var session = Current.SqlDataSession;
            var wa = string.IsNullOrWhiteSpace(alias)
                ? session.GetWorkArea(session.CurrentArea)
                : session.GetWorkArea(FindAreaByAlias(session, alias));
            if (wa?.Driver is Basic.Databases.Rdd.IsamDriver isam) return isam.CurrentKeyNo();
            // RDD USE (PCode) su .dbf → DbfDriver: CurrentKeyNo() e' l'index order (0), il recno
            // e' GetCurrentRecordNumber() dell'engine (DbfDriver.cs:298/344).
            if (wa?.Driver is Basic.Databases.Rdd.DbfDriver dbfDrv)
                return (double)(dbfDrv._engine?.GetCurrentRecordNumber() ?? 0);
            // RDD USE (PCode) registra l'area solo in _dataSession (RegisterDirect), non in
            // _dbfHandles: senza questo fallback RECNO() su area RDD tornava 0 (IL 1).
            if (wa?.Driver is Basic.Databases.Rdd.IDatabaseDriver rddDrv) return rddDrv.CurrentKeyNo();
        }
        catch { }
        return 0.0;
    }
    public static double DbfLastrec(string? alias = null)
    {
        var h = DbfHandleFor(alias);
        if (h >= 0) return Current.Database.DbfGetRecordCount(h);
        // ISAM.LASTREC(alias) è mappato su DbfLastrec: fallback alle aree ISAM (come DbfFound).
        var ih = IsamHandleFor(alias);
        return ih >= 0 ? Current.Database.IsamGetRecordCount(ih) : 0.0;
    }
    public static double DbfSelected(string? alias = null)
    {
        // SELECTED(alias) → numero di work-area (1-based) dell'area indicata.
        // L'emitter (EmitDbfAliasCall) richiede una firma con parametro string; prima era
        // senza parametri → "metodo runtime 'DbfSelected' non trovato" (DbIsamFullTests).
        // Risolve via DataSession (FindAreaByAlias), come il PCode ResolveAreaNum — il
        // tracking interno (_isamHandles/_dbfHandles) poteva divergere dall'area reale.
        try
        {
            var session = Current.SqlDataSession;
            var explicitAlias = !string.IsNullOrWhiteSpace(alias);
            // Trim: una conversione numero→stringa BASIC aggiunge lo spazio-segno
            // (" 2"): senza trim int.TryParse/alias non trovavano l'area.
            var key = (explicitAlias ? alias! : _dbfCurrentAlias).Trim();
            if (int.TryParse(key, out var pn) && pn > 0 && session.GetWorkArea(pn)?.Driver != null) return pn;
            if (!string.IsNullOrWhiteSpace(key))
            {
                for (var a = 1; a <= Basic.Databases.Rdd.DataSession.MaxWorkareas; a++)
                {
                    var wa = session.GetWorkArea(a);
                    if (wa != null && string.Equals(wa.Alias, key, StringComparison.OrdinalIgnoreCase)) return a;
                }
                // Alias ESPLICITO sconosciuto → 0 ("0 se chiusa"). Prima FindAreaByAlias
                // ripiegava sull'area CORRENTE: SPEED.SELECTED("T") (T = alias di TABELLA,
                // non di work-area) dava 2 su IL contro 1/0/0 di PCode/VM-C/C99.
                if (explicitAlias) return 0.0;
            }
            // Nessun alias esplicito: l'area corrente vale solo se è una work-area
            // DBF/ISAM/RDD. Un database SPEED non è una work-area DBF: le gambe C
            // (che non registrano SPEED nel layer delle aree) rispondono 0.
            var current = session.GetWorkArea(session.CurrentArea);
            if (current?.Driver is null) return 0.0;
            if (current.Driver is Basic.Databases.Rdd.SpeedDriver) return 0.0;
            return session.CurrentArea;
        }
        catch { return 1.0; }
    }
    public static string IsamInfo(string? alias = null)
    {
        // ISAM.INFO(alias) → JSON d'ispezione completo (parità col PCode che accede
        // all'IsamEngine via ResolveIsamArea). Raggiunge il driver via DataSession e usa
        // Engine/Header direttamente; fallback al DatabaseService per record/field names.
        try
        {
            var session = Current.SqlDataSession;
            var area = string.IsNullOrWhiteSpace(alias)
                ? session.CurrentArea
                : FindAreaByAlias(session, alias);
            var wa = session.GetWorkArea(area);
            if (wa?.Driver is Basic.Databases.Rdd.IsamDriver idrv && idrv.Engine is { } eng)
            {
                var hdr = eng.Header;
                var schema = eng.Schema ?? (wa.Meta != null && wa.Meta.TryGetValue("Schema", out var s) ? s as Basic.ISAM.Config.IsamSchema : null);
                var fields = idrv.Fields ?? [];
                var sb = new System.Text.StringBuilder();
                sb.Append('{');
                sb.Append("\"file\":\"").Append(eng.FilePath).Append('"');
                sb.Append(",\"size_bytes\":").Append(eng.GetFileLength());
                sb.Append(",\"format_version\":").Append(hdr.Version);
                sb.Append(",\"type_name\":\"").Append(schema?.TypeName ?? "").Append('"');
                sb.Append(",\"record_size\":").Append(hdr.RecordSize);
                sb.Append(",\"active_records\":").Append(hdr.ActiveRecordCount);
                sb.Append(",\"last_rec_number\":").Append(hdr.LastRecNumber);
                sb.Append(",\"primary_key_root\":").Append(hdr.PrimaryKeyRootOffset);
                sb.Append(",\"lob_heap_start\":").Append(hdr.LobHeapStartOffset);
                sb.Append(",\"next_available_page\":").Append(hdr.NextAvailablePageOffset);
                sb.Append(",\"free_list_head\":").Append(hdr.FreeListHeadOffset);
                sb.Append(",\"page_free_list_head\":").Append(hdr.PageFreeListHeadOffset);
                sb.Append(",\"schema_offset\":").Append(hdr.SchemaOffset);
                sb.Append(",\"schema_length\":").Append(hdr.SchemaLength);
                sb.Append(",\"secondary_indexes\":").Append(schema?.SecondaryKeys?.Count ?? 0);
                sb.Append(",\"durability_mode\":\"").Append(eng.DurabilityMode).Append('"');
                sb.Append(",\"locking_strategy\":\"").Append(eng.LockingStrategy).Append('"');
                sb.Append(",\"field_names\":[");
                sb.Append(string.Join(",", fields.Select(f => "\"" + f.Name + "\"")));
                sb.Append(']');
                sb.Append('}');
                return sb.ToString();
            }
            // Fallback: DatabaseService (record count/record size/field names).
            var h = IsamHandleFor(alias);
            if (h < 0) return "{}";
            var fields2 = Current.Database.IsamFieldNames(h) ?? [];
            var sb2 = new System.Text.StringBuilder();
            sb2.Append('{');
            sb2.Append("\"active_records\":").Append(Current.Database.IsamGetRecordCount(h));
            sb2.Append(",\"record_size\":").Append(Current.Database.IsamRecordSize(h));
            sb2.Append(",\"field_names\":[");
            sb2.Append(string.Join(",", fields2.Select(f => "\"" + f + "\"")));
            sb2.Append(']');
            sb2.Append('}');
            return sb2.ToString();
        }
        catch { return "{}"; }
    }
    public static long IsamRecSize(string? alias = null)
    {
        // RECSIZE([area]) → dimensione del record in byte (somma lunghezze campi).
        // Token condiviso ISAM/DBF → risolve su entrambi i registry di handle.
        // Ritorna LONG (tipo dichiarato LongType): il box del chiamante è Int64,
        // un double avrebbe prodotto IL invalido (StackUnexpected, trovato da ILVerify).
        var h = IsamHandleFor(alias);
        if (h < 0) h = DbfHandleFor(alias);
        return h >= 0 ? Current.Database.IsamRecordSize(h) : 0;
    }
    public static double IsamConvertDbf(string source, string dest, string typeName, string pkField, double keyLength, double isUnsafe, string? schemaJson = null)
    {
        // CONVERT DBF "src" TO ISAM "dst" TYPE <UDT> KEY <pk> LEN <n> — pattern PCode
        // (IsamExportImport.ImportDbf: traduzione schema + copia record). `typeName` (la
        // clausola TYPE <UDT>, es. "DbfTestType") va passato a ImportDbf: senza, lo schema
        // scritto nel file usava il nome del file destinazione come TypeName, che non
        // corrisponde al TYPE del codice BASIC — il successivo `ISAM OPEN ... OF <UDT>`
        // falliva silenziosamente la verifica di compatibilità schema (SchemaManager.
        // AreSchemasCompatible, "[SCHEMA] TypeName mismatch") e la lettura restituiva
        // record vuoti (scoperto dal vivo su DbIsamFullTests.bas sez. 11). Stesso bug
        // presente anche nel motore PCodeVM di riferimento (PCodeProcessor.Syscalls.cs,
        // SysCall.CONVERT_DBF_TO_ISAM) — corretto in entrambi.
        //
        // `schemaJson` (compilato da IlProgramCompiler.BuildIsamSchemaJson, stesso formato
        // di ISAM OPEN/SPEED OPEN — IlRuntime non ha accesso alla SymbolTable, solo il
        // compilatore può risolvere i campi/tipi reali del TYPE) risolve due bug gemelli:
        // TranslateDbfSchemaToIsam semplifica OGNI campo DBF Numeric a DoubleType a
        // prescindere dal vero tipo dichiarato ("Codice AS LONG" scritto come DoubleType,
        // "[SCHEMA] Field[i] type" mismatch), e i nomi campo DBF sono troncati a 10
        // caratteri ("Descrizione" -> "Descrizion", "[SCHEMA] Field[i] name" mismatch).
        try
        {
            System.Collections.Generic.List<(string Name, string TypeCode)>? fieldOverrides = null;
            if (!string.IsNullOrEmpty(schemaJson))
            {
                try
                {
                    var doc = System.Text.Json.JsonDocument.Parse(schemaJson);
                    if (doc.RootElement.TryGetProperty("Fields", out var fieldsEl))
                    {
                        fieldOverrides = new System.Collections.Generic.List<(string, string)>();
                        foreach (var f in fieldsEl.EnumerateArray())
                        {
                            var fname = f.TryGetProperty("Name", out var nameEl) ? nameEl.GetString() ?? "" : "";
                            var ftype = f.TryGetProperty("Type", out var typeEl) ? typeEl.GetString() ?? "STRING" : "STRING";
                            fieldOverrides.Add((fname, ftype));
                        }
                    }
                }
                catch { }
            }
            Basic.ISAM.IsamExportImport.ImportDbf(
                source, dest,
                Basic.ISAM.IsamKeyExpressionEvaluator.Chain(null),
                string.IsNullOrEmpty(pkField) ? null : pkField,
                (int)keyLength > 0 ? (int)keyLength : 16,
                string.IsNullOrEmpty(typeName) ? null : typeName,
                fieldOverrides);
            return 1.0;
        }
        catch { return 0.0; }
    }
