    /// <summary>LUPDATE() → data dell'ultimo aggiornamento come SERIALE (DateType), non
    /// stringa: la StdLib dichiara DateType mentre il runtime ritornava string → il codegen IL
    /// emetteva una stringa dove il type system si aspettava un double → InvalidProgramException
    /// (§ MiniTests/dbf/zz_a + dbf_replication). Stessa classe di DBRELATION/replicazione.</summary>
    public static string DbfLupdate(string? alias = null)
    {
        try
        {
            var session = Current.SqlDataSession;
            var wa = string.IsNullOrWhiteSpace(alias)
                ? session.GetWorkArea(session.CurrentArea)
                : session.GetWorkArea(FindAreaByAlias(session, alias));
            if (wa?.Driver is Basic.Databases.Rdd.DbfDriver dbf && dbf.Engine is { } eng)
            {
                // Header DBF: primo byte = versione, poi YY MM DD (anno a 2 cifre, 1900+).
                // Si legge dal FILE: il valore non dipende dallo stato dell'area/engine (che fra
                // le gambe PCode/IL nello stesso processo può differire → IL dava 0).
                var path = eng.FilePath;
                if (!string.IsNullOrEmpty(path) && System.IO.File.Exists(path))
                {
                    var head = new byte[4];
                    using (var fs = System.IO.File.OpenRead(path)) { if (fs.Read(head, 0, 4) != 4) return ""; }
                    // L'anno nell'header è Year % 100 (DbfFile.cs:275/348): 2000 + YY, NON 1900 + YY
                    // (un file del 2026 dava 1926). Ritorna lo stesso testo di PCode (GbDate) e
                    // della VM/C (runtime condiviso): "YYYY-MM-DD".
                    // Il byte è "Year - 1900" (writer C) oppure "Year % 100" (writer C#):
                    // la regola copre entrambi (126 -> 2026, 26 -> 2026).
                    var yy = head[1] < 100 ? 2000 + head[1] : 1900 + head[1];
                    return yy.ToString("0000") + "-" + (head[2] < 1 ? 1 : head[2]).ToString("00")
                           + "-" + (head[3] < 1 ? 1 : head[3]).ToString("00");
                }
            }
        }
        catch { }
        return "";
    }
