    public static void DbfSetFilter(string? filterExpr, string? alias = null)
    {
        /* Il filtro va impostato SULLO STESSO driver che DBFILTER() poi legge: la lettura
         * risolve l'area via DataSession, mentre DbfHandleFor(alias) usa il registro handle
         * dell'IL → erano due istanze diverse e il filtro risultava sempre vuoto
         * (§ MiniTests/dbf/dbf_lock_filter.bas: SetFilter=[ID = 'A2'] ma la lettura dava ""). */
        try
        {
            var session = Current.SqlDataSession;
            var wa = string.IsNullOrWhiteSpace(alias)
                ? session.GetWorkArea(session.CurrentArea)
                : session.GetWorkArea(FindAreaByAlias(session, alias));
            if (wa?.Driver is Basic.Databases.Rdd.DbfDriver dbfDrv)
            {
                dbfDrv.SetFilter(filterExpr);
                // Il filtro va anche NEL MOTORE: SetFilter(string) salvava solo il testo, quindi
                // EvaluateFilter restava senza evaluator e DBF SKIP/EOF scorrevano i record
                // filtrati (divergenza con VM/C dopo il fix filter-aware di DbfEngine_Skip).
                try
                {
                    // Stesso evaluator delle operazioni scoped (RuntimeExpressionEvaluator →
                    // pipeline P-Code): RuntimeFilterParser ha semantica diversa sui confronti
                    // stringa (campo padded `"Torino   "` ≠ "Torino") → filtro a 0 record su IL.
                    var cond = Basic.Databases.Rdd.RuntimeExpressionEvaluator.CreateEvaluator(filterExpr);
                    dbfDrv.Engine?.SetFilter(
                        cond is null ? null
                            : new System.Func<System.Collections.Generic.Dictionary<string, object?>, bool>(
                                d => cond(null, d)),
                        null);
                }
                catch { }
                return;
            }
        }
        catch { }
        var h = DbfHandleFor(alias); if (h < 0) return;
        try { Current.Database.DbfSetFilter(h, filterExpr); } catch { }
    }
