    public static void DbfSortTo(string destPath, string[] fields, bool[] descending, string? alias = null, string? condition = null)
    {
        var h = DbfHandleFor(alias); if (h < 0) return;
        Basic.Databases.Rdd.DbfDriver? drv = null;
        try
        {
            var session = Current.SqlDataSession;
            var area = string.IsNullOrWhiteSpace(alias) ? session.CurrentArea : FindAreaByAlias(session, alias);
            if (session.GetWorkArea(area)?.Driver is Basic.Databases.Rdd.DbfDriver d) drv = d;
        }
        catch { }
        try
        {
            // FOR di SORT TO: il motore filtra in SkipInternal; si applica l'evaluator
            // (stessa pipeline P-Code di ScopeInfo) e si azzera al termine.
            if (condition is not null && drv?.Engine is { } eng)
            {
                var cand = Basic.Databases.Rdd.RuntimeExpressionEvaluator.CreateEvaluator(condition);
                eng.SetFilter(cand is null ? null
                    : new System.Func<System.Collections.Generic.Dictionary<string, object?>, bool>(d => cand(null, d)), null);
            }
            Current.Database.DbfSortTo(h, ResolveDbPath(destPath), fields, descending);
        }
        catch { }
        finally { try { drv?.Engine?.SetFilter(null, null); } catch { } }
    }
    /// <summary>Evaluator per le condizioni testuali di TOTAL/COPY/APPEND FROM: usa la
    /// stessa pipeline P-Code di SET FILTER/scope (RuntimeExpressionEvaluator). Con
    /// RuntimeFilterParser i confronti numerici (CURRENCY vs double) non trovavano record.</summary>
    private static System.Func<System.Collections.Generic.IReadOnlyDictionary<string, object?>, bool>?
        MakeDbfConditionEvaluator(object? condition)
    {
        var text = condition?.ToString();
        if (string.IsNullOrWhiteSpace(text)) return null;
        var ce = Basic.Databases.Rdd.RuntimeExpressionEvaluator.CreateEvaluator(text);
        return ce is null ? null
            : new System.Func<System.Collections.Generic.IReadOnlyDictionary<string, object?>, bool>(d => ce(null, d));
    }
