    public static void DbfUpdate(string keyField, string[] fieldNames, string[] valueExprs, string? srcAlias = null)
    {
        var h = DbfHandleFor(null); if (h < 0) return;
        var hs = string.IsNullOrEmpty(srcAlias) ? -1 : DbfHandleFor(srcAlias);
        if (hs >= 0)
        {
            // UPDATE ON <key> FROM <alias>: i valori possono riferire SOLO il sorgente con
            // `<alias>.<campo>`; per-record il riferimento viene sostituito col valore letto
            // dal record sorgente abbinato e il resto è valutato sul contesto della destinazione.
            var evalsOn = new System.Func<System.Collections.Generic.IReadOnlyDictionary<string, object?>,
                                          System.Collections.Generic.IReadOnlyDictionary<string, object?>, object?>[valueExprs.Length];
            for (var i = 0; i < valueExprs.Length; i++)
            {
                var text = valueExprs[i];
                var sa = srcAlias!;
                evalsOn[i] = (dctx, sctx) =>
                {
                    var substituted = Basic.Databases.Rdd.DbfDriver.SubstituteQualifiedRefs(text, sa, sctx);
                    var ev = DbExprPCodeEvaluator.GetOrCompileCached(substituted);
                    return ev?.Evaluate(dctx);
                };
            }
            try { Current.Database.DbfUpdateOn(h, hs, srcAlias!, keyField, fieldNames, evalsOn); } catch { }
            return;
        }
        var evals = new System.Func<System.Collections.Generic.IReadOnlyDictionary<string, object?>, object?>[valueExprs.Length];
        for (var i = 0; i < valueExprs.Length; i++)
        {
            var expr = RuntimeFilterParser.Parse(valueExprs[i]);
            var compiled = expr is null ? null : DbExprPCodeEvaluator.TryCompile(expr);
            evals[i] = compiled is null ? _ => null : compiled.Evaluate;
        }
        try { Current.Database.DbfUpdate(h, keyField, fieldNames, evals); } catch { }
    }
