    public static double IsamAppendMany(object? batch, string? alias = null)
    {
        var h = IsamHandleFor(alias); if (h < 0 || batch is not System.Collections.IEnumerable en) return 0.0;
        try
        {
            var records = new System.Collections.Generic.List<System.Collections.Generic.Dictionary<string, object?>>();
            foreach (var item in en)
            {
                var dict = new System.Collections.Generic.Dictionary<string, object?>(System.StringComparer.OrdinalIgnoreCase);
                // Un RECORD LITERALE ({Campo: valore}) è già un dizionario: va usato così com'è.
                // Prima si leggevano solo i CAMPI di un oggetto (item.GetType().GetFields): su un
                // dizionario non ce ne sono → dizionari vuoti → APPENDMANY non inseriva nulla e
                // ritornava 0 (§ MiniTests/dbf/isam_replication.bas e zz_b per il lato DBF).
                if (item is System.Collections.IDictionary dicoN)
                    foreach (System.Collections.DictionaryEntry kv in dicoN) dict[kv.Key?.ToString() ?? ""] = kv.Value;
                else if (item is not null)
                    foreach (var fld in item.GetType().GetFields(System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance))
                        dict[fld.Name] = fld.GetValue(item);
                records.Add(dict);
            }
            return Current.Database.IsamAppendMany(h, records);
        }
        catch { return 0.0; }
    }
