    public static string IsamIntegrity(string? alias = null)
    {
        // ISAM.INTEGRITY(alias) → JSON, pattern PCodeVM ISAM_INTEGRITY ({"valid":...,"message":...}).
        // Il return type è JsonType (vedi StdLib.Isam): tornare double (vecchio) assegnato a
        // DIM x AS JSON generava IL invalido (mismatch tipo reference vs value type).
        var h = IsamHandleFor(alias);
        // Difensivo: il servizio DB può sollevare (es. IndexOutOfRange su un handle non mappato)
        // e il chiamante (PCode/VM) non deve ricevere un'eccezione per una DIAGNOSTICA.
        // Senza area/engine: JSON valido "vuoto".
        try { return h >= 0 ? Current.Database.IsamValidateJson(h) : "{}"; }
        catch { return "{\"valid\":false,\"message\":\"\"}"; }
    }
