    {
        try
        {
            var session = Current.SqlDataSession;
            var wa = string.IsNullOrWhiteSpace(alias)
                ? session.GetWorkArea(session.CurrentArea)
                : session.GetWorkArea(FindAreaByAlias(session, alias));
            if (wa?.Driver is Basic.Databases.Rdd.SpeedDriver spd && spd.Db is { } db)
            {
                db.DurabilityMode = Enum.TryParse<Basic.SPEED.SpeedDurabilityMode>(mode, true, out var m)
                    ? m : Basic.SPEED.SpeedDurabilityMode.Full;
                return db.DurabilityMode.ToString();
            }
            return "";
        }
        catch { return ""; }
    }
