    /// <summary>Snapshot nome→valore del record corrente per `DBF GET &lt;var&gt;` late-binding:
    /// la variabile dinamica è un Dictionary e `var.Campo` passa da DynamicFieldGet.</summary>
    public static System.Collections.Generic.Dictionary<string, object?>? DbfGetRecordDict(string? alias = null)
    {
        var h = DbfHandleFor(alias);
        return h >= 0 ? Current.Database.DbfGetRecordNamed(h) : null;
    }
    /// <summary>Membro su un valore dinamico (dict late-binding o reflection); 0.0 per i
    /// primitivi (preserva il default storico dei campi non risolvibili, es. MODES(I).Active).</summary>
    public static object? DynamicFieldGet(object? obj, string name)
    {
        if (obj is null) return null;
        if (obj is System.Collections.Generic.Dictionary<string, object?> d)
            return d.TryGetValue(name, out var v) ? v : null;
        if (obj is System.Collections.IDictionary gd)
            return gd.Contains(name) ? gd[name] : null;
        if (obj is double || obj is int || obj is long || obj is bool || obj is string) return 0.0;
        var t = obj.GetType();
        var fi = t.GetField(name, System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.IgnoreCase);
        if (fi is not null) return fi.GetValue(obj);
        var pi = t.GetProperty(name, System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.IgnoreCase);
        return pi?.GetValue(obj);
    }
