    /// <summary>DBF REPLACE campo WITH valore [, ...] [scope]: come DbfReplaceByName ma con
    /// clausola di scope (ALL/NEXT/RECORD/REST/FOR/WHILE) — l'emissione precedente ignorava
    /// completamente drp.Scope e applicava SEMPRE solo al record corrente, indipendentemente
    /// da ALL/FOR (scoperto verificando "DBF REPLACE Nome WITH X ALL" su 3 record: solo
    /// l'ultimo veniva modificato, quello su cui il cursore si trovava per caso). Risolve
    /// l'area DataSession dall'alias DBF corrente (stessa DataSession condivisa da RDD/DBF/
    /// ISAM/SPEED — RddAreaFor funziona per qualunque alias registrato, non solo RDD) e
    /// delega a CoreDb.ScopedReplace, lo stesso motore già usato da RDD REPLACE.</summary>
    public static void DbfReplaceScoped(object? fields, int scopeType, object? countOrArg, object? condition = null, string? alias = null)
    {
        var resolvedAlias = alias ?? _dbfCurrentAlias;
        var (scope, forCond, whileCond) = RddScopeData(scopeType, countOrArg, condition);
        var area = RddAreaFor(resolvedAlias);
        var dict = new System.Collections.Generic.Dictionary<string, object?>();
        if (fields is System.Collections.Generic.Dictionary<string, object?> d) dict = d;
        try { Basic.Databases.Rdd.CoreDb.ScopedReplace(Current.SqlDataSession, area, scope, dict, forCond, whileCond); }
        catch { }
    }
