    /// <summary>DBF DELETE [scope]/DBF RECALL [scope]: DbfDelete/DbfRecall sopra ignoravano
    /// del tutto ddl.Scope/drc.Scope, applicando SEMPRE solo al record corrente indipendentemente
    /// da ALL/FOR/NEXT/REST (stesso bug/causa già risolto per DBF REPLACE). Riusa il motore
    /// scope-aware RDD (RddDelete/RddRecall -> CoreDb.ScopedDelete/ScopedRecall) passando
    /// l'alias DBF corrente: DBF/RDD/ISAM/SPEED condividono la stessa DataSession, quindi
    /// RddAreaFor(alias) risolve correttamente l'area anche per un alias aperto con DBF USE.</summary>
    public static long DbfDeleteScoped(int scopeType, object? countOrArg, object? condition = null)
        => RddDelete(scopeType, countOrArg, condition, _dbfCurrentAlias);
    public static long DbfRecallScoped(int scopeType, object? countOrArg, object? condition = null)
        => RddRecall(scopeType, countOrArg, condition, _dbfCurrentAlias);

    /// <summary>RDD DELETE [scope] [FOR cond] [WHILE cond] — marca come cancellati i record
    /// dell'area corrente (scope: 0=All, 1=Next, 2=Record, 3=Rest, 4=Current, 5=For, 6=While).
    /// La condizione (stringa) è valutata da RuntimeExpressionEvaluator sul record corrente,
    /// quindi funziona con qualunque driver RDD (community e commerciale).</summary>
    public static long RddDelete(int scopeType, object? countOrArg, object? condition = null, string? alias = null)
        => RddScopedOperation(scopeType, countOrArg, condition, alias,
            (s, area, scope, fc, wc) => Basic.Databases.Rdd.CoreDb.ScopedDelete(s, area, scope, fc, wc));

    /// <summary>RDD.DELETE(scope, expr) — forma FUNZIONE (ritorna il conteggio). Il primo
    /// argomento è lo scope: numerico → NEXT n, altrimenti stringa keyword/condizione.</summary>
    public static long RddDeleteScoped(object? scope, object? expr)
    {
        var (scopeType, count, cond) = ParseFunctionScope(scope, expr);
        return RddScopedOperation(scopeType, count, cond, null,
            (s, area, sc, fc, wc) => Basic.Databases.Rdd.CoreDb.ScopedDelete(s, area, sc, fc, wc));
    }

    public static long RddRecallScoped(object? scope, object? expr)
    {
        var (scopeType, count, cond) = ParseFunctionScope(scope, expr);
        return RddScopedOperation(scopeType, count, cond, null,
            (s, area, sc, fc, wc) => Basic.Databases.Rdd.CoreDb.ScopedRecall(s, area, sc, fc, wc));
    }

    /// <summary>RDD.REPLACE(scope, field, value, expr): forma FUNZIONE — scope come sopra,
    /// field = NOME campo (ScopedReplace risolve il nome sul driver del record corrente,
    /// stesso dizionario per-nome usato dalla forma statement RDD REPLACE).</summary>
    public static long RddReplaceScoped(object? scope, object? field, object? value, object? expr)
    {
        var (scopeType, count, cond) = ParseFunctionScope(scope, expr);
        var dict = new System.Collections.Generic.Dictionary<string, object?>(System.StringComparer.OrdinalIgnoreCase)
        {
            [field?.ToString() ?? ""] = value
        };
        var scopeData = scopeType switch
        {
            1 => Basic.Databases.Rdd.ScopeInfoData.NextN(count is double n ? (long)n : 1),
            2 => Basic.Databases.Rdd.ScopeInfoData.RecordN(count is double r ? (long)r : 1),
            3 => Basic.Databases.Rdd.ScopeInfoData.Rest,
            4 => Basic.Databases.Rdd.ScopeInfoData.Current,
            _ => Basic.Databases.Rdd.ScopeInfoData.All
        };
        try
        {
            return Basic.Databases.Rdd.CoreDb.ScopedReplace(Current.SqlDataSession, Current.SqlDataSession.CurrentArea,
                scopeData, dict, cond as string, null);
        }
        catch { return 0; }
    }

