    /// <summary>Risolve il token "area" di EXPORT/IMPORT (numero di area O alias, es.
    /// `ISAM EXPORT Clienti TO ...` — Clienti è un ALIAS, non un numero, vedi
    /// DbIsamFullTests.bas) allo stesso modo di RddLock: numero → area diretta, altrimenti
    /// FindAreaByAlias.</summary>
    private static int ResolveExportImportArea(Basic.Databases.Rdd.DataSession session, string? areaToken)
    {
        if (string.IsNullOrEmpty(areaToken)) return session.CurrentArea;
        // 0 = area implicita (`DBF EXPORT TO "f" AS CSV`, `DBF.EXPORT(0, …)`): l'area corrente.
        if (int.TryParse(areaToken, out var n)) return n > 0 ? n : session.CurrentArea;
        return session.FindAreaByAlias(areaToken);
    }

    /// <summary>
    /// `EXPORT ISAM|DBF area TO "file" AS CSV|JSON`: prima un no-op incondizionato. CSV
    /// riusa CoreDb.CopyTo (driver CSV già registrato, DriverRegistry) — stesso motore già
    /// usato da RDD COPY TO. JSON non ha un driver registrato (nessun "JsonDriver" in
    /// DriverRegistry): scritto qui direttamente via System.Text.Json, genericamente su
    /// QUALUNQUE IDatabaseDriver (Fields/GetCurrentRecord — DBF/ISAM/SPEED indifferentemente).
    /// `engineType` non influisce sulla logica (l'area è già un driver concreto aperto),
    /// portato solo per simmetria con l'AST/firma.
    /// </summary>
    public static void ExportToFile(string engineType, string? areaToken, string filePath, string format)
    {
        try
        {
            var session = Current.SqlDataSession;
            var area = ResolveExportImportArea(session, areaToken);
            if (area <= 0) return;
            if (format.Equals("JSON", StringComparison.OrdinalIgnoreCase))
                ExportAreaToJson(session, area, filePath);
            else
                Basic.Databases.Rdd.CoreDb.CopyTo(session, area, filePath, "CSV");
        }
        catch { }
    }

    /// <summary>`IMPORT ISAM|DBF area FROM "file" AS CSV|JSON`: prima un no-op
    /// incondizionato. CSV riusa il nuovo CoreDb.CopyFrom (simmetrico a CopyTo, stesso
    /// DriverRegistry); JSON letto e appeso direttamente, come ExportToFile.</summary>
    public static void ImportFromFile(string engineType, string? areaToken, string filePath, string format)
    {
        try
        {
            var session = Current.SqlDataSession;
            var area = ResolveExportImportArea(session, areaToken);
            if (area <= 0) return;
            if (format.Equals("JSON", StringComparison.OrdinalIgnoreCase))
                ImportAreaFromJson(session, area, filePath);
            else
                Basic.Databases.Rdd.CoreDb.CopyFrom(session, area, filePath, "CSV");
        }
        catch { }
    }

    private static void ExportAreaToJson(Basic.Databases.Rdd.DataSession session, int area, string filePath)
    {
        var driver = session.GetWorkArea(area)?.Driver;
        if (driver == null || !driver.IsOpen) return;
        var rows = new List<Dictionary<string, object?>>();
        driver.GoTop();
        while (!driver.Eof)
        {
            var record = driver.GetCurrentRecord();
            if (record != null)
            {
                var row = new Dictionary<string, object?>(StringComparer.OrdinalIgnoreCase);
                foreach (var f in driver.Fields)
                    if (record.TryGetValue(f.SymbolId, out var v)) row[f.Name] = v;
                rows.Add(row);
            }
            driver.Skip(1);
        }
        var json = System.Text.Json.JsonSerializer.Serialize(rows, new System.Text.Json.JsonSerializerOptions { WriteIndented = true });
        System.IO.File.WriteAllText(filePath, json);
    }

    private static void ImportAreaFromJson(Basic.Databases.Rdd.DataSession session, int area, string filePath)
    {
        var driver = session.GetWorkArea(area)?.Driver;
        if (driver == null || !driver.IsOpen || !System.IO.File.Exists(filePath)) return;
        using var doc = System.Text.Json.JsonDocument.Parse(System.IO.File.ReadAllText(filePath));
        if (doc.RootElement.ValueKind != System.Text.Json.JsonValueKind.Array) return;
        foreach (var item in doc.RootElement.EnumerateArray())
        {
            var outRecord = new Dictionary<int, object?>();
            foreach (var f in driver.Fields)
            {
                if (item.TryGetProperty(f.Name, out var prop))
                    outRecord[f.SymbolId] = JsonElementToObject(prop);
            }
            driver.Append(outRecord);
        }
    }

    /// <summary>Interpreta lo scope della forma FUNZIONE: numerico → NEXT n; stringa con
    /// keyword (ALL/REST/CURRENT) → scope corrispondente; altrimenti → ALL con condizione.</summary>
    private static (int ScopeType, object? Count, object? Condition) ParseFunctionScope(object? scope, object? expr)
    {
        if (scope is double d) return (1, d, null); // NEXT n
        var s = scope?.ToString()?.Trim() ?? "";
        var upper = s.ToUpperInvariant();
        if (upper is "" or "ALL" or "NEXT" or "FOR" or "WHILE") return (0, null, s);
        if (upper == "REST") return (3, null, null);
        if (upper == "RECORD") return (2, expr, null);
        if (upper == "CURRENT") return (4, null, null);
        if (double.TryParse(s, System.Globalization.CultureInfo.InvariantCulture, out var n)) return (1, n, null);
        return (0, null, s);
    }

    /// <summary>RDD RECALL [scope] [FOR cond] [WHILE cond] — ripristina i record cancellati dell'area corrente.</summary>
    public static long RddRecall(int scopeType, object? countOrArg, object? condition = null, string? alias = null)
        => RddScopedOperation(scopeType, countOrArg, condition, alias,
            (s, area, scope, fc, wc) => Basic.Databases.Rdd.CoreDb.ScopedRecall(s, area, scope, fc, wc));

    /// <summary>RDD REPLACE field WITH value [scope] [FOR cond] [WHILE cond] — sostituisce i valori dei campi.
    /// Dizionario per NOME campo (non FieldSymbolId): vedi EmitRddReplaceStatement per il motivo
    /// (RddFieldInfo.SymbolId è l'indice posizionale per DBF/Speed, non l'ID del Linker).</summary>
    public static long RddReplace(object? fields, int scopeType, object? countOrArg, object? condition = null, string? alias = null)
    {
        var (scope, forCond, whileCond) = RddScopeData(scopeType, countOrArg, condition);
        var area = RddAreaFor(alias);
        var dict = new System.Collections.Generic.Dictionary<string, object?>();
        if (fields is System.Collections.Generic.Dictionary<string, object?> d) dict = d;
        // Row-buffer ATTIVO + scope Current: deviazione nel buffer (ADR §6, pari al PCode).
        try
        {
            var session2 = Current.SqlDataSession;
            if (session2._buffers.TryGetValue(area, out var ibuf) && ibuf.IsActive && dict.Count > 0
                && scope?.Type == Basic.Databases.Rdd.ScopeType.Current)
            {
                var idrv = session2.GetWorkArea(area)?.Driver ?? session2.CurrentDriver;
                if (idrv != null)
                {
                    long rn = 0;
                    foreach (var kvf in dict)
                    {
                        var symf = idrv.Fields.FirstOrDefault(ff => string.Equals(ff.Name, kvf.Key, StringComparison.OrdinalIgnoreCase))?.SymbolId
                                   ?? idrv.GetFieldIndex(kvf.Key);
                        ibuf.SetField(symf, kvf.Value);
                        rn++;
                    }
                    return rn;
                }
            }
        }
        catch { }
        try
        {
            return Basic.Databases.Rdd.CoreDb.ScopedReplace(Current.SqlDataSession, area, scope, dict, forCond, whileCond);
        }
        catch { return 0; }
    }

