    private static Basic.Databases.Rdd.IDatabaseDriver? RddDriver(string? alias, int area = 0)
    {
        try
        {
            var session = Current.SqlDataSession;
            var a = alias != null ? RddAreaFor(alias) : (area != 0 ? area : session.CurrentArea);
            return session.GetWorkArea(a)?.Driver ?? session.CurrentDriver;
        }
        catch { return null; }
    }

    /// <summary>RDD GETFIELD(area, field) — valore del campo del record corrente.
    /// field può essere un indice NUMERICO (RDD.GETFIELD(1, 0)) o un NOME (RDD.GETFIELD(1, "Name")).
    /// Gli argomenti arrivano boxed (double/int/long) — gestiti tutti.</summary>
    public static object? RddGetField(object? areaArg, object? fieldArg)
    {
        { var _s0 = Current.SqlDataSession; RddRequireValidField(_s0.GetWorkArea(RddNumericArg(areaArg) != 0 ? RddNumericArg(areaArg) : _s0.CurrentArea), fieldArg); }
        try
        {
            var session = Current.SqlDataSession;
            var area = RddNumericArg(areaArg) != 0 ? RddNumericArg(areaArg) : session.CurrentArea;
            var wa = session.GetWorkArea(area);
            // Row-buffer ATTIVO su quest'area: si legge DAL BUFFER (ADR-RowBuffer §6).
            if (wa != null && session._buffers.TryGetValue(area, out var gbuf) && gbuf.IsActive)
            {
                var gk = RddResolveFieldSymbol(wa, fieldArg);
                return RddTypedValue(wa?.Driver, gk, gbuf.GetField(gk));
            }
            var driver = wa?.Driver ?? session.CurrentDriver;
            if (driver is null) return null;
            // Indice numerico = ordinale Clipper 1-based (ADR §1) → colonna 0-based.
            // Decimal/double del motore canonizzati a double (display uniforme).
            if (fieldArg is double or int or long or short)
                return RddTypedValue(driver, RddNumericArg(fieldArg) - 1, driver.GetFieldValue(RddNumericArg(fieldArg) - 1));
            var fieldName = fieldArg?.ToString() ?? "";
            return RddTypedValue(driver, driver.GetFieldIndex(fieldName), driver.GetFieldValue(driver.GetFieldIndex(fieldName)));
        }
        catch { return null; }
    }

    /// <summary>Ordinale Clipper 1-based → chiave reale del buffer: SymbolId del campo
    /// sulle work area con UDT (ISAM/DBF da TYPE, come RddResolveFieldSymbolId del PCode),
    /// colonna 0-based altrove; nome → indice di nome.</summary>
    /// <summary>Wrapper pubblico per il PCode (RDD SET FIELD): la chiave di SET deve coincidere
    /// con quella di GET (RddGetField/OLDVAL/GETFLDSTATE) — altrimenti il buffer scrive una chiave
    /// che i getter non leggono (es. campo 0: SET 0 vs GET -1 → vuoto).</summary>
    public static int RddResolveFieldSymbolPub(Basic.Databases.Rdd.DatabaseWorkArea? wa, object? fieldArg)
        => RddResolveFieldSymbol(wa, fieldArg);

    /// <summary>Validazione dell'ordinale di campo RDD — convenzione Clipper **1-based**: un
    /// indice numerico &lt; 1 o &gt; n. campi è un ERRORE (non un accesso silenzioso a vuoto).
    /// Va chiamata PRIMA del try/catch dei getter/setter RDD, che altrimenti inghiottirebbe
    /// l'eccezione restituendo null/vuoto. Solo per fieldArg NUMERICO (per nome non si valida).</summary>
    public static void RddRequireValidField(Basic.Databases.Rdd.DatabaseWorkArea? wa, object? fieldArg)
    {
        if (fieldArg is not (double or int or long or short)) return;
        int ord = RddNumericArg(fieldArg);
        int n = wa?.Meta.GetValueOrDefault("Udt") is UserDefinedType udt2 && udt2.Fields.Length > 0
            ? udt2.Fields.Length
            : (wa?.Driver?.Fields.Length ?? 0);
        if (ord < 1 || (n > 0 && ord > n))
            throw new BasicException(ErrorCode.InvalidParameter, SourcePosition.Unknown,
                $"RDD: indice campo {ord} non valido (convenzione Clipper 1-based{(n > 0 ? $", 1..{n}" : "")})");
    }

    private static int RddResolveFieldSymbol(Basic.Databases.Rdd.DatabaseWorkArea? wa, object? fieldArg)
    {
        var ord = RddNumericArg(fieldArg);
        if (ord > 0 && wa?.Meta.GetValueOrDefault("Udt") is UserDefinedType udt && ord <= udt.Fields.Length)
            return udt.Fields[ord - 1].SymbolId;
        if (ord > 0) return ord - 1;
        var nm = fieldArg?.ToString() ?? "";
        if (nm.Length == 0) return -1;
        // Il nome DEVE risolversi al SymbolId del campo (chiave reale del buffer e di
        // GetCurrentRecord), non alla posizione di GetFieldIndex: sulle aree ISAM con UDT
        // le due cose coincidono solo per coincidenza (DbfDriver sì, IsamDriver NO).
        var f = wa?.Driver?.Fields.FirstOrDefault(ff => string.Equals(ff.Name, nm, StringComparison.OrdinalIgnoreCase));
        return f?.SymbolId ?? -1;
    }
    /// <summary>Coercizione del valore esposto dai getter RDD al TIPO DICHIARATO del campo
    /// (chiave = SymbolId/ordinale del driver): snapshot testuali di campi numerici (N/F in
    /// DBF, celle C99) diventano double — parità con la superficie C (gmb_print_text_typed)
    /// e fra IL/PCode su valori catturati in forme diverse dal motore.</summary>
    public static object? RddTypedValuePub(Basic.Databases.Rdd.IDatabaseDriver? drv, int keySymId, object? v) => RddTypedValue(drv, keySymId, v);

    private static object? RddTypedValue(Basic.Databases.Rdd.IDatabaseDriver? drv, object? keySymId, object? v)
    {
        // I driver possono esporre lo stesso campo numerico come Decimal (motore DBF) o
        // double: i getter RDD canonizzano a double (display Clipper identico su 4 gambe).
        if (v is decimal dm) return (double)dm;
        if (v is not string txt || txt.Length == 0) return v;
        try
        {
            var f = drv?.Fields.FirstOrDefault(ff => ff.SymbolId == (int)(keySymId ?? -1));
            if (f is null) return v;
            var dt = f.DataType.GetType().Name;
            if (dt is not ("DoubleType" or "IntegerType" or "LongType" or "FloatType" or "CurrencyType")) return v;
            var t = txt.Trim();
            if (t.Length == 0) return v;
            foreach (var ch in t) if (!(char.IsDigit(ch) || ch == '-' || ch == '+' || ch == '.' || ch == ' ')) return v;
            if (!double.TryParse(t.Trim(), System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out var dv)) return v;
            // "35000" → 35000 e "35000.000000" → 35000: TRAILING-ZERO normalization che
            // rende i due rami (driver testuale del PCode e typed dell'IL) identici.
            return dv;
        }
        catch { return v; }
    }

    private static int RddNumericArg(object? arg)
    {
        if (arg is double d) return (int)d;
        if (arg is int i) return i;
        if (arg is long l) return (int)l;
        if (arg is short s) return s;
        if (arg is byte b) return b;
        if (arg is float f) return (int)f;
        return 0;
    }

    /// <summary>RDD SET FIELD area, campo, valore — scrive il campo del record corrente.</summary>
    public static void RddSetField(object? areaArg, object? fieldArg, object? valueArg)
    {
        { var _s0 = Current.SqlDataSession; RddRequireValidField(_s0.GetWorkArea(RddNumericArg(areaArg) != 0 ? RddNumericArg(areaArg) : _s0.CurrentArea), fieldArg); }
        try
        {
            var session = Current.SqlDataSession;
            var area = RddNumericArg(areaArg) != 0 ? RddNumericArg(areaArg) : session.CurrentArea;
            var wa = session.GetWorkArea(area);
            // Con row-buffer ATTIVO la scrittura è DEVIATA nel buffer (ADR §6).
            if (wa != null && session._buffers.TryGetValue(area, out var sbuf) && sbuf.IsActive)
            { sbuf.SetField(RddResolveFieldSymbol(wa, fieldArg), valueArg); return; }
            var driver = wa?.Driver ?? session.CurrentDriver;
            if (driver is null) return;
            if (fieldArg is double or int or long or short)
                driver.SetFieldValue(RddNumericArg(fieldArg) - 1, valueArg);
            else
                driver.SetFieldValue(driver.GetFieldIndex(fieldArg?.ToString() ?? ""), valueArg);
        }
        catch { }
    }

    /// <summary>RDD GETFLDSTATE(area, field) — stato del campo (0=unchanged, 1=modified, 2=deleted).</summary>
    public static double RddGetFieldState(object? areaArg, object? fieldArg)
    {
        { var _s0 = Current.SqlDataSession; RddRequireValidField(_s0.GetWorkArea((int)(areaArg is double _da ? _da : _s0.CurrentArea)), fieldArg); }
        try
        {
            var session = Current.SqlDataSession;
            var area = (int)(areaArg is double da ? da : session.CurrentArea);
            if (session._buffers.TryGetValue(area, out var buf) && buf.IsActive)
            {
                var st = buf.GetFieldState(RddResolveFieldSymbol(session.GetWorkArea(area), fieldArg));
                // Mappa l'enum 1-based interno sulla superficie canonica 0/1/2 (ADR §4).
                return st switch
                {
                    Basic.Databases.Rdd.FieldState.Deleted => 2,
                    Basic.Databases.Rdd.FieldState.Modified or Basic.Databases.Rdd.FieldState.Appended => 1,
                    _ => 0
                };
            }
            return 0;
        }
        catch { return 0; }
    }

