    /// <summary>RDD DTOC(date) — data a stringa.</summary>
    public static string RddDtoc(object? d)
    {
        // Una DATA puo' arrivare come DateTime oppure come seriale OA (double): una variabile non
        // tipizzata/DOUBLE che riceve RDD.CTOD() la conserva come numero. Prima il double finiva su ToString()
        // -> "46381" invece di "2026-12-25" (C99/C99Native/VM-C gia' formattano la data).
        try
        {
            if (d is DateTime dt) return dt.ToString("yyyy-MM-dd");
            if (d is double od && od > 0 && od < 2958466) return DateTime.FromOADate(od).ToString("yyyy-MM-dd");
            return d?.ToString() ?? "";
        }
        catch { return ""; }
    }

