    /// <summary>RDD BUFFER(area, mode) — attiva la modalità buffer. Ritorna il bit
    /// canonico del linguaggio come DOUBLE: -1 = buffer attivo, 0 = non attivo (ADR §3).</summary>
    public static double RddBuffer(object? areaArg, object? mode)
    {
        try
        {
            var session = Current.SqlDataSession;
            var area = (int)(areaArg is double da ? da : session.CurrentArea);
            var wa = session.GetWorkArea(area);
            if (wa?.Driver is { IsOpen: true })
            {
                var m = RddNumericArg(mode);
                if (m == 2 || m == 3)
                {
                    var buf = new Basic.Databases.Rdd.RowsBuffer();
                    buf.Activate(wa.Driver, m == 2 ? Basic.Databases.Rdd.BufferMode.Pessimistic
                                                   : Basic.Databases.Rdd.BufferMode.Optimistic);
                    session._buffers[area] = buf;
                    return -1;
                }
                // mode 0/1 = disattiva (ADR §2): DEATTIVARE davvero (rilascia il lock
                // pessimistico preso in Activate) prima di rimuovere — un Remove secco
                // lasciava il record write-locked e ogni scrittura successiva sul
                // motore crashava con "recursive write lock" (misurato su PCode).
                if (session._buffers.TryGetValue(area, out var obuf) && wa?.Driver != null)
                {
                    try { obuf.TableRevert(wa.Driver); } catch { }
                    session._buffers.Remove(area);
                }
                return 0;
            }
            return 0;
        }
        catch { return 0; }
    }

    /// <summary>RDD TABLEREVERT(area) — annulla le modifiche in sospeso.</summary>
    public static bool RddTableRevert(object? areaArg)
    {
        try
        {
            var session = Current.SqlDataSession;
            var area = (int)(areaArg is double da ? da : session.CurrentArea);
            var wa = session.GetWorkArea(area);
            if (session._buffers.TryGetValue(area, out var buf) && wa?.Driver != null)
            {
                buf.TableRevert(wa.Driver);
                session._buffers.Remove(area);
                return true;
            }
            return false;
        }
        catch { return false; }
    }

    /// <summary>RDD TABLEUPDATE(area) — applica le modifiche in sospeso.</summary>
    public static bool RddTableUpdate(object? areaArg)
    {
        try
        {
