    }

    /// <summary>RDD OLDVAL(area, field) — valore originale del campo.</summary>
    public static object? RddOldVal(object? areaArg, object? fieldArg)
    {
        { var _s0 = Current.SqlDataSession; RddRequireValidField(_s0.GetWorkArea((int)(areaArg is double _da ? _da : _s0.CurrentArea)), fieldArg); }
        try
        {
            var session = Current.SqlDataSession;
            var area = (int)(areaArg is double da ? da : session.CurrentArea);
            if (session._buffers.TryGetValue(area, out var buf) && buf.IsActive)
            {
                var wk = session.GetWorkArea(area);
                var ok2 = RddResolveFieldSymbol(wk, fieldArg);
                // Assente nello snapshot → 0.0 (default numerico, parità col gestito: il valore
                // OLDVAL non-null evita che il PCode lasci "" — bug RDD_Memory_CRUD OLDVAL vuoto).
                return RddTypedValue(wk?.Driver, ok2, buf.GetOldValue(ok2)) ?? 0.0;
            }
            return null;
        }
        catch { return null; }
    }

