    private static long RddScopedOperation(int scopeType, object? countOrArg, object? condition, string? alias,
        Func<Basic.Databases.Rdd.DataSession, int, Basic.Databases.Rdd.ScopeInfoData, string?, string?, long> op)
    {
        var (scope, forCond, whileCond) = RddScopeData(scopeType, countOrArg, condition);
        var area = RddAreaFor(alias);
        try { return op(Current.SqlDataSession, area, scope, forCond, whileCond); }
        catch { return 0; }
    }

    private static (Basic.Databases.Rdd.ScopeInfoData Scope, string? For, string? While) RddScopeData(
        int scopeType, object? countOrArg, object? condition)
    {
        var cond = condition as string;
        return scopeType switch
        {
            0 => (Basic.Databases.Rdd.ScopeInfoData.All, null, null),
            1 => (Basic.Databases.Rdd.ScopeInfoData.NextN(countOrArg is double n ? (long)n : 1), null, null),
            2 => (Basic.Databases.Rdd.ScopeInfoData.RecordN(countOrArg is double r ? (long)r : 1), null, null),
            3 => (Basic.Databases.Rdd.ScopeInfoData.Rest, null, null),
            5 => (Basic.Databases.Rdd.ScopeInfoData.All, cond, null),
            6 => (Basic.Databases.Rdd.ScopeInfoData.All, null, cond),
            _ => (Basic.Databases.Rdd.ScopeInfoData.Current, null, null)
        };
    }

    private static int RddAreaFor(string? alias)
    {
        var session = Current.SqlDataSession;
        if (alias != null)
        {
            try
            {
                var drv = session.FindAlias(alias);
                if (drv != null)
                {
                    for (int a = 0; a <= session.CurrentArea; a++)
                    {
                        var wa = session.GetWorkArea(a);
                        if (wa != null && wa.Driver == drv) return a;
                    }
                }
            }
            catch { /* alias non trovato: usa l'area corrente */ }
        }
        return session.CurrentArea;
    }

