    // ================================================================
    // ISAM — delega a IDatabaseService (NativeDb / gmb_db)
    // ================================================================
    private static readonly System.Collections.Generic.Dictionary<string, long> _isamHandles = new(System.StringComparer.OrdinalIgnoreCase);
    private static string _isamCurrentAlias = "";

    /// <summary>Tutti i Basic.ISAM.Engine attualmente aperti in QUALUNQUE work area della
    /// DataSession condivisa (dedup per istanza: un engine può comparire su più alias/aree
    /// tramite JOIN/relazioni). Stesso pattern di PCodeProcessor.Helpers.GetOpenIsamEngines
    /// (motore di riferimento già corretto per BEGIN/COMMIT/ROLLBACK).</summary>
    private static System.Collections.Generic.IEnumerable<Basic.ISAM.Engine> GetOpenIsamEngines()
    {
        var session = Current.SqlDataSession;
        var seen = new System.Collections.Generic.HashSet<Basic.ISAM.Engine>();
        for (var a = 1; a <= Basic.Databases.Rdd.DataSession.MaxWorkareas; a++)
        {
            var engine = (session.GetWorkArea(a)?.Driver as Basic.Databases.Rdd.IsamDriver)?.Engine;
            if (engine != null && seen.Add(engine)) yield return engine;
        }
    }


    /// <summary>ISAM BEGIN TRANSACTION [LEVEL ...]: EmitBeginTransactionStatement (backend IL)
    /// era un no-op completo (caricava il DatabaseService e lo scartava subito, senza mai
    /// aprire nulla) — a differenza del compilatore PCode, che emette una vera SysCall
    /// BEGIN_TRANSACTION collegata a Engine.BeginTransaction su ogni ISAM engine aperto.
    /// Conseguenza: ISAM ROLLBACK non aveva NULLA da annullare (nessuna transazione era mai
    /// stata aperta), quindi una PUT dentro un blocco BEGIN/ROLLBACK restava permanente —
    /// scoperto verificando la sezione Transazioni di DbIsamFullTests.bas ("[ASSERT] ROLLBACK
    /// FAIL: atteso -120, ottenuto -20": il valore modificato non veniva mai annullato).</summary>
    public static void IsamBeginTransaction(byte level)
    {
        var isoLevel = (Basic.TransactionIsolationLevel)level switch
        {
            Basic.TransactionIsolationLevel.RepeatableRead => Basic.Databases.IsolationLevel.RepeatableRead,
            Basic.TransactionIsolationLevel.Serializable => Basic.Databases.IsolationLevel.Serializable,
            _ => Basic.Databases.IsolationLevel.ReadCommitted
        };
        foreach (var engine in GetOpenIsamEngines()) engine.BeginTransaction(isoLevel);
        try { FindAnySqlDriver()?.ExecRaw("BEGIN TRANSACTION", null, null); } catch { }
    }

    /// <summary>ISAM COMMIT: vedi IsamBeginTransaction — stesso no-op da correggere.</summary>
    public static void IsamCommitTransaction()
    {
        foreach (var engine in GetOpenIsamEngines())
            if (engine.HasActiveTransaction) engine.Commit();
        try { FindAnySqlDriver()?.ExecRaw("COMMIT", null, null); } catch { }
    }

    /// <summary>ISAM ROLLBACK: vedi IsamBeginTransaction — stesso no-op da correggere.</summary>
    public static void IsamRollbackTransaction()
    {
        foreach (var engine in GetOpenIsamEngines())
            if (engine.HasActiveTransaction) engine.Rollback();
        try { FindAnySqlDriver()?.ExecRaw("ROLLBACK", null, null); } catch { }
    }

    private static long IsamHandleFor(string? alias)
    {
        if (alias != null && _isamHandles.TryGetValue(alias, out var h)) return h;
        if (_isamCurrentAlias.Length > 0 && _isamHandles.TryGetValue(_isamCurrentAlias, out var ch)) return ch;
        return _isamHandles.Count > 0 ? _isamHandles.Values.First() : -1;
    }

    public static long IsamOpen(string path, string? alias = null)
    {
        path = ResolveDbPath(path);
        var handle = Current.Database.IsamOpen(path);
        var key = alias ?? "isam";
        _isamHandles[key] = handle;
        _isamCurrentAlias = key;
        return handle;
    }
    public static long IsamOpenSchema(string path, string alias, string schemaJson)
    {
        path = ResolveDbPath(path);
        var handle = Current.Database.IsamOpenSchema(path, alias, schemaJson);
        _isamHandles[alias] = handle;
        _isamCurrentAlias = alias;
        return handle;
    }
    /// <summary>Chiude TUTTE le aree DBF/ISAM e azzera le mappe alias→handle (statiche di
    /// processo). Per gli harness che eseguono più programmi nello stesso processo: un alias
    /// lasciato aperto da un programma (es. `C`) altrimenti viene risolto dal successivo prima
    /// del proprio (DbfLastRec/Bof/Eof provano _dbfHandles prima di _isamHandles).</summary>
    public static void ResetDatabaseState()
    {
        foreach (var h in _isamHandles.Values.ToArray()) { try { Current.Database.IsamClose(h); } catch { } }
        _isamHandles.Clear();
        _isamCurrentAlias = "";
        try { DbfCloseAll(); } catch { }
    }

    public static void IsamClose(string? alias = null)
    {
        // Alias NOMINATO ma sconosciuto = no-op (IsamHandleFor ripiegherebbe sul primo handle aperto e
        // chiuderebbe un'area a caso). Senza alias = area corrente.
        string key;
        long h;
        if (alias != null)
        {
            if (!_isamHandles.TryGetValue(alias, out h)) return;
            key = alias;
        }
        else
        {
            h = IsamHandleFor(null);
            if (h < 0) return;
            key = _isamCurrentAlias.Length > 0 && _isamHandles.ContainsKey(_isamCurrentAlias)
                ? _isamCurrentAlias : _isamHandles.First(kv => kv.Value == h).Key;
        }
        try { Current.Database.IsamClose(h); } catch { }
        _isamHandles.Remove(key);
        if (string.Equals(_isamCurrentAlias, key, StringComparison.OrdinalIgnoreCase)) _isamCurrentAlias = "";
    }
