    /// <summary>Legge il record ISAM CORRENTE come dict {nomeCampo: valore} — pattern
    /// PCodeVM GET_FILE (ISAM): la VM popola l'UDT dal dict, non da binario.</summary>
    public static System.Collections.Generic.Dictionary<string, object?> IsamReadCurrentRecord(string? alias = null)
    {
        var h = IsamHandleFor(alias);
        var result = new System.Collections.Generic.Dictionary<string, object?>(System.StringComparer.OrdinalIgnoreCase);
        if (h < 0) return result;
        var values = Current.Database.IsamReadCurrent(h);
        var names = Current.Database.IsamFieldNames(h);
        for (var i = 0; i < values.Length; i++)
            result[i < names.Length ? names[i] : $"F{i}"] = values[i];
        return result;
    }
