    /// <summary>Riposiziona le aree FIGLIE in relazione quando il PADRE si muove
    /// (GO/SKIP/SEEK) — stessa logica di PCodeProcessor.SyncChildRelations. Prima l'IL non
    /// sincronizzava mai il figlio: dopo SET RELATION, ISAM.FOUND(figlio) restava false
    /// ("Nessun ordine trovato", divergenza IL vs PCode/VM-C).</summary>
    private static void SyncChildRelationsFor(Basic.Databases.Rdd.IDatabaseDriver? moved)
    {
        if (moved == null) return;
        var session = Current.SqlDataSession;
        if (session == null) return;
        for (var a = 1; a <= Basic.Databases.Rdd.DataSession.MaxWorkareas; a++)
        {
            var child = session.GetWorkArea(a)?.Driver;
            if (child != null && child.HasActiveRelation && ReferenceEquals(child.ParentRelationDriver, moved))
            {
                try { child.SyncRelation(); } catch { }
            }
        }
    }

