    // ==================================================================
    // GAP CHIUSI 2026-08-29 — letture DBF/ISAM/SPEED/RDD/NET mancanti.
    // Stessa base dati della PCodeVM (Current.SqlDataSession) — regola §0bis:
    // una sola implementazione (IlRuntime), PCodeVM e ILBackend la chiamano.
    // ==================================================================
    private static Basic.Databases.Rdd.IDatabaseDriver? DbDriverFor(string? alias)
    {
        try
        {
            var session = Current.SqlDataSession;
            var wa = string.IsNullOrWhiteSpace(alias)
                ? session.GetWorkArea(session.CurrentArea)
                : session.GetWorkArea(FindAreaByAlias(session, alias));
            return wa?.Driver;
        }
        catch { return null; }
    }
    /// DBF.DBRELATION([area]) / ISAM.DBRELATION([area]) → ESPRESSIONE della relazione attiva
    /// (stringa vuota se non c'e' relazione), come in Clipper e come dichiara la StdLib
    /// (StringType; vedi ClipperDbfLegacySyntax.bas: `"DBRELATION: " + DBF.DBRELATION()`).
    /// Prima ritornava -1.0/0.0 (double) mentre il tipo dichiarato e' stringa: il codegen IL
    /// emetteva un double dove il type system si aspettava una stringa → InvalidProgramException
    /// (§ trovato da MiniTests/dbf/dbf_state.bas).
    public static string DbfRelation(string? alias = null)
    {
        try
        {
            var drv = DbDriverFor(alias);
            if (drv is null) return "";
            // SetRelation memorizza la chiave sul driver FIGLIO; DBRELATION() si legge dall'area
            // PADRE (quella che ha eseguito SET RELATION): cerca il figlio che la punta.
            if (!string.IsNullOrEmpty(drv.RelationKeyExpression)) return drv.RelationKeyExpression!;
            var session = Current.SqlDataSession;
            for (var a = 1; a <= Basic.Databases.Rdd.DataSession.MaxWorkareas; a++)
            {
                var child = session.GetWorkArea(a)?.Driver;
                if (child != null && child.HasActiveRelation && ReferenceEquals(child.ParentRelationDriver, drv))
                    return child.RelationKeyExpression ?? "";
            }
            return "";
        }
        catch { return ""; }
    }
    /// DBF.INDEXKEY([area]) / ISAM.INDEXKEY([area]) → chiave corrente.
    public static string DbfIndexKey(string? alias = null)
    {
        try { return DbDriverFor(alias)?.CurrentKey() ?? ""; } catch { return ""; }
    }
    /// DBF.INDEXORD([area]) / ISAM.INDEXORD([area]) → ordine corrente.
    public static long DbfIndexOrd(string? alias = null)
    {
        try { return DbDriverFor(alias)?.CurrentKeyNo() ?? 0; } catch { return 0; }
    }
    /// DBF.FIELDNAME(fieldNum, [area]) / ISAM.FIELDNAME → nome campo.
    /// <summary>DBF.FIELDNAME(fieldNum [, area]) → nome del campo, 1-BASED come in Clipper
    /// (FIELDNAME(1) = primo campo dichiarato). Unica implementazione per IL e PCode (§0bis):
    /// per i DBF legge i campi dall'ENGINE (ordine reale del file), per ISAM dal driver.
    /// Prima IL usava drv.Fields con indice 0-based e PCode l'engine con indice 1-based: lo
    /// stesso FIELDNAME(n) dava campi diversi (§ MiniTests/dbf/dbf_state.bas).</summary>
    public static string DbfFieldName(object? fieldIndex, object? area = null)
    {
        try
        {
            var fi = (int)Convert.ToDouble(fieldIndex ?? 0) - 1;
            if (fi < 0) return "";
            var drv = DbDriverFor(area?.ToString());
            if (drv is null) return "";
            if (drv is Basic.Databases.Rdd.DbfDriver dbf && dbf._engine is not null)
            {
                var fields = dbf._engine.GetFields();
                return fi < fields.Count ? fields[fi].Name : "";
            }
            return fi < drv.Fields.Length ? drv.Fields[fi].Name : "";
        }
        catch { return ""; }
    }
    /// DBF.NETERR() → stato ultimo errore di rete (CommonLib).
    public static double DbfNetErr() => CommonLib.Network.NetworkUtils.NetErr;
    /// DBF.LOOKUP([area, ]key, field) → valore campo del record cercato (via SEEK).
    public static object? DbfLookup(object?[] args)
    {
        try
        {
            /* Ordine degli argomenti della StdLib: LOOKUP(returnField, searchExpr,
             * searchField [, alias]). Prima li leggeva come (area, key, field) → il campo
             * ritornato era il valore cercato e la ricerca era per CHIAVE DI INDICE (senza
             * indice non trovava nulla) → LOOKUP rispondeva sempre vuoto
             * (§ MiniTests/dbf/dbf_lock_filter.bas). */
            if (args.Length < 3) return null;
            var retField = args[0]?.ToString() ?? "";
            var searchVal = args[1];
            var searchField = args[2]?.ToString() ?? "";
            var alias = args.Length >= 4 ? args[3]?.ToString() : null;
            var drv = DbDriverFor(alias);
            if (drv == null || retField.Length == 0 || searchField.Length == 0) return null;
            /* Scan del driver: primo record in cui searchField == searchExpr. */
            try
            {
                drv.GoTop();
                for (var rec = 0; rec < drv.RecCount; rec++)
                {
                    var sf = drv.GetFieldIndex(searchField);
                    if (sf >= 0 && string.Equals(drv.GetFieldValue(sf)?.ToString(), searchVal?.ToString(), StringComparison.OrdinalIgnoreCase))
                    {
                        var rf = drv.GetFieldIndex(retField);
                        return rf >= 0 ? drv.GetFieldValue(rf) : null;
                    }
                    drv.Skip(1);
                }
            }
            catch { }
            return null;
        }
        catch { return null; }
    }
