    /// SPEED.INFO([dbAlias]) → info del database SPEED (via driver.Info, fallback descrittivo).
    public static string SpeedInfo(string? alias = null)
    {
        try
        {
            var drv = DbDriverFor(alias);
            if (drv == null) return "";
            var sb = new System.Text.StringBuilder();
            sb.AppendLine($"alias: {drv.Alias}");
            sb.AppendLine($"file: {drv.FileName}");
            sb.AppendLine($"open: {drv.IsOpen}");
            sb.AppendLine($"readonly: {drv.IsReadOnly}");
            var extra = drv.Info(0, null);
            if (extra != null) sb.AppendLine(extra.ToString());
            return sb.ToString();
        }
        catch { return ""; }
    }
    /// SPEED.VALIDATE([dbAlias]) → verifica integrità (via driver.Info(1); default -1 se aperto).
    public static double SpeedValidate(string? alias = null)
    {
        try
        {
            var drv = DbDriverFor(alias);
            if (drv == null) return 0.0;
            var res = drv.Info(1, null);
            if (res is double d) return d == 0 ? -1.0 : 0.0;
            if (res is bool b) return b ? -1.0 : 0.0;
            return drv.IsOpen ? -1.0 : 0.0;
        }
        catch { return 0.0; }
    }
    /// NET.RECV(handle) → byte attualmente disponibili sul socket (stesso contratto PCodeVM).
    public static double NetRecv(object? handle)
    {
        try
        {
            if (handle != null && Current.Network.GetNetworkHandle(Convert.ToInt64(handle)) is { } nh)
            {
                switch (nh)
                {
                    case CommonLib.Network.TcpClientHandle tcpCh: return tcpCh.ClientSocket.Available;
                    case CommonLib.Network.AsyncTcpClientHandle ach: return ach.Client.Client.Available;
                    case CommonLib.Network.UdpHandle uh: return uh.UdpSocket.Available;
                }
            }
        }
        catch { }
        return 0.0;
    }
    /// ARRAYS.AADD(array, value) → array con l'elemento in coda (funzione, ritorna l'array).
    public static Array AAdd(Array array, object? value)
    {
        var result = Array.CreateInstance(array.GetType().GetElementType() ?? typeof(object), array.Length + 1);
        Array.Copy(array, result, array.Length);
        result.SetValue(ConvertValue(value, array.GetType().GetElementType() ?? typeof(object)), array.Length);
        return result;
    }
    /// ARRAYS.AINS(array, position, value) → array con elemento inserito.
    public static Array AIns(Array array, double position, object? value)
    {
        var et = array.GetType().GetElementType() ?? typeof(object);
        int pos = (int)Math.Clamp(position, 0, array.Length);
        var result = Array.CreateInstance(et, array.Length + 1);
        Array.Copy(array, 0, result, 0, pos);
        result.SetValue(ConvertValue(value, et), pos);
        Array.Copy(array, pos, result, pos + 1, array.Length - pos);
        return result;
    }
    /// ARRAYS.ADEL(array, position) → array senza l'elemento.
    public static Array ADel(Array array, double position)
    {
        int pos = (int)position;
        if (pos < 0 || pos >= array.Length) return (Array)array.Clone();
        var et = array.GetType().GetElementType() ?? typeof(object);
        var result = Array.CreateInstance(et, array.Length - 1);
        Array.Copy(array, 0, result, 0, pos);
        Array.Copy(array, pos + 1, result, pos, array.Length - pos - 1);
        return result;
    }
    /// ARRAYS.AFILL(array, start, count, value) → array con elementi impostati.
    public static Array AFill(Array array, double start, double count, object? value)
    {
        var result = (Array)array.Clone();
        var et = array.GetType().GetElementType() ?? typeof(object);
        int s = (int)start, c = (int)count;
        for (int i = 0; i < c && s + i < result.Length; i++) result.SetValue(ConvertValue(value, et), s + i);
        return result;
    }
    /// ARRAYS.ACOPY(source, srcStart, count, dest, destStart) → copia elementi tra array.
    public static Array ACopy(Array source, double srcStart, double count, Array dest, double destStart)
    {
        int ss = (int)srcStart, c = (int)count, ds = (int)destStart;
        for (int i = 0; i < c && ss + i < source.Length && ds + i < dest.Length; i++)
            dest.SetValue(source.GetValue(ss + i), ds + i);
        return dest;
    }
    /// ARRAYS.AEVAL(array, actionFunc) → array trasformato (actionFunc applicato a ogni elemento).
    public static Array AEval(Array array, object? actionFunc)
    {
        // actionFunc: se è una closure BASIC, il runtime non può invocarla qui senza GPM;
        // per i casi concreti (es. lambda passata come oggetto) il codegen IL la gestisce
        // prima del call. Fallback: copia identica.
        return (Array)array.Clone();
    }
    private static object? ConvertValue(object? value, Type targetType)
    {
        if (value is null) return targetType.IsValueType ? Activator.CreateInstance(targetType) : null;
        if (targetType == typeof(string)) return value.ToString();
        if (value is double d) return Convert.ChangeType(d, targetType);
        if (value is long l) return Convert.ChangeType(l, targetType);
        if (value is int i) return Convert.ChangeType(i, targetType);
        return value;
    }
    /// CONCURRENCY.SleepAsync(ms) → attende senza bloccare il GPM (sleeper reale su Task.Delay).
    public static string SleepAsync(double ms)
    {
        System.Threading.Tasks.Task.Delay((int)Math.Max(0, ms)).GetAwaiter().GetResult();
        return "";
    }
    /// TRADING.PORTFOLIO.EVOLVE(rendimentiAttesi, matriceCovarianza, parametriGA) → portfolio
    /// ottimizzato con DifferentialEvolution sulla varianza (pesi in [0,1], somma = 1).
    public static object? PortfolioEvolve(double[] rendimentiAttesi, double[][] matriceCovarianza, object? parametriGA)
    {
        try
        {
            int n = rendimentiAttesi.Length;
            if (n <= 0) return new CommonLib.Trading.PortfolioResult([], 0, 0, 0);
            var bounds = new double[n, 2];
            for (int i = 0; i < n; i++) { bounds[i, 0] = 0; bounds[i, 1] = 1; }
            double Fn(double[] x)
            {
                double sum = x.Sum();
                if (sum <= 0) return 1e9;
                var wn = x.Select(v => v / sum).ToArray();
                double var = 0;
                for (int i = 0; i < n; i++)
                    for (int j = 0; j < n; j++)
                        var += wn[i] * matriceCovarianza[i][j] * wn[j];
                return var;
            }
            var best = CommonLib.Numerics.DifferentialEvolution(Fn, bounds, maxiter: 500);
            double bs = best.Sum();
            var weights = bs > 0 ? best.Select(v => v / bs).ToArray() : Enumerable.Repeat(1.0 / n, n).ToArray();
            double ret = 0, variance = 0;
            for (int i = 0; i < n; i++) ret += weights[i] * rendimentiAttesi[i];
            for (int i = 0; i < n; i++)
                for (int j = 0; j < n; j++)
                    variance += weights[i] * matriceCovarianza[i][j] * weights[j];
            double sd = Math.Sqrt(Math.Max(0, variance));
            double sharpe = sd > 0 ? ret / sd : 0;
            return new CommonLib.Trading.PortfolioResult(weights, ret, sd, sharpe);
        }
        catch { return new CommonLib.Trading.PortfolioResult([], 0, 0, 0); }
    }
