    {
        var h = IsamHandleFor(alias); if (h < 0) return;
        var (ast, eval) = RuntimeFilterParser.CreateEvaluator(condition?.ToString());
        try { Current.Database.IsamCopyTo(h, destPath, ast, eval); } catch { }
    }
    public static void IsamSortTo(string destPath, string[] fields, bool[] descending, object? condition, string? alias = null)
    {
