    public static void IsamJoin(string secondaryAlias, string destPath, object? condition, string? alias = null)
    {
        var h = IsamHandleFor(alias); var hs = IsamHandleFor(secondaryAlias);
        if (h < 0 || hs < 0) return;
        var (ast, eval) = RuntimeFilterParser.CreateEvaluator(condition?.ToString());
        if (ast is null) ast = new BooleanExpr(true, default!);
        try { Current.Database.IsamJoin(h, hs, destPath, ast, eval); } catch { }
    }
    public static void IsamSetRelation(string keyExpression, string? childAlias = null, string? alias = null)
    {
        // `SET RELATION ON <parent> TO <key> INTO <child>`: alias = PADRE ("ON Clienti"),
        // childAlias = FIGLIO ("INTO Ordini"). La relazione va impostata sul FIGLIO, con il
        // PADRE come parent (IsamDriver.SetRelation(parent, key)). Prima i due handle erano
        // invertiti (relazione sul padre con parent=figlio) → SyncRelation non scattava mai
        // sul figlio e ISAM.FOUND(figlio) restava sempre false ("Nessun ordine trovato",
        // divergenza IL vs PCode/VM-C).
        var parentHandle = IsamHandleFor(alias);
        var childHandle = childAlias != null ? IsamHandleFor(childAlias) : -1;
        if (parentHandle < 0) return;
        try { Current.Database.IsamSetRelation(childHandle >= 0 ? childHandle : parentHandle, parentHandle, keyExpression); } catch { }
    }
    public static void IsamLock(bool isRecordLock, string? alias = null)
    {
        var h = IsamHandleFor(alias); if (h < 0) return;
        try { Current.Database.IsamLock(h, isRecordLock); } catch { }
    }
    public static void IsamUnlock(bool isRecordLock, string? alias = null)
    {
        var h = IsamHandleFor(alias); if (h < 0) return;
        try { Current.Database.IsamUnlock(h, isRecordLock); } catch { }
    }
    public static void IsamSetOrder(string indexName, string? alias = null)
    {
        try
        {
            var session = Current.SqlDataSession;
            var wa = string.IsNullOrWhiteSpace(alias)
                ? session.GetWorkArea(session.CurrentArea)
                : session.GetWorkArea(FindAreaByAlias(session, alias));
            if (wa?.Driver is Basic.Databases.Rdd.IsamDriver isam && isam.Engine is { } eng)
                eng.SetActiveOrder(indexName ?? "");
        }
        catch { }
    }

    private static int FindAreaByAlias(Basic.Databases.Rdd.DataSession session, string alias)
    {
        for (var a = 1; a <= Basic.Databases.Rdd.DataSession.MaxWorkareas; a++)
        {
            var wa = session.GetWorkArea(a);
            if (wa != null && string.Equals(wa.Alias, alias, StringComparison.OrdinalIgnoreCase)) return a;
        }
        return session.CurrentArea;
    }

    // ================================================================
    // SPEED — delega a IDatabaseService
    // ================================================================
    private static readonly System.Collections.Generic.Dictionary<string, long> _speedHandles = new(System.StringComparer.OrdinalIgnoreCase);
    private static string _speedCurrentAlias = "";

    private static long SpeedHandleFor(string? alias)
    {
        if (alias != null && _speedHandles.TryGetValue(alias, out var h)) return h;
        if (_speedCurrentAlias.Length > 0 && _speedHandles.TryGetValue(_speedCurrentAlias, out var ch)) return ch;
        return _speedHandles.Count > 0 ? _speedHandles.Values.First() : -1;
    }

    /// <summary>Chiude tutti i database SPEED aperti da questo runtime e azzera il registro.
    /// Il WAL SPEED usa FileShare.None: senza chiusura a fine run l'handle resta locked e la
    /// gamba successiva nello STESSO processo (harness di parità IL/PCode/VMC) fallisce con
    /// "file in uso" (vedi Bugs/(open) - SPEED-Parity-Runner-WAL-Lock).</summary>
    public static void SpeedCloseAll()
    {
        foreach (var h in _speedHandles.Values.ToArray())
        {
            // Il Database va disposto ESPLICITAMENTE: SpeedClose→DisposeHandle agisce solo
            // su entry IDisposable, mentre l'handle SPEED è un driver (SpeedDriver.Close non
            // viene chiamato) → il WAL resterebbe aperto.
            try { Current.Database.SpeedGetDatabaseFor(h)?.Dispose(); } catch { /* best effort */ }
            try { Current.Database.SpeedClose(h); } catch { /* best effort */ }
        }
        _speedHandles.Clear();
        _speedCurrentAlias = "";
    }

    public static long SpeedOpen(string path, string? alias = null)
    {
        path = ResolveDbPath(path);
        var handle = Current.Database.SpeedOpen(path);
        var key = alias ?? "speed";
        _speedHandles[key] = handle;
        _speedCurrentAlias = key;
        return handle;
    }

    /// <summary>
    /// `SPEED USE tableName FROM dbAlias OF Type ALIAS tableAlias INDEXED BY key`: prima
    /// chiamava solo <see cref="SpeedOpen"/> con `dbAlias` come path — ignorava `tableName`,
    /// lo schema UDT e `INDEXED BY`, riaprendo un secondo `Database` invece di legarsi alla
    /// tabella corretta nel database già aperto (vedi
    /// `DatabaseService.Commercial.SpeedOpenSchema` per il dettaglio completo del bug e del
    /// fix). Risolve `dbAlias` all'handle già aperto (stesso registro di <see cref="SpeedOpen"/>)
    /// e lo passa a `SpeedOpenSchema` invece del path grezzo.
    /// </summary>
    public static long SpeedUseSchema(string dbAlias, string tableName, string tableAlias, string schemaJson)
    {
        var dbHandle = SpeedHandleFor(dbAlias);
        if (dbHandle < 0) return -1;
        var handle = Current.Database.SpeedOpenSchema(tableName, dbHandle, tableAlias, schemaJson);
        if (handle >= 0) { _speedHandles[tableAlias] = handle; _speedCurrentAlias = tableAlias; }
        return handle;
    }
    public static void SpeedClose(string? alias = null)
    {
        var h = SpeedHandleFor(alias); if (h >= 0) { try { Current.Database.SpeedClose(h); } catch { } }
        _speedHandles.Remove(alias ?? _speedCurrentAlias);
    }
    /// <summary>SPEED.EOF(alias) → BIT (-1 vero / 0 falso) dal cursore dell'area SPEED.
    /// Prima `SPEED.EOF` cadeva su `Eof(long)` (handle FILE) perché il case EofFunc non
    /// copriva il namespace SPEED → "Handle file non valido".</summary>
    public static double SpeedEof(string? alias = null)
    {
        var h = SpeedHandleFor(alias);
        if (h < 0) return 0.0;
        try { return Current.Database.SpeedEof(h) ? -1.0 : 0.0; } catch { return 0.0; }
    }
