    // ================================================================
    // SPEED SELECT / CREATE VIEW / REFRESH VIEW / DROP VIEW
    //
    // Il motore (Basic.Databases.Speed.Database.ExecuteQuery) è già completo — JOIN
    // indicizzato, WHERE con ottimizzatore, GROUP BY/aggregati, HAVING, ORDER BY — e IlBackend
    // vi accede DIRETTAMENTE (BRT -> modules/Database è transitivo, verificato: IlBackend non
    // referenzia modules/Database esplicitamente ma lo vede comunque). Prima questi 4
    // statement erano EmitDatabaseNoop() incondizionati: nessuna delle due metà (wiring +
    // motore) esisteva ancora lato compilatore/IlRuntime.
    // ================================================================

    /// <summary>Cache dei piani di query compilati (P-Code), per testo espressione GIÀ
    /// appiattito (Alias__Campo) — una query SPEED valuta la STESSA espressione su
    /// centinaia/migliaia di righe, non ha senso ricompilare a ogni riga.</summary>
    private static readonly System.Collections.Concurrent.ConcurrentDictionary<string, DbExprPCodeEvaluator?> _speedQueryExprCache = new();

    /// <summary>Definizione (alias FROM sorgente + piano JSON) delle VIEW create in questa
    /// esecuzione — serve a REFRESH VIEW (ri-esegue la STESSA query) e DROP VIEW (deve
    /// risalire al Database che la contiene, non c'è un FROM esplicito in quella sintassi).
    /// Vive solo per la durata del programma, non persiste fra esecuzioni (le viste SPEED
    /// sono tabelle fisiche nel database, ma la loro DEFINIZIONE di query è un concetto BASIC,
    /// non salvato dal motore).</summary>
    private static readonly System.Collections.Generic.Dictionary<string, (string FromAlias, string PlanJson)> _speedViewDefs = new(System.StringComparer.OrdinalIgnoreCase);

    /// <summary>
    /// Valuta una singola espressione di query (proiezione SELECT, WHERE, condizione JOIN,
    /// GROUP BY, HAVING, ORDER BY) contro una riga risultato. Le funzioni di aggregazione
    /// (COUNT/SUM/AVG/MIN/MAX) vengono spacchettate qui: Database.ExecuteGroupByAndHavingPhase
    /// richiama l'evaluator con l'espressione INTERA (es. "SUM(Ordini.Importo)") per OGNI riga
    /// del gruppo e si aspetta il valore GREZZO del singolo campo — è Database.Aggregate (nel
    /// motore) a sommare/contare i valori raccolti, non l'evaluator. COUNT(*) ritorna una
    /// sentinella 1 per riga (Aggregate poi fa Count sulla lista, non Sum).
    /// </summary>
    private static object? EvaluateSpeedQueryExpr(string exprText, System.Collections.Generic.Dictionary<string, object?> row, string[] knownAliases)
    {
        var trimmed = exprText.Trim();
        var parenIdx = trimmed.IndexOf('(');
        if (parenIdx > 0 && trimmed.EndsWith(')'))
        {
            var func = trimmed[..parenIdx].Trim().ToUpperInvariant();
            if (func is "COUNT" or "SUM" or "AVG" or "MIN" or "MAX")
            {
                var inner = trimmed[(parenIdx + 1)..^1].Trim();
                if (func == "COUNT" && inner == "*") return 1L;
                return EvaluateSpeedFlatExpr(inner, row, knownAliases);
            }
        }
        return EvaluateSpeedFlatExpr(trimmed, row, knownAliases);
    }

    /// <summary>
    /// Il contesto riga di Database.ExecuteQuery usa SEMPRE chiavi qualificate "Alias.Campo"
    /// (QualifyRow), anche per una singola tabella senza JOIN — ma "Alias.Campo" non è
    /// un'espressione BASIC valida per il parser P-Code (il punto è l'operatore di chiamata
    /// namespace-qualificata, "Alias" non è un namespace reale). Si appiattisce sia il testo
    /// dell'espressione ("Alias.Campo" → "Alias__Campo", solo per gli alias NOTI di questa
    /// query) sia le chiavi del contesto riga, poi si compila/valuta il tutto in forma piatta.
    /// </summary>
    private static object? EvaluateSpeedFlatExpr(string exprText, System.Collections.Generic.Dictionary<string, object?> row, string[] knownAliases)
    {
        var flatExpr = exprText;
        foreach (var alias in knownAliases)
            flatExpr = flatExpr.Replace(alias + ".", alias + "__", StringComparison.Ordinal);
        var compiled = _speedQueryExprCache.GetOrAdd(flatExpr, DbExprPCodeEvaluator.TryCompile);
        if (compiled is null) return null;
        var flatRow = new System.Collections.Generic.Dictionary<string, object?>(System.StringComparer.OrdinalIgnoreCase);
        foreach (var kv in row)
        {
            // I campi STRING * N (lunghezza fissa) arrivano dal marshaller SPEED riempiti di
            // spazi a destra fino a N — un confronto `Citta = "Roma"` contro il valore grezzo
            // "Roma                          " fallisce sempre (0/false). QueryOptimizer.
            // RowMatchesEqualities (usato dal percorso indice) fa già TrimEnd() per lo stesso
            // motivo; qui serve lo stesso trattamento per il percorso generico (WHERE/HAVING/
            // JOIN via evaluator, non tramite indice).
            var value = kv.Value is string s ? s.TrimEnd() : kv.Value;
            flatRow[kv.Key] = value;
            var dot = kv.Key.IndexOf('.');
            if (dot > 0) flatRow[kv.Key[..dot] + "__" + kv.Key[(dot + 1)..]] = value;
        }
        return compiled.Evaluate(flatRow);
    }

    /// <summary>Isola "Alias.Campo = AltroAlias.Campo" (unica forma di condizione JOIN
    /// supportata dal motore, vedi QueryOptimizer.ResolveJoinIndex/Database.ExecuteJoinPhase)
    /// nel lato sinistro (espressione da valutare sulla riga SINISTRA già qualificata) e nel
    /// nome campo destro (usato per trovare l'indice sulla tabella JOIN). Null se la
    /// condizione non è un'uguaglianza a due termini con l'alias JOIN da un lato.</summary>
    private static (string LeftKeyExpr, string RightFieldName)? SplitSpeedJoinCondition(string condition, string joinAlias)
    {
        var text = condition.Trim();
        if (text.StartsWith('(') && text.EndsWith(')')) text = text[1..^1].Trim();
        var eqIdx = text.IndexOf('=');
        if (eqIdx < 0) return null;
        var left = text[..eqIdx].Trim();
        var right = text[(eqIdx + 1)..].Trim();
        var prefix = joinAlias + ".";
        if (right.StartsWith(prefix, System.StringComparison.OrdinalIgnoreCase)) return (left, right[prefix.Length..]);
        if (left.StartsWith(prefix, System.StringComparison.OrdinalIgnoreCase)) return (right, left[prefix.Length..]);
        return null;
    }

    /// <summary>Deserializza il piano JSON costruito a compile-time
    /// (IlProgramCompiler.BuildSpeedQueryPlanJson) in un Basic.Databases.Speed.QueryPlan
    /// pronto per Database.ExecuteQuery/RefreshView. `tableNameForAlias` risolve un alias SPEED
    /// (nome runtime, usato per gli handle) al nome REALE della tabella nel manifest (possono
    /// differire, vedi IDatabaseService.SpeedGetTableNameFor).</summary>
    private static (Basic.Databases.Speed.QueryPlan? Plan, string[] DestFields, string? JoinAlias) ParseSpeedQueryPlanJson(
        string planJson, System.Func<string, string?> tableNameForAlias)
    {
        var doc = System.Text.Json.JsonDocument.Parse(planJson);
        var root = doc.RootElement;
        var fromAlias = root.GetProperty("FromAlias").GetString() ?? "";
        var fromTable = tableNameForAlias(fromAlias) ?? fromAlias;

        var projections = new System.Collections.Generic.List<Basic.Databases.Speed.QueryProjection>();
        if (root.TryGetProperty("Fields", out var fieldsEl))
            foreach (var f in fieldsEl.EnumerateArray())
                projections.Add(new Basic.Databases.Speed.QueryProjection(
                    f.GetProperty("Expr").GetString() ?? "", f.GetProperty("Alias").GetString() ?? ""));

        Basic.Databases.Speed.QueryJoin? join = null;
        string? joinAlias = null;
        if (root.TryGetProperty("JoinAlias", out var jaEl))
        {
            joinAlias = jaEl.GetString();
            var joinCondition = root.TryGetProperty("JoinCondition", out var jcEl) ? jcEl.GetString() ?? "" : "";
            if (joinAlias is not null && SplitSpeedJoinCondition(joinCondition, joinAlias) is { } split)
            {
                var joinTable = tableNameForAlias(joinAlias) ?? joinAlias;
                join = new Basic.Databases.Speed.QueryJoin(
                    new Basic.Databases.Speed.QuerySource(joinTable, joinAlias), split.LeftKeyExpr, split.RightFieldName);
            }
        }

        var where = root.TryGetProperty("Where", out var whereEl) ? whereEl.GetString() : null;
        System.Collections.Immutable.ImmutableArray<string>? groupBy = null;
        if (root.TryGetProperty("GroupBy", out var gbEl))
            groupBy = [.. gbEl.EnumerateArray().Select(g => g.GetString() ?? "")];
        var having = root.TryGetProperty("Having", out var havEl) ? havEl.GetString() : null;
        System.Collections.Immutable.ImmutableArray<Basic.Databases.Speed.QueryOrderBy>? orderBy = null;
        if (root.TryGetProperty("OrderBy", out var obEl))
            orderBy = [.. obEl.EnumerateArray().Select(o =>
                new Basic.Databases.Speed.QueryOrderBy(o.GetProperty("Expr").GetString() ?? "", o.GetProperty("Desc").GetBoolean()))];

        var destFields = root.TryGetProperty("DestFields", out var dfEl)
            ? dfEl.EnumerateArray().Select(d => d.GetString() ?? "").ToArray()
            : [];

        var plan = new Basic.Databases.Speed.QueryPlan(
            [.. projections], "", "",
            new Basic.Databases.Speed.QuerySource(fromTable, fromAlias),
            join, where, groupBy, having, orderBy);

        return (plan, destFields, joinAlias);
    }

    /// <summary>`SPEED SELECT ... INTO arr() OF Type FROM ... [JOIN ...] [WHERE ...] [GROUP BY
    /// ...] [HAVING ...] [ORDER BY ...]`: prima un no-op incondizionato. Ritorna le righe
    /// risultato GIÀ riordinate secondo DestFields (l'ordine dei campi del TYPE di
    /// destinazione) — il compilatore (EmitCopyObjectArrayArrayToUdtArrayTarget) copia
    /// ciascuna riga posizionalmente nello struct UDT di destinazione, stesso schema di
    /// EmitCopyObjectArrayToTarget per un singolo record.</summary>
    public static object?[][] SpeedSelect(string planJson)
    {
        string? TableNameFor(string alias)
        {
            var h = SpeedHandleFor(alias);
            return h < 0 ? null : Current.Database.SpeedGetTableNameFor(h);
        }

        var (plan, destFields, joinAlias) = ParseSpeedQueryPlanJson(planJson, TableNameFor);
        if (plan is null) return [];
        var fromHandle = SpeedHandleFor(plan.FromSource.Alias);
        if (fromHandle < 0) return [];
        var db = Current.Database.SpeedGetDatabaseFor(fromHandle);
        if (db is null) return [];

        var knownAliases = joinAlias is null ? [plan.FromSource.Alias] : new[] { plan.FromSource.Alias, joinAlias };
        Basic.Databases.Speed.ExpressionEvaluator evaluator = (expr, row) => EvaluateSpeedQueryExpr(expr, row, knownAliases);

        List<System.Collections.Generic.Dictionary<string, object?>> rows;
        try { rows = db.ExecuteQuery(plan, evaluator); } catch { return []; }

        var result = new object?[rows.Count][];
        for (var i = 0; i < rows.Count; i++)
        {
            var arr = new object?[destFields.Length];
            for (var j = 0; j < destFields.Length; j++)
                arr[j] = rows[i].TryGetValue(destFields[j], out var v) ? v : null;
            result[i] = arr;
        }
        return result;
    }

    /// <summary>`SPEED CREATE VIEW viewName OF Type AS SELECT ...`: prima un no-op
    /// incondizionato. Crea la tabella fisica della vista (schema derivato dal TYPE di
    /// destinazione, risolto a compile-time — vedi IlProgramCompiler.BuildSpeedQueryPlanJson/
    /// BuildIsamSchemaJson) e la popola subito eseguendo la query una prima volta.</summary>
    public static void SpeedCreateView(string fromAlias, string viewName, string schemaJson, string planJson)
    {
        var h = SpeedHandleFor(fromAlias); if (h < 0) return;
        if (!Current.Database.SpeedCreateViewTable(h, viewName, schemaJson)) return;
        _speedViewDefs[viewName] = (fromAlias, planJson);
        RefreshSpeedViewTable(viewName, fromAlias, planJson);
    }

    /// <summary>`SPEED REFRESH VIEW viewName`: prima un no-op incondizionato. Ri-esegue la
    /// STESSA query della CREATE VIEW (cache in-process, vedi _speedViewDefs) e ripopola la
    /// tabella della vista.</summary>
    public static void SpeedRefreshView(string viewName)
    {
        if (!_speedViewDefs.TryGetValue(viewName, out var def)) return;
        RefreshSpeedViewTable(viewName, def.FromAlias, def.PlanJson);
    }

    private static void RefreshSpeedViewTable(string viewName, string fromAlias, string planJson)
    {
        string? TableNameFor(string alias)
        {
            var ah = SpeedHandleFor(alias);
            return ah < 0 ? null : Current.Database.SpeedGetTableNameFor(ah);
        }

        var (plan, _, joinAlias) = ParseSpeedQueryPlanJson(planJson, TableNameFor);
        if (plan is null) return;
        var h = SpeedHandleFor(fromAlias); if (h < 0) return;
        var db = Current.Database.SpeedGetDatabaseFor(h); if (db is null) return;

        var knownAliases = joinAlias is null ? new[] { fromAlias } : new[] { fromAlias, joinAlias };
        Basic.Databases.Speed.ExpressionEvaluator evaluator = (expr, row) => EvaluateSpeedQueryExpr(expr, row, knownAliases);
        try { db.RefreshView(viewName, plan, evaluator); } catch { }
    }

    /// <summary>`SPEED DROP VIEW viewName`: prima un no-op incondizionato.</summary>
    public static void SpeedDropView(string viewName)
    {
        if (!_speedViewDefs.TryGetValue(viewName, out var def)) return;
        var h = SpeedHandleFor(def.FromAlias);
        var db = h >= 0 ? Current.Database.SpeedGetDatabaseFor(h) : null;
        try { db?.DropView(viewName); } catch { }
        _speedViewDefs.Remove(viewName);
    }

