    private static readonly System.Collections.Generic.Dictionary<string, long> _ledgerHandles = new(System.StringComparer.OrdinalIgnoreCase);
    private static string _ledgerCurrentAlias = "";

    private static long LedgerHandleFor(string? alias)
    {
        if (alias != null && _ledgerHandles.TryGetValue(alias, out var h)) return h;
        if (_ledgerCurrentAlias.Length > 0 && _ledgerHandles.TryGetValue(_ledgerCurrentAlias, out var ch)) return ch;
        return _ledgerHandles.Count > 0 ? _ledgerHandles.Values.First() : -1;
    }

