    /// <summary>LOCALPORT(handle): porta locale del socket (parità VM). Il handle BASIC è
    /// l'ID numerico — risolto al NetworkHandle via il servizio. Prima il backend IL non
    /// supportava LOCALPORT/PORT/REMOTE ("funzione builtin non ancora supportata").</summary>
    /// <summary>MUTEX.TRYLOCK(mu) (parità Go mu.TryLock(), Go 1.18): acquisizione NON bloccante —
    /// ritorna 1 se acquisito, 0 altrimenti. RWMUTEX → TryLockNonBlocking scrittore.</summary>
    public static double MutexTryLock(object? mu)
    {
        if (mu is Basic.Runtime.Gpm.PCodeRwMutex rw) return rw.TryLockNonBlocking() ? -1.0 : 0.0;
        if (mu is Basic.Runtime.Gpm.PCodeMutex m) return m.TryLockNonBlocking() ? -1.0 : 0.0;
        return 0.0;
    }

