    // ── Events ────────────────────────────────────────────────────────
    private static readonly ConcurrentDictionary<string, List<(WeakReference<object>? Source, Delegate Handler)>> _eventSubscriptions = new();

    /// <summary>Sottoscrive un handler a un evento. Se <paramref name="source"/> è null
    /// l'evento è GLOBALE per NOME (dispatch su tutti gli handler registrati col nome, parità
    /// ADD HANDLER/RAISE EVENT nudi su PCodeVM/VM-C); altrimenti è legato all'istanza sorgente.</summary>
    public static void EventSubscribe(object source, string eventName, object handler)
    {
        if (handler is not Delegate handlerDel) return;
        var key = source is null ? eventName : EventKey(source, eventName);
        _eventSubscriptions.GetOrAdd(key, _ => []).Add((source is null ? null : new WeakReference<object>(source), handlerDel));
    }

    public static void EventUnsubscribe(object source, string eventName, object handler)
    {
        if (handler is not Delegate handlerDel) return;
        var key = source is null ? eventName : EventKey(source, eventName);
        if (!_eventSubscriptions.TryGetValue(key, out var subs)) return;
        // Confronto per Method+Target (ogni emissione crea un delegate NUOVO che wrappa la
        // stessa procedura — ReferenceEquals sul delegate fallirebbe sempre per REMOVE).
        var dead = subs.Where(s =>
            (source is not null && (s.Source is null || !s.Source.TryGetTarget(out _))) ||
            (s.Handler.Method == handlerDel.Method && ReferenceEquals(s.Handler.Target, handlerDel.Target)))
            .ToArray();
        foreach (var d in dead) subs.Remove(d);
    }

    /// <summary>ADD HANDLER per symbolId: il delegate dell'handler si crea a RUNTIME (il
    /// MethodBuilder non è ancora CreateType quando il codegen farebbe ldftn →
    /// InvalidProgramException). Stesso schema di RegisterKeyHandlerBySymbol.</summary>
    public static void EventSubscribeBySymbol(object source, string eventName, int symbolId)
    {
        if (symbolId < 0) return;
        var method = FindProcedureMethodIn(Assembly.GetCallingAssembly(), symbolId, paramTypes: null);
        var del = CreateHandlerDelegate(method);
        if (del is not null) EventSubscribe(source, eventName, del);
    }

    /// <summary>REMOVE HANDLER per symbolId (vedi EventSubscribeBySymbol).</summary>
    public static void EventUnsubscribeBySymbol(object source, string eventName, int symbolId)
    {
        if (symbolId < 0) return;
        var method = FindProcedureMethodIn(Assembly.GetCallingAssembly(), symbolId, paramTypes: null);
        var del = CreateHandlerDelegate(method);
        if (del is not null) EventUnsubscribe(source, eventName, del);
    }

    private static Delegate? CreateHandlerDelegate(System.Reflection.MethodInfo? method)
    {
        if (method is null) return null;
        var ps = method.GetParameters();
        var types = new Type[ps.Length + 1];
        for (var i = 0; i < ps.Length; i++) types[i] = ps[i].ParameterType;
        types[ps.Length] = method.ReturnType;
        try
        {
            var delType = System.Linq.Expressions.Expression.GetDelegateType(types);
            return Delegate.CreateDelegate(delType, method);
        }
        catch { return null; }
    }

    private static string EventKey(object source, string eventName)
    {
        var typeName = source.GetType().FullName ?? source.GetType().Name;
        return typeName + "." + eventName;
    }

    public static void RaiseEvent(object source, string eventName, object[] args)
    {
        var key = source is null ? eventName : EventKey(source, eventName);
        if (!_eventSubscriptions.TryGetValue(key, out var subs)) return;
        foreach (var (srcRef, handler) in subs.ToArray())
        {
            if (source is not null)
            {
                // Dispatch SOLO agli handler del SOURCE che alza l'evento (key per tipo+evento:
                // più istanze della stessa classe condividono la chiave, ma ogni handler è legato
                // alla propria istanza via WeakReference).
                if (srcRef is null || !srcRef.TryGetTarget(out var target)) continue;
                if (!ReferenceEquals(target, source)) continue;
            }
            try { handler.DynamicInvoke(args); } catch { /* fire-and-forget */ }
        }
    }

    // ── File I/O Advanced ─────────────────────────────────────────────
    public static string GetFile(long handle, long recordNumber)
    {
        var stream = GetFile(handle);
        if (recordNumber >= 0)
        {
            var recSize = 128L; // default record length
            stream.Seek(recordNumber * recSize, SeekOrigin.Begin);
        }
        using var reader = new StreamReader(stream, Encoding.UTF8, leaveOpen: true);
        return reader.ReadToEnd();
    }

    public static void PutFile(long handle, object data)
    {
        var stream = GetFile(handle);
        var bytes = data switch
        {
            byte[] b => b,
            string s => Encoding.UTF8.GetBytes(s),
            _ => Encoding.UTF8.GetBytes(data.ToString() ?? string.Empty)
        };
        stream.Write(bytes, 0, bytes.Length);
    }

    /// <summary>PUT #n, pos, &lt;array di BYTE&gt;: scrive i byte grezzi (pos &gt; 0 = offset di byte pos-1).</summary>
    public static void FilePutBytes(long fileNum, long pos, byte[] data)
    {
        var stream = GetFile(ResolveFileNumber(fileNum));
        if (pos > 0) stream.Seek(pos - 1, SeekOrigin.Begin);
        stream.Write(data, 0, data.Length);
    }

    /// <summary>GET #n, pos, &lt;array di BYTE&gt;: legge dest.Length byte (oltre EOF → 0) nell'array.</summary>
    public static void FileGetBytes(long fileNum, long pos, byte[] dest)
    {
        var stream = GetFile(ResolveFileNumber(fileNum));
        if (pos > 0) stream.Seek(pos - 1, SeekOrigin.Begin);
        var got = 0;
        while (got < dest.Length)
        {
            var r = stream.Read(dest, got, dest.Length - got);
            if (r <= 0) break;
            got += r;
        }
        if (got < dest.Length) Array.Clear(dest, got, dest.Length - got);
    }

    // ── Record I/O su file RANDOM (PUT/GET #n, rec, <UDT>) ───────────────────────────
    // Layout canonico SIZEOF packed little-endian: CommonLib.RandomRecordCodec (gemello di
    // gmb_file_put_record/gmb_file_get_record del runtime C). Il record è lungo LEN byte
    // (OPEN … FOR RANDOM LEN = n, default 128).
    private static long ResolveFileNumber(long fileNum) => FileNumberToHandle.TryGetValue(fileNum, out var h) ? h : fileNum;

    /// <summary>OPEN … FOR RANDOM [LEN = n]: abilita il record I/O sullo stream del file number.</summary>
    public static void FileMarkRandom(long fileNum, long recordLength)
        => CommonLib.RandomRecordCodec.MarkRandom(GetFile(ResolveFileNumber(fileNum)), recordLength);

    /// <summary>True se il file number è un file aperto FOR RANDOM (PUT/GET su UDT → record).</summary>
    public static bool FileIsRandom(long fileNum)
        => OpenFiles.TryGetValue(ResolveFileNumber(fileNum), out var s) && CommonLib.RandomRecordCodec.IsRandom(s);

    public static void FilePutRecord(long fileNum, long record, string tokens, object?[] values)
    {
        var rc = CommonLib.RandomRecordCodec.Put(GetFile(ResolveFileNumber(fileNum)), record, tokens, values);
        if (rc == -2)
            throw new BasicException(ErrorCode.BadRecordLength, SourcePosition.Unknown, CommonLib.RandomRecordCodec.BadRecordLengthMessage);
    }

    public static object?[] FileGetRecord(long fileNum, long record, string tokens)
    {
        var rc = CommonLib.RandomRecordCodec.Get(GetFile(ResolveFileNumber(fileNum)), record, tokens, out var values);
        if (rc == -2)
            throw new BasicException(ErrorCode.BadRecordLength, SourcePosition.Unknown, CommonLib.RandomRecordCodec.BadRecordLengthMessage);
        return values;
    }

    // ── Memory Mapping ────────────────────────────────────────────────
    private static ConcurrentDictionary<long, IDisposable> _memoryMaps = new();

    public static long MemoryMap(string filePath)
    {
        // Crea il file se non esiste; capacità minima 128 byte così POKE/WRITEBYTES
        // oltre la dimensione iniziale non falliscono (stessa policy della VM).
        var capacity = Math.Max(128L, File.Exists(filePath) ? new FileInfo(filePath).Length : 0L);
        var mmf = MemoryMappedFile.CreateFromFile(
            filePath, FileMode.OpenOrCreate, null, capacity, MemoryMappedFileAccess.ReadWrite);
        // Registra in _memoryMaps (Poke/Peek/ReadBytes/WriteBytes leggono DA QUESTO
        // dizionario — StoreHandle usa _disposableHandles, che li lascerebbe no-op).
        var handle = Interlocked.Increment(ref _nextHandle);
        _memoryMaps.TryAdd(handle, mmf);
        return handle;
    }

    /// <summary>Chiude la mappa (IO.CLOSE handleMMap): rilascia il MemoryMappedFile.
    /// UNICA implementazione — la PCodeVM la usa dal suo syscall CLOSE (prima aveva
    /// un dizionario proprio, mai popolato → dispose no-op e leak).</summary>
    public static void MemoryMapClose(long handle)
    {
        if (_memoryMaps.TryRemove(handle, out var mmf))
        {
            try { mmf.Dispose(); } catch { /* già rilasciato */ }
        }
    }

    /// <summary>Chiude TUTTE le mappe (IO.CLOSE senza numero).</summary>
    public static void MemoryMapCloseAll()
    {
        foreach (var key in _memoryMaps.Keys.ToArray())
            MemoryMapClose(key);
    }

    public static void MemoryPoke(long handle, long offset, double value)
    {
        if (!_memoryMaps.TryGetValue(handle, out var mmf)) return;
        try
        {
            using var accessor = ((MemoryMappedFile)mmf).CreateViewAccessor(offset, 1);
            accessor.Write(0, (byte)value);
        }
        catch { /* oltre la mappa: ignora */ }
    }

    public static byte MemoryPeek(long handle, long offset)
    {
        if (!_memoryMaps.TryGetValue(handle, out var mmf)) return 0;
        try
        {
            using var accessor = ((MemoryMappedFile)mmf).CreateViewAccessor(offset, 1);
            accessor.Read(0, out byte value);
            return value;
        }
        catch { return 0; }
    }

    public static byte[] MemoryReadBytes(long handle, long offset, long count)
    {
        if (!_memoryMaps.TryGetValue(handle, out var mmf) || count <= 0) return Array.Empty<byte>();
        var result = new byte[count];
        try
        {
            using var accessor = ((MemoryMappedFile)mmf).CreateViewAccessor(offset, count);
            accessor.ReadArray(0, result, 0, (int)count);
        }
        catch { /* oltre la mappa: zero-fill */ }
        return result;
    }

    public static void MemoryWriteBytes(long handle, long offset, byte[] data, long count)
    {
        if (!_memoryMaps.TryGetValue(handle, out var mmf) || data == null || data.Length == 0) return;
        var len = count >= 0 && count < data.Length ? (int)count : data.Length;
        try
        {
            using var accessor = ((MemoryMappedFile)mmf).CreateViewAccessor(offset, len);
            accessor.WriteArray(0, data, 0, len);
        }
        catch { /* oltre la mappa: ignora */ }
    }

    // ── Clipboard ─────────────────────────────────────────────────────
    public static string Clip(string command, string? arg)
    {
        // Parità PCode/VM-C (gruppo Console): prima stub (GET→"", PUT→echo).
        // Usa il clipboard dell'host (in-memory in headless/test, sistema su desktop);
        // mai eccezioni verso il BASIC (fallback "").
        try
        {
            switch (command.ToUpperInvariant())
            {
                case "GET":
                    return Current.Clipboard.GetText() ?? string.Empty;
                case "PUT":
                case "SET":
                    Current.Clipboard.SetText(arg ?? string.Empty);
                    return arg ?? string.Empty;
                case "CLEAR":
                    Current.Clipboard.Clear();
                    return string.Empty;
                default:
                    return string.Empty;
            }
        }
        catch { return string.Empty; }
    }

