    public static double DateDiff(string interval, double d1, double d2)
    {
        try
        {
            var dt1 = DateTime.FromOADate(d1);
            var dt2 = DateTime.FromOADate(d2);
            var span = dt2 - dt1;
            return interval.ToLowerInvariant() switch
            {
                "yyyy" or "y" => (dt2.Year - dt1.Year),
                "m" or "month" => (dt2.Month - dt1.Month) + 12 * (dt2.Year - dt1.Year),
                "d" or "day" => span.TotalDays,
                "h" => span.TotalHours,
                "n" => span.TotalMinutes,
                "s" => span.TotalSeconds,
                _ => span.TotalDays
            };
        }
        catch { return 0; }
    }

    /// <summary>HashSet.Union/Intersect/Except/SymmetricExcept — ritorna un NUOVO set
    /// (il CLR UnionWith/IntersectWith modificano in-place e ritornano void).</summary>
    public static object? SetUnion(object a, object b)
    {
        if (a is not System.Collections.IEnumerable ea || b is not System.Collections.IEnumerable eb) return null;
        var result = new System.Collections.Generic.HashSet<object?>(ea.Cast<object?>(), EqualityComparer<object?>.Default);
        foreach (var item in eb) result.Add(item);
        return result;
    }
    public static object? SetIntersect(object a, object b)
    {
        if (a is not System.Collections.IEnumerable ea || b is not System.Collections.IEnumerable eb) return null;
        var setB = new System.Collections.Generic.HashSet<object?>(eb.Cast<object?>(), EqualityComparer<object?>.Default);
        return ea.Cast<object?>().Where(setB.Contains).Distinct().ToList();
    }
    public static object? SetExcept(object a, object b)
    {
        if (a is not System.Collections.IEnumerable ea || b is not System.Collections.IEnumerable eb) return null;
        var setB = new System.Collections.Generic.HashSet<object?>(eb.Cast<object?>(), EqualityComparer<object?>.Default);
        return ea.Cast<object?>().Where(x => !setB.Contains(x)).ToList();
    }
    public static object? SetSymmetricExcept(object a, object b)
    {
        if (a is not System.Collections.IEnumerable ea || b is not System.Collections.IEnumerable eb) return null;
        var setA = new System.Collections.Generic.HashSet<object?>(ea.Cast<object?>(), EqualityComparer<object?>.Default);
        var setB = new System.Collections.Generic.HashSet<object?>(eb.Cast<object?>(), EqualityComparer<object?>.Default);
        var result = new System.Collections.Generic.HashSet<object?>(setA);
        result.SymmetricExceptWith(setB);
        return result;
    }
    /// <summary>
    /// Converte il contenitore boxed (HashSet&lt;object&gt;/List&lt;object&gt; prodotto da
    /// SetUnion/SetIntersect/SetExcept/SetSymmetricExcept) in un HashSet&lt;T&gt; col tipo
    /// ELEMENTO del BASIC (es. HashSet&lt;short&gt; per HASHSET&lt;INTEGER&gt;). Senza, il
    /// valore object verrebbe stoccato in un local HashSet&lt;T&gt; senza castclass (IL
    /// invalido) o con castclass a HashSet&lt;object&gt; → InvalidCastException.
    /// </summary>
    public static HashSet<T> ToTypedSet<T>(object? source)
    {
        var result = new HashSet<T>();
        if (source is not System.Collections.IEnumerable en) return result;
        foreach (var item in en)
        {
            if (item is T typed) result.Add(typed);
            else if (item is null) { /* elemento null: salta (T value type) */ }
            else result.Add((T)Convert.ChangeType(item, typeof(T), System.Globalization.CultureInfo.InvariantCulture));
        }
        return result;
    }

    /// <summary>NEW HASHRING<T>(nodes): crea un CommonLib ConsistentHash<object> e popola i
    /// nodi (il ctor generico con IEnumerable<object> non accetta List<string> — invariance).</summary>
    public static object NewHashRing(System.Collections.IEnumerable nodes, int replicas)
    {
        var ring = new CommonLib.Collections.ConsistentHash<object>(Array.Empty<object>(), replicas);
        foreach (var n in nodes) ring.AddNode(n!);
        return ring;
    }

    /// <summary>Somma dei valori numerici di un IDictionary con chiave numerica in [lo, hi]
    /// (parità BITREE/Fenwick del VM — il backend materializza BITREE come SortedDictionary).</summary>
    private static double BitQuery(System.Collections.IDictionary map, double lo, double hi)
    {
        double sum = 0;
        foreach (System.Collections.DictionaryEntry e in map)
        {
            var k = Convert.ToDouble(e.Key);
            if (k >= lo && k <= hi) sum += Convert.ToDouble(e.Value);
        }
        return sum;
    }

    /// <summary>Confronto di chiavi di un IDictionary boxed: numeriche per valore, altrimenti
    /// ordine alfabetico della stringa (parità SortedDictionary/AVL del VM).</summary>
    private static int CompareDictKeys(object? a, object? b)
    {
        if (a is IConvertible ca && b is IConvertible cb && ca.GetTypeCode() is System.TypeCode.SByte or System.TypeCode.Byte or System.TypeCode.Int16
            or System.TypeCode.UInt16 or System.TypeCode.Int32 or System.TypeCode.UInt32 or System.TypeCode.Int64 or System.TypeCode.UInt64 or System.TypeCode.Single or System.TypeCode.Double or System.TypeCode.Decimal)
        {
            return Convert.ToDouble(a).CompareTo(Convert.ToDouble(b));
        }
        return string.Compare(Convert.ToString(a, System.Globalization.CultureInfo.InvariantCulture),
            Convert.ToString(b, System.Globalization.CultureInfo.InvariantCulture), StringComparison.Ordinal);
    }

    /// <summary>DIM x AS TRIE = [letterale]: popola un CommonLib.Collections.Trie dagli
    /// elementi (stringhe) di un IEnumerable qualsiasi (List&lt;string&gt;/string[]...).</summary>
    public static CommonLib.Collections.Trie TrieFromItems(System.Collections.IEnumerable items)
    {
        var trie = new CommonLib.Collections.Trie();
        foreach (var item in items)
        {
            if (item is null) continue;
            trie.Add(Convert.ToString(item, System.Globalization.CultureInfo.InvariantCulture) ?? "");
        }
        return trie;
    }

    /// <summary>DIM x AS BAG&lt;T&gt; = [letterale]: conteggia le occorrenze in un
    /// BagMultiset&lt;T&gt; (la materializzazione CLR di BAG&lt;T&gt;: Dictionary&lt;T,long&gt; con la
    /// semantica di MULTISET del runtime condiviso C: Count() = molteplicità TOTALE,
    /// Remove toglie UNA istanza).</summary>
    public static Dictionary<T, long> BagFromItems<T>(System.Collections.IEnumerable items) where T : notnull
    {
        var bag = new BagMultiset<T>();
        foreach (var item in items)
        {
            if (item is null) continue;
            var key = item is T typed ? typed : (T)Convert.ChangeType(item, typeof(T), System.Globalization.CultureInfo.InvariantCulture);
            bag[key] = bag.GetValueOrDefault(key) + 1;
        }
        return bag;
    }

    /// <summary>MyList2(0) = "BETA" quando MyList2 è AnyType (object boxed di una List):
    /// dispatch runtime sull'indexer — IList per le List (indice int), IDictionary per le
    /// Dict (chiave). Mai fallire con un cast statico.</summary>
    /// <summary>MyList(0) in lettura quando il tipo statico è AnyType/object: dispatch
    /// runtime su IList/IDictionary (indice int o chiave).</summary>
    public static object? CollectionIndexGet(object? collection, object? index)
    {
        if (collection is System.Collections.IList list && index is not null)
            return list[Convert.ToInt32(index, System.Globalization.CultureInfo.InvariantCulture)];
        if (collection is System.Collections.IDictionary dict)
            return dict[index!];
        return null;
    }

    private static object? CoerceElement(object? value, Type? elem)
    {
        if (value is null || elem is null || elem.IsInstanceOfType(value)) return value;
        var inv = System.Globalization.CultureInfo.InvariantCulture;
        if (elem == typeof(string)) return Convert.ToString(value, inv);
        if (elem == typeof(bool)) return Convert.ToBoolean(value, inv);
        if (elem == typeof(double)) return Convert.ToDouble(value, inv);
        if (elem == typeof(float)) return (float)Convert.ToDouble(value, inv);
        if (elem == typeof(long)) return (long)Convert.ToDouble(value, inv);
        if (elem == typeof(int)) return (int)Convert.ToDouble(value, inv);
        if (elem == typeof(short)) return (short)Convert.ToDouble(value, inv);
        if (elem == typeof(byte)) return (byte)Convert.ToDouble(value, inv);
        if (elem == typeof(sbyte)) return (sbyte)Convert.ToDouble(value, inv);
        if (elem == typeof(ushort)) return (ushort)Convert.ToDouble(value, inv);
        if (elem == typeof(uint)) return (uint)Convert.ToDouble(value, inv);
        if (elem == typeof(ulong)) return (ulong)Convert.ToDouble(value, inv);
        if (elem.IsEnum) return Enum.ToObject(elem, (long)Convert.ToDouble(value, inv));
        return Convert.ChangeType(value, elem, inv);
    }

    public static void CollectionIndexSet(object? collection, object? index, object? value)
    {
        if (collection is null)
            return; // parità VM: `DIM j AS JSON` poi j("k")="v" su j null è un no-op silenzioso
        // ARRAY (anche globale/dinamico): Array.SetValue NON converte (double -> short[]
        // lancia "Cannot widen..."). Converti al tipo elemento con la stessa semantica
        // degli store statici (cast C# = troncamento verso zero, come conv.i2).
        if (collection is Array array && index is not null)
        {
            var ai = Convert.ToInt32(index, System.Globalization.CultureInfo.InvariantCulture);
            array.SetValue(CoerceElement(value, array.GetType().GetElementType()), ai);
            return;
        }
        if (collection is System.Collections.IList list && index is not null)
        {
            list[Convert.ToInt32(index, System.Globalization.CultureInfo.InvariantCulture)] = value;
            return;
        }
        if (collection is System.Collections.IDictionary dict)
        {
            dict[index!] = value;
            return;
        }
        throw new InvalidOperationException("CollectionIndexSet: collezione non indicizzabile.");
    }

    /// <summary>Istantanea degli elementi di una collection. Serve perché il backend IL
    /// rappresenta LINKEDLIST/DOUBLYLINKEDLIST come <c>LinkedList&lt;T&gt;</c>: NON implementa
    /// <c>IList</c> (né ha un indicizzatore), quindi gli helper in-place basati su IList non
    /// la toccavano affatto (Sort/Reverse/IndexOf no-op silenziosi su DOUBLYLINKEDLIST).</summary>
    private static object?[] SnapshotItems(object? collection)
    {
        if (collection is not System.Collections.IEnumerable en) return [];
        var items = new System.Collections.Generic.List<object?>();
        foreach (var item in en) items.Add(item);
        return items.ToArray();
    }

    /// <summary>Riscrive gli elementi nella STESSA istanza: IList in-place; per
    /// <c>LinkedList&lt;T&gt;</c> (e ogni altro contenitore con Clear/AddLast) ricostruisce via
    /// riflessione (il tipo generico T non è noto a compile time).</summary>
    private static void RewriteItems(object? collection, object?[] items)
    {
        if (collection is null) return;
        if (collection is System.Collections.IList list)
        {
            for (var i = 0; i < items.Length; i++) list[i] = items[i];
            return;
        }
        var type = collection.GetType();
        var clear = type.GetMethod("Clear", Type.EmptyTypes);
        if (clear is null) return;
        clear.Invoke(collection, null);
        var elemType = type.IsGenericType ? type.GetGenericArguments()[0] : typeof(object);
        var add = type.GetMethod("AddLast", [elemType]) ?? type.GetMethod("Add", [elemType]);
        if (add is null) return;
        foreach (var item in items) add.Invoke(collection, [item]);
    }

    /// <summary>IndexOf(value) su una collection (LinkedList/Doubly/Circular): il CLR non ha
    /// Enumerable.IndexOf — scansione lineare (Object.Equals) come la VM.</summary>
    public static double CollectionIndexOf(object? collection, object? value)
    {
        var items = SnapshotItems(collection);
        for (var i = 0; i < items.Length; i++)
        {
            if (Equals(items[i], value)) return i;
            /* Uguaglianza NUMERICA fra tipi diversi: LinkedList<long> contiene boxed
             * Int64, mentre il literal BASIC `20` arriva boxed Double → Equals(long,double)=
             * false. Senza, IndexOf(20) dava -1 (CollectionsDictLists/Linked). */
            if (items[i] is IConvertible && value is IConvertible
                && IsNumericObject(items[i]) && IsNumericObject(value))
            {
                try
                {
                    if (Convert.ToDouble(items[i], System.Globalization.CultureInfo.InvariantCulture)
                        == Convert.ToDouble(value, System.Globalization.CultureInfo.InvariantCulture))
                        return i;
                }
                catch { /* non convertibile: prosegue con Equals */ }
            }
        }
        return -1;
    }

    private static bool IsNumericObject(object? o) => o is sbyte or byte or short or ushort
        or int or uint or long or ulong or float or double or decimal;

    private static bool IsLinkedListInstance(object? o)
        => o is not null && o.GetType().IsGenericType
           && o.GetType().GetGenericTypeDefinition() == typeof(System.Collections.Generic.LinkedList<>);

    private static readonly System.Collections.Concurrent.ConcurrentDictionary<object, int> _circularState = new();

    /// <summary>Current() su una CIRCULAR list: l'elemento all'indice corrente (stato per
    /// istanza, default 0).</summary>
    public static object? CircularCurrent(object? collection)
    {
        if (collection is null) return null;
        var items = SnapshotItems(collection);
        if (items.Length == 0) return null;
        var idx = _circularState.TryGetValue(collection, out var i) ? i : 0;
        return items[idx % items.Length];
    }

    /// <summary>Rotate(n) su una CIRCULAR list: sposta la "testa" logica di n posizioni.
    /// ROTAZIONE FISICA (come gmb_coll_rotate della VM/C e il transpiler C99): il cursore
    /// resta all'indice 0 e il FOR EACH riparte dalla nuova testa. Prima si teneva solo un
    /// indice separato → Current() era giusto ma l'iterazione ripartiva dalla testa originale
    /// (IL stampava A,B,C,D dove VM-C/C99/PCode stampano D,A,B,C).</summary>
    public static void CircularRotate(object? collection, double steps)
    {
        if (collection is null) return;
        var items = SnapshotItems(collection);
        var count = items.Length;
        if (count == 0) return;
        var m = (((int)steps % count) + count) % count;
        if (m != 0)
        {
            var rotated = new object?[count];
            for (var k = 0; k < count; k++) rotated[k] = items[(k + m) % count];
            RewriteItems(collection, rotated);
        }
        _circularState[collection] = 0;
    }

    /// <summary>Sort() su una collection non-sortabile nativamente (LinkedList/Doubly/
    /// Circular): estrae gli elementi, ordina, ricostruisce nella stessa istanza.</summary>
    public static void CollectionSort(object? collection)
    {
        var items = SnapshotItems(collection);
        if (items.Length == 0) return;
        Array.Sort(items, (a, b) => Comparer<object?>.Default.Compare(a, b));
        RewriteItems(collection, items);
    }

    /// <summary>Reverse() su una collection (LinkedList/Doubly/Circular): in-place o
    /// ricostruita (LinkedList&lt;T&gt; non è IList).</summary>
    public static void CollectionReverse(object? collection)
    {
        var items = SnapshotItems(collection);
        if (items.Length == 0) return;
        Array.Reverse(items);
        RewriteItems(collection, items);
    }

