    public static double Zip(string sources, string dest)
    {
        var list = new System.Collections.Generic.List<string>();
        foreach (var part in (sources ?? "").Split(';'))
            if (!string.IsNullOrWhiteSpace(part)) list.Add(part.Trim());
        try { return CommonLib.CompressionUtils.CreateZip(dest ?? "", list) ? -1.0 : 0.0; }
        catch { return 0.0; }
    }
    public static double Unzip(string archive, string dir)
    {
        try { return CommonLib.CompressionUtils.ExtractZip(archive ?? "", dir ?? "") ? -1.0 : 0.0; }
        catch { return 0.0; }
    }
