            ? "\x1b[48;2;" + (byte)Math.Clamp(r, 0, 255) + ";" + (byte)Math.Clamp(g, 0, 255) + ";" + (byte)Math.Clamp(b, 0, 255) + "m" + (text ?? "") + "\x1b[0m"
            : (text ?? "");

