    public static bool ControlApplyProps(IReadOnlyList<object?> a)
    {
        try {
            int handle = (int)UiLastHandle();
            object? G(int i) => i < a.Count ? a[i] : null;
            string? S(int i) => G(i) as string;
            double? N(int i) { object? v = G(i); return v == null ? null : System.Convert.ToDouble(v); }
            Current.Graphics.UiControlApplyProps(handle, S(0), S(1), S(2), N(3), N(4), N(5), N(6));
            if (G(7) != null) Current.Graphics.UiControlApplyFocus(handle);
            string? style = S(8);
            if (style != null) Current.Graphics.UiControlApplyStyle(handle, style);
            string? color = S(9);
            if (color != null) Current.Graphics.UiControlApplyStyle(handle, "color=" + color);
            string? colorf = S(10);
            if (colorf != null) Current.Graphics.UiControlApplyStyle(handle, "focuscolor=" + colorf);
            string? colorsel = S(11);
            if (colorsel != null) Current.Graphics.UiControlApplyStyle(handle, "selcolor=" + colorsel);
            string? colorerr = S(12);
            if (colorerr != null) Current.Graphics.UiControlApplyStyle(handle, "errorcolor=" + colorerr);
        } catch { }
        return true;
    }
