    /// <summary>§11.7-3: cabla un metodo-evento della classe UserControl (generato come
    /// `procName`) sul firing dell'evento `ev` del controllo (istanza appena aggiunta).</summary>
    public static void FormBindUserControlEvent(object? instance, string ev, string procName)
    {
        if (instance == null) return;
        try
        {
            EnsureControlEventSink();
            int handle = (int)Current.Graphics.UserControlLastHandle();
            int evIndex = Current.Graphics.FormEventIndex((ev ?? "").ToUpperInvariant());
            FormBindUserControlEventEx(handle, evIndex, procName, instance);
        }
        catch { }
    }
    /// <summary>§11.7-3: come FormBindUserControlEvent ma con handle/evIndex espliciti (PCode). L'evento
    /// gira come TASK GPM (SpawnGoSub), mai BASIC inline / thread .NET fuori GPM.</summary>
    public static void FormBindUserControlEventEx(int handle, int evIndex, string procName, object? instance)
    {
        if (instance == null || string.IsNullOrEmpty(procName)) return;
        try
        {
            EnsureControlEventSink();
            if (handle < 0 || evIndex <= 0) return;
            var m = instance.GetType().GetMethod(procName,
                System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            if (m == null) return;
            int key = (handle << 8) | (evIndex & 0xFF);
            var inst = instance;
            int symId = procName.StartsWith("Proc_", StringComparison.Ordinal) &&
                        int.TryParse(procName.AsSpan(5), out var sid) ? sid : -1;
            ControlEventHandlers2[key] = () =>
            {
                try
                {
                    var sched = IlGpmRuntime.CurrentScheduler;
                    if (sched != null && symId >= 0)
                    {
                        IlGpmRuntime.SpawnGoSub(sched, symId, new object?[] { inst }, null);
                        return;
                    }
                    m.Invoke(inst, null);
                }
                catch { }
            };
        }
        catch { }
    }
