    /* ON <EV> CONTROL <h> <azione>: registra il gestore per (handle, evento). Il firing sulle
     * gambe gestite arriva col bridge eventi nativo->managed (Fase 6). */
    private static readonly System.Collections.Generic.Dictionary<(int, string), string> ControlEventHandlers = new();
    public static void FormSetEventId(double handle, string ev, string sub)
    { try { ControlEventHandlers[((int)handle, (ev ?? "").ToUpperInvariant())] = sub ?? ""; } catch { } }
    private static readonly System.Collections.Generic.Dictionary<int, Action?> ControlEventHandlers2 = new();
    private static bool _ctrlSinkSet;
    private static void EnsureControlEventSink()
    {
        if (_ctrlSinkSet) return; _ctrlSinkSet = true;
        try { Current.Graphics.FormSetControlEventSink(DispatchControlEvent); } catch { }
    }
    private static void DispatchControlEvent(int ctl, int evIndex)
    {
        int key = (ctl << 8) | (evIndex & 0xFF);
        if (ControlEventHandlers2.TryGetValue(key, out var a) && a != null) { try { a(); } catch { } }
    }
    /// <summary>ON <EV> CONTROL <h> <azione> sulle gambe managed: registra il gestore (symbolId)
    /// e il thunk nativo; il firing C rientra qui e dispatcha la SUB sul worker GPM.</summary>
    public static void RegisterControlEventHandler(int handle, string ev, int symbolId)
    {
        try
        {
            int evIndex = Current.Graphics.FormEventIndex(ev);
            if (evIndex <= 0) return;
            EnsureControlEventSink();
            int key = (handle << 8) | (evIndex & 0xFF);
            if (symbolId < 0) ControlEventHandlers2.Remove(key);
            else
            {
                var method = FindProcedureMethodIn(System.Reflection.Assembly.GetCallingAssembly(), symbolId, paramTypes: null);
                ControlEventHandlers2[key] = method is null ? null : (Action)(() => { try { method.Invoke(null, null); } catch { } });   /* controllo evento: esecuzione SINCRONA (inline) */
            }
            Current.Graphics.FormRegisterEventThunk(handle, evIndex);
        }
        catch { }
    }
    public static int FormEventIndex(string ev) { try { return Current.Graphics.FormEventIndex(ev); } catch { return 0; } }
    public static void FormSetLastEvent(double handle, string ev) { try { Current.Graphics.FormSetLastEvent((int)handle, Current.Graphics.FormEventIndex(ev)); } catch { } }
    public static void FormFireEvent(double handle, string ev)
    {
        try
        {
            int h = (int)handle; string e = (ev ?? "").ToUpperInvariant();
            Current.Graphics.FormSetLastEvent(h, Current.Graphics.FormEventIndex(e));   /* stato, senza firing */
            int key = (h << 8) | (Current.Graphics.FormEventIndex(e) & 0xFF);
            if (ControlEventHandlers2.TryGetValue(key, out var a) && a != null) a();    /* esecuzione SINCRONA */
        }
        catch { }
    }
    public static void RegisterControlThunk(int handle, int evIndex, Action<int, int> dispatch)
    { try { Current.Graphics.FormSetControlEventSink(dispatch); Current.Graphics.FormRegisterEventThunk(handle, evIndex); } catch { } }
