    { try { return ControlEventHandlers.TryGetValue(((int)handle, (ev ?? "").ToUpperInvariant()), out var v) ? v : ""; } catch { return ""; } }

public static double TextWidth(string s)
    {
        /* Sorgente UNICA: metrica LOGICA del motore C (stessa di VM/C e C99). Prima, con
         * GraphicsManager (SDL C#) o host Null, IL/PCode davano 25/19 o 24/16 contro 21/16
         * della VM/C. Vale anche senza host grafico attivo. */
        try { if (Basic.Runtime.CGfxGraphicsService.UseCGraphics) return Basic.Runtime.CGfxGraphicsService.TextWidthLogical(s); } catch { }
        if (IsGraphicScreenOn)
        {
            try { return CommonGraphics.Graphics.GraphicsManager.Instance.TextWidthInternal(s ?? ""); } catch { }
        }
        return Current.Graphics?.TextWidth(s) ?? (s?.Length ?? 0) * 8;
    }
    public static double TextHeight()
    {
        try { if (Basic.Runtime.CGfxGraphicsService.UseCGraphics) return Basic.Runtime.CGfxGraphicsService.TextHeightLogical(); } catch { }
        if (IsGraphicScreenOn)
        {
            try { return CommonGraphics.Graphics.GraphicsManager.Instance.TextHeightInternal(); } catch { }
        }
        return Current.Graphics?.TextHeight() ?? 16;
    }

    // --- Categoria 6: COLL/STR (funzioni lista/dict — semantica = case VM) ---
    public static double Enqueue(System.Collections.IList q, object val) { q?.Add(val); return 0.0; }
    public static object? Dequeue(System.Collections.IList q)
    { if (q is { Count: > 0 }) { var v = q[0]; q.RemoveAt(0); return v; } return null; }
    public static object? First(System.Collections.IList l) => l is { Count: > 0 } ? l[0] : null;
    public static object? Last(System.Collections.IList l) => l is { Count: > 0 } ? l[l.Count - 1] : null;
    public static object? Clear(object c)
    { if (c is System.Collections.IList l) l.Clear(); else if (c is System.Collections.IDictionary d) d.Clear(); return null; }
    public static double IndexOf(System.Collections.IList l, object v) => (double)l.IndexOf(v);
    public static object? Insert(System.Collections.IList l, double idx, object v) { l?.Insert((int)idx, v); return null; }
    public static object? RemoveAt(System.Collections.IList l, double idx) { l?.RemoveAt((int)idx); return null; }
    public static object? GetRange(System.Collections.IList l, double start, double count)
    {
        var res = new List<object?>();
        if (l != null)
            for (var i = (int)start; i < (int)start + (int)count && i < l.Count; i++) res.Add(l[i]);
        return res;
    }
    public static object? Sort(System.Collections.IList l)
    {
        if (l == null) return null;
        var arr = l.Cast<object>().OrderBy(x => Convert.ToDouble(x)).ToArray();
        l.Clear();
        foreach (var x in arr) l.Add(x);
        return null;
    }
    public static object? AddRange(System.Collections.IList tgt, object src)
    { if (tgt != null && src is System.Collections.IEnumerable en) foreach (var item in en) tgt.Add(item); return null; }
    public static double TryGetValue(System.Collections.IDictionary d, object k, System.Collections.IList outList)
    { if (d == null) return 0; var found = d.Contains(k ?? ""); if (found && outList is { Count: > 0 }) outList[0] = d[k ?? ""]; return found ? 1 : 0; }
