    // FFT/IFFT: object[,] (reale/immaginaria) -> double[][] (2 colonne per riga).
    private static double[][] MatrixToJagged(object[,] m)
    {
        var n = m.GetLength(0);
        var res = new double[n][];
        for (var i = 0; i < n; i++) res[i] = new double[] { Convert.ToDouble(m[i, 0]), Convert.ToDouble(m[i, 1]) };
        return res;
    }

    public static double[][] Fft(double[] data)
    {
        var m = CommonLib.Numerics.Fft(data ?? Array.Empty<double>());
        return MatrixToJagged(m);
    }

    public static double[][] Ifft(double[][] matrix)
    {
        var n = matrix?.Length ?? 0;
        var real = new double[n];
        var imag = new double[n];
        for (var i = 0; i < n; i++) { real[i] = matrix![i][0]; imag[i] = matrix[i][1]; }
        return MatrixToJagged(CommonLib.Numerics.Ifft(real, imag));
    }

    public static double[][] FftComplex(double[] real, double[] imag)
        => MatrixToJagged(CommonLib.Numerics.Fft(real, imag));

    public static double[][] IfftComplex(double[] real, double[] imag)
        => MatrixToJagged(CommonLib.Numerics.Ifft(real, imag));

    // Integrate/Differentiate: quad adattivo Gauss-Kronrod (scipy.quad) / derivata centrale.
    public static double Integrate(Func<double, double> f, double a, double b)
        => CommonLib.Numerics.IntegrateQuad(f ?? (_ => 0), a, b);

    public static double Differentiate(Func<double, double> f, double x)
    {
        if (f == null) return 0;
        const double h = 1e-6;
        return (f(x + h) - f(x - h)) / (2 * h);
    }

