    public static Dictionary<string, object?> Pca(double[][] rows)
    {
        if (rows == null || rows.Length == 0) return new() { ["EigenValues"] = Array.Empty<double>(), ["EigenVectors"] = Array.Empty<double[]>() };
        var cols = rows[0].Length;
        var mat = new double[rows.Length, cols];
        for (var r = 0; r < rows.Length; r++)
            for (var c = 0; c < cols; c++) mat[r, c] = rows[r][c];
        var (eigVals, eigVecs) = CommonLib.Numerics.PCA(mat);
        return new() { ["EigenValues"] = eigVals, ["EigenVectors"] = eigVecs };
    }

    /// <summary>Converte un array RETTANGOLARE rank-2 (DIM M(3,1)) in jagged double[][] —
    /// i runtime ANALYSIS (Pca/Anova) vogliono jagged; il rettangolare CLR non è convertibile.</summary>
    public static double[][] RectToJagged(double[,] m)
    {
        var rows = m.GetLength(0);
        var cols = m.GetLength(1);
        var res = new double[rows][];
        for (var r = 0; r < rows; r++)
        {
            res[r] = new double[cols];
            for (var c = 0; c < cols; c++) res[r][c] = m[r, c];
        }
        return res;
    }

