    public static Dictionary<string, object?> Anova(double[][] groups)
    {
        var g = groups ?? Array.Empty<double[]>();
        var (f, p, ssb, ssw) = CommonLib.Numerics.Anova(g);
        var degreesBetween = g.Length - 1;
        var degreesWithin = g.Sum(static group => group.Length) - g.Length;
        return new()
        {
            ["FValue"] = f,
            ["PValue"] = p,
            ["DFBetween"] = degreesBetween,
            ["DFWithin"] = degreesWithin,
            ["SSBetween"] = ssb,
            ["SSWithin"] = ssw,
            ["MSBetween"] = ssb / degreesBetween,
            ["MSWithin"] = ssw / degreesWithin
        };
    }
