    public static double StatsRange(double[] a)
    {
        if (a.Length == 0) return 0;
        double lo = a[0], hi = a[0];
        foreach (var v in a) { if (v < lo) lo = v; if (v > hi) hi = v; }
        return hi - lo;
    }

    public static double GammaSf(double shape, double scale, double x) => 1.0 - CommonLib.Numerics.GammaCdf(shape, scale, x);

    public static double Covariance(double[] x, double[] y)
    {
        var n = Math.Min(x.Length, y.Length);
        if (n < 2) return 0;
        double mx = 0, my = 0;
        for (var i = 0; i < n; i++) { mx += x[i]; my += y[i]; }
        mx /= n; my /= n;
        double sxy = 0;
        for (var i = 0; i < n; i++) sxy += (x[i] - mx) * (y[i] - my);
        return sxy / (n - 1);
    }

