    public static double Mnpv(double rate, double[] cashflows)
    {
        // Stessa implementazione del P-Code VM (case BuiltInFunction.MNPV).
        if (cashflows is null) return 0.0;
        double npv = 0;
        for (int i = 0; i < cashflows.Length; i++) npv += cashflows[i] / Math.Pow(1 + rate, i + 1);
        return npv;
    }

    /// <summary>LEN su oggetto dinamico (campo FetchResult/JSON boxed): stringa → Length,
    /// IList/Array → Count, numerico → numero di cifre (come la VM).</summary>
    public static long Len(object? value)
    {
        // Stringa: CARATTERI (code point Unicode) — "é"=1, "─"=1, "😀"=1.
        // Per i BYTE della codifica UTF-8 c'è LENB (gmb_str_bytes / LenBytes).
        if (value is string s) return CommonLib.StringUtils.CharCount(s);
        if (value is System.Collections.ICollection c) return c.Count;
        if (value is System.Array a) return a.Length;
        if (value is double d) return d.ToString("G17", System.Globalization.CultureInfo.InvariantCulture).Replace(".", "").TrimStart('-').Length;
        return value?.ToString() is { } t ? CommonLib.StringUtils.CharCount(t) : 0;
    }

    /// <summary>LENB(s): numero di BYTE della codifica UTF-8 (non di caratteri).
    /// Per un argomento NON stringa restituisce -1 (parità su tutte le gambe).</summary>
    public static long LenBytes(object? value) =>
        value is string s ? CommonLib.StringUtils.ByteCount(s) : -1L;

