    public static double DividendYield(double div, double price) => price > 0 ? div / price * 100 : 0;
    public static double KellyCriterion(double[] rets)
    {
        if (rets.Length == 0) return 0.0;
        double winRate = rets.Count(x => x > 0) / (double)rets.Length;
        double avgWin = rets.Where(x => x > 0).DefaultIfEmpty().Average();
        double avgLoss = Math.Abs(rets.Where(x => x < 0).DefaultIfEmpty().Average());
        return avgLoss > 0 ? winRate - (1 - winRate) / (avgWin / avgLoss) : 0;
    }
    /// <summary>KELLYCRITERION(rendimenti[], tassoRiskFree) — stessa formula col risk-free
    /// (parità P-Code): Kelly = (p*b - q)/b con i rendimenti storici come proxi.</summary>
    public static double KellyCriterion(double[] rets, double riskFree)
    {
        var kelly = KellyCriterion(rets);
        return kelly - riskFree;
    }

    /// <summary>KELLYCRITERION del namespace TRADING.PORTFOLIO → PortfolioResult dict (parità
    /// VM/C case 189 e dichiarazione StdLib PortfolioResultType). Prima il dispatch IL usava
    /// IlRuntime.KellyCriterion (double) → slot Dictionary corrotto → AccessViolation.</summary>
    public static Dictionary<string, object?> PortfolioKellyCriterion(double[] rets, double riskFree)
    {
        var k = KellyCriterion(rets, riskFree);
        var result = new Dictionary<string, object?>
        {
            ["ExpectedReturn"] = k,
            ["Volatility"] = 0.0,
            ["SharpeRatio"] = 0.0,
            ["Weights"] = new[] { k }
        };
        return result;
    }
    /// <summary>MINCDAR(rendimenti[], confidenza, riskFree) → PortfolioResult boxed:
    /// Conditional Drawdown-at-Risk (media del max drawdown della coda) meno il risk-free.</summary>
    public static Dictionary<string, object> MinCdar(object retsObj, double confidence, double riskFree)
    {
        var rets = FlattenReturns(retsObj);
        var result = new Dictionary<string, object>();
        if (rets.Length == 0) { result["CDaR"] = 0.0; result["Weights"] = Array.Empty<double>(); return result; }
        var alpha = Math.Clamp(confidence, 0.0, 1.0);
        var tailCount = Math.Max(1, (int)Math.Ceiling((1.0 - alpha) * rets.Length));
        var tail = rets.OrderBy(x => x).Take(tailCount).ToArray();
        result["CDaR"] = tail.Average() - riskFree;
        result["Weights"] = new double[] { 1.0 }; // parità VM/C (gmb_bf_187) e PCode
        return result;
    }
    public static Dictionary<string, object> MinCvar(object retsObj, double confidence, double riskFree)
    {
        var rets = FlattenReturns(retsObj);
        var result = new Dictionary<string, object>();
        if (rets.Length == 0) { result["CVaR"] = 0.0; result["Weights"] = Array.Empty<double>(); return result; }
        var sorted = rets.OrderBy(x => x).ToArray();
        var alpha = Math.Clamp(confidence, 0.0, 1.0);
        var tailCount = Math.Max(1, (int)Math.Ceiling((1.0 - alpha) * sorted.Length));
        var tail = sorted.Take(tailCount).ToArray();
        var cvar = tail.Average() - riskFree;
        result["CVaR"] = cvar;
        result["Weights"] = new double[] { 1.0 }; // parità VM/C (gmb_bf_187) e PCode
        return result;
    }
