    // Appiattisce in un double[] sia un array 1D (double[]) sia una matrice 2D
    // (double[][] — storici multi-asset, come la ToDoubleArray della VM) sia una
    // List<double>: le misure di rischio VAR/CVAR/MAD/STDEV della VM lavorano sul
    // vettore appiattito (row-major), NON per periodo.
    public static double[] FlattenReturns(object? val)
    {
        if (val is double[] d1) return d1;
        var flat = new List<double>();
        void Flatten(object? item)
        {
            if (item is double[] d) { flat.AddRange(d); return; }
            if (item is System.Collections.IEnumerable en && item is not string && item is not System.Collections.IDictionary)
            {
                foreach (var sub in en) Flatten(sub);
                return;
            }
            flat.Add(item is double dd ? dd : 0.0);
        }
        Flatten(val);
        return flat.ToArray();
    }
    public static double SharpeRatio3(double portRet, double risk, double riskFree)
        => risk > 0 ? (portRet - riskFree) / risk : 0.0;
    public static double PortfolioExpectedReturn(object w, object r)
    { var ww = FlattenReturns(w); var rr = FlattenReturns(r); double sum = 0; for (int i = 0; i < Math.Min(ww.Length, rr.Length); i++) sum += ww[i] * rr[i]; return sum; }
    public static double PortfolioSharpeRatio(object w, object r)
    {
        var ww = FlattenReturns(w); var rr = FlattenReturns(r);
        if (rr.Length < 2) return 0.0;
        double pRet = 0; for (int i = 0; i < Math.Min(ww.Length, rr.Length); i++) pRet += ww[i] * rr[i];
        var avg = rr.Average(); var std = Math.Sqrt(rr.Sum(x => Math.Pow(x - avg, 2)) / (rr.Length - 1));
        return std > 0 ? (pRet / std) * Math.Sqrt(252) : 0;
    }
    public static double PortfolioStDev(object w, object r)
    {
        // STDEV(pesi[], covarianza[][]): sqrt(w^T * cov * w) — N asset (StdLib).
        var ww = FlattenReturns(w);
        var cov = FlattenReturns(r);
        int n = ww.Length;
        if (n == 0 || cov.Length < n * n) return 0.0;
        double pv = 0;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                pv += ww[i] * cov[i * n + j] * ww[j];
        return pv > 0 ? Math.Sqrt(pv) : 0.0;
    }
    public static double PortfolioVar(object rets, double conf)
    {
        var rr = FlattenReturns(rets);
        if (rr.Length == 0) return 0.0;
        var sorted = rr.OrderBy(x => x).ToArray();
        int idx = (int)((1 - conf) * sorted.Length);
        if (idx < 0) idx = 0;
        if (idx >= sorted.Length) idx = sorted.Length - 1;
        return -sorted[idx] * 100;
    }
    public static double PortfolioCVar(object rets, double conf) => CommonLib.Numerics.ConditionalVaR(FlattenReturns(rets), conf);
    public static double PortfolioMad(object rets, double conf)
    {
        // Supporta sia matrice 2D (T x N, come il PCode via MadSolver) sia array 1D
        // (dispersione rispetto alla mediana). conf ignorato.
        try
        {
            var mat = ToDoubleMatrix2D(rets);
            if (mat != null)
            {
                try { return CommonLib.Trading.MadSolver.SolveMadPortfolio(mat).Mad; } catch { return 0.0; }
            }
            var rr = FlattenReturns(rets);
            if (rr.Length == 0) return 0.0;
            var sorted = rr.OrderBy(x => x).ToArray();
            var med = sorted[sorted.Length / 2];
            return rr.Average(x => Math.Abs(x - med));
        }
        catch { return 0.0; }
    }

    /// <summary>Converte un valore in una matrice double[,] 2D (Array rank 2 o IList di
    /// IList), altrimenti null — parità col TryToMatrix2D della PCodeVM.</summary>
    private static double[,]? ToDoubleMatrix2D(object? val)
    {
        if (val is Array arr && arr.Rank == 2)
        {
            var t = arr.GetLength(0); var n = arr.GetLength(1);
            var m = new double[t, n];
            for (var i = 0; i < t; i++)
                for (var j = 0; j < n; j++)
                    m[i, j] = Convert.ToDouble(arr.GetValue(i, j));
            return m;
        }
        if (val is System.Collections.IList rows && rows.Count > 0 && rows[0] is System.Collections.IList firstRow)
        {
            var t = rows.Count; var n = firstRow.Count;
            var m = new double[t, n];
            for (var i = 0; i < t; i++)
            {
                if (rows[i] is System.Collections.IList row)
                    for (var j = 0; j < n && j < row.Count; j++) m[i, j] = Convert.ToDouble(row[j]);
            }
            return m;
        }
        return null;
    }
    public static Dictionary<string, object?> BacktestRun(object? data, object? strategy, double[]? portfolio)
    {
        // Parità VM (PCodeProcessor case BuiltInFunction.RUN): la strategia è ignorata;
        // i rendimenti per periodo sono la MEDIA degli asset; il portfolio ottimo resta
        // un parametro pass-through non usato nei metriche di base.
        // `data` può essere un array RETTANGOLARE (double[,] — rappresentazione del linguaggio
        // per `DIM data(1,1)`) oppure jagged/lista di periodi.
        var rets = new List<double>();
        if (data is Array mat && mat.Rank >= 2)
        {
            // Array RETTANGOLARE (double[,] per IL, object[,] per PCode/VM-C): media per riga.
            int rows = mat.GetLength(0), cols = mat.GetLength(1);
            for (int r = 0; r < rows; r++)
            {
                double s = 0;
                for (int c = 0; c < cols; c++) s += Convert.ToDouble(mat.GetValue(r, c) ?? 0.0);
                if (cols > 0) rets.Add(s / cols);
            }
        }
        else if (data is System.Collections.IEnumerable en && data is not string)
        {
            foreach (var period in en)
            {
                if (period is System.Collections.IEnumerable row && period is not string)
                {
                    double s = 0; int n = 0;
                    foreach (var v in row) { s += Convert.ToDouble(v ?? 0.0); n++; }
                    if (n > 0) rets.Add(s / n);
                }
                else if (period != null) rets.Add(Convert.ToDouble(period));
            }
        }
        var retArr = rets.ToArray();
        var totalRet = 1.0;
        foreach (var r in retArr) totalRet *= 1 + r;
        totalRet = (totalRet - 1) * 100;
        var annRet = retArr.Length > 0 ? (Math.Pow(totalRet / 100 + 1, 12.0 / retArr.Length) - 1) * 100 : 0.0;
        double peak = 0, maxDD = 0, cum = 0;
        foreach (var r in retArr) { cum += r; if (cum > peak) peak = cum; var d = cum - peak; if (d < maxDD) maxDD = d; }
        maxDD *= 100;
        var avg = retArr.Length > 0 ? retArr.Average() : 0.0;
        var std = retArr.Length > 1 ? Math.Sqrt(retArr.Sum(r => Math.Pow(r - avg, 2)) / (retArr.Length - 1)) : 0.0;
        var sharpe = std > 0 ? avg / std * Math.Sqrt(252) : 0.0;
        return new Dictionary<string, object?>(StringComparer.OrdinalIgnoreCase)
        {
            ["TotalReturn"] = totalRet,
            ["AnnualizedReturn"] = annRet,
            ["MaxDrawdown"] = maxDD,
            ["SharpeRatio"] = sharpe,
            ["TradesCount"] = (double)retArr.Length,
            ["Turnover"] = 0.0,
            ["EquityCurve"] = retArr,
        };
    }

    public static double PortfolioSemiMad(object rets, double target)
    {
        // Supporta sia matrice 2D (T x N) via MadSolver sia array 1D (downside vs target).
        try
        {
            var mat = ToDoubleMatrix2D(rets);
            if (mat != null)
            {
                try { return CommonLib.Trading.MadSolver.SolveSemiMadPortfolio(mat).Mad; } catch { return 0.0; }
            }
            var rr = FlattenReturns(rets);
            var below = rr.Where(x => x < target).ToArray();
            if (below.Length == 0) return 0.0;
            var med = below.OrderBy(x => x).ToArray()[below.Length / 2];
            return below.Average(x => Math.Abs(x - med));
        }
        catch { return 0.0; }
    }

