    /// <summary>F6 multimodale (2026-09-11): AI.AGENTASKFILE(name, path [, question]) — l'agente
    /// riceve un input multimodale: il file viene instradato a vision (immagine), STT (audio) o
    /// estrazione documento (pdf/testo), poi il testo estratto è passato all'agente. Nessun nuovo
    /// modello (riuso OCR/TRANSCRIBE/DOCEXTRACT). File mancante/contenuto non estraibile → errore
    /// esplicito (mai un risultato silenzioso).</summary>
    public static string AiAgentAskFile(string name, string path, string question)
    {
        if (string.IsNullOrEmpty(path) || !System.IO.File.Exists(path))
            return $"ERROR: file non trovato: {path}";
        var ext = System.IO.Path.GetExtension(path).ToLowerInvariant();
        string content;
        if (ext is ".png" or ".jpg" or ".jpeg" or ".bmp" or ".gif" or ".webp" or ".tif" or ".tiff")
            content = AiOcrFull(path, "Descrivi il contenuto dell'immagine.", 0);
        else if (ext is ".wav" or ".mp3" or ".m4a" or ".ogg" or ".flac" or ".aac")
            content = AiTranscribe(path);
        else if (ext is ".txt" or ".md" or ".csv" or ".log" or ".json" or ".xml" or ".html" or ".htm")
        {
            try { content = System.IO.File.ReadAllText(path); } catch { content = ""; }
        }
        else
            content = DocExtract(path);
        if (string.IsNullOrEmpty(content))
            return $"ERROR: contenuto non estraibile: {path}";
        var prompt = string.IsNullOrEmpty(question) ? content : question + "\n\n" + content;
        return AiAgentAsk(name, prompt);
    }

