        if (!CommonLib.VideoUtils.TryReadY4mFrame(path, (int)index, out int w, out int h, out var rgba, out _)) return 0;
        return CommonLib.ImageUtils.TryWritePng(output, rgba, w, h, out _) ? 1 : 0;
    }
