    /// <summary>AI.ANALYZEIMAGE(path, prompt) (D1 — loop computer-use): legge l'immagine e la
    /// descrive col completer VISION attivo (IVisionCompleter), con fallback deterministico
    /// FixtureVisionCompleter in headless/test. MAI un risultato silenzioso: file mancante o
    /// nessun completer vision → errore esplicito.</summary>
    public static string AiAnalyzeImage(string path, string prompt)
    {
        if (string.IsNullOrWhiteSpace(path) || !System.IO.File.Exists(path))
            return $"ERROR: file immagine non trovato: {path}";
        byte[] bytes;
        try
        {
            bytes = System.IO.File.ReadAllBytes(path);
        }
        catch (Exception ex)
        {
            return $"ERROR: lettura immagine fallita: {ex.Message}";
        }
        var fmt = System.IO.Path.GetExtension(path).TrimStart('.').ToLowerInvariant();
        if (fmt is "jpg" or "jpeg") fmt = "jpeg";
        var completer = Basic.Providers.ProviderServer.Instance.GetActiveCompletion();
        var vision = completer as Basic.AI.Rag.IVisionCompleter ?? new Basic.AI.Rag.FixtureVisionCompleter();
        try
        {
            return vision.DescribeImage(bytes, fmt, string.IsNullOrEmpty(prompt) ? "Descrivi l'immagine" : prompt);
        }
        catch (Exception ex)
        {
            return $"ERROR: analisi immagine fallita: {ex.Message}";
        }
    }

    /// <summary>PROCESS &lt;file&gt; PROMPT: &lt;istruzioni&gt; (E0): estrae il testo del documento
    /// (dispatch per estensione: pdf/docx/xlsx/csv/md/html/rtf/epub/odt/pptx via ConversionLib,
    /// json/testo raw) e lo invia all'agente con il prompt di elaborazione — l'agente esegue le
    /// istruzioni (riassunto, RAG, SQL, report). Usa un agente interno "doc" (creato al primo
    /// uso) col completer attivo (fixture nei test).</summary>
    public static string ProcessDocument(string file, string? prompt)
    {
        try
        {
            var text = ExtractDocumentText(file);
            var agent = "doc";
            Basic.Agents.AgentServer.Instance.Create(agent); // idempotente
            var agentPrompt = string.IsNullOrWhiteSpace(prompt) ? "Riassumi il documento." : prompt!;
            agentPrompt += "\n\n--- DOCUMENTO (" + file + ") ---\n" + text;
            var answer = Basic.Agents.AgentServer.Instance.Ask(agent, agentPrompt);
            // Stampa la risposta dell'agente (riassunto/risultato) — comportamento unificato su
            // tutti i backend (il comando è void ma il risultato deve essere visibile).
            try { PrintDispatch(answer); } catch { }
            return answer;
        }
        catch (Exception ex)
        {
            return $"PROCESS ERROR: {ex.Message}";
        }
    }

    /// <summary>Estrae il testo di un documento per PROCESS (dispatch per estensione).</summary>
    public static string ExtractDocumentText(string file)
    {
        if (!File.Exists(file))
            throw new FileNotFoundException($"Documento non trovato: {file}");
        var ext = Path.GetExtension(file).ToLowerInvariant();
        try
        {
            return ext switch
            {
                ".pdf" or ".docx" or ".xlsx" or ".csv" or ".md" or ".html" or ".rtf" or ".epub" or ".odt" or ".pptx" or ".txt"
                    => ConversionLazy.ConvertDocFile(file, "txt"),
                _ => File.ReadAllText(file),
            };
        }
        catch (Exception ex)
        {
            // Fallback: legge raw se la conversione non è disponibile.
            try { return File.ReadAllText(file); }
            catch { throw new InvalidOperationException($"Conversione di '{file}' fallita: {ex.Message}"); }
        }
    }

    /// <summary>C7 — estrazione STRUTTURATA: il modello estrae dati da un testo (pagina/documento)
    /// secondo uno SCHEMA (JSON `{"campo":"tipo"}`) con validazione. L'agente (completer attivo,
    /// fixture nei test) produce il JSON; <see cref="ValidateStructuredOutput"/> lo verifica contro
    /// lo schema. Ritorna il JSON strutturato o un errore esplicito.</summary>
    public static string StructuredOutput(string text, string instruction, string schema)
    {
        try
        {
            var agent = "extract";
            Basic.Agents.AgentServer.Instance.Create(agent);
            var prompt = "EXTRACT STRUCTURED SCHEMA: " + schema +
                         "\nINSTRUCTION: " + (string.IsNullOrWhiteSpace(instruction) ? "Estrai i dati come da schema." : instruction) +
                         "\nPAGE: " + text;
            var json = Basic.Agents.AgentServer.Instance.Ask(agent, prompt);
            return ValidateStructuredOutput(json, schema);
        }
        catch (Exception ex)
        {
            return $"EXTRACT ERROR: {ex.Message}";
        }
    }

    /// <summary>Valida un JSON strutturato contro uno schema `{"campo":"tipo"}`: verifica che sia
    /// JSON valido e che OGNI campo dello schema sia presente col tipo dichiarato. Ritorna il JSON
    /// se valido, altrimenti un errore esplicito (mai un risultato muto).</summary>
    public static string ValidateStructuredOutput(string json, string schema)
    {
        if (string.IsNullOrWhiteSpace(json)) return "EXTRACT ERROR: risposta vuota.";
        try
        {
            using var doc = System.Text.Json.JsonDocument.Parse(json);
            if (doc.RootElement.ValueKind != System.Text.Json.JsonValueKind.Object)
                return "EXTRACT ERROR: la risposta non è un oggetto JSON.";
            if (string.IsNullOrWhiteSpace(schema)) return json;

            using var sch = System.Text.Json.JsonDocument.Parse(schema);
            if (sch.RootElement.ValueKind != System.Text.Json.JsonValueKind.Object)
                return json;
            foreach (var prop in sch.RootElement.EnumerateObject())
            {
                if (!doc.RootElement.TryGetProperty(prop.Name, out var val))
                    return $"EXTRACT ERROR: campo '{prop.Name}' mancante nella risposta.";
                var want = (prop.Value.GetString() ?? "string").ToLowerInvariant();
                var ok = want switch
                {
                    "number" or "integer" or "double" => val.ValueKind is System.Text.Json.JsonValueKind.Number,
                    "bool" or "boolean" => val.ValueKind is System.Text.Json.JsonValueKind.True or System.Text.Json.JsonValueKind.False,
                    "string" => val.ValueKind is System.Text.Json.JsonValueKind.String,
                    "array" => val.ValueKind is System.Text.Json.JsonValueKind.Array,
                    "object" => val.ValueKind is System.Text.Json.JsonValueKind.Object,
                    _ => true,
                };
                if (!ok)
                    return $"EXTRACT ERROR: campo '{prop.Name}' ha tipo non '{want}'.";
            }
            return json;
        }
        catch (Exception ex)
        {
            return $"EXTRACT ERROR: JSON non valido — {ex.Message}";
        }
    }
    public static Action<string>? GetStringProcedureDelegate(int symbolId)
    {
        var method = FindProcedureMethod(symbolId, [typeof(string)]);
        return method is null ? null : (Action<string>)Delegate.CreateDelegate(typeof(Action<string>), method);
    }
    public static Action<string, string>? GetStringPairProcedureDelegate(int symbolId)
    {
        var method = FindProcedureMethod(symbolId, [typeof(string), typeof(string)]);
        return method is null ? null : (Action<string, string>)Delegate.CreateDelegate(typeof(Action<string, string>), method);
    }
    public static System.Reflection.MethodInfo? FindProcedureMethod(int symbolId, Type[]? paramTypes)
        // PREFERISCE l'assembly del programma corrente (`SetProcedureAssembly`, emesso
        // dall'entry di ogni programma) e solo in mancanza cerca negli altri. Prima partiva da
        // null, quindi scandiva TUTTI gli assembly caricati nell'AppDomain: in un processo che
        // esegue più programmi (harness MiniTest xUnit, sweep, BSP) i `Proc_<id>` collidono fra
        // assembly e la ricerca poteva risolvere la procedura di un ALTRO programma — sintomo:
        // il 2° MiniTest HTTP dispatchava gli handler del 1° (corpo "body" invece di "GET-OK")
        // e poi andava in TIMEOUT. Vedi Bugs/(solved) - MiniTest-HTTP-Server-Stesso-Processo.
        => FindProcedureMethodIn(Volatile.Read(ref _basicProcedureAssembly), symbolId, paramTypes);

    /// <summary>Come <see cref="FindProcedureMethod(int, Type[])"/> ma limitato all'assembly
    /// PREFERITO (quello del sample corrente): in un processo condiviso (sweep/harness) i proc
    /// id collidono tra assembly — senza il preferred, FindProcedureMethod poteva risolvere la
    /// Proc_&lt;id&gt; di un ALTRO sample ('Invalid cast String→ChannelInfo').</summary>
    public static System.Reflection.MethodInfo? FindProcedureMethod(System.Reflection.Assembly preferred, int symbolId, Type[]? paramTypes)
        => FindProcedureMethodIn(preferred, symbolId, paramTypes);

    private static System.Reflection.MethodInfo? FindProcedureMethodIn(
        System.Reflection.Assembly? preferred, int symbolId, Type[]? paramTypes)
    {
        var methodName = "Proc_" + symbolId;
        foreach (var asm in ProcedureAssemblies(preferred))
        {
            var programType = asm.GetType("GeneratedProgram");
            if (programType is null) continue;
            System.Reflection.MethodInfo? method = paramTypes is null
                ? programType.GetMethod(methodName, BindingFlags.Public | BindingFlags.Static | BindingFlags.DeclaredOnly)
                : programType.GetMethod(methodName, BindingFlags.Public | BindingFlags.Static | BindingFlags.DeclaredOnly, binder: null, paramTypes, modifiers: null);
            if (method is not null) return method;
            foreach (var m in programType.GetMethods(BindingFlags.Public | BindingFlags.Static | BindingFlags.DeclaredOnly))
                if (m.Name == methodName) return m;
        }
        return null;
    }

    private static IEnumerable<System.Reflection.Assembly> ProcedureAssemblies(System.Reflection.Assembly? preferred)
    {
        if (preferred is not null) yield return preferred;
        foreach (var asm in AppDomain.CurrentDomain.GetAssemblies())
            if (!ReferenceEquals(asm, preferred)) yield return asm;
    }
    public static double AiAgentAskStream(string name, string prompt, int callbackSymbolId)
    {
        // La callback (token in streaming) NON invoca la SUB in diretta sul thread di
        // Task.Run (iniezione esterna nel GPM): la dispatcha come TASK GPM, parità WS/input.
        var method = FindProcedureMethod(callbackSymbolId, [typeof(string)]);
        Action<string> onToken = method is null
            ? _ => { }
            : token => DispatchHandlerAsGpmOrDirect(callbackSymbolId, method, [token]);
        _ = Task.Run(() =>
        {
            try
            {
                Basic.Agents.AgentServer.Instance.AskStream(name, prompt, onToken);
            }
            catch (Exception ex)
            {
                Console.Error.WriteLine($"[AI AGENT ASK stream] {ex.Message}");
            }
        });
        return 1.0;
    }

    /// <summary>Variante PCode di <see cref="AiAgentAskStream"/>: il compiler PCode emette il
    /// NOME della SUB callback (StringExpr) come 3° argomento, non lo symbol id (il path
    /// reflection su GeneratedProgram è solo IL). La callback per-token viene dispatchata come
    /// TASK PCode via <see cref="InvokeBasicProcedureGpm"/> (GPM = unico esecutore), mai sul
    /// thread di Task.Run.</summary>
    public static double AiAgentAskStreamByName(string name, string prompt, string callbackName)
    {
        Action<string> onToken = token =>
        {
            try
            {
                var json = "{\"p0\":" + System.Text.Json.JsonSerializer.Serialize(token ?? "") + "}";
                InvokeBasicProcedureGpm(callbackName, json);
            }
            catch (Exception ex)
            {
                Console.Error.WriteLine($"[AI AGENT ASK stream] callback '{callbackName}': {ex.Message}");
            }
        };
        _ = Task.Run(() =>
        {
            try
            {
                Basic.Agents.AgentServer.Instance.AskStream(name, prompt, onToken);
            }
            catch (Exception ex)
            {
                Console.Error.WriteLine($"[AI AGENT ASK stream] {ex.Message}");
            }
        });
        return 1.0;
    }
