        {
            if (Basic.AI.Managed.ManagedMacAx.Available())
                return Basic.AI.Managed.ManagedMacAx.FindJson(target);
        }
        catch (System.Exception ex) { return "{\"found\":false,\"error\":\"" + ex.Message.Replace("\"", "\\\"") + "\"}"; }
        return "{\"found\":false,\"error\":\"AX non disponibile (Accessibilità su macOS)\"}";
