    public static bool UiClick(string target)
    {
        // UI.CLICK è dichiarato BitType in StdLib.Ui.cs (DataTypeMapper.Map(BitType) =
        // System.Boolean): la firma DEVE ritornare bool, non double — altrimenti il call
        // pusha un double genuino sullo stack ma il coercion codegen (EmitNumeric, guidato
        // dal tipo DICHIARATO BitType) applica comunque la sequenza bool→numerico
        // (Ldc_I4_M1; Mul, la conversione -1/0 di un vero bool CLR) a un double — IL non
        // valido (mul fra float64 e int32 senza widening), rifiutato da ILOptim
        // (BinaryInst "Invalid operand types") pur girando nel fallback non ottimizzato del
        // JIT. Con bool, la stessa sequenza produce correttamente -1/0 (parità con il resto
        // della convenzione BASIC: true = -1, non 1 — ClickOk sotto ritorna un raw int 0/1).
        try
        {
            if (Basic.AI.Managed.ManagedMacAx.Available())
                return Basic.AI.Managed.ManagedMacAx.ClickOk(target) != 0;
        }
        catch { }
        return false;
    }
    public static string UiFindAll(string target)
    {
        // Headless/CI (AX non disponibile) o needle vuota → array vuoto (deterministico).
        // Con AX: walk collect-all reale in ManagedMacAx (parità VMC gmb_action_resolver_findall).
        try
        {
            return Basic.AI.Managed.ManagedMacAx.FindAllJson(target ?? "");
        }
        catch { return "[]"; }
    }
