    // 1 chromium, 2 obscura). Il percorso stringa `BrowserStart(string,...)` resta SOLO
    // per il dispatch MCP/CLI (mai esposto al BASIC).
    public static string BrowserStart(string provider = "auto", int port = 0, string profile = "")
    {
        if (string.IsNullOrWhiteSpace(provider)) provider = "auto";
