    /// la stringa motore è derivata da Basic.AI.Browser.BrowserProviderRegistry.EngineName
    /// (controllo di compilazione — mai stringhe "auto"/"chromium"/"obscura" nel BASIC).</summary>
    public static string BrowserStartEngine(double engine = 0, int port = 0, string profile = "")
        => BrowserStart(Basic.AI.Browser.BrowserProviderRegistry.EngineName(engine), port, profile);

    /// <summary>Dispatch nativo MCP per i tool browser_* (§5 Camoufox — MCP browser server esterno).
    /// Percorso puro C# (BrowserRuntime → CDP), NIENTE wrapper BASIC: i tool MCP puntano a questo
    /// invece che a una FUNCTION (aggira il limite UnresolvedCallExpr di BROWSER.* come RHS/ritorno).
    /// Args JSON letti per nome; default tolleranti. Ritorna il testo della risposta tool.</summary>
    public static string BrowserToolDispatch(string toolName, string argsJson)
    {
        using var doc = System.Text.Json.JsonDocument.Parse(string.IsNullOrWhiteSpace(argsJson) ? "{}" : argsJson);
        var r = doc.RootElement;
        string S(string p) => r.TryGetProperty(p, out var v) && v.ValueKind == System.Text.Json.JsonValueKind.String ? v.GetString() ?? "" : "";
        int I(string p, int d) => r.TryGetProperty(p, out var v) && v.TryGetInt32(out var i) ? i : d;
        switch (toolName.ToLowerInvariant())
        {
            case "browser_navigate": return BrowserNavigate(S("url"));
            case "browser_snapshot": case "browser_text": return BrowserSnapshot();
            case "browser_accesstree": return BrowserAccessTree();
            case "browser_click": return BrowserClick(S("selector"));
            case "browser_human_click": return BrowserHumanClick(S("selector"));
            case "browser_fill": return BrowserFill(S("selector"), S("value"));
            case "browser_human_fill": return BrowserHumanFill(S("selector"), S("value"));
            case "browser_evaluate": return BrowserEvaluate(S("expression"));
            case "browser_screenshot": return BrowserScreenshot(S("path"));
            case "browser_get_cookies": return BrowserGetCookies();
            case "browser_set_cookie": return BrowserSetCookie(S("name"), S("value"), S("url"));
            case "browser_clear_cookies": return BrowserClearCookies();
            case "browser_set_header": return BrowserSetHeader(S("name"), S("value"));
            case "browser_set_user_agent": return BrowserSetUserAgent(S("userAgent"));
            case "browser_human_scroll": return BrowserHumanScroll(I("dy", 0));
            case "browser_observe": return BrowserObserve(S("preset") is { Length: > 0 } pr_o ? pr_o : null);
            case "browser_find": return BrowserFind(S("text"), r.TryGetProperty("regex", out var rg) && rg.ValueKind == System.Text.Json.JsonValueKind.True);
            case "browser_auth": return BrowserAuth(S("op"), S("name"));
            case "browser_start": return BrowserStart(S("provider") is { } pv && pv.Length > 0 ? pv : "auto", I("port", 0), S("profile"));
            default: throw new System.InvalidOperationException($"browser tool sconosciuto: {toolName}");
        }
    }

    /// <summary>InputSchema MCP per i tool browser_* nativi (nomi parametro reali dei builtin),
    /// usato da McpRegisterTool quando procName = nome tool (non una FUNCTION BASIC).</summary>
    public static System.Text.Json.Nodes.JsonObject? BrowserToolSchema(string toolName)
    {
        (string, bool)[] Ps(params (string Name, bool Opt)[] p) => p;
        System.Text.Json.Nodes.JsonObject Build((string, bool)[] pars)
        {
            var props = new System.Text.Json.Nodes.JsonObject();
            var req = new System.Text.Json.Nodes.JsonArray();
            foreach (var (n, opt) in pars)
            {
                props[n] = new System.Text.Json.Nodes.JsonObject { ["type"] = n is "dy" or "port" ? "integer" : "string" };
                if (!opt) req.Add(n);
            }
            return new System.Text.Json.Nodes.JsonObject { ["type"] = "object", ["properties"] = props, ["required"] = req };
        }
        switch (toolName.ToLowerInvariant())
        {
            case "browser_navigate": return Build(Ps(("url", false)));
            case "browser_snapshot": case "browser_text": case "browser_accesstree": case "browser_get_cookies": case "browser_clear_cookies": return Build(Ps());
            case "browser_click": case "browser_human_click": return Build(Ps(("selector", false)));
            case "browser_fill": case "browser_human_fill": return Build(Ps(("selector", false), ("value", false)));
            case "browser_evaluate": return Build(Ps(("expression", false)));
            case "browser_screenshot": return Build(Ps(("path", true)));
            case "browser_set_cookie": return Build(Ps(("name", false), ("value", false), ("url", true)));
            case "browser_set_header": return Build(Ps(("name", false), ("value", false)));
            case "browser_set_user_agent": return Build(Ps(("userAgent", false)));
            case "browser_human_scroll": return Build(Ps(("dy", false)));
            case "browser_start": return Build(Ps(("provider", true), ("port", true), ("profile", true)));
            default: return null;
        }
    }

