    /// <summary>AI.CACHESTATS(name) — legge le stats della KV-cache del contesto risolto per
    /// nome (oggi: sessione dell'agente; futuro: alias di cache first-class). Usa il resolver
    /// unificato KvCacheContextResolver, con errore esplicito se il nome non risolve.</summary>
    public static string AiCacheStats(string name)
    {
        var ctx = Basic.AI.Rag.KvCacheContextResolver.Resolve(name);
        var s = ctx?.Stats();
        if (ctx is null || s is null)
            return $"{{\"error\":\"'{name}' non risolve a un contesto KV con completer cache-manager (agente non registrato o fixture)\"}}";
        return $"{{\"context\":\"{ctx.Name}\",\"nCtx\":{s.NCtx},\"nTokens\":{s.NTokens},\"bytes\":{s.Bytes},\"posMin\":{s.PosMin},\"posMax\":{s.PosMax},\"usedPercent\":{s.UsedPercent.ToString("0.00", System.Globalization.CultureInfo.InvariantCulture)}}}";
    }

