    /// <summary>AI PREFILL alias, "testo" [, {json}] — fa il prefill della sessione KV
    /// dell'agente (context = agente; futuro: alias cache first-class via KvCacheContextResolver)
    /// appendendo il testo come turno nel formato della chat. json opzionale: {"role":"user"|"system"}
    /// (default user). Ritorna JSON con esito o errore esplicito se il nome non risolve o il
    /// completer non è session-aware. Mai stub: nessun risultato silenzioso.</summary>
    public static string AiPrefill(string name, string text, string json)
    {
        if (string.IsNullOrWhiteSpace(text))
            return "{\"error\":\"testo prefill vuoto\"}";
        var role = "user";
        if (!string.IsNullOrWhiteSpace(json))
        {
            try
            {
                using var doc = System.Text.Json.JsonDocument.Parse(json);
                if (doc.RootElement.TryGetProperty("role", out var r) && r.ValueKind == System.Text.Json.JsonValueKind.String)
                    role = r.GetString() ?? "user";
            }
            catch { /* json malformato: usa default */ }
        }
        return Basic.Agents.AgentServer.Instance.Prefill(name, role, text);
    }

