    // ── MODEL COMPILER LLM (namespace LLM) — P/Invoke al runtime CONDIVISO C (dylib gmb_ai_llm) ──
    // I verbi PLAN/POLICY/QUANT/MERGE/PRUNE/EXTRACT/PROFILE/ARCH sono eseguiti dalla STESSA logica C
    // di C99Native/VM-C (una sola sorgente, AGENTS: C#→C ammesso; C→C# mai). Mai
    // silenzioso: rc != 0 → errore esplicito.
    private static string LlmEnsure(int rc, string verb, string detail)
    {
        if (rc != 0) throw new InvalidOperationException("LLM verbo fallito");   /* testo UNIFORME su 4 backend */
        return "{\"ok\":true}";
    }

    public static string LlmPlan(string input, string output) =>
        LlmEnsure(Basic.Providers.LlmModelNative.llmmodelio_model_plan(input, output), "PLAN", input);
    public static string LlmPolicy(string sub, string a, string b, string c)
    {
        var buf = new byte[16384];
        int rc = Basic.Providers.LlmModelNative.llmmodelio_policy_cmd_to(sub, a ?? "", b ?? "", c ?? "", buf, buf.Length);
        int n = Array.IndexOf(buf, (byte)0); if (n < 0) n = buf.Length;
        string txt = System.Text.Encoding.UTF8.GetString(buf, 0, n);
        if (txt.Length > 0) { Current.Console.Print(txt); if (!txt.EndsWith("\n")) Current.Console.PrintNewLine(); }
        return LlmEnsure(rc, "POLICY", sub);
    }
    /// <summary>Policy Livello B (mondo gestito): la GPM C# itera il piano (nativo) e invoca la
    /// SUB BASIC via delegate `decide(name, role, dflt) -> fmt` (il delegate e' la SUB compilata,
    /// passata dall'emitter). Registra gli override per-tensore. MAI da thread .NET esterni:
    /// gira nel task GPM che esegue lo statement.</summary>
    public static double LlmPolicyCallback(System.Func<string, string, string, string> decide)
    {
        if (decide == null) throw new InvalidOperationException("LLM POLICY CALLBACK: callback nullo");
        int n = Basic.Providers.LlmModelNative.llmmodelio_policy_item_count();
        var buf = new byte[1024]; int applied = 0;
        for (int i = 0; i < n; i++)
        {
            System.Array.Clear(buf, 0, buf.Length);
            if (Basic.Providers.LlmModelNative.llmmodelio_policy_item_to(i, buf, buf.Length) != 0) continue;
            int len = System.Array.IndexOf(buf, (byte)0); if (len < 0) len = buf.Length;
            var parts = System.Text.Encoding.UTF8.GetString(buf, 0, len).Split('\t');
            if (parts.Length < 3) continue;
            var fmt = decide(parts[0], parts[1], parts[2]) ?? "";
            if (fmt.Length > 0) { Basic.Providers.LlmModelNative.llmmodelio_policy_set_item(parts[0], fmt); applied++; }
        }
        return applied;
    }

    // GMB MODULE <REGISTER|PRIORITY|LIST|SYM> — registry di moduli esterni (model compiler §4.3).
    // Lato IL/PCode (C#): registry in-process mirror del runtime C (gmb_module_*). §0bis: la logica
    // C vive una volta sola (gmb_module.c); questo è l'equivalente nel mondo gestito.
    private static readonly System.Collections.Generic.List<(string slot, string dylib, int pri, int seq)> _gmbMods = new();
    private static int _gmbModSeq = 0;
    public static string GmbModule(string sub, string a, string b)
    {
        switch ((sub ?? "").ToUpperInvariant())
        {
            case "REGISTER":
                if (string.IsNullOrEmpty(a) || string.IsNullOrEmpty(b))
                    throw new InvalidOperationException("GMB MODULE REGISTER: attesi (slot, dylib)");
                _gmbMods.RemoveAll(m => m.slot == a && m.dylib == b);
                _gmbMods.Add((a, b, 0, _gmbModSeq++));
                return "{\"ok\":true}";
            case "PRIORITY": {
                if (string.IsNullOrEmpty(a)) throw new InvalidOperationException("GMB MODULE PRIORITY: atteso (slot, pri)");
                int pri = 0; int.TryParse(b, out pri);
                int n = 0;
                for (int i = 0; i < _gmbMods.Count; i++)
                    if (_gmbMods[i].slot == a) { var m = _gmbMods[i]; _gmbMods[i] = (m.slot, m.dylib, pri, m.seq); n++; }
                if (n == 0) throw new InvalidOperationException($"GMB MODULE PRIORITY: slot '{a}' non registrato");
                return "{\"ok\":true}";
            }
            case "LIST": {
                var sb = new System.Text.StringBuilder();
                for (int i = 0; i < _gmbMods.Count; i++)
                    sb.Append(_gmbMods[i].slot).Append('\t').Append(_gmbMods[i].dylib).Append('\t').Append(_gmbMods[i].pri).Append('\n');
                var txt = sb.ToString();
                if (txt.Length > 0) { Current.Console.Print(txt); if (!txt.EndsWith("\n")) Current.Console.PrintNewLine(); }
                return "{\"ok\":true}";
            }
            case "SYM":
                if (string.IsNullOrEmpty(a) || string.IsNullOrEmpty(b))
                    throw new InvalidOperationException("GMB MODULE SYM: attesi (slot, simbolo)");
                return GmbModuleSymbol(a, b);
            case "CALL":
                if (string.IsNullOrEmpty(a) || string.IsNullOrEmpty(b))
                    throw new InvalidOperationException("GMB MODULE CALL: attesi (slot, \"simbolo|sig|args\")");
                return GmbModuleCall(a, b);
            default:
                throw new InvalidOperationException($"GMB MODULE: sotto-verbo '{sub}' non supportato (REGISTER|PRIORITY|LIST|SYM)");
        }
    }
    // GMB MODULE CALL: invoca un export della dylib vincente dello slot via P/Invoke (C#->C,
    // §REGOLA PRIMARIA). `packed` = "simbolo|sig|argsCsv"; sig = <ritorno><param...> ('d'=double,
    // 'i'=int64). Stessa forma e stesse firme del runtime C (gmb_module_call_to).
    private static string GmbModuleCall(string slot, string packed)
    {
        var parts = (packed ?? "").Split('|');
        if (parts.Length < 2) throw new InvalidOperationException("GMB MODULE CALL: atteso \"simbolo|sig|args\"");
        string sym = parts[0], sig = parts[1], csv = parts.Length >= 3 ? parts[2] : "";
        int best = -1;
        for (int i = 0; i < _gmbMods.Count; i++)
            if (_gmbMods[i].slot == slot && (best < 0 || _gmbMods[i].pri > _gmbMods[best].pri
                || (_gmbMods[i].pri == _gmbMods[best].pri && _gmbMods[i].seq > _gmbMods[best].seq)))
                best = i;
        if (best < 0) throw new InvalidOperationException($"GMB MODULE CALL: slot '{slot}' non risolto");
        var h = System.Runtime.InteropServices.NativeLibrary.Load(_gmbMods[best].dylib);
        var fp = System.Runtime.InteropServices.NativeLibrary.GetExport(h, sym);
        if (fp == IntPtr.Zero) throw new InvalidOperationException($"GMB MODULE CALL: simbolo '{sym}' non risolto");
        var tk = csv.Length == 0 ? System.Array.Empty<string>() : csv.Split(',');
        double D(int k) => k < tk.Length ? double.Parse(tk[k], System.Globalization.CultureInfo.InvariantCulture) : 0.0;
        long I(int k) => k < tk.Length ? long.Parse(tk[k], System.Globalization.CultureInfo.InvariantCulture) : 0L;
        string res;
        switch (sig)
        {
            case "dd":   { var f = System.Runtime.InteropServices.Marshal.GetDelegateForFunctionPointer<D_D>(fp); res = f(D(0)).ToString("G10", System.Globalization.CultureInfo.InvariantCulture); break; }
            case "ddd":  { var f = System.Runtime.InteropServices.Marshal.GetDelegateForFunctionPointer<D_DD>(fp); res = f(D(0), D(1)).ToString("G10", System.Globalization.CultureInfo.InvariantCulture); break; }
            case "dddd": { var f = System.Runtime.InteropServices.Marshal.GetDelegateForFunctionPointer<D_DDD>(fp); res = f(D(0), D(1), D(2)).ToString("G10", System.Globalization.CultureInfo.InvariantCulture); break; }
            case "ii":   { var f = System.Runtime.InteropServices.Marshal.GetDelegateForFunctionPointer<I_I>(fp); res = f(I(0)).ToString(System.Globalization.CultureInfo.InvariantCulture); break; }
            case "iii":  { var f = System.Runtime.InteropServices.Marshal.GetDelegateForFunctionPointer<I_II>(fp); res = f(I(0), I(1)).ToString(System.Globalization.CultureInfo.InvariantCulture); break; }
            case "iiii": { var f = System.Runtime.InteropServices.Marshal.GetDelegateForFunctionPointer<I_III>(fp); res = f(I(0), I(1), I(2)).ToString(System.Globalization.CultureInfo.InvariantCulture); break; }
            default: throw new InvalidOperationException($"GMB MODULE CALL: firma '{sig}' non supportata");
        }
        Current.Console.Print(res); Current.Console.PrintNewLine();
        return "{\"ok\":true}";
    }
    [System.Runtime.InteropServices.UnmanagedFunctionPointer(System.Runtime.InteropServices.CallingConvention.Cdecl)] private delegate double D_D(double a);
    [System.Runtime.InteropServices.UnmanagedFunctionPointer(System.Runtime.InteropServices.CallingConvention.Cdecl)] private delegate double D_DD(double a, double b);
    [System.Runtime.InteropServices.UnmanagedFunctionPointer(System.Runtime.InteropServices.CallingConvention.Cdecl)] private delegate double D_DDD(double a, double b, double c);
    [System.Runtime.InteropServices.UnmanagedFunctionPointer(System.Runtime.InteropServices.CallingConvention.Cdecl)] private delegate long I_I(long a);
    [System.Runtime.InteropServices.UnmanagedFunctionPointer(System.Runtime.InteropServices.CallingConvention.Cdecl)] private delegate long I_II(long a, long b);
    [System.Runtime.InteropServices.UnmanagedFunctionPointer(System.Runtime.InteropServices.CallingConvention.Cdecl)] private delegate long I_III(long a, long b, long c);

    private static string GmbModuleSymbol(string slot, string symbol)
    {
        int best = -1;
        for (int i = 0; i < _gmbMods.Count; i++)
            if (_gmbMods[i].slot == slot && (best < 0 || _gmbMods[i].pri > _gmbMods[best].pri
                || (_gmbMods[i].pri == _gmbMods[best].pri && _gmbMods[i].seq > _gmbMods[best].seq)))
                best = i;
        if (best < 0) throw new InvalidOperationException($"GMB MODULE SYM: slot '{slot}' non risolto");
        try
        {
            var h = System.Runtime.InteropServices.NativeLibrary.Load(_gmbMods[best].dylib);
            var s = System.Runtime.InteropServices.NativeLibrary.GetExport(h, symbol);
            return s != IntPtr.Zero ? $"{{\"slot\":\"{slot}\",\"symbol\":\"{symbol}\"}}" : "{}";
        }
        catch (System.Exception e) { throw new InvalidOperationException($"GMB MODULE SYM: {e.Message}"); }
    }
