    // Model compiler LLM: verbi TENSOR/KERNEL/MODULE/KV (superficie .gmbarch data-driven). Stesso
    // schema di LlmArch: P/Invoke alla variante `_to` (cattura il testo), stampa col console del
    // runtime, esito come stringa. Una sola sorgente C per tutti i backend (AGENTS C#→C).
    public static string LlmTensor(string sub, string a, string b, string c) => LlmCmdTo4("TENSOR", sub, a, b, c,
        (s, x, y, z, buf) => Basic.Providers.LlmModelNative.llmmodelio_tensor_cmd_to(s, x, y, z, buf, buf.Length));
    /// <summary>B2 — LLM.TOKENCOUNT(model, testo): numero di token (fonte unica llmtoken, in C).</summary>
    public static double LlmTokenCount(string model, string text)
        => Basic.Providers.LlmModelNative.llmmodelio_token_count(model ?? "", text ?? "");

    // ── B2 (2026-10-30) — verbi LLM come VALORE ─────────────────────────────────────────────
    // Il comando (`LLM TENSOR <sub>`, `LLM TOKENS …`) STAMPA l'output; queste varianti lo
    // RESTITUISCONO senza stampare (cattura nel buffer, nessuna scrittura su console).
    // Sorgente unica: il dispatcher C `llmmodelio_tensor_cmd_to` (una sola implementazione).
    private static string LlmCapture4(string sub, string a, string b, string c)
    {
        int cap = 1 << 16; string txt = "";
        while (true)
        {
            var buf = new byte[cap];
            int rc = Basic.Providers.LlmModelNative.llmmodelio_tensor_cmd_to(
                sub ?? "", a ?? "", b ?? "", c ?? "", buf, buf.Length);
            int n = Array.IndexOf(buf, (byte)0); if (n < 0) n = buf.Length;
            txt = System.Text.Encoding.UTF8.GetString(buf, 0, n);
            if (n < cap - 1 || cap >= (1 << 24)) break;
            cap <<= 1;
        }
        return txt;
    }

    /// <summary>LLM.TOKENS(model, testo) → "74,71,78,…" (gli id come dato, non stampati).</summary>
    public static string LlmTokens(string model, string text)
        => LlmCaptureStr((buf, cap) => Basic.Providers.LlmModelNative.llmmodelio_tokenize_ids_to(model ?? "", text ?? "", buf, (nuint)cap));

    /// <summary>LLM.DETOKENIZE(model, "74,71,…") → testo.</summary>
    public static string LlmDetokenize(string model, string ids)
        => LlmCaptureStr((buf, cap) => Basic.Providers.LlmModelNative.llmmodelio_detokenize_to(model ?? "", ids ?? "", buf, (nuint)cap));

    /// <summary>Buffer adattivo + decodifica UTF-8 (stesso contratto di LlmCmdTo4).</summary>
    private static string LlmCaptureStr(Func<byte[], int, int> call)
    {
        int cap = 1 << 16;
        while (true)
        {
            var buf = new byte[cap];
            int rc = call(buf, cap);
            int n = Array.IndexOf(buf, (byte)0); if (n < 0) n = buf.Length;
            string txt = System.Text.Encoding.UTF8.GetString(buf, 0, n);
            if (rc == -2) { cap <<= 1; if (cap > (1 << 24)) throw new InvalidOperationException("LLM: output troppo grande (> 16 MiB)."); continue; }
            if (rc < 0) throw new InvalidOperationException("LLM: verbo fallito (output non disponibile: modello/argomenti non validi).");
            if (n < cap - 1 || cap >= (1 << 24)) return txt;
            cap <<= 1;
        }
    }

    /// <summary>LLM.TENSOROUT(sub, a[, b[, c]]) → output del sotto-verbo (niente stampa).</summary>
    public static string LlmTensorValue(string sub, string a, string b, string c)
        => LlmFamilyOut(FamTensor, sub, a, b, c);

    // Famiglie del dispatch gmbllm (stesso ordine dell'enum C in gmb_llm_tok.h).
    private const int FamTensor = 0, FamPolicy = 1, FamArch = 2, FamModule = 3, FamKernel = 4, FamKv = 5;

    /// <summary>Output catturato di una famiglia LLM (dispatch sui `_cmd_to` di gmbllm: una sola
    /// implementazione nel motore; i backend C usano il wrapper statico gmb_llm_cmd_out).</summary>
    private static string LlmFamilyOut(int family, string sub, string a, string b, string c)
    {
        string s0 = sub ?? "", s1 = a ?? "", s2 = b ?? "", s3 = c ?? "";
        Func<byte[], int, int> call = family switch
        {
            FamPolicy => (buf, cap) => Basic.Providers.LlmModelNative.llmmodelio_policy_cmd_to(s0, s1, s2, s3, buf, cap),
            FamArch => (buf, cap) => Basic.Providers.LlmModelNative.llmmodelio_arch_cmd_to(s0, s1, s2, buf, cap),
            FamModule => (buf, cap) => Basic.Providers.LlmModelNative.llmmodelio_module_cmd_to(s0, s1, s2, buf, cap),
            FamKernel => (buf, cap) => Basic.Providers.LlmModelNative.llmmodelio_kernel_cmd_to(s0, s1, s2, buf, cap),
            FamKv => (buf, cap) => Basic.Providers.LlmModelNative.llmmodelio_kv_cmd_to(s0, s1, s2, buf, cap),
            _ => (buf, cap) => Basic.Providers.LlmModelNative.llmmodelio_tensor_cmd_to(s0, s1, s2, s3, buf, cap),
        };
        return LlmCaptureStr(call).TrimEnd('\n', '\r');
    }

    public static string LlmPolicyOut(string sub, string a, string b, string c) => LlmFamilyOut(FamPolicy, sub, a, b, c);
    public static string LlmArchOut(string sub, string a, string b, string c) => LlmFamilyOut(FamArch, sub, a, b, c);
    public static string LlmModuleOut(string sub, string a, string b, string c) => LlmFamilyOut(FamModule, sub, a, b, c);
    public static string LlmKernelOut(string sub, string a, string b, string c) => LlmFamilyOut(FamKernel, sub, a, b, c);
    public static string LlmKvOut(string sub, string a, string b, string c) => LlmFamilyOut(FamKv, sub, a, b, c);

    /// <summary>Estrae "74,71,…" dalla riga `LLM TENSOR TOKENIZE '…': n=26 ids=74,71,…`. Se non
    /// c'è la forma attesa, restituisce la riga intera (nessuna perdita di informazione).</summary>
    private static string LlmIdsOf(string raw)
    {
        int k = raw.IndexOf("ids=", StringComparison.Ordinal);
        if (k >= 0) return raw[(k + 4)..].TrimEnd('\n', '\r');
        return raw.TrimEnd('\n', '\r');
    }
