    public static string LlmCompile(string model, string output)
    {
        // Via la variante _to (stesso percorso di LLM TENSOR COMPILE): l output resta nel canale
        // del runtime (captured+stampato in ordine), evitando che il C scriva su stdout reale fuori
        // ordine rispetto al console gestito (parity IL/PCode/VM-C).
        LlmCmdTo4("COMPILE", "COMPILE", model, output, "", (s, x, y, z, buf) => Basic.Providers.LlmModelNative.llmmodelio_tensor_cmd_to(s, x, y, z, buf, buf.Length));
        return "{\"ok\":true}";
    }

