    /// <summary>LLM.EVALGATE(ref, cand) → verdetto JSON ACCEPT/REJECT-FLAG/ERROR (TRAIN EVAL GATE).
    /// Confronto ppl cand vs ref via llmmodelio_model_gate (stessa metrica di QUALITY).</summary>
    public static string LlmEvalGate(string refModel, string candModel)
    {
        var buf = new byte[1024];
        int rc = Basic.Providers.LlmModelNative.llmmodelio_model_gate(
            refModel ?? "", candModel ?? "", "", buf, buf.Length);
        int n = Array.IndexOf(buf, (byte)0); if (n < 0) n = buf.Length;
        if (rc != 0) throw new InvalidOperationException($"LLM.EVALGATE: fallito ({rc}).");
