    // Variante a 4 argomenti (sub,a,b,c) per i verbi con un parametro opzionale in coda (TENSOR).
    private static string LlmCmdTo4(string label, string sub, string a, string b, string c,
        Func<string, string, string, string, byte[], int> call)
    {
        int cap = 1 << 16; string txt = ""; int rc;
        while (true)
        {
            var buf = new byte[cap];
            rc = call(sub ?? "", a ?? "", b ?? "", c ?? "", buf);
            int n = Array.IndexOf(buf, (byte)0); if (n < 0) n = buf.Length;
            txt = System.Text.Encoding.UTF8.GetString(buf, 0, n);
            if (n < cap - 1 || cap >= (1 << 24)) break;
            cap <<= 1;
        }
        if (txt.Length > 0) { Current.Console.Print(txt); Current.Console.PrintNewLine(); }
        return LlmEnsure(rc, label, sub);
    }

    private static string LlmCmdTo(string label, string sub, string a, string b,
        Func<string, string, string, byte[], int> call)
    {
        // Buffer ADATTIVO: IR/INFO di modelli grandi (377 tensori ~ 22 KB) superano i 16 KiB -> troncamento
        // su IL/PCode (divergenza vs VMC che scrive su stdout reale). Se il testo riempie il buffer
        // (n == cap-1) il C ha troncato -> raddoppia e riprova, fino a 16 MiB.
        int cap = 1 << 16; string txt = ""; int rc;
        while (true)
        {
            var buf = new byte[cap];
            rc = call(sub ?? "", a ?? "", b ?? "", buf);
            int n = Array.IndexOf(buf, (byte)0); if (n < 0) n = buf.Length;
            txt = System.Text.Encoding.UTF8.GetString(buf, 0, n);
            if (n < cap - 1 || cap >= (1 << 24)) break;
            cap <<= 1;
        }
        if (txt.Length > 0) { Current.Console.Print(txt); Current.Console.PrintNewLine(); }
        return LlmEnsure(rc, label, sub);
    }

