    /// <summary>LLM.DATASETSTATS(path) → JSON del dataset — TRAIN DATASET STATS. Se è un dataset
    /// .bin del fine-tune (int32 count; per record int32 n, n×int32 ids, int32 target) riporta
    /// anche n/esempi, token e distribuzione target; altrimenti solo i byte.</summary>
    public static string DatasetStats(string path)
    {
        long bytes = -1, samples = -1, tokens = -1, tmin = 0, tmax = 0, tn = 0; double tsum = 0;
        try
        {
            if (System.IO.File.Exists(path))
            {
                bytes = new System.IO.FileInfo(path).Length;
                using var fs = System.IO.File.OpenRead(path);
                using var br = new System.IO.BinaryReader(fs);
                if (bytes >= 4)
                {
                    int count = br.ReadInt32();
                    if (count > 0 && count < 100000000)
                    {
                        samples = 0; tokens = 0; tmin = int.MaxValue; tmax = int.MinValue;
                        for (int i = 0; i < count; i++)
                        {
                            int n = br.ReadInt32();
                            if (n < 0) { samples = -1; break; }
                            for (int k = 0; k < n; k++) br.ReadInt32();
                            int tgt = br.ReadInt32();
                            samples++; tokens += n;
                            if (tgt < tmin) tmin = tgt; if (tgt > tmax) tmax = tgt; tsum += tgt; tn++;
                        }
                    }
                }
            }
        }
        catch { samples = -1; }
        var f = path ?? "";
        if (samples >= 0 && tn > 0)
            return "{\"file\":\"" + f + "\",\"bytes\":" + bytes + ",\"samples\":" + samples + ",\"tokens\":" + tokens
                 + ",\"target_min\":" + tmin + ",\"target_max\":" + tmax
                 + ",\"target_mean\":" + (tsum / tn).ToString("0.00", CultureInfo.InvariantCulture) + "}";
        if (samples >= 0)
            return "{\"file\":\"" + f + "\",\"bytes\":" + bytes + ",\"samples\":" + samples + ",\"tokens\":" + tokens + "}";
        return "{\"file\":\"" + f + "\",\"bytes\":" + bytes + "}";
    }

    /// <summary>LLM.RUNSITEM(id) → JSON di una run ("" se assente) — TRAIN RUNS SHOW.</summary>
    public static string RunsItem(string id)
        => int.TryParse(id, System.Globalization.NumberStyles.Integer,
               System.Globalization.CultureInfo.InvariantCulture, out var v)
           ? Basic.AI.JobRegistry.Item(v) : "";

    /// <summary>LLM.RUNSTOP(id) → rimuove la run dal registro (1 se trovata) — TRAIN STOP.</summary>
    public static long RunsStop(string id)
        => int.TryParse(id, System.Globalization.NumberStyles.Integer,
               System.Globalization.CultureInfo.InvariantCulture, out var v)
           && Basic.AI.JobRegistry.Remove(v) ? 1 : 0;

    /// <summary>LLM.TRAINEXPORT(out) | LLM.TRAINEXPORT(run, out) → esporta l'adapter di una run
    /// (l'ultima se <paramref name="run"/> è ""). Ritorna il numero di file copiati — TRAIN EXPORT.</summary>
    public static long TrainExport(string a, string b)
    {
        // Arità dipendente: 1 arg → (out, "") esporta l'ultima; 2 arg → (run, out).
        string runId, outDir;
        if (string.IsNullOrEmpty(b)) { outDir = a; runId = ""; }
        else { runId = a; outDir = b; }
        string ck;
        if (string.IsNullOrEmpty(runId)) ck = Basic.AI.JobRegistry.LastCkpt();
        else ck = int.TryParse(runId, System.Globalization.NumberStyles.Integer,
                    System.Globalization.CultureInfo.InvariantCulture, out var v)
                  ? Basic.AI.JobRegistry.CkptOf(v) : "";
        if (string.IsNullOrEmpty(ck) || string.IsNullOrEmpty(outDir)) return 0;
        long copied = 0;
        foreach (var sfx in new[] { "_best_A.raw", "_best_B.raw" })
            try { if (System.IO.File.Exists(ck + sfx)) { System.IO.File.Copy(ck + sfx, outDir + sfx, true); copied++; } } catch { }
        try { System.IO.File.WriteAllText(outDir + "_best.meta", "exported_from=" + ck + "\n"); } catch { }
        return copied;
    }

