    public static string AiBenchmark(string name, string mode, string json)
    {
        if (string.IsNullOrWhiteSpace(name))
            return "{\"error\":\"nome agente vuoto\"}";
        var iterations = 1;
        var text = "";
        if (!string.IsNullOrWhiteSpace(json))
        {
            try
            {
                using var doc = System.Text.Json.JsonDocument.Parse(json);
                if (doc.RootElement.TryGetProperty("iterations", out var it) && it.ValueKind == System.Text.Json.JsonValueKind.Number)
                    iterations = Math.Max(1, it.GetInt32());
                if (doc.RootElement.TryGetProperty("text", out var tx) && tx.ValueKind == System.Text.Json.JsonValueKind.String)
                    text = tx.GetString() ?? "";
            }
            catch { /* json malformato: usa default */ }
        }
        return Basic.Agents.AgentServer.Instance.Benchmark(name, mode, iterations, text);
    }

