    public static string AiAgentCode(string task, string outputPath = "") {
        var loop = new Basic.Agents.CodeGenLoop();
        var path = string.IsNullOrWhiteSpace(outputPath) ? System.IO.Path.Combine(System.IO.Path.GetTempPath(), "gmb_code_" + System.Guid.NewGuid().ToString("N") + ".bas") : outputPath;
        var (ok, p, output, diag) = loop.Run(task, path);
