    public static double AiAgentStopServer()
    {
        try
        {
            _ilAgentHttpCts?.Cancel();
            _ilAgentHttpCts?.Dispose();
            _ilAgentHttpCts = null;
            try { _ilAgentHttpListener?.Close(); } catch { }
            _ilAgentHttpListener = null;
            return 1.0;
        }
        catch { return 0.0; }
    }

    private static System.Threading.CancellationTokenSource? _ilAgentHttpCts;
    private static System.Net.HttpListener? _ilAgentHttpListener;
    public static double AiAgentServe(double port)
    {
        _ilAgentHttpCts = new System.Threading.CancellationTokenSource();
        var cts = _ilAgentHttpCts;
        var listener = new System.Net.HttpListener();
        listener.Prefixes.Add($"http://*:{(int)port}/");
        try { listener.Start(); }
        catch { return 0.0; }
        _ilAgentHttpListener = listener;
        _ = System.Threading.Tasks.Task.Run(async () =>
        {
            try
            {
                while (!cts.IsCancellationRequested)
                {
                    var ctx = await listener.GetContextAsync();
                    _ = HandleAgentHttpRequestAsync(ctx);
                }
            }
            catch { }
        });
        return 1.0;
    }
    private static async System.Threading.Tasks.Task HandleAgentHttpRequestAsync(System.Net.HttpListenerContext ctx)
    {
        try
        {
            var request = ctx.Request;
            var response = ctx.Response;
            var path = request.Url?.AbsolutePath?.Trim('/') ?? "";
            var method = request.HttpMethod ?? "GET";
            var body = await new System.IO.StreamReader(request.InputStream).ReadToEndAsync();
            try
            {
                // Helper to get query string param
                string GetQueryParam(string key)
                {
                    var q = request.Url?.Query ?? "";
                    if (string.IsNullOrEmpty(q)) return "";
                    // q starts with ?
                    var qs = q.TrimStart('?').Split('&', StringSplitOptions.RemoveEmptyEntries);
                    foreach (var kv in qs)
                    {
                        var parts = kv.Split('=', 2);
                        if (parts.Length == 2 && Uri.UnescapeDataString(parts[0]) == key)
                            return Uri.UnescapeDataString(parts[1]);
                    }
                    return "";
                }

                // For GET without body, try to parse query string as fallback
                System.Text.Json.JsonElement root = default;
                bool hasJson = false;
                if (!string.IsNullOrWhiteSpace(body))
                {
                    try { var doc = System.Text.Json.JsonDocument.Parse(body); root = doc.RootElement; hasJson = true; } catch { hasJson = false; }
                }

                switch (path)
                {
                    case "chat":
                    {
                        var agentName = hasJson && root.TryGetProperty("agent", out var a) ? a.GetString() ?? "" : GetQueryParam("agent");
                        var prompt = hasJson && root.TryGetProperty("prompt", out var p) ? p.GetString() ?? "" : GetQueryParam("prompt");
                        if (string.IsNullOrWhiteSpace(agentName) || string.IsNullOrWhiteSpace(prompt))
                        {
                            await WriteJsonResponse(response, 400, "{\"error\":\"Missing 'agent' or 'prompt'\"}");
                            break;
                        }
                        var answer = Basic.Agents.AgentServer.Instance.Ask(agentName, prompt);
                        await WriteJsonResponse(response, 200, $"{{\"answer\":\"{EscapeJson(answer)}\"}}");
                        break;
                    }
                    case "execute":
                    {
                        // POST /execute {"agent":"name","prompt":"..."} or {"agent":"name","tool":"calc_sum","args":{}}
                        var agentName = hasJson && root.TryGetProperty("agent", out var a) ? a.GetString() ?? "" : GetQueryParam("agent");
                        if (string.IsNullOrWhiteSpace(agentName))
                        {
                            await WriteJsonResponse(response, 400, "{\"error\":\"Missing 'agent'\"}");
                            break;
                        }
                        // Tool execution path
                        if (hasJson && root.TryGetProperty("tool", out var toolEl) && toolEl.ValueKind == System.Text.Json.JsonValueKind.String)
                        {
                            var toolName = toolEl.GetString() ?? "";
                            var argsJson = hasJson && root.TryGetProperty("args", out var argsEl) ? argsEl.GetRawText() : "{}";
                            var reg = Basic.Mcp.McpToolRegistry.Instance.Get(toolName);
                            if (reg == null)
                            {
                                await WriteJsonResponse(response, 404, $"{{\"error\":\"Tool '{EscapeJson(toolName)}' not found\"}}");
                                break;
                            }
                            var dispatcher = new Basic.IlBackend.IlMcpToolDispatcher();
                            var result = await dispatcher.DispatchAsync(reg.QualifiedProcedureName, argsJson, System.Threading.CancellationToken.None);
                            await WriteJsonResponse(response, 200, $"{{\"tool\":\"{EscapeJson(toolName)}\",\"result\":\"{EscapeJson(result.TextContent)}\",\"isError\":{result.IsError.ToString().ToLowerInvariant()}}}");
                            break;
                        }
                        var prompt = hasJson && root.TryGetProperty("prompt", out var p) ? p.GetString() ?? "" : GetQueryParam("prompt");
                        if (string.IsNullOrWhiteSpace(prompt))
                        {
                            // also support "input" alias
                            prompt = hasJson && root.TryGetProperty("input", out var inp) ? inp.GetString() ?? "" : "";
                        }
                        if (string.IsNullOrWhiteSpace(prompt))
                        {
                            await WriteJsonResponse(response, 400, "{\"error\":\"Missing 'prompt' or 'tool'\"}");
                            break;
                        }
                        var answer = Basic.Agents.AgentServer.Instance.Ask(agentName, prompt);
                        await WriteJsonResponse(response, 200, $"{{\"answer\":\"{EscapeJson(answer)}\"}}");
                        break;
                    }
                    case "workflow":
                    {
                        // POST /workflow {"workflow":"name"} or {"name":"..."} or GET /workflow?workflow=name
                        var wfName = hasJson && (root.TryGetProperty("workflow", out var w) || root.TryGetProperty("name", out w)) ? w.GetString() ?? "" : GetQueryParam("workflow");
                        if (string.IsNullOrWhiteSpace(wfName)) wfName = GetQueryParam("name");
                        if (string.IsNullOrWhiteSpace(wfName))
                        {
                            await WriteJsonResponse(response, 400, "{\"error\":\"Missing 'workflow' or 'name'\"}");
                            break;
                        }
                        var wf = Basic.Workflow.WorkflowServer.Instance.Get(wfName);
                        if (wf == null)
                        {
                            await WriteJsonResponse(response, 404, $"{{\"error\":\"Workflow '{EscapeJson(wfName)}' not found\"}}");
                            break;
                        }
                        // If already defined and not running, execute it
                        var executed = false;
                        if (wf.Status == "ready" || wf.Status == "failed" || wf.Status == "completed")
                        {
                            executed = Basic.Workflow.WorkflowServer.Instance.Execute(wfName);
                            wf = Basic.Workflow.WorkflowServer.Instance.Get(wfName);
                        }
                        var logJson = System.Text.Json.JsonSerializer.Serialize(wf!.ExecutionLog);
                        await WriteJsonResponse(response, 200, $"{{\"workflow\":\"{EscapeJson(wfName)}\",\"status\":\"{EscapeJson(wf.Status)}\",\"steps\":\"{EscapeJson(string.Join(",", wf.Steps.Select(s=>s.Name)))}\",\"log\":{logJson},\"executed\":{executed.ToString().ToLowerInvariant()}}}");
                        break;
                    }
                    case "memory":
                    {
                        // GET /memory?agent=name or POST {"agent":"name"}
                        var agentName = hasJson && root.TryGetProperty("agent", out var a) ? a.GetString() ?? "" : GetQueryParam("agent");
                        if (string.IsNullOrWhiteSpace(agentName))
                        {
                            await WriteJsonResponse(response, 400, "{\"error\":\"Missing 'agent'\"}");
                            break;
                        }
                        var agent = Basic.Agents.AgentServer.Instance.List().FirstOrDefault(x => x.Name.Equals(agentName, StringComparison.OrdinalIgnoreCase));
                        if (agent == null)
                        {
                            await WriteJsonResponse(response, 404, $"{{\"error\":\"Agent '{EscapeJson(agentName)}' not found\"}}");
                            break;
                        }
                        var history = agent.History.Select(m => new { role = m.Role, content = m.Content }).ToArray();
                        var historyJson = System.Text.Json.JsonSerializer.Serialize(history);
                        var status = Basic.Agents.AgentServer.Instance.GetStatusSummary(agentName);
                        var memStore = Basic.Agents.AgentServer.Instance.GetMemoryStore();
                        // also include memory search if query present
                        var query = hasJson && root.TryGetProperty("query", out var q) ? q.GetString() : GetQueryParam("query");
                        string memJson = "[]";
                        if (!string.IsNullOrWhiteSpace(query))
                        {
                            try { memJson = System.Text.Json.JsonSerializer.Serialize(memStore.Search(query!)); } catch { memJson = "[]"; }
                        }
                        await WriteJsonResponse(response, 200, $"{{\"agent\":\"{EscapeJson(agentName)}\",\"status\":\"{EscapeJson(status)}\",\"history\":{historyJson},\"memory\":{memJson}}}");
                        break;
                    }
                    // SOLO GET: un POST /api/teams è la CREAZIONE (branch più sotto, dopo lo
                    // switch). Senza il guard il case catturava anche POST/DELETE e restituiva
                    // la lista, quindi creare un team "funzionava" senza crearlo (bug reale
                    // visto col selftest: POST duplicato rispondeva 200/201 con la lista).
                    case "api/agents" when method == "GET":
                    case "api/teams" when method == "GET":
                    {
                        // C1/B5.4 — GET /api/agents|teams → JSON array (AgentStatusManager)
                        var payload = path == "api/agents"
                            ? Basic.Agents.AgentStatusManager.GetAgentsJson()
                            : Basic.Agents.AgentStatusManager.GetTeamsJson();
                        await WriteJsonResponse(response, 200, payload);
                        break;
                    }
                    case "api/events":
                    {
                        // V1.1 — GET /api/events → JSON array [{timestamp,kind,agent,detail}] (AgentEventLog, 500 ring)
                        var evs = Basic.Agents.AgentEventLog.Instance.Snapshot();
                        var arr = evs.Select(e => new { timestamp = e.Timestamp.ToString("O"), kind = e.Kind.ToString(), agent = e.AgentName, detail = e.Detail }).ToArray();
                        var payload = System.Text.Json.JsonSerializer.Serialize(arr);
                        await WriteJsonResponse(response, 200, payload);
                        break;
                    }
                    case "api/workflows":
                    {
                        if (method == "POST")
                        {
                            // POST /api/workflows {"name":"MyWf"} → crea workflow vuoto (pronto per STEP via BASIC o futuri POST /steps)
                            var name = hasJson && (root.TryGetProperty("name", out var wn) || root.TryGetProperty("workflow", out wn)) ? wn.GetString() ?? "" : GetQueryParam("name");
                            if (string.IsNullOrWhiteSpace(name))
                                await WriteJsonResponse(response, 400, "{\"error\":\"Missing 'name'\"}");
                            else if (!Basic.Workflow.WorkflowServer.Instance.BeginDefinition(name))
                                await WriteJsonResponse(response, 409, $"{{\"error\":\"Workflow '{EscapeJson(name)}' already in definition or existing\"}}");
                            else
                            {
                                Basic.Workflow.WorkflowServer.Instance.EndDefinition();
                                var wf = Basic.Workflow.WorkflowServer.Instance.Get(name);
                                var payload = System.Text.Json.JsonSerializer.Serialize(new { name, status = wf?.Status ?? "empty", steps = wf?.Steps.Select(s=>s.Name).ToArray() ?? Array.Empty<string>() });
                                await WriteJsonResponse(response, 201, payload);
                            }
                        }
                        else
                        {
                            // GET /api/workflows → [{name,status,steps[]}]
                            var wfs = Basic.Workflow.WorkflowServer.Instance.List();
                            var arr = wfs.Select(w => new { name = w.Name, status = w.Status, steps = w.Steps.Select(s => s.Name).ToArray() }).ToArray();
                            var payload = System.Text.Json.JsonSerializer.Serialize(arr);
                            await WriteJsonResponse(response, 200, payload);
                        }
                        break;
                    }
                    case "api/memory":
                    {
                        // GET /api/memory?key=foo → MEMORY.LOAD(key)
                        // GET /api/memory → MEMORY.LIST()
                        // POST /api/memory {"key":"k","value":...,"longTerm":0} → MEMORY.STORE
                        // DELETE /api/memory?key=k → MEMORY.DELETE
                        if (method == "POST")
                        {
                            var key = hasJson && root.TryGetProperty("key", out var kk) ? kk.GetString() ?? "" : GetQueryParam("key");
                            if (string.IsNullOrWhiteSpace(key))
                                await WriteJsonResponse(response, 400, "{\"error\":\"Missing 'key'\"}");
                            else
                            {
                                object? val = null;
                                if (hasJson && root.TryGetProperty("value", out var vv)) val = vv.ValueKind == System.Text.Json.JsonValueKind.String ? vv.GetString() : vv.GetRawText();
                                else val = GetQueryParam("value") ?? "";
                                var lt = 0.0;
                                if (hasJson && root.TryGetProperty("longTerm", out var ltv) && ltv.TryGetDouble(out var ltd)) lt = ltd;
                                else if (hasJson && root.TryGetProperty("isLongTerm", out var ilt) && ilt.ValueKind == System.Text.Json.JsonValueKind.True) lt = 1;
                                var ok = MemoryStore(key, val, lt);
                                var payload = System.Text.Json.JsonSerializer.Serialize(new { key, ok = ok != 0, value = val });
                                await WriteJsonResponse(response, 200, payload);
                            }
                        }
                        else if (method == "DELETE")
                        {
                            var key = GetQueryParam("key") ?? (hasJson && root.TryGetProperty("key", out var dk) ? dk.GetString() ?? "" : "");
                            if (string.IsNullOrWhiteSpace(key))
                                await WriteJsonResponse(response, 400, "{\"error\":\"Missing 'key'\"}");
                            else
                            {
                                var ok = MemoryDelete(key);
                                await WriteJsonResponse(response, ok != 0 ? 200 : 404, System.Text.Json.JsonSerializer.Serialize(new { key, deleted = ok != 0 }));
                            }
                        }
                        else
                        {
                            var key = GetQueryParam("key") ?? (hasJson && root.TryGetProperty("key", out var gk) ? gk.GetString() ?? "" : "");
                            if (!string.IsNullOrWhiteSpace(key))
                            {
                                var v = MemoryLoad(key);
                                await WriteJsonResponse(response, 200, System.Text.Json.JsonSerializer.Serialize(new { key, value = v }));
                            }
                            else
                            {
                                var list = MemoryList();
                                var keys = list.Split('\n', StringSplitOptions.RemoveEmptyEntries);
                                await WriteJsonResponse(response, 200, System.Text.Json.JsonSerializer.Serialize(new { keys }));
                            }
                        }
                        break;
                    }
                    case "api/memory/search":
                    {
                        var pat = GetQueryParam("pattern") ?? GetQueryParam("q") ?? (hasJson && root.TryGetProperty("pattern", out var pp) ? pp.GetString() : null) ?? (hasJson && root.TryGetProperty("query", out var pq) ? pq.GetString() : null) ?? "";
                        var res = MemorySearch(pat ?? "");
                        var keys = (res ?? "").Split('\n', StringSplitOptions.RemoveEmptyEntries);
                        await WriteJsonResponse(response, 200, System.Text.Json.JsonSerializer.Serialize(new { pattern = pat, keys }));
                        break;
                    }
                    case "api/enrich":
                    {
                        if (method != "POST") { await WriteJsonResponse(response, 405, "{\"error\":\"POST required\"}"); break; }
                        var text = hasJson && root.TryGetProperty("text", out var tt) ? tt.GetString() ?? "" : GetQueryParam("text") ?? "";
                        var mode = hasJson && root.TryGetProperty("mode", out var mm2) ? mm2.GetString() ?? "SUMMARIZATION" : GetQueryParam("mode") ?? "SUMMARIZATION";
                        if (string.IsNullOrWhiteSpace(text))
                            await WriteJsonResponse(response, 400, "{\"error\":\"Missing 'text'\"}");
                        else
                        {
                            try
                            {
                                var summary = Basic.AI.Knowledge.Enricher.Enrich(text, mode.Equals("SUMMARIZATION", StringComparison.OrdinalIgnoreCase) ? Basic.AI.Knowledge.EnrichMode.Summarization : mode.Equals("TAGGING", StringComparison.OrdinalIgnoreCase) ? Basic.AI.Knowledge.EnrichMode.Tagging : Basic.AI.Knowledge.EnrichMode.EntityExtraction);
                                await WriteJsonResponse(response, 200, System.Text.Json.JsonSerializer.Serialize(new { text, mode, summary }));
                            }
                            catch (Exception ex) { await WriteJsonResponse(response, 500, System.Text.Json.JsonSerializer.Serialize(new { error = ex.Message })); }
                        }
                        break;
                    }
                    case "api/brain/note":
                    {
                        if (method != "POST") { await WriteJsonResponse(response, 405, "{\"error\":\"POST required\"}"); break; }
                        var txt = hasJson && root.TryGetProperty("text", out var t1) ? t1.GetString() ?? "" : GetQueryParam("text") ?? (hasJson && root.TryGetProperty("note", out var n1) ? n1.GetString() ?? "" : "");
                        if (string.IsNullOrWhiteSpace(txt)) await WriteJsonResponse(response, 400, "{\"error\":\"Missing 'text'\"}");
                        else { var id = Basic.AI.MemoryBrain.Add(txt, Basic.AI.MemoryBrain.MemoryKind.Note); await WriteJsonResponse(response, 200, System.Text.Json.JsonSerializer.Serialize(new { id, text = txt, kind = "Note" })); }
                        break;
                    }
                    case "api/brain/save":
                    {
                        if (method != "POST") { await WriteJsonResponse(response, 405, "{\"error\":\"POST required\"}"); break; }
                        var fact = hasJson && root.TryGetProperty("fact", out var f1) ? f1.GetString() ?? "" : hasJson && root.TryGetProperty("text", out var tf1) ? tf1.GetString() ?? "" : GetQueryParam("fact") ?? GetQueryParam("text") ?? "";
                        if (string.IsNullOrWhiteSpace(fact)) await WriteJsonResponse(response, 400, "{\"error\":\"Missing 'fact'\"}");
                        else { var id2 = Basic.AI.MemoryBrain.Add(fact, Basic.AI.MemoryBrain.MemoryKind.Fact); await WriteJsonResponse(response, 200, System.Text.Json.JsonSerializer.Serialize(new { id = id2, fact, kind = "Fact" })); }
                        break;
                    }
                    case "api/brain/forget":
                    {
                        if (method != "POST" && method != "DELETE") { await WriteJsonResponse(response, 405, "{\"error\":\"POST or DELETE required\"}"); break; }
                        var idS = hasJson && root.TryGetProperty("id", out var idp) ? idp.ValueKind == System.Text.Json.JsonValueKind.Number ? idp.GetInt64().ToString() : idp.GetString() ?? "" : GetQueryParam("id") ?? "";
                        if (string.IsNullOrWhiteSpace(idS) || !long.TryParse(idS, out var lid)) await WriteJsonResponse(response, 400, "{\"error\":\"Missing numeric 'id'\"}");
                        else { var ok = Basic.AI.MemoryBrain.Forget(lid); await WriteJsonResponse(response, ok ? 200 : 404, System.Text.Json.JsonSerializer.Serialize(new { id = lid, deleted = ok })); }
                        break;
                    }
                    case "api/brain/import":
                    {
                        if (method != "POST") { await WriteJsonResponse(response, 405, "{\"error\":\"POST required\"}"); break; }
                        var p = hasJson && root.TryGetProperty("path", out var pp) ? pp.GetString() ?? "" : GetQueryParam("path") ?? "";
                        if (string.IsNullOrWhiteSpace(p)) await WriteJsonResponse(response, 400, "{\"error\":\"Missing 'path'\"}");
                        else { try { var id = Basic.AI.MemoryBrain.ImportFile(p); await WriteJsonResponse(response, 200, System.Text.Json.JsonSerializer.Serialize(new { path = p, id })); } catch (Exception ex) { await WriteJsonResponse(response, 500, System.Text.Json.JsonSerializer.Serialize(new { error = ex.Message })); } }
                        break;
                    }
                    case "api/brain/watch":
                    {
                        if (method == "GET")
                        {
                            var watched2 = Basic.AI.MemoryBrain.Watched();
                            await WriteJsonResponse(response, 200, System.Text.Json.JsonSerializer.Serialize(new { watched = watched2 }));
                            break;
                        }
                        if (method != "POST") { await WriteJsonResponse(response, 405, "{\"error\":\"GET or POST required\"}"); break; }
                        var pw = hasJson && root.TryGetProperty("path", out var wp) ? wp.GetString() ?? "" : GetQueryParam("path") ?? "";
                        if (string.IsNullOrWhiteSpace(pw)) await WriteJsonResponse(response, 400, "{\"error\":\"Missing 'path'\"}");
                        else { try { Basic.AI.MemoryBrain.AddWatch(pw); var watched = Basic.AI.MemoryBrain.Watched(); await WriteJsonResponse(response, 200, System.Text.Json.JsonSerializer.Serialize(new { path = pw, watched })); } catch (Exception ex) { await WriteJsonResponse(response, 500, System.Text.Json.JsonSerializer.Serialize(new { error = ex.Message })); } }
                        break;
                    }
                    case "api/brain/refresh":
                    {
                        if (method != "POST") { await WriteJsonResponse(response, 405, "{\"error\":\"POST required\"}"); break; }
                        try { var n = Basic.AI.MemoryBrain.RefreshWatched(); await WriteJsonResponse(response, 200, System.Text.Json.JsonSerializer.Serialize(new { refreshed = n })); } catch (Exception ex) { await WriteJsonResponse(response, 500, System.Text.Json.JsonSerializer.Serialize(new { error = ex.Message })); }
                        break;
                    }
                    case "api/brain/consolidate":
                    {
                        if (method != "POST") { await WriteJsonResponse(response, 405, "{\"error\":\"POST required\"}"); break; }
                        try { Basic.AI.Rag.MemoryRanker.Consolidate(); await WriteJsonResponse(response, 200, System.Text.Json.JsonSerializer.Serialize(new { consolidated = true })); } catch (Exception ex) { await WriteJsonResponse(response, 500, System.Text.Json.JsonSerializer.Serialize(new { error = ex.Message })); }
                        break;
                    }
                    case "api/brain/list":
                    {
                        // GET /api/brain/list?limit=20 → lista ultime memorie (Note/Fact/Episodic)
                        var lim = 20;
                        if (int.TryParse(GetQueryParam("limit"), out var ll)) lim = ll;
                        else if (hasJson && root.TryGetProperty("limit", out var lj) && lj.TryGetInt32(out var lli)) lim = lli;
                        var all = Basic.AI.MemoryBrain.Search("", topK: Math.Max(lim, 50));
                        var lines = (all ?? "").Split('\n', StringSplitOptions.RemoveEmptyEntries);
                        var take = lines.Take(Math.Min(lim, lines.Length)).ToArray();
                        await WriteJsonResponse(response, 200, System.Text.Json.JsonSerializer.Serialize(new { count = take.Length, items = take }));
                        break;
                    }
                    case "api/brain/search":
                    {
                        var q = GetQueryParam("query") ?? GetQueryParam("q") ?? (hasJson && root.TryGetProperty("query", out var qb) ? qb.GetString() : null) ?? "";
                        var topK = 5.0;
                        if (hasJson && root.TryGetProperty("topK", out var tk) && tk.TryGetDouble(out var tv2)) topK = tv2;
                        else if (double.TryParse(GetQueryParam("topK"), out var tk2)) topK = tk2;
                        var res = MemoryAsk(q ?? "", topK);
                        await WriteJsonResponse(response, 200, System.Text.Json.JsonSerializer.Serialize(new { query = q, topK = (int)topK, result = res }));
                        break;
                    }
                }

                // V1.2d — POST /api/workflows/{name}/steps {"name":"s1","action":"tool","retryCount":0,"timeoutMs":0}
                if (path.StartsWith("api/workflows/", StringComparison.OrdinalIgnoreCase) && path.EndsWith("/steps", StringComparison.OrdinalIgnoreCase) && method == "POST")
                {
                    var inner = path.Substring("api/workflows/".Length);
                    var wfName = inner.Substring(0, inner.Length - "/steps".Length);
                    if (string.IsNullOrWhiteSpace(wfName))
                        await WriteJsonResponse(response, 400, "{\"error\":\"Missing workflow name\"}");
                    else
                    {
                        string stepName = "", action = "";
                        var retry = 0; var timeout = 0;
                        if (hasJson)
                        {
                            if (root.TryGetProperty("name", out var sn) || root.TryGetProperty("step", out sn)) stepName = sn.GetString() ?? "";
                            if (root.TryGetProperty("action", out var ac)) action = ac.GetString() ?? "";
                            if (root.TryGetProperty("retryCount", out var rc) && rc.TryGetInt32(out var rv)) retry = rv;
                            if (root.TryGetProperty("timeoutMs", out var tm) && tm.TryGetInt32(out var tv)) timeout = tv;
                        }
                        if (string.IsNullOrWhiteSpace(stepName)) stepName = GetQueryParam("name") ?? GetQueryParam("step") ?? "";
                        if (string.IsNullOrWhiteSpace(action)) action = GetQueryParam("action") ?? "";
                        if (string.IsNullOrWhiteSpace(stepName))
                            await WriteJsonResponse(response, 400, "{\"error\":\"Missing 'name' for step\"}");
                        else if (!Basic.Workflow.WorkflowServer.Instance.AddStepToWorkflow(wfName, stepName, action, retry, timeout))
                            await WriteJsonResponse(response, 404, $"{{\"error\":\"Workflow '{EscapeJson(wfName)}' not found or under construction\"}}");
                        else
                        {
                            var wf2 = Basic.Workflow.WorkflowServer.Instance.Get(wfName);
                            var payload = System.Text.Json.JsonSerializer.Serialize(new { name = wfName, status = wf2?.Status ?? "ready", steps = wf2?.Steps.Select(s=>new{ s.Name, s.Action, s.RetryCount, s.TimeoutMs }).ToArray() ?? Array.Empty<object>() });
                            await WriteJsonResponse(response, 201, payload);
                        }
                    }
                }
                // V2 — TEAM CRUD + persistenza (i comandi BASIC `AI TEAM CREATE/ADD AGENT` vogliono
                // un nome STATICO; da HTTP il nome è dinamico). La persistenza la guida il
                // chiamante: `save`/`load` ricevono il PATH, così l'app decide dove stanno i file
                // (niente path cablati qui).
                else if (path.Equals("api/teams", StringComparison.OrdinalIgnoreCase) && method == "POST")
                {
                    var tname = hasJson && root.TryGetProperty("name", out var tn2) ? tn2.GetString() ?? "" : GetQueryParam("name");
                    var strat = hasJson && root.TryGetProperty("strategy", out var ts2) ? ts2.GetString() ?? "" : GetQueryParam("strategy");
                    if (string.IsNullOrWhiteSpace(tname))
                        await WriteJsonResponse(response, 400, "{\"error\":\"Missing 'name'\"}");
                    else if (!Basic.Agents.TeamServer.Instance.Create(tname!))
                        await WriteJsonResponse(response, 409, $"{{\"error\":\"Team '{EscapeJson(tname!)}' already exists\"}}");
                    else
                    {
                        if (!string.IsNullOrWhiteSpace(strat) &&
                            Enum.TryParse<Basic.Agents.TeamStrategy>(strat, ignoreCase: true, out var strategy))
                            Basic.Agents.TeamServer.Instance.SetStrategy(tname!, strategy);
                        var t = Basic.Agents.TeamServer.Instance.Get(tname!);
                        var payload = System.Text.Json.JsonSerializer.Serialize(new
                        {
                            name = t?.Name ?? tname,
                            strategy = (t?.Strategy ?? Basic.Agents.TeamStrategy.Sequential).ToString(),
                            members = t?.Members.Select(m => m.AgentName).ToArray() ?? Array.Empty<string>()
                        });
                        await WriteJsonResponse(response, 201, payload);
                    }
                }
                else if (path.StartsWith("api/teams/", StringComparison.OrdinalIgnoreCase) && method == "DELETE")
                {
                    var tdel = path.Substring("api/teams/".Length);
                    if (string.IsNullOrWhiteSpace(tdel))
                        await WriteJsonResponse(response, 400, "{\"error\":\"Missing team name\"}");
                    else if (!Basic.Agents.TeamServer.Instance.Delete(tdel))
                        await WriteJsonResponse(response, 404, $"{{\"error\":\"Team '{EscapeJson(tdel)}' not found\"}}");
                    else
                        await WriteJsonResponse(response, 200, $"{{\"deleted\":\"{EscapeJson(tdel)}\"}}");
                }
                // POST /api/teams/{name}/agents {"agent":"X","role":"Worker"} → aggiunge un membro
                else if (path.StartsWith("api/teams/", StringComparison.OrdinalIgnoreCase)
                         && path.EndsWith("/agents", StringComparison.OrdinalIgnoreCase) && method == "POST")
                {
                    var inner2 = path.Substring("api/teams/".Length);
                    var tname = inner2[..(inner2.Length - "/agents".Length)];
                    var agentName = hasJson && root.TryGetProperty("agent", out var an2) ? an2.GetString() ?? "" : GetQueryParam("agent");
                    var roleStr = hasJson && root.TryGetProperty("role", out var rl2) ? rl2.GetString() ?? "" : GetQueryParam("role");
                    if (string.IsNullOrWhiteSpace(tname) || string.IsNullOrWhiteSpace(agentName))
                        await WriteJsonResponse(response, 400, "{\"error\":\"Missing team or agent\"}");
                    else
                    {
                        var role = Basic.Agents.TeamRole.Worker;
                        if (!string.IsNullOrWhiteSpace(roleStr))
                            Enum.TryParse<Basic.Agents.TeamRole>(roleStr, ignoreCase: true, out role);
                        if (!Basic.Agents.TeamServer.Instance.AddAgent(tname, agentName!, role))
                            await WriteJsonResponse(response, 404, $"{{\"error\":\"Team '{EscapeJson(tname)}' or agent '{EscapeJson(agentName!)}' not valid (already a member?)\"}}");
                        else
                        {
                            var t3 = Basic.Agents.TeamServer.Instance.Get(tname);
                            var payload = System.Text.Json.JsonSerializer.Serialize(new
                            {
                                team = tname,
                                agent = agentName,
                                role = role.ToString(),
                                members = t3?.Members.Select(m => m.AgentName).ToArray() ?? Array.Empty<string>()
                            });
                            await WriteJsonResponse(response, 200, payload);
                        }
                    }
                }
                // DELETE /api/teams/{name}/agents/{agent}
                else if (path.StartsWith("api/teams/", StringComparison.OrdinalIgnoreCase)
                         && path.Contains("/agents/", StringComparison.OrdinalIgnoreCase) && method == "DELETE")
                {
                    var rest = path.Substring("api/teams/".Length);
                    var sep = rest.IndexOf("/agents/", StringComparison.OrdinalIgnoreCase);
                    var tname = sep > 0 ? rest[..sep] : "";
                    var agentName = sep > 0 ? rest[(sep + "/agents/".Length)..] : "";
                    if (string.IsNullOrWhiteSpace(tname) || string.IsNullOrWhiteSpace(agentName))
                        await WriteJsonResponse(response, 400, "{\"error\":\"Missing team or agent\"}");
                    else if (!Basic.Agents.TeamServer.Instance.RemoveAgent(tname, agentName))
                        await WriteJsonResponse(response, 404, $"{{\"error\":\"'{EscapeJson(agentName)}' is not a member of '{EscapeJson(tname)}'\"}}");
                    else
                        await WriteJsonResponse(response, 200, $"{{\"team\":\"{EscapeJson(tname)}\",\"removed\":\"{EscapeJson(agentName)}\"}}");
                }
                // POST /api/teams/{name}/save {"path": "..."} → persiste il team su file (path dal chiamante)
                else if (path.StartsWith("api/teams/", StringComparison.OrdinalIgnoreCase)
                         && path.EndsWith("/save", StringComparison.OrdinalIgnoreCase) && method == "POST")
                {
                    var inner3 = path.Substring("api/teams/".Length);
                    var tname = inner3[..(inner3.Length - "/save".Length)];
                    var p = hasJson && root.TryGetProperty("path", out var pj) ? pj.GetString() ?? "" : GetQueryParam("path");
                    if (string.IsNullOrWhiteSpace(tname) || string.IsNullOrWhiteSpace(p))
                        await WriteJsonResponse(response, 400, "{\"error\":\"Missing team or path\"}");
                    else
                    {
                        try { Basic.Agents.TeamServer.Instance.Save(tname, p!); await WriteJsonResponse(response, 200, "{\"saved\":true}"); }
                        catch (Exception ex) { await WriteJsonResponse(response, 500, $"{{\"error\":\"{EscapeJson(ex.Message)}\"}}"); }
                    }
                }
                // POST /api/teams/load {"name":"X","path":"..."} → carica un team da file
                else if (path.Equals("api/teams/load", StringComparison.OrdinalIgnoreCase) && method == "POST")
                {
                    var lname = hasJson && root.TryGetProperty("name", out var ln2) ? ln2.GetString() ?? "" : GetQueryParam("name");
                    var lp = hasJson && root.TryGetProperty("path", out var lp2) ? lp2.GetString() ?? "" : GetQueryParam("path");
                    if (string.IsNullOrWhiteSpace(lname) || string.IsNullOrWhiteSpace(lp))
                        await WriteJsonResponse(response, 400, "{\"error\":\"Missing name or path\"}");
                    else if (!File.Exists(lp))
                        await WriteJsonResponse(response, 404, $"{{\"error\":\"File not found: {EscapeJson(lp!)}\"}}");
                    else
                    {
                        try { Basic.Agents.TeamServer.Instance.Load(lname!, lp!); await WriteJsonResponse(response, 200, $"{{\"loaded\":\"{EscapeJson(lname!)}\"}}"); }
                        catch (Exception ex) { await WriteJsonResponse(response, 500, $"{{\"error\":\"{EscapeJson(ex.Message)}\"}}"); }
                    }
                }
                else if (path.StartsWith("api/teams/", StringComparison.OrdinalIgnoreCase) && method == "GET")
                {
                    var teamName = path.Substring("api/teams/".Length);
                    if (string.IsNullOrWhiteSpace(teamName))
                        await WriteJsonResponse(response, 400, "{\"error\":\"Missing team name\"}");
                    else
                    {
                        var payload = Basic.Agents.AgentStatusManager.GetTeamStatusJson(teamName);
                        var isError = payload.Contains("\"error\"");
                        await WriteJsonResponse(response, isError ? 404 : 200, payload);
                    }
                }
                // V1.2 — GET /api/workflows/{name} → workflow detail
                else if (path.StartsWith("api/workflows/", StringComparison.OrdinalIgnoreCase) && method == "GET")
                {
                    var wfName = path.Substring("api/workflows/".Length);
                    if (string.IsNullOrWhiteSpace(wfName))
                        await WriteJsonResponse(response, 400, "{\"error\":\"Missing workflow name\"}");
                    else
                    {
                        var wf = Basic.Workflow.WorkflowServer.Instance.Get(wfName);
                        if (wf == null)
                            await WriteJsonResponse(response, 404, $"{{\"error\":\"Workflow '{EscapeJson(wfName)}' not found\"}}");
                        else
                        {
                            var logJson = System.Text.Json.JsonSerializer.Serialize(wf.ExecutionLog);
                            var payload = $"{{\"workflow\":\"{EscapeJson(wfName)}\",\"status\":\"{EscapeJson(wf.Status)}\",\"steps\":\"{EscapeJson(string.Join(",", wf.Steps.Select(s=>s.Name)))}\",\"log\":{logJson}}}";
                            await WriteJsonResponse(response, 200, payload);
                        }
                    }
                }
                // V1.2e — POST /api/workflows/{name}/execute → esegue workflow → {ok,status,log[]}
                else if (path.StartsWith("api/workflows/", StringComparison.OrdinalIgnoreCase) && path.EndsWith("/execute", StringComparison.OrdinalIgnoreCase) && method == "POST")
                {
                    var inner2 = path.Substring("api/workflows/".Length);
                    var wfExec = inner2.Substring(0, inner2.Length - "/execute".Length);
                    if (string.IsNullOrWhiteSpace(wfExec))
                        await WriteJsonResponse(response, 400, "{\"error\":\"Missing workflow name\"}");
                    else
                    {
                        var wfOk = Basic.Workflow.WorkflowServer.Instance.Execute(wfExec);
                        var wf3 = Basic.Workflow.WorkflowServer.Instance.Get(wfExec);
                        if (wf3 == null)
                            await WriteJsonResponse(response, 404, $"{{\"error\":\"Workflow '{EscapeJson(wfExec)}' not found\"}}");
                        else
                        {
                            var payload = System.Text.Json.JsonSerializer.Serialize(new { workflow = wfExec, ok = wfOk, status = wf3.Status, log = wf3.ExecutionLog });
                            await WriteJsonResponse(response, wfOk ? 200 : 500, payload);
                        }
                    }
                }
                // V1.2e — DELETE /api/workflows/{name} → {deleted}
                else if (path.StartsWith("api/workflows/", StringComparison.OrdinalIgnoreCase) && method == "DELETE" && !path.EndsWith("/steps", StringComparison.OrdinalIgnoreCase) && !path.EndsWith("/execute", StringComparison.OrdinalIgnoreCase))
                {
                    var wfDel = path.Substring("api/workflows/".Length);
                    if (string.IsNullOrWhiteSpace(wfDel))
                        await WriteJsonResponse(response, 400, "{\"error\":\"Missing workflow name\"}");
                    else if (!Basic.Workflow.WorkflowServer.Instance.Delete(wfDel))
                        await WriteJsonResponse(response, 404, $"{{\"error\":\"Workflow '{EscapeJson(wfDel)}' not found or under construction\"}}");
                    else
                        await WriteJsonResponse(response, 200, $"{{\"deleted\":\"{EscapeJson(wfDel)}\"}}");
                }
                else if (path.StartsWith("api/team/", StringComparison.OrdinalIgnoreCase)
                    && path.EndsWith("/broadcast", StringComparison.OrdinalIgnoreCase) && method == "POST")
                {
                    var teamName = path.Substring("api/team/".Length, path.Length - "api/team/".Length - "/broadcast".Length);
                    var msg = hasJson && root.TryGetProperty("message", out var mm) ? mm.GetString() ?? "" : GetQueryParam("message");
                    if (string.IsNullOrWhiteSpace(teamName))
                        await WriteJsonResponse(response, 400, "{\"error\":\"Missing team name\"}");
                    else if (string.IsNullOrWhiteSpace(msg))
                        await WriteJsonResponse(response, 400, "{\"error\":\"Missing 'message'\"}");
                    else
                    {
                        try
                        {
                            var ok = TeamBroadcast(teamName, msg);
                            var payload = System.Text.Json.JsonSerializer.Serialize(new { team = teamName, message = msg, ok });
                            await WriteJsonResponse(response, ok > 0 ? 200 : 404, payload);
                        }
                        catch (Exception ex)
                        {
                            await WriteJsonResponse(response, 500, $"{{\"error\":\"{EscapeJson(ex.Message)}\"}}");
                        }
                    }
                }
                // C1/B5.4 — POST /api/agent/{name}/prompt → {"prompt":"..."} → {"answer":"..."}
                // (fuori dallo switch: path parametrizzato)
                else if (path.StartsWith("api/agent/", StringComparison.OrdinalIgnoreCase)
                    && path.EndsWith("/prompt", StringComparison.OrdinalIgnoreCase))
                {
                    var name = path.Substring("api/agent/".Length, path.Length - "api/agent/".Length - "/prompt".Length);
                    if (string.IsNullOrWhiteSpace(name))
                        await WriteJsonResponse(response, 400, "{\"error\":\"Missing agent name\"}");
                    else if (!hasJson || !root.TryGetProperty("prompt", out var p) || string.IsNullOrWhiteSpace(p.GetString()))
                        await WriteJsonResponse(response, 400, "{\"error\":\"Missing 'prompt'\"}");
                    else
                    {
                        var answer = Basic.Agents.AgentServer.Instance.Ask(name, p.GetString()!);
                        await WriteJsonResponse(response, 200, $"{{\"agent\":\"{EscapeJson(name)}\",\"answer\":\"{EscapeJson(answer)}\"}}");
                    }
                }
            }
            catch (System.Text.Json.JsonException ex)
            {
                await WriteJsonResponse(response, 400, $"{{\"error\":\"Invalid JSON: {EscapeJson(ex.Message)}\"}}");
            }
            catch (Exception ex)
            {
                await WriteJsonResponse(response, 500, $"{{\"error\":\"{EscapeJson(ex.Message)}\"}}");
            }
            finally { try{ response.Close(); } catch{} }
        }
        catch { }
    }

    private static string EscapeJson(string s) =>
        (s ?? "").Replace("\\", "\\\\").Replace("\"", "\\\"").Replace("\n", "\\n").Replace("\r", "\\r").Replace("\t", "\\t");

    private static async System.Threading.Tasks.Task WriteJsonResponse(System.Net.HttpListenerResponse response, int statusCode, string json)
    {
        response.StatusCode = statusCode;
        response.ContentType = "application/json";
        var bytes = System.Text.Encoding.UTF8.GetBytes(json);
        await response.OutputStream.WriteAsync(bytes);
        response.OutputStream.Close();
    }

