    public static string AiVectorSearch(string db, string coll, string query, double topK, double hybrid, string? filterJson,
        double reranker = 1, double minEvidence = double.NaN, double explain = 0)
    {
        // Senza provider embedding attivo (es. sample admin) la ricerca dà lista vuota "[]" come
        // il PCode (VECTORDB_SEARCH catch -> "[]"); prima l'eccezione propagava e interrompeva
        // la gamba IL (VectorDbAdmin.bas).
        try
        {
            var rk = Basic.AI.Rag.AiVectorRuntime.RerankerFor(reranker);
            return Basic.AI.Rag.AiVectorRuntime.SearchJson(db, coll, query, (int)topK, hybrid != 0, filterJson,
                reranker: rk, rerankEvidenceMin: minEvidence, explain: explain != 0, rerankEnabled: reranker != 0) ?? "[]";
        }
        catch { return "[]"; }
    }
