    public static string AiVectorRerank(string query, string jsonResults, double topK)
    {
        var k = (int)topK; if (k <= 0) k = 5;
        try
        {
            using var doc = System.Text.Json.JsonDocument.Parse(jsonResults);
            var root = doc.RootElement;
            var hits = root.TryGetProperty("hits", out var h) ? h : default;
            if (hits.ValueKind != System.Text.Json.JsonValueKind.Array) return jsonResults;
            var results = new System.Collections.Generic.List<Basic.SQLite.Vector.VectorSearchResult>();
            foreach (var hit in hits.EnumerateArray())
            {
                results.Add(new Basic.SQLite.Vector.VectorSearchResult(
                    hit.TryGetProperty("chunkId", out var cid) ? cid.GetInt64() : 0,
                    hit.TryGetProperty("documentId", out var did) ? did.GetInt64() : 0,
                    hit.TryGetProperty("sourceId", out var sid) ? sid.GetString() ?? "" : "",
                    hit.TryGetProperty("text", out var txt) ? txt.GetString() ?? "" : "",
                    (hit.TryGetProperty("score", out var sc) && sc.TryGetSingle(out var f)) ? f : 0f,
                    hit.TryGetProperty("modelVersion", out var mv) ? mv.GetString() ?? "" : "",
                    hit.TryGetProperty("metadataJson", out var mj) ? mj.GetString() : null));
            }
            var reranker = Basic.Providers.ProviderServer.Instance.GetActiveReranker();
            var reranked = Basic.SQLite.Vector.RerankerScoring.Rerank(reranker, query, results, k);
            var sb = new System.Text.StringBuilder();
            sb.Append("{\"status\":\"Success\",\"hits\":[");
            for (var i = 0; i < reranked.Count; i++)
            {
                if (i > 0) sb.Append(',');
                sb.Append(System.Text.Json.JsonSerializer.Serialize(reranked[i]));
            }
            sb.Append("]}");
            return sb.ToString();
        }
        catch { return jsonResults; }
    }

