    // ── Self-Consistency / Semantic Entropy — AI namespace.
    // Il backend gestito implementa lo stesso algoritmo in C# (Basic.AI.Uncertainty.SemanticEntropy);
    // il P/Invoke C# → C sarebbe ammesso (CLAUDE.md), ma oggi non serve. Parità di risultato col
    // runtime C (`gmb_uncertainty.c`) verificata dai MiniTest.
    public static double AiConsistency(string prompt, object? options = null)
    {
        // options: {k: 5, temp: 0.7, maxTokens: 1024}
        int k = 5; float temp = 0.7f; int maxTok = 1024;
        if (options is System.Collections.IDictionary dict)
        {
            if (dict.Contains("k")) k = Convert.ToInt32(dict["k"]);
            if (dict.Contains("temp")) temp = Convert.ToSingle(dict["temp"]);
            if (dict.Contains("maxTokens")) maxTok = Convert.ToInt32(dict["maxTokens"]);
        }
        if (k < 1) k = 1;
        if (k > Basic.AI.Uncertainty.SemanticEntropy.MaxResponses)
            k = Basic.AI.Uncertainty.SemanticEntropy.MaxResponses;

        // Il campionamento K× richiede un provider LLM configurato: senza, la
        // self-consistency NON è calcolabile → NaN e dettaglio invalidato ({}), esattamente
        // come il runtime C dove il provider vive nel processo host. Mai un numero inventato.
        var completer = Basic.AI.Rag.LlmCompleterResolver.Default;
        if (completer == null)
        {
            // Fallback al provider attivato via PROVIDER.ACTIVE (%CHAT): il resolver
            // statico non viene alimentato dal comando (P4 SelfConsistency: q27 → NaN
            // anche con provider attivo). Se nessun provider è attivo, resta NaN.
            try { completer = Basic.Providers.ProviderServer.Instance.GetActiveCompletion(); }
            catch { completer = null; }
        }
        // Il provider "fixture" (bootstrap di ProviderServer.EnsureDefaultsLocked) NON è un LLM
        // reale: produce risposte deterministiche di test. Usarlo per AI.CONSISTENCY darebbe un
        // risk finto (parità rotta coi backend C, che non hanno provider e restituiscono NaN).
        // Senza provider REALE la self-consistency non è calcolabile → NaN, ovunque.
        if (completer == null || completer is Basic.AI.Rag.FixtureLlmCompleter)
        {
            Basic.AI.Uncertainty.SemanticEntropy.Invalidate();
            return double.NaN;
        }
        const string sysPrompt = "You are a helpful assistant. Answer concisely.";
        var responses = completer.AskMulti(sysPrompt, prompt ?? string.Empty, k, temp, maxTok);
        if (responses == null || responses.Length == 0)
        {
            Basic.AI.Uncertainty.SemanticEntropy.Invalidate();
            return double.NaN;
        }
        return Basic.AI.Uncertainty.SemanticEntropy.ConsistencyRisk(responses);
    }

    /// <summary>AI.LEXICALENTROPY(responses$): entropia di Shannon (bit) sulle risposte
    /// separate da ';' o newline (C# puro, deterministico, nessun provider).</summary>
    public static double AiLexicalEntropy(string responses)
        => Basic.AI.Uncertainty.SemanticEntropy.LexicalEntropy(responses);

