    private static double IndexAllVaults()
    {
        var names = Basic.AI.Knowledge.VaultManager.ListVaults();
        double total = 0;
        try
        {
            using var doc = System.Text.Json.JsonDocument.Parse(names);
            foreach (var el in doc.RootElement.EnumerateArray())
                total += Basic.AI.Knowledge.VaultManager.VaultIndex(el.GetString() ?? "");
        }
        catch { return -1; }
        return total;
    }
