    private static string GraphDirFor(string? brain) =>
        brain is { Length: > 0 } ? Path.GetDirectoryName(Basic.AI.Knowledge.BrainRegistry.GraphJsonPath(brain) ?? "")
        : Basic.AI.AiConfig.GraphsDefaultDir;

    /// <summary>GRAPH BUILD/UPDATE &lt;dir&gt; [, outputDir] — costruisce il grafo arricchito
    /// (8 campi + edge tipizzati) e lo persiste. outputDir opzionale (default GraphsDefaultDir):
    /// il programma BASIC lo imposta (es. "work/" per il pattern fixtures→samples/Fixtures,
    /// artefatti→cartella work/ accanto al programma). Scrive l'export standard &lt;name&gt;.json
    /// (GraphExporter) così le funzioni GRAPH.NEIGHBORS/PATH/... lo leggono. Il grafo resta
    /// disponibile come ActiveGraph per la sessione (LoadBrain usa ActiveGraph se brain coincide).
    /// Ritorna numero di nodi.</summary>
    public static double GraphBuild(string wikiDir, string? outputDir)
    {
        if (string.IsNullOrWhiteSpace(wikiDir)) return -1;
        var dir = Path.GetFullPath(wikiDir);
        if (!Directory.Exists(dir)) return -1;

        var g = Basic.AI.Knowledge.GraphManager.Build(dir);
        var name = Path.GetFileName(dir.TrimEnd('/', '\\'));

        var graphsDir = string.IsNullOrWhiteSpace(outputDir)
            ? Basic.AI.AiConfig.GraphsDefaultDir
            : Path.GetFullPath(outputDir);
        if (!Directory.Exists(graphsDir)) Directory.CreateDirectory(graphsDir);

        // export standard per le funzioni GRAPH.* (leggono <graphs>/<name>.json)
        var export = Basic.AI.Graph.GraphExporter.Export(Basic.AI.Graph.GraphStore.Build(dir), name);
        File.WriteAllText(Path.Combine(graphsDir, name + ".json"), export.Json);
        // export arricchito (8 campi + edge tipizzati) per GRAPH FIND PATH su file — backend
        // selezionato da GRAPH RDD (JSON → .graph.json, SQLITE → .graph.db).
        var backend = Basic.AI.Knowledge.GraphManager.DefaultBackend;
        if (backend == Basic.AI.Knowledge.GraphRddBackend.Json)
            Basic.AI.Knowledge.GraphManager.Save(g, graphsDir, name);
        else if (backend == Basic.AI.Knowledge.GraphRddBackend.Sqlite)
            Basic.AI.Knowledge.GraphManager.SaveSqlite(g, graphsDir, name);

        Basic.AI.Knowledge.GraphManager.ActiveGraph = g;
        Basic.AI.Knowledge.GraphManager.ActiveName = name;
        Basic.AI.Knowledge.GraphManager.ActiveDir = graphsDir;
        return g.NodeCount;
    }

    /// <summary>GRAPH FIND PATH &lt;from&gt; TO &lt;to&gt; — path più corto nel grafo del brain
    /// attivo (o ActiveGraph MEMORY). Stampa il path e ritorna il JSON ["a","x","b"] o []
    /// se irraggiungibile.</summary>
    public static string GraphFindPath(string from, string to)
    {
        Basic.AI.Knowledge.RichGraph? g = Basic.AI.Knowledge.GraphManager.ActiveGraph;
        if (g is null)
        {
            var name = Basic.AI.Knowledge.GraphManager.ActiveName;
            var dir = Basic.AI.Knowledge.GraphManager.ActiveDir;
            if (name is not null && dir is not null)
            {
                var jsonPath = Path.Combine(dir, name + ".graph.json");
                var dbPath = Path.Combine(dir, name + ".graph.db");
                if (File.Exists(jsonPath)) g = Basic.AI.Knowledge.GraphManager.TryLoad(dir, name);
                else if (File.Exists(dbPath)) g = Basic.AI.Knowledge.GraphManager.TryLoadSqlite(dir, name);
            }
        }
        if (g is null)
        {
            var used = Basic.AI.Knowledge.BrainRegistry.Used();
            foreach (var name in used)
            {
                var dir = GraphDirFor(name);
                if (dir is { Length: > 0 } && File.Exists(Path.Combine(dir, name + ".graph.json")))
                    g = Basic.AI.Knowledge.GraphManager.TryLoad(dir, name);
                if (g is not null) break;
            }
        }
        var json = g is null ? "[]" : System.Text.Json.JsonSerializer.Serialize(g.ShortestPath(from, to).ToArray());
        return json;
    }

    /// <summary>GRAPH RDD &lt;backend&gt; — seleziona il backend di storage
    /// (MEMORY|JSON|SQLITE). ISAM/DBF non sono supportati da questo percorso →
    /// errore esplicito, mai stub silenzioso.</summary>
    public static double GraphRdd(string backend)
    {
        var b = Basic.AI.Knowledge.GraphManager.ParseBackend(backend ?? "");
        if (b is Basic.AI.Knowledge.GraphRddBackend.Isam or Basic.AI.Knowledge.GraphRddBackend.Dbf)
            throw new NotSupportedException(
                $"GRAPH RDD backend {b} non e' supportato da questo percorso — usa MEMORY, JSON o SQLITE");
        if (b != Basic.AI.Knowledge.GraphRddBackend.Memory
            && b != Basic.AI.Knowledge.GraphRddBackend.Json
            && b != Basic.AI.Knowledge.GraphRddBackend.Sqlite)
            throw new NotSupportedException($"GRAPH RDD backend non disponibile: {b} (usa MEMORY, JSON o SQLITE)");
        Basic.AI.Knowledge.GraphManager.DefaultBackend = b;
        return 1.0;
    }

