    // ── BRAIN VAULT (Second Brain §2) — documentazione StdLib indicizzata in RAG ──
    /// <summary>AI.BRAINVAULTBUILD(outputDir$) — genera brain/&lt;Ns&gt;.md dalla StdLib e li
    /// indicizza in &lt;RagDefaultDir&gt;/brainvault.db (RAG). outputDir = dove scrivere le
    /// pagine .md (es. "work"). Ritorna il numero di pagine indicizzate.</summary>
    public static double BrainVaultBuild(string outputDir)
    {
        if (string.IsNullOrWhiteSpace(outputDir)) return -1;
        if (Basic.SQLite.Vector.EmbeddingProviderResolver.Default is null)
            throw new InvalidOperationException(
                "BrainVaultBuild richiede un provider embedding attivo (AI SET ACTIVE %EMBEDDING, alias)");
        var pages = new System.Collections.Generic.List<(string, string)>();
        foreach (var (nsName, procs) in StdLib.Instance.BuiltinProcedures
                     .OrderBy(kv => kv.Key, StringComparer.OrdinalIgnoreCase))
        {
            var list = procs.OfType<Basic.NativeProcedureDefinition>().ToList();
            if (list.Count == 0) continue;
            pages.Add((nsName, Basic.AI.Knowledge.BrainVault.BuildNamespacePage(nsName, list)));
        }
        if (pages.Count == 0) return 0;
        var absOut = System.IO.Path.GetFullPath(outputDir);
        System.IO.Directory.CreateDirectory(System.IO.Path.Combine(absOut, "brain"));
        Basic.AI.Knowledge.BrainVault.WritePages(absOut, pages);

        // Il db RAG vive nel RagDefaultDir (il brain "brainvault" è globale) — così la query
        // BrainVault.Query lo trova via BrainRegistry.RagDbPath("brainvault").
        var ragDir = Basic.AI.AiConfig.RagDefaultDir;
        if (!Directory.Exists(ragDir)) Directory.CreateDirectory(ragDir);
        var dbPath = Path.Combine(ragDir, "brainvault.db");
        var pagesDir = Path.Combine(absOut, "brain");
        var indexed = Basic.AI.Knowledge.BrainVault.IndexTo(dbPath, pagesDir, "brainvault");
        Basic.AI.Knowledge.BrainRegistry.Register("brainvault", mode: "rag", source: dbPath);
        return indexed;
    }

