    public static double Pythagoras(double a, double b) => Math.Sqrt(a * a + b * b);
    public static object? Transpose(object? matrix)
    {
        if (matrix is System.Collections.IList outer)
        {
            if (outer.Count == 0 || outer[0] is not System.Collections.IList firstRow) return matrix;
            int rows = outer.Count, cols = firstRow.Count;
            var result = new List<List<object?>>();
            for (int c = 0; c < cols; c++)
            {
                var row = new List<object?>();
                for (int r = 0; r < rows; r++) row.Add((outer[r] as System.Collections.IList)?[c]);
                result.Add(row);
            }
            return result;
        }
        return matrix;
    }
