    // ── Dispatcher MCP → procedure BASIC (lato SERVER) ────────────────────────
    // Il compilatore IL registra all'avvio ogni procedura BASIC (nome → symbolId +
    // nomi parametri) via RegisterBasicProcedure; il dispatcher le invoca per nome
    // quando un client MCP chiama tools/call.

    private static readonly System.Collections.Concurrent.ConcurrentDictionary<string, (int SymbolId, string[] ParamNames)>
        _basicProcedures = new(StringComparer.OrdinalIgnoreCase);

    public static void RegisterBasicProcedure(string name, int symbolId, string paramNamesCsv) =>
        _basicProcedures[name] = (symbolId, SplitParams(paramNamesCsv));

    /// <summary>S_eval §ii: assembly del programma corrente (per risolvere le procedure
    /// utente chiamate da EVAL/macro). Impostato dal prologo emesso (insieme a
    /// RegisterBasicProcedure); modello single-program come SetMacroContext/SetCurrent.</summary>
    private static System.Reflection.Assembly? _basicProcedureAssembly;

    /// <summary>Registra l'assembly del programma in esecuzione (prologo emesso). Vedi
    /// <see cref="_basicProcedureAssembly"/> per il modello.</summary>
    public static void SetProcedureAssembly(System.Reflection.Assembly asm) => _basicProcedureAssembly = asm;

    /// <summary>S_eval §ii: invoca una SUB/FUNCTION utente per nome+arità con argomenti
    /// object (coercizione tollerante per parametro). Risolve SymbolId dal _macroProgram
    /// corrente e MethodInfo "Proc_ID" dall'assembly registrato. SUB (void) → null.
    /// Errori espliciti (mai no-op): nome ignoto, arità senza overload, invoke fallito.
    /// Limiti: niente metodi di classe (serve receiver), niente GENERATOR (non eseguibili
    /// in sync), parametri ByRefBox avvolti (scritture perse), park dentro la chiamata
    /// non supportato (deadlock — il chiamante EVAL è sincrono).</summary>
    public static object? InvokeBasicProcedureByName(string name, int argc, object?[] args)
    {
        var program = Volatile.Read(ref _macroProgram);
        if (program == null)
            throw new InvalidOperationException($"EVAL chiama '{name}' ma nessun programma host è registrato (SetMacroContext).");
        var allMatches = program.Symbols.GetAllProcedures()
            .OfType<FunctionDefinition>()
            .Where(fd => string.Equals(fd.OriginalName.Lexeme, name, StringComparison.OrdinalIgnoreCase))
            .ToList();
        // Overload: arità esatta prima, poi il minore formale maggiore (i default mancanti
        // falliscono espliciti all'Invoke — mai prese in silenzio quelle sbagliate).
        var chosen = allMatches.FirstOrDefault(fd => fd.Parameters.Length == argc)
            ?? allMatches.Where(fd => fd.Parameters.Length > argc).OrderBy(fd => fd.Parameters.Length).FirstOrDefault();
        if (chosen == null)
            throw new InvalidOperationException($"EVAL chiama '{name}' con {argc} argomenti: nessun overload valido nel programma host.");
        var asm = _basicProcedureAssembly;
        System.Reflection.MethodInfo? method = null;
        if (asm != null)
        {
            var programType = asm.GetType("GeneratedProgram");
            method = programType?.GetMethod("Proc_" + chosen.SymbolId,
                System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.DeclaredOnly);
        }
        method ??= FindProcedureMethod(chosen.SymbolId, null);
        if (method is null)
            throw new InvalidOperationException($"EVAL chiama '{name}': metodo CLR 'Proc_{chosen.SymbolId}' non trovato.");
        var pis = method.GetParameters();
        var invokeArgs = new object?[pis.Length];
        for (var i = 0; i < pis.Length; i++)
        {
            if (i >= args.Length)
            {
                // Parametri opzionali omessi: il binder usa il default (Type.Missing),
                // altrimenti Invoke lancia esplicito (mai prese silenziose).
                invokeArgs[i] = Type.Missing;
                continue;
            }
            var pt = pis[i].ParameterType;
            var raw = args[i];
            invokeArgs[i] = CoerceInvokeArg(raw, pt, name);
        }
        try
        {
            var result = method.Invoke(null, invokeArgs);
            return method.ReturnType == typeof(void) ? null : result;
        }
        catch (System.Reflection.TargetInvocationException tie)
        {
            throw new InvalidOperationException($"EVAL chiama '{name}': {tie.InnerException?.Message ?? tie.Message}", tie.InnerException ?? tie);
        }
    }

    private static object? CoerceInvokeArg(object? raw, Type pt, string procName)
    {
        if (raw == null) return pt.IsValueType ? Activator.CreateInstance(pt) : null;
        if (pt.IsInstanceOfType(raw)) return raw;
        if (pt.IsGenericType && pt.GetGenericTypeDefinition() == typeof(Basic.Runtime.Gpm.ByRefBox<>))
        {
            // Parametro ByRefBox<T>: avvolgi (scritture perse — EVAL passa r-values).
            try { return Activator.CreateInstance(pt, CoerceInvokeArg(raw, pt.GetGenericArguments()[0], procName)); }
            catch (Exception ex) { throw new InvalidOperationException($"EVAL chiama '{procName}': argomento non coercibile a {pt.Name}.", ex); }
        }
        try
        {
            if (pt == typeof(string)) return ObjToStr(raw);
            if (pt == typeof(bool)) return ToDouble(raw) != 0.0;
            return Convert.ChangeType(raw, pt, System.Globalization.CultureInfo.InvariantCulture);
        }
        catch (Exception ex)
        {
            throw new InvalidOperationException($"EVAL chiama '{procName}': argomento '{raw}' non coercibile a {pt.Name}.", ex);
        }
    }

    /// <summary>S_eval §ii: contesto host CLR per OP_CALL_HOST (tabella nomi+arity dal
    /// programma + invocatore registro). Addr=-1 sempre (risoluzione per nome).</summary>
    private static (List<global::Compiler.MacroHostProc>? Table, Func<int, object?[], object?>? Invoker) ClrHostContext()
    {
        var program = Volatile.Read(ref _macroProgram);
        if (program == null) return (null, null);
        var table = new List<global::Compiler.MacroHostProc>();
        foreach (var fd in program.Symbols.GetAllProcedures().OfType<FunctionDefinition>())
        {
            table.Add(new global::Compiler.MacroHostProc(fd.OriginalName.Lexeme, -1, fd.Parameters.Length));
        }
        if (table.Count == 0) return (null, null);
        Func<int, object?[], object?> inv = (idx, args) => (idx < 0 || idx >= table.Count)
            ? throw new InvalidOperationException($"OP_CALL_HOST idx={idx}: tabella host CLR assente.")
            : InvokeBasicProcedureByName(table[idx].Name, args.Length, args);
        return (table, inv);
    }

    /// <summary>Registra una procedura del chunk P-Code per l'invoke-by-name: il SymbolId è un
    /// MARKER negativo (-(ip+1)) che distingue il path PCodeVM da quello IL (symbolId ≥ 0).
    /// I nomi dei parametri sono generici (p0,p1,... per arità) — l'argomento JSON viene
    /// mappato per posizione.</summary>
    public static void RegisterPCodeProcedure(string name, int ip, int arity)
    {
        var names = new string[arity];
        for (var i = 0; i < arity; i++) names[i] = "p" + i;
        _basicProcedures[name] = (-(ip + 1), names);
    }

    /// <summary>Hook del PCodeVM per l'invoke-by-name: dato l'Ip della procedura + gli argomenti
    /// (ordine dichiarativo) + i globals del programma, spawna un task PCode sul suo scheduler con
    /// un FutureToResolve e ritorna il future (il chiamante lo polla). Registrato dal PCodeProcessor
    /// quando carica il chunk — la GPM è l'unico esecutore, MAI task .NET.</summary>
    public static Func<int, object?[], object?[], Basic.Runtime.Gpm.PCodeFutureValue>? PCodeInvokeHook { get; set; }

    private static string[] SplitParams(string csv) =>
        string.IsNullOrWhiteSpace(csv) ? [] : csv.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);

    public static string InvokeBasicProcedure(string name, string argsJson)
    {
        if (!_basicProcedures.TryGetValue(name, out var info))
            throw new KeyNotFoundException($"Procedura BASIC '{name}' non registrata (MCP tool non disponibile).");
        var method = FindProcedureMethod(info.SymbolId, paramTypes: null)
            ?? throw new KeyNotFoundException($"Procedura BASIC '{name}' non trovata nell'assembly.");
        var parameters = method.GetParameters();
        object?[] args;
        if (string.IsNullOrWhiteSpace(argsJson))
        {
            args = new object?[parameters.Length];
        }
        else
        {
            using var doc = System.Text.Json.JsonDocument.Parse(argsJson);
            var root = doc.RootElement;
            args = new object?[parameters.Length];
            for (var i = 0; i < parameters.Length; i++)
            {
                var paramName = info.ParamNames.Length > i ? info.ParamNames[i] : parameters[i].Name ?? ("arg" + i);
                if (root.TryGetProperty(paramName, out var v))
                    args[i] = ConvertToolArg(v, parameters[i].ParameterType);
            }
        }
        var result = method.Invoke(null, args);
        return result?.ToString() ?? "";
    }

    /// <summary>Come <see cref="InvokeBasicProcedure"/> ma GPM-aware: quando uno scheduler del
    /// programma è attivo, la procedura gira come TASK GPM (SpawnGoFunction + attesa del future)
    /// in-context — MAI invocata in diretta sul thread del chiamante esterno (listener MCP/HTTP).
    /// Fallback deterministico (invocazione diretta col ProgramGlobalScope applicato) solo senza
    /// GPM attivo.</summary>
    public static string InvokeBasicProcedureGpm(string name, string argsJson, int timeoutMs = 30000)
    {
        if (!_basicProcedures.TryGetValue(name, out var info))
            throw new KeyNotFoundException($"Procedura BASIC '{name}' non registrata (MCP tool non disponibile).");

        // Path PCodeVM (symbolId negativo = marker -(ip+1)): la procedura è un chunk P-Code —
        // spawn come task PCode sul suo scheduler (PCodeInvokeHook) + attesa del future. La GPM
        // PCode è l'unico esecutore, MAI il thread del chiamante esterno. Gli argomenti sono
        // boxed (object) — i tipi reali dei parametri PCode non sono noti qui.
        if (info.SymbolId < 0)
        {
            var pcodeArgs = BuildArgsFromJson(info, argsJson, System.Array.Empty<System.Type>());
            if (PCodeInvokeHook is { } pcodeHook)
            {
                var ip = -info.SymbolId - 1;
                var future = pcodeHook(ip, pcodeArgs, []);
                var deadline = Environment.TickCount64 + Math.Max(1000, timeoutMs);
                while (!future.IsResolved && Environment.TickCount64 < deadline)
                    System.Threading.Thread.Sleep(5);
                if (!future.IsResolved)
                    throw new TimeoutException($"PCode procedure '{name}' in timeout ({timeoutMs}ms) — il task non è terminato.");
                if (future.FailureException != null)
                    throw new InvalidOperationException(future.FailureException.Message);
                return future.Result?.ToString() ?? "";
            }
            throw new InvalidOperationException($"Procedura P-Code '{name}' non invocabile: nessun PCodeVM attivo (PCodeInvokeHook non registrato).");
        }

        var method = FindProcedureMethod(info.SymbolId, paramTypes: null)
            ?? throw new KeyNotFoundException($"Procedura BASIC '{name}' non trovata nell'assembly.");
        var parameters = method.GetParameters();
        var args = BuildArgsFromJson(info, argsJson, parameters.Length > 0 ? parameters.Select(p => p.ParameterType).ToArray() : []);
        var scheduler = IlGpmRuntime.CurrentScheduler;
        if (scheduler != null)
        {
            var future = IlGpmRuntime.SpawnGoFunction(scheduler, info.SymbolId, args, null);
            var deadline = Environment.TickCount64 + Math.Max(1000, timeoutMs);
            while (!future.IsResolved && Environment.TickCount64 < deadline)
                System.Threading.Thread.Sleep(5);
            if (!future.IsResolved)
                throw new TimeoutException($"MCP tool '{name}' in timeout ({timeoutMs}ms) — la procedura non è terminata.");
            if (future.FailureException != null)
                throw new InvalidOperationException(future.FailureException.Message);
            return future.Result?.ToString() ?? "";
        }

        var scope = ProgramGlobalScope;
        if (scope != null) BeginGlobalScope(scope);
        try { var result = method.Invoke(null, args); return result?.ToString() ?? ""; }
        finally { if (scope != null) EndGlobalScope(); }
    }

    private static object?[] BuildArgsFromJson((int SymbolId, string[] ParamNames) info, string argsJson, Type?[] paramTypes)
    {
        var n = info.ParamNames.Length;
        var args = new object?[n];
        if (string.IsNullOrWhiteSpace(argsJson)) return args;
        using var doc = System.Text.Json.JsonDocument.Parse(argsJson);
        var root = doc.RootElement;
        for (var i = 0; i < n; i++)
        {
            var paramName = info.ParamNames[i];
            if (root.TryGetProperty(paramName, out var v))
                args[i] = ConvertToolArg(v, i < paramTypes.Length && paramTypes[i] is { } t ? t : typeof(object));
        }
        return args;
    }

    private static object? ConvertToolArg(System.Text.Json.JsonElement v, Type targetType)
    {
        if (v.ValueKind == System.Text.Json.JsonValueKind.String)
            return Convert.ChangeType(v.GetString(), Nullable.GetUnderlyingType(targetType) ?? targetType, System.Globalization.CultureInfo.InvariantCulture);
        if (v.ValueKind is System.Text.Json.JsonValueKind.True or System.Text.Json.JsonValueKind.False)
            return v.GetBoolean();
        if (v.ValueKind == System.Text.Json.JsonValueKind.Number)
            return Convert.ChangeType(v.GetDouble(), Nullable.GetUnderlyingType(targetType) ?? targetType, System.Globalization.CultureInfo.InvariantCulture);
        return v.GetRawText();
    }
    public static string McpPrompts()
    {
        // Ordinati per nome (vedi McpResources: parità deterministica con gmb_mcp_prompts).
        var agents = Basic.Agents.AgentServer.Instance.List()
            .OrderBy(a => a.Name, StringComparer.OrdinalIgnoreCase);
        var sb = new System.Text.StringBuilder();
        sb.Append('[');
        var first = true;
        foreach (var agent in agents)
        {
            if (!first) sb.Append(',');
            first = false;
            sb.Append($"{{\"name\":\"{agent.Name}\",\"description\":\"Chat with agent {agent.Name}\"}}");
        }
        sb.Append(']');
        return sb.ToString();
    }
