    public static double McpRegisterTool(string toolName, string procName, string desc)
        => McpRegisterTool(toolName, procName, desc, readOnly: false);

    /// <summary>Registro con classificazione read-only (pattern MCP-001): un tool
    /// dichiarato READONLY consulta/calcola senza mutare stato — il McpServer in modalità
    /// read-only può rifiutare i tool mutanti, e tools/list espone il flag.</summary>
    public static double McpRegisterTool(string toolName, string procName, string desc, bool readOnly)
        => McpRegisterToolEx(toolName, procName, desc, readOnly, outputSchemaJson: "");

    /// <summary>Registrazione con outputSchema OPZIONALE (5° argomento BASIC di
    /// `AI MCP REGISTER TOOL`): metadato del risultato del tool, emesso in tools/list.
    /// Unica implementazione reale della registrazione (McpRegisterTool è wrapper) —
    /// parità con `gmb_mcp_register_tool_ex` del runtime C condiviso.</summary>
    public static double McpRegisterToolEx(string toolName, string procName, string desc, bool readOnly,
                                           string outputSchemaJson)
        => McpRegisterToolCore(toolName, procName, desc, readOnly, outputSchemaJson, inputSchemaJson: null);

    /// <summary>Registrazione con `inputSchema` ESPLICITO (già compilato nel chunk dal
    /// compiler P-Code tramite `McpInputSchemaJsonFor`): ha precedenza sulla derivazione per
    /// reflection, che sul percorso P-Code/VM-C non conosce le procedure del chunk e
    /// produrrebbe `{}` → `AI.MCPLISTTOOLS()` divergeva da IL/C99. Stessa ABI degli altri
    /// produttori: (tool, proc, desc, readOnly, inputSchema, outputSchema).</summary>
    public static double McpRegisterToolWithSchema(string toolName, string procName, string desc, bool readOnly,
                                                   string inputSchemaJson, string outputSchemaJson)
        => McpRegisterToolCore(toolName, procName, desc, readOnly, outputSchemaJson, inputSchemaJson);

    private static double McpRegisterToolCore(string toolName, string procName, string desc, bool readOnly,
                                              string outputSchemaJson, string? inputSchemaJson)
    {
        System.Text.Json.Nodes.JsonObject? explicitSchema = null;
        if (!string.IsNullOrWhiteSpace(inputSchemaJson))
        {
            try
            {
                explicitSchema = System.Text.Json.Nodes.JsonNode.Parse(inputSchemaJson)
                    as System.Text.Json.Nodes.JsonObject;
            }
            catch (System.Text.Json.JsonException) { explicitSchema = null; }
        }
        var schema = explicitSchema ?? (_basicProcedures.ContainsKey(procName)
            ? BuildInputSchema(procName)
            : BrowserToolSchema(procName)); // tool browser_* nativi: procName = nome tool, schema statico
        System.Text.Json.Nodes.JsonObject? outputSchema = null;
        if (!string.IsNullOrWhiteSpace(outputSchemaJson))
        {
            try
            {
                outputSchema = System.Text.Json.Nodes.JsonNode.Parse(outputSchemaJson)
                    as System.Text.Json.Nodes.JsonObject;
            }
            catch (System.Text.Json.JsonException)
            {
                // outputSchema non valido: dichiarazione ignorata (non emessa), mai un crash
                // silenzioso sul dato dell'utente — il tool resta registrato.
                outputSchema = null;
            }
        }
        Basic.Mcp.McpToolRegistry.Instance.Register(new Basic.Mcp.McpToolDefinition
        {
            Name = toolName,
            Description = desc,
            QualifiedProcedureName = procName,
            InputSchema = schema ?? BuildInputSchema(procName),
            OutputSchema = outputSchema,
            ReadOnly = readOnly
        });
        return 1.0;
    }

    /// <summary>InputSchema MCP dai parametri reali della procedura BASIC registrata
    /// (nomi + tipi CLR → JSON Schema), via McpSchemaBuilder. Prima era un oggetto vuoto.</summary>
    private static System.Text.Json.Nodes.JsonObject BuildInputSchema(string procName)
    {
        if (!_basicProcedures.TryGetValue(procName, out var info)) return new System.Text.Json.Nodes.JsonObject();
        var method = FindProcedureMethod(info.SymbolId, paramTypes: null);
        var ps = method?.GetParameters();
        if (ps is null || ps.Length == 0) return new System.Text.Json.Nodes.JsonObject();
        var pars = new List<(string Name, string TypeName, bool Optional)>();
        for (var i = 0; i < ps.Length; i++)
        {
            var name = info.ParamNames.Length > i ? info.ParamNames[i] : (ps[i].Name ?? "p" + i);
            pars.Add((name, ClrToBasicType(ps[i].ParameterType), Optional: false));
        }
        return Basic.Mcp.McpSchemaBuilder.FromParameters(pars);
    }

    private static string ClrToBasicType(Type t)
    {
        var u = Nullable.GetUnderlyingType(t) ?? t;
        if (u == typeof(string)) return "STRING";
        if (u == typeof(bool)) return "BIT";
        if (u == typeof(int) || u == typeof(long) || u == typeof(short) || u == typeof(byte) ||
            u == typeof(uint) || u == typeof(ulong) || u == typeof(ushort) || u == typeof(sbyte)) return "INTEGER";
        if (u == typeof(double) || u == typeof(float)) return "DOUBLE";
        if (u == typeof(object) || u == typeof(System.Text.Json.JsonElement)) return "JSON";
        if (u.IsArray) return "ARRAY OF " + (u.GetElementType() == typeof(string) ? "STRING" : "NUMBER");
        return "STRING";
    }

    /// <summary>Assicura che il dispatcher MCP → procedure BASIC sia cablato (usato dagli
    /// agenti con tool anche senza MCP.SERVE, e da McpServe stesso).</summary>
    public static void EnsureMcpDispatcher() =>
        Basic.Mcp.McpRuntimeBridge.Dispatcher ??= new IlMcpToolDispatcher();

    /// <summary>Inizializza il provider SQLite (SQLitePCL.Batteries_V2.Init) — senza, il
    /// type initializer di SqliteConnection lancia nei programmi IL generati. Via reflection
    /// per non aggiungere il pacchetto SQLitePCLRaw al backend.</summary>
    public static void EnsureSqlite()
    {
        try
        {
            var t = Type.GetType("SQLitePCL.Batteries_V2, SQLitePCLRaw.batteries_v2");
            t?.GetMethod("Init")?.Invoke(null, null);
        }
        catch { /* best effort: se il bundle non e' presente, il primo uso fallira' con un messaggio chiaro */ }
    }
    public static string McpResources()
    {
        // Ordinati per nome (case-insensitive): l'ordine di Dictionary.Values non è
        // garantito e divergeva dal runtime C (gmb_mcp_resources ordina) → parità
        // deterministica del JSON di AI.MCPRESOURCES() fra 4 backend.
        var tools = Basic.Mcp.McpToolRegistry.Instance.List()
            .OrderBy(t => t.Name, StringComparer.OrdinalIgnoreCase);
        var sb = new System.Text.StringBuilder();
        sb.Append('[');
        var first = true;
        foreach (var tool in tools)
        {
            if (!first) sb.Append(',');
            first = false;
            sb.Append(System.Text.Json.JsonSerializer.Serialize(new { uri = $"basic://tools/{tool.Name}", name = tool.Name, description = tool.Description }));
        }
        sb.Append(']');
        return sb.ToString();
    }
    private static System.Threading.CancellationTokenSource? _ilMcpCts;
    public static double McpServe(string mode, double port)
        => McpServe(mode, port, readOnly: false);

    /// <summary>Serve con modalità read-only (pattern MCP-001): il server rifiuta ogni
    /// tool NON dichiarato READONLY alla registrazione — un capability server di sola
    /// consultazione non esegue mai tool mutanti per costruzione.</summary>
    public static double McpServe(string mode, double port, bool readOnly)
    {
        Basic.Mcp.McpRuntimeBridge.Dispatcher ??= new IlMcpToolDispatcher();
        if (mode.Equals("stdio", StringComparison.OrdinalIgnoreCase))
        {
            // Compatibilità GPM: un server stdio blocca il thread su stdin. Fuori da un
            // task GPM (Main top-level, thread dedicato) il blocco è sicuro — come
            // IslandRuntime.Sleep; dentro un worker GPM bloccherebbe l'intero pool
            // (affamando le altre green-thread), quindi lo vietiamo con un errore chiaro.
            bool inGpmTask = false;
            try { _ = Basic.Runtime.Gpm.IslandRuntime.CurrentTask; inGpmTask = true; }
            catch { /* _currentTask non impostato: siamo fuori da un'isola */ }
            if (inGpmTask)
                throw new NotSupportedException(
                    "MCP.SERVE(\"stdio\") deve essere eseguito nel Main top-level (fuori da un task GPM).");

            // Server MCP stdio (newline-delimited JSON-RPC): bloccante su stdin finché il
            // client chiude la pipe (EOF) — stesso comportamento del riferimento VM.
            var audit = Basic.Mcp.McpAuditLog.CreateDefault();
            var server = new Basic.Mcp.McpServer(dispatcher: Basic.Mcp.McpRuntimeBridge.Dispatcher, audit: audit, readOnlyServer: readOnly);
            var transport = new Basic.Mcp.McpStdioTransport();
            var host = new Basic.Mcp.McpServerHost(server, transport);
            host.RunAsync(System.Threading.CancellationToken.None).GetAwaiter().GetResult();
            return 1.0;
        }
        if (mode.Equals("http", StringComparison.OrdinalIgnoreCase))
        {
            var apiKey = System.Environment.GetEnvironmentVariable(Basic.Mcp.McpConstants.EnvApiKey);
            if (string.IsNullOrWhiteSpace(apiKey)) return 0.0;
            var p = (int)port;
            if (p is < 1 or > 65535) return 0.0;
            try
            {
                var audit = Basic.Mcp.McpAuditLog.CreateDefault();
                var server = new Basic.Mcp.McpServer(dispatcher: Basic.Mcp.McpRuntimeBridge.Dispatcher, audit: audit, readOnlyServer: readOnly);
                var options = new Basic.Mcp.McpHttpOptions
                {
                    Port = p,
                    ApiKey = apiKey,
                    Path = Basic.Mcp.McpHttpOptions.FromEnvironment(p).Path,
                    MaxBodyBytes = Basic.Mcp.McpHttpOptions.FromEnvironment(p).MaxBodyBytes,
                    RequestsPerMinutePerIp = Basic.Mcp.McpHttpOptions.FromEnvironment(p).RequestsPerMinutePerIp,
                    RequestTimeout = Basic.Mcp.McpHttpOptions.FromEnvironment(p).RequestTimeout
                };
                var httpHost = new Basic.Mcp.McpHttpListenerHost(server, options, audit);
                _ilMcpCts?.Cancel();
                _ilMcpCts = new System.Threading.CancellationTokenSource();
                _ = httpHost.RunAsync(_ilMcpCts.Token);
                return 1.0;
            }
            catch { return 0.0; }
        }
        return 0.0;
    }
    public static double McpStop()
    {
        _ilMcpCts?.Cancel();
        _ilMcpCts = null;
        return 1.0;
    }
