    public static long SqlChanges(string alias)
    { try { var drv = IlRuntime.Current.SqlDataSession.FindAlias(alias) as Basic.Databases.Rdd.SqlDriver ?? FindAnySqlDriver(); return drv?.Changes() ?? 0; } catch { return 0; } }
    /// <summary>SQL.EXEC alias, sql [, param...] — esegue lo statement SQL sul driver dell'area
    /// indicata. Supporta parametri: un singolo DICT → named, altrimenti posizionali.
    /// Firma estesa per la riunificazione con la PCodeVM (che li supportava già).</summary>
    public static double SqlExec(string alias, string sql, object?[] extra)
    {
        try
        {
            var drv = IlRuntime.Current.SqlDataSession.FindAlias(alias) as Basic.Databases.Rdd.SqlDriver
                ?? FindAnySqlDriver();
            if (drv is null) return 0.0;
            System.Collections.Generic.IReadOnlyList<object?>? pos = null;
            System.Collections.Generic.IReadOnlyDictionary<string, object?>? named = null;
            if (extra.Length == 1 && extra[0] is System.Collections.IDictionary dd)
            {
                var d2 = new System.Collections.Generic.Dictionary<string, object?>(StringComparer.OrdinalIgnoreCase);
                foreach (System.Collections.DictionaryEntry e in dd) d2[Convert.ToString(e.Key) ?? ""] = e.Value;
                named = d2;
            }
            else if (extra.Length > 0) pos = extra;
            return (double)drv.ExecRaw(sql, pos, named);
        }
        catch { return 0.0; }
    }
    /// <summary>Coarse-park: true se lo statement è una scrittura PESANTE (riscrive un file
    /// via vtab csv/parquet) da eseguire fuori dal worker GPM. Mirror del classificatore C.</summary>
    public static bool SqlIsHeavyWrite(string alias, string sql)
    {
        try
        {
            var drv = IlRuntime.Current.SqlDataSession.FindAlias(alias) as Basic.Databases.Rdd.SqlDriver
                ?? FindAnySqlDriver();
            return drv?.IsHeavyWrite(sql) ?? false;
        }
        catch { return false; }
    }
    private static Basic.Databases.Rdd.SqlDriver? FindAnySqlDriver()
    {
        var session = Current.SqlDataSession;
        for (var area = 1; area <= Basic.Databases.Rdd.DataSession.MaxWorkareas; area++)
            if (session.GetWorkArea(area)?.Driver is Basic.Databases.Rdd.SqlDriver driver)
                return driver;
        return null;
    }
    public static bool SqlFetch(double rsId)
    { try { return FindAnySqlDriver()?.Fetch((int)rsId) == true; } catch { return false; } }
    public static object? SqlResultSetField(double rsId, string column)
    { try { var row = FindAnySqlDriver()?.GetCurrentRow((int)rsId); return row?.TryGetValue(column, out var v) == true ? v : null; } catch { return null; } }
    /// <summary>rs(i) — valore della colonna per INDICE nella riga corrente.</summary>
    public static object? SqlResultSetFieldByIndex(double rsId, int columnIndex)
    { try { return FindAnySqlDriver()?.GetCurrentFieldByIndex((int)rsId, columnIndex); } catch { return null; } }
    /// <summary>rs.COUNT — numero di righe del result set materializzato.</summary>
    public static double SqlResultSetCount(double rsId)
    { try { return FindAnySqlDriver()?.ResultSetCount((int)rsId) ?? 0; } catch { return 0; } }
    /// <summary>rs.COLUMNS — numero di colonne.</summary>
    public static double SqlResultSetColumnCount(double rsId)
    { try { return FindAnySqlDriver()?.ResultSetColumnCount((int)rsId) ?? 0; } catch { return 0; } }
    public static void SqlCloseResultSet(double rsId)
    { try { FindAnySqlDriver()?.CloseResultSet((int)rsId); } catch { } }
    public static long SqlLastInsertRowId(string alias)
    { try { var drv = IlRuntime.Current.SqlDataSession.FindAlias(alias) as Basic.Databases.Rdd.SqlDriver ?? FindAnySqlDriver(); return drv?.LastInsertRowId() ?? 0; } catch { return 0; } }

    /// <summary>SQL.DESCRIBE(rs): schema (colonne) come JSON — G10 (2026-10-09).</summary>
    public static string SqlDfSchema(double rsId)
    { try { var drv = FindAnySqlDriver(); if (drv is null) return ""; int id = (int)rsId; var cols = drv.ResultSetColumns(id); int rows = drv.ResultSetCount(id); var sb = new System.Text.StringBuilder(); sb.Append("{\"rows\":").Append(rows).Append(",\"columns\":["); for (int i = 0; i < cols.Count; i++) { if (i > 0) sb.Append(','); var v = rows > 0 ? drv.ResultSetValue(id, 0, i) : null; string ty = (v is long or int or short or byte) ? "int" : (v is double or float or decimal) ? "float" : "text"; sb.Append("{\"name\":\"").Append(cols[i]).Append("\",\"type\":\"").Append(ty).Append("\"}"); } sb.Append("]}"); return sb.ToString(); } catch { return ""; } }

    /// <summary>SQL.TOCSV(rs, path): result set -> CSV — G10.</summary>
    public static long SqlToCsv(double rsId, string path)
    { try { var drv = FindAnySqlDriver(); if (drv is null) return -1; int id = (int)rsId; var cols = drv.ResultSetColumns(id); int rows = drv.ResultSetCount(id); using var w = new System.IO.StreamWriter(path); w.WriteLine(string.Join(",", cols.Select(IlSqlCsvField))); for (int r = 0; r < rows; r++) { var vals = new List<string>(); for (int c = 0; c < cols.Count; c++) vals.Add(IlSqlCsvField(drv.ResultSetValue(id, r, c)?.ToString() ?? "")); w.WriteLine(string.Join(",", vals)); } return 0; } catch { return -1; } }
    private static string IlSqlCsvField(string? s) { s ??= ""; return s.IndexOfAny(new[] { ',', '"', '\n', '\r' }) < 0 ? s : "\"" + s.Replace("\"", "\"\"") + "\""; }

    /// <summary>SQL.FROMCSV(alias, table, path): CSV -> tabella — G10.</summary>
    public static long SqlFromCsv(string alias, string table, string path)
    { try { var drv = IlRuntime.Current.SqlDataSession.FindAlias(alias) as Basic.Databases.Rdd.SqlDriver ?? FindAnySqlDriver(); return drv is null ? -1 : drv.LoadCsv(table, path); } catch { return -1; } }

    /// <summary>SQL.COL(rs, col): intera colonna → ARRAY di stringhe (G10).</summary>
    public static string[] SqlCol(double rsId, string col)
    { try { var drv = FindAnySqlDriver(); if (drv is null) return Array.Empty<string>(); int id = (int)rsId; var cols = drv.ResultSetColumns(id); int ci = -1; for (int i = 0; i < cols.Count; i++) if (string.Equals(cols[i], col, StringComparison.OrdinalIgnoreCase)) { ci = i; break; } if (ci < 0) return Array.Empty<string>(); int rows = drv.ResultSetCount(id); var a = new string[rows]; for (int r = 0; r < rows; r++) a[r] = drv.ResultSetValue(id, r, ci)?.ToString() ?? ""; return a; } catch { return Array.Empty<string>(); } }
