    /// <summary>Normalizza una capability/ruolo (es. %CHAT → "completion", %EMBEDDING →
    /// "embedding") al ruolo canonico del registry. Unico resolver: costante numerica
    /// 0..4 (CONSTANTS %CHAT/%OCR/%AUDIO/%EMBEDDING/%RERANKER) o nome ruolo storico.</summary>
    private static string NormalizeRole(string role)
        => Basic.Providers.ProviderRole.FromCapabilityOrRole(role);
    public static string ProviderActive(string role) => Basic.Providers.ProviderServer.Instance.GetActiveName(NormalizeRole(role)) ?? "";
    public static string[] ProviderList(string role) => Basic.Providers.ProviderServer.Instance.List(NormalizeRole(role)).ToArray();
    public static double ProviderUnregister(string name) => Basic.Providers.ProviderServer.Instance.Unregister(name) ? 1.0 : 0.0;
    /// <summary>PROVIDER REGISTER — dispatch per firma (runtime comune con la PCodeVM):
    /// REGISTER("embedding"/"reranker", name, kind, json) retro-compat, oppure
    /// REGISTER(alias, capability, source [, param]) nuova firma.</summary>
    /// REGISTERLOCAL(path): registra un provider locale dal path (auto-detect capability/kind/config).
    /// Alias = basename del path (o "local"). Delega a RegisterSource (semantica C99 gmb_provider_register).
    public static double ProviderRegisterLocal(string path)
    {
        try
        {
            var prov = Basic.Providers.ProviderServer.Instance;
            var expanded = Basic.ModelDownload.PathExpansion.Expand(path ?? "");
            if (!File.Exists(expanded) && !Directory.Exists(expanded))
            {
                // il path può essere un endpoint/identificatore: RegisterSource lo gestisce
                prov.RegisterSource("local", null, path ?? "", null);
                return 1.0;
            }
            var alias = Path.GetFileName(expanded.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar));
            if (string.IsNullOrWhiteSpace(alias)) alias = "local";
            var detected = Basic.ModelDownload.ModelScanner.DetectConfig(expanded, null);
            prov.Register(Basic.AI.Rag.AiCapabilityExtensions.ToRole(detected.Capability), alias, detected.Kind, detected.Config);
            return 1.0;
        }
        catch { return 0.0; }
    }

    public static double ProviderRegister(string role, string name, string kind, string configJson)
    {
        try
        {
            var prov = Basic.Providers.ProviderServer.Instance;
            if (string.Equals(role, "embedding", StringComparison.OrdinalIgnoreCase)
                || string.Equals(role, "reranker", StringComparison.OrdinalIgnoreCase))
            {
                prov.RegisterSource(name, role, kind, string.IsNullOrEmpty(configJson) ? null : configJson);
                return 1.0;
            }
            prov.RegisterFromJson(NormalizeRole(role), name, kind, configJson);
            return 1.0;
        }
        catch { return 0.0; }
    }
