    // ── AI SKILLS ... ────────────────────────────────────────────────────────
    public static double AiSkillsAdd(string path)
    {
        var full = Path.GetFullPath(Basic.ModelDownload.PathExpansion.Expand(path));
        var defaultDir = Basic.AI.AiConfig.SkillsDefaultPath;
        if (Directory.Exists(full))
        {
            // Cartella di skills: copia ogni SKILL.md nella defaultPath.
            foreach (var d in Directory.EnumerateDirectories(full))
            {
                var skillFile = Path.Combine(d, "SKILL.md");
                if (!File.Exists(skillFile)) continue;
                var name = Path.GetFileName(d);
                var dest = Path.Combine(defaultDir, name);
                Directory.CreateDirectory(dest);
                File.Copy(skillFile, Path.Combine(dest, "SKILL.md"), overwrite: true);
            }
            Basic.AI.AiConfig.AddSkillPath(defaultDir);
        }
        else if (File.Exists(full))
        {
            // File SKILL.md singolo: copia in una cartella col nome del file.
            var name = Path.GetFileNameWithoutExtension(full);
            var dest = Path.Combine(defaultDir, name);
            Directory.CreateDirectory(dest);
            File.Copy(full, Path.Combine(dest, "SKILL.md"), overwrite: true);
            Basic.AI.AiConfig.AddSkillPath(defaultDir);
        }
        else
        {
            return 0.0;
        }
        Basic.AI.SkillIndex.Refresh();
        return 1.0;
    }

    public static double AiSkillsRemove(string name)
    {
        var defaultDir = Basic.AI.AiConfig.SkillsDefaultPath;
        var dest = Path.Combine(defaultDir, name);
        if (Directory.Exists(dest))
        {
            Directory.Delete(dest, recursive: true);
            Basic.AI.SkillIndex.Refresh();
            return 1.0;
        }
        return 0.0;
    }

