    public static double AiSkillsMarketplace(string url, string? dest = null)
    {
        // git clone del marketplace in una cartella (default GmbiPaths.SkillsMarketplacesDir,
        // oppure la destinazione esplicita passata da BASIC). Le skills restano come REF
        // (il percorso viene aggiunto alla config senza copiare i file).
        var target = dest;
        if (string.IsNullOrWhiteSpace(target))
            target = Path.Combine(GmbiPaths.SkillsMarketplacesDir, Path.GetFileNameWithoutExtension(url.TrimEnd('/')));
        target = Basic.ModelDownload.PathExpansion.Expand(target);
        Directory.CreateDirectory(target);
        var psi = new System.Diagnostics.ProcessStartInfo("git")
        {
            UseShellExecute = false,
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            WorkingDirectory = target,
        };
        psi.ArgumentList.Add("clone");
        psi.ArgumentList.Add("--depth");
        psi.ArgumentList.Add("1");
        psi.ArgumentList.Add(url);
        psi.ArgumentList.Add("repo");
        using var proc = System.Diagnostics.Process.Start(psi);
        proc?.WaitForExit(120000);
        if (proc is null || proc.ExitCode != 0) return 0.0;

        Basic.AI.AiConfig.AddSkillPath(Path.Combine(target, "repo"));
        Basic.AI.SkillIndex.Refresh();
        return 1.0;
    }

