    public static double AiPluginsAdd(string path)
    {
        var full = Path.GetFullPath(Basic.ModelDownload.PathExpansion.Expand(path));
        var defaultDir = Basic.AI.AiConfig.PluginsDefaultPath;
        if (Directory.Exists(full))
        {
            foreach (var d in Directory.EnumerateDirectories(full))
            {
                if (!File.Exists(Path.Combine(d, "PLUGIN.md"))) continue;
                var name = Path.GetFileName(d);
                var dest = Path.Combine(defaultDir, name);
                Directory.CreateDirectory(dest);
                foreach (var f in Directory.EnumerateFiles(d))
                    File.Copy(f, Path.Combine(dest, Path.GetFileName(f)), overwrite: true);
            }
        }
        else if (File.Exists(full) && Path.GetFileName(full).Equals("PLUGIN.md", StringComparison.OrdinalIgnoreCase))
        {
            var name = Path.GetFileName(Path.GetDirectoryName(full)) ?? "plugin";
            var dest = Path.Combine(defaultDir, name);
            Directory.CreateDirectory(dest);
            File.Copy(full, Path.Combine(dest, "PLUGIN.md"), overwrite: true);
        }
        else return 0.0;
        Basic.AI.PluginIndex.Refresh();
        return 1.0;
    }

