    // ── GET/SET/RANGE/PERATIO/KEYCLOSE (parità VM) ───────────────────────
    public static object? Get(object? coll, object? key)
    {
        if (coll is System.Collections.IDictionary d) return d[key ?? ""];
        if (coll is System.Collections.IList l)
        {
            var i = Convert.ToInt32(key);
            if (i >= 0 && i < l.Count) return l[i];
        }
        return null;
    }
    public static void Set(object? coll, object? key, object? value)
    {
        if (coll is System.Collections.IDictionary d) d[key ?? ""] = value;
        else if (coll is System.Collections.IList l)
        {
            var i = Convert.ToInt32(key);
            if (i >= 0 && i < l.Count) l[i] = value;
        }
    }
    /// <summary>
    /// BUG REALE trovato 2026-09-07 (AccessViolationException, due FOR EACH su RANGE(...)
    /// nella stessa SUB): ritornava `List&lt;object?&gt;`, ma la firma StdLib di RANGE
    /// (StdLib.Math.cs) lo dichiara `ArrayType(InferredType)` -- il backend IL, per un
    /// `DIM a = RANGE(...)` seguito da FOR EACH, registra `a` come vero array CLR
    /// (RegisterDynamicArrayLocal, fast path `ldlen`/`ldelem.r8` diretto, MAI
    /// IlRuntime.ForEachValues) perché il DataType del simbolo è ArrayType. Un local
    /// dichiarato `double[]` che riceve in realtà una `List&lt;object&gt;` è un mismatch di
    /// tipo silenzioso: lo `stloc` (nessun cast, prima di oggi) copiava il riferimento
    /// grezzo, e `ldlen`/`ldelem.r8` applicati a quella `List&lt;object&gt;` come se fosse un
    /// `double[]` leggevano/interpretavano memoria a offset sbagliati -- funziona per caso
    /// quando l'esecuzione non tocca quella memoria in modo distruttivo, va in
    /// AccessViolationException (memoria corrotta) quando cambia la pressione di
    /// allocazione (es. un secondo ciclo nella stessa SUB). Il chiamante inline
    /// (`FOR EACH x IN RANGE(...)`, mai assegnato a un DIM) passa invece da RangeBuiltin +
    /// IlRuntime.ForEachValues (percorso generico, List-based) -- MAI toccato da questo bug,
    /// verificato funzionante prima e dopo. Fix: costruisce e ritorna un vero `double[]`,
    /// allineando l'implementazione al contratto DICHIARATO (ArrayType) invece di
    /// cambiare il codegen per trattare RANGE come lista dinamica in ogni punto che lo usa
    /// (DIM, UBOUND, indicizzazione diretta a(i), ecc. si aspettano TUTTI un vero array per
    /// un simbolo di DataType ArrayType). Vedi anche il castclass difensivo aggiunto in
    /// IlProgramCompiler.Operators.cs (EmitCoerceToTarget) e IlProgramCompiler.Collections.cs
    /// (EmitArrayRefFromInfo) -- chiudono la classe di bug per QUALUNQUE builtin futuro con
    /// lo stesso mismatch (ReturnType ArrayType ma implementazione che ritorna un'altra
    /// forma), questo fix chiude la causa specifica di RANGE.
    /// </summary>
    public static object? Range(object? args)
    {
        var rArgs = args is System.Collections.IList r0 && r0.Count > 0 && r0[0] is System.Collections.IList r00
            ? (System.Collections.IList)r00
            : args is System.Collections.IList r1 ? r1 : null;
        // unwrap a profondità variabile (come la VM: il wrapping ParamArray può essere doppio)
        while (rArgs is not null && rArgs.Count == 1 && rArgs[0] is System.Collections.IList inner)
            rArgs = inner;
        if (rArgs is not { Count: >= 2 }) return null;
        int start = Convert.ToInt32(rArgs[0] ?? 0);
        int end = Convert.ToInt32(rArgs[1] ?? 0);
        int step = rArgs.Count >= 3 ? Convert.ToInt32(rArgs[2] ?? 1) : 1;
        if (step == 0) step = 1;
        var count = step > 0 ? Math.Max(0, (end - start) / step + 1) : Math.Max(0, (start - end) / -step + 1);
        var result = new double[count];
        var idx = 0;
        if (step > 0) for (int i = start; i <= end; i += step) result[idx++] = i;
        else for (int i = start; i >= end; i += step) result[idx++] = i;
        return result;
    }
