    /// <summary>Accesso SAFE a dict/list ([k]?): null se la chiave/indice è assente.</summary>
    public static object? DictTryGetValue(object? dict, object? key)
    {
        if (dict is System.Collections.IDictionary d && d.Contains(key ?? "")) return d[key ?? ""];
        if (dict is System.Collections.IList l)
        {
            var i = Convert.ToInt32(key);
            if (i >= 0 && i < l.Count) return l[i];
        }
        return null;
    }

    /// <summary>Accesso SAFE a un array (arr(i)?): il valore boxed o null se fuori range.</summary>
    public static object? ArraySafeIndex(object? array, double index)
    {
        if (array is System.Array a)
        {
            var i = (int)index;
            if (i >= 0 && i < a.Length) return a.GetValue(i);
        }
        return null;
    }

    /// <summary>DUP(n, valore): ripete il PRIMO carattere di una stringa, oppure il char
    /// ASCII di un numero (DUP(10, 42) = '**********') — parità VM.</summary>
    public static string Dup(long count, object? value)
    {
        var c = (int)count; if (c < 0) c = 0;
        if (value is string s && s.Length > 0) return new string(s[0], c);
        // `INTEGER` in BASIC è a 16 bit → sulla gamba IL arriva BOXATO come short/byte:
        // senza questi tipi nel pattern il codice (DUP(n, codice) / STRING$(n, codice)) tornava
        // stringa VUOTA mentre le altre gambe davano i caratteri.
        if (value is double or float or int or long or short or byte or sbyte or ushort or uint)
        {
            var ch = Convert.ToInt32(value);
            if (ch >= 0 && ch <= 0xFFFF) return new string((char)ch, c);
        }
        return "";
    }

    /// <summary>Formato PRINT parità VM (porting GM 8e48bed0/1ed14c73/79511cce): spazi
    /// intorno ai numerici (G15/G9), bool come -1/0, IEnumerable come "[...]" — la VM
    /// stampa "Età:  42 " (spazi), prima DoubleToInvariantString senza spazi → golden mismatch.</summary>
    public static string PrintFormatValue(object? value) => PrintFormatValueCore(value);

    /// <summary>Campo di tipo STRING mai assegnato: in IL un campo string C# è null, ma il
    /// canone dei 4 backend è la STRINGA VUOTA (PCode/VM-C/C99Native). La lettura
    /// di un campo stringa lo coalesce a "" — così TRIM/LEN/confronti coincidono sugli altri
    /// backend (bug: `TRIM(campo) = ""` era FALSE, `LEN` ritornava vuoto su IL).</summary>
    public static string EmptyIfNull(string? s) => s ?? string.Empty;

    /// <summary>PRINT in modalità grafica: con una grafica presente (runner test_graphics
    /// inietta SdlGraphicsService) il testo viene SEMPRE accodato alla pagina (PRINT_GPM,
    /// come la PCodeVM di gmo) — PrintInternal decide a runtime se lo schermo è attivo, nel
    /// corretto ordine di coda dopo SCREEN. Senza grafica (NullGraphicsService) → console.</summary>
    // Staging di stampa PER-STATEMENT (canone: SCARTARE il parziale su errore, parità
    // PCode/VM-C/C99). EmitPrintStatement avvolge ogni PRINT in PrintStageBegin/PrintStageEnd(1);
    // i print di console vanno nel buffer e sono emessi in un solo colpo a fine istruzione. Se la
    // valutazione di un argomento solleva un'eccezione (builtin/future), PrintStageEnd NON è
    // raggiunto → il parziale resta nel buffer e viene scartato dal PrintStageBegin successivo (o
    // a fine programma). Finestre/grafica restano immediate (come PCode).
    [ThreadStatic] private static System.Text.StringBuilder? _printStage;

    /// <summary>Exit code del programma BASIC: valore di ritorno di FUNCTION Main()
    /// (VB6/script tool). Il runner lo usa come codice di uscita del processo.</summary>
    public static int ProgramExitCode { get; private set; }
    public static void SetProgramExitCode(double v) { ProgramExitCode = (int)v; }
    public static void PrintStageBegin() { _printStage ??= new System.Text.StringBuilder(); _printStage.Clear(); }

    public static void PrintStageEnd(bool commit)
    {
        if (commit && _printStage is { Length: > 0 })
        {
            var staged = _printStage.ToString();
            _printStage.Clear();
            // SOLO un servizio grafico GIÀ creato (una finestra attiva): leggere la proprietà
            // `Graphics` qui la creava → caricava libgmb_gfx (+SDL, ~8 MB) per un PRINT testuale.
            var g = (Current as Runtime.HeadlessRuntimeHost)?.CreatedGraphics;
            bool gfx;
            try { gfx = g?.IsAvailable == true; } catch { gfx = false; }
            if (gfx) g!.Print(staged);
            else Current.Console.Print(staged);
            return;
        }
        _printStage?.Clear();
    }

    public static void PrintDispatch(string text)
    {
        // Finestra attiva → scrive nel buffer della finestra (viewport corrente).
        if (ActivePixelWindow() is { } pw)
        {
            pw.AppendLine(text ?? "");
            RenderPixelWindows();
            return;
        }
        if (ActiveWindowObj() is { } aw)
        {
            aw.AppendLine(text ?? "");
            RenderTuiWindows();
            return;
        }
        /* PRINT va sul canale TESTUALE (stdout/console): e' la semantica delle gambe C
         * (gmb_console_print), che stampano anche con SCREEN grafico attivo. Prima qui si
         * usava Graphics.Print quando il servizio era disponibile: in grafica il testo
         * spariva nel frame (chart_financial: IL vuoto, VMC "OK-chart-financial"). */
        if (_printStage != null) _printStage.Append(text ?? "");
        else Current.Console.Print(text);
    }
    public static void PrintNewLineDispatch()
    {
        if (ActivePixelWindow() is { } pw)
        {
            pw.AppendLine("");
            RenderPixelWindows();
            return;
        }
        if (ActiveWindowObj() is { } aw)
        {
            aw.AppendLine("");
            RenderTuiWindows();
            return;
        }
        if (_printStage != null)
        {
            // Il newline è l'ultimo elemento dell'istruzione PRINT: emette SUBITO il testo
            // staged con il newline in UN SOLO write (atomico tra task GPM concorrenti:
            // due chiamate separate Print(t)+PrintNewLine() permetterebbbero all'altro task
            // di infilarsi tra testo e '\n', incollando righe di task diversi).
            if (_printStage.Length > 0) { var t = _printStage.ToString(); _printStage.Clear(); Current.Console.Print(t + Environment.NewLine); }
            else Current.Console.PrintNewLine();
        }
        else Current.Console.PrintNewLine();
    }

    // Stage per-statement per il path GPM v2 (stepper/coroutine, IlGpmRuntime.PrintValue):
    // stesso buffer ThreadStatic e stessa disciplina del path flat (scarta il parziale su
    // errore: PrintStageBegin successivo pulisce). Senza stage attivo → scrittura diretta.
    public static void PrintStageAppend(string text)
    {
        if (_printStage != null) _printStage.Append(text ?? "");
        else Current.Console.Print(text ?? "");
    }
    public static void PrintStageNewLine()
    {
        // Un solo write di testo+newline (vedi PrintNewLineDispatch): atomico tra task.
        if (_printStage is { Length: > 0 })
        { var t = _printStage.ToString(); _printStage.Clear(); Current.Console.Print(t + Environment.NewLine); }
        else Current.Console.PrintNewLine();
    }
    /// <summary>LOCATE con schermo grafico attivo → LOCATE_GPM(col, line) senza -1 (PCodeVM
    /// di gmo); altrimenti Console.SetCursorPosition(col - 1, line - 1).</summary>
    // GRAPHICS C2PX/C2PY/P2CX/P2CY: conversione celle<->pixel con dimensione del font.
    // size omessa nel BASIC → il backend passa TEXTWIDTH(" ") (X) o TEXTHEIGHT() (Y).
    public static double C2PX(double col, double size) => col * size;
    public static double C2PY(double row, double size) => row * size;
    public static double P2CX(double x, double size) => x / size;
    public static double P2CY(double y, double size) => y / size;

    // CLS polimorfico (parità PRINT/LOCATE): schermo grafico attivo → cancella la pagina
    // grafica (CLS_GPM); altrimenti console. Prima EmitClsStatement andava SEMPRE alla
    // console → il CLS grafico non cancellava mai la pagina (sprites/poligoni vecchi
    // restavano sullo schermo).
    public static void ClsDispatch(object? color)
    {
        // Finestra attiva → svuota il buffer della finestra.
        if (ActivePixelWindow() is { } pw)
        {
            pw.Lines.Clear();
            pw.ScrollOffset = 0;
            pw.CursorLine = 0;
            pw.CursorCol = 0;
            RenderPixelWindows();
            return;
        }
        if (ActiveWindowObj() is { } aw)
        {
            aw.Lines.Clear();
            aw.ScrollOffset = 0;
            aw.CursorLine = 0;
            aw.CursorCol = 0;
            RenderTuiWindows();
            return;
        }
        var resolved = ResolveClsColorArg(color);
        var g = Current.Graphics;
        bool gfx;
        try { gfx = g.IsAvailable; } catch { gfx = false; }
        if (gfx) { g.Clear(resolved); return; }
        if (resolved is { } idx && idx is >= 0 and <= 255) Current.Console.SetBackgroundColor(idx);
        Current.Console.Clear();
    }

    /// <summary>Converte l'argomento RAW di CLS (indice palette numerico, o array [r,g,b]/
    /// [r,g,b,a] da RGB()) in un int per ClsInternal: indici di palette passano invariati,
    /// gli array vengono marcati col flag 0x40000000 (0x00RRGGBB) — stessa convenzione già
    /// usata da GfxResolveColor/ResolveNumericColor per COLOR e i comandi grafici della
    /// finestra pixel.</summary>
    private static int? ResolveClsColorArg(object? color)
    {
        switch (color)
        {
            case null: return null;
            case double d: return (int)d;
            case int i: return i;
            case long l: return (int)l;
            case System.Collections.IEnumerable en:
            {
                var vals = new double[4];
                var k = 0;
                foreach (var it in en) { if (k >= 4) break; vals[k++] = Convert.ToDouble(it); }
                if (k == 0) return null;
                var r = (int)Math.Clamp(vals[0], 0, 255);
                var g2 = (int)Math.Clamp(vals[1], 0, 255);
                var b = (int)Math.Clamp(vals[2], 0, 255);
                return 0x40000000 | (r << 16) | (g2 << 8) | b;
            }
            default: return null;
        }
    }

    public static void LocateDispatch(int col, int line)
    {
        // Finestra attiva → posiziona il cursore nel buffer (riga/colonna relativi alla viewport).
        if (ActivePixelWindow() is { } pw)
        {
            var cr = pw.ClientRect;
            pw.CursorCol = Math.Max(0, col - 1);
            var targetLine = Math.Max(0, line - 1);
            if (pw.Lines.Count == 0) pw.Lines.Add("");
            pw.CursorLine = Math.Min(targetLine, pw.Lines.Count - 1);
            if (pw.CursorLine < pw.ScrollOffset) pw.ScrollOffset = pw.CursorLine;
            var rows = Math.Max(1, cr.h / Math.Max(1, CommonGraphics.Graphics.GfxWindowManager.CharHeight()));
            if (pw.CursorLine >= pw.ScrollOffset + rows) pw.ScrollOffset = pw.CursorLine - rows + 1;
            RenderPixelWindows();
            return;
        }
        if (ActiveWindowObj() is { } aw)
        {
            var cr = aw.ContentRect;
            aw.CursorCol = Math.Max(0, col - 1);
            var targetLine = Math.Max(0, line - 1);
            if (aw.Lines.Count == 0) aw.Lines.Add("");
            aw.CursorLine = Math.Min(targetLine, aw.Lines.Count - 1);
            if (aw.CursorLine < aw.ScrollOffset) aw.ScrollOffset = aw.CursorLine;
            if (aw.CursorLine >= aw.ScrollOffset + Math.Max(1, cr.H)) aw.ScrollOffset = aw.CursorLine - Math.Max(1, cr.H) + 1;
            RenderTuiWindows();
            return;
        }
        var g = Current.Graphics;
        bool gfx;
        try { gfx = g.IsAvailable; } catch { gfx = false; }
        if (gfx) g.Locate(col, line);
        else Current.Console.SetCursorPosition(col - 1, line - 1);
    }
    /// <summary>COLOR con schermo grafico attivo → IGraphicsService.Color (indice palette per
    /// numerici, colore RGB completo per RGBA); altrimenti console (indici). Con finestra
    /// attiva è no-op: il buffer della finestra segue il tema (nessun reset console).</summary>
    public static void ColorDispatch(object? fg, object? bg)
    {
        // RGBA come UDT (Dictionary Red/Green/Blue/Alpha): converti nel formato colore
        // grafico 0x40000000|RGB PRIMA del dispatch (prima arrivava il Dictionary grezzo
        // a ToColorIndex → "cast Dictionary to IConvertible"). Numerici e double[] passano
        // come prima (indice palette / conversione nel servizio).
        fg = NormalizeColorArg(fg);
        bg = NormalizeColorArg(bg);
        // Finestra pixel attiva: COLOR fg,bg imposta testo/titolo (fg) e sfondo (bg) della
        // finestra (polimorfismo, come PRINT/LOCATE/CLS). fg/bg = indice palette o ARGB.
        if (ActivePixelWindow() is { } pw)
        {
            try
            {
                var gm2 = CommonGraphics.Graphics.GraphicsManager.Instance;
                if (fg != null) pw.FgColor = pw.TitleColor = gm2.GfxResolveColor(fg, pw.FgColor);
                if (bg != null) pw.BodyColor = gm2.GfxResolveColor(bg, pw.BodyColor);
                RenderPixelWindows();
            }
            catch { }
            return;
        }
        // Finestra attiva: il colore del buffer segue il tema della finestra — niente da fare.
        if (ActiveWindowObj() is not null) return;
        var g = Current.Graphics;
        bool gfx;
        try { gfx = g.IsAvailable; } catch { gfx = false; }
        if (gfx) { g.Color(fg, bg); return; }
        if (fg == null && bg == null) Current.Console.ResetColor();
        if (fg != null) Current.Console.SetForegroundColor((int)System.Convert.ToDouble(fg));
        if (bg != null) Current.Console.SetBackgroundColor((int)System.Convert.ToDouble(bg));
    }
    /// <summary>Normalizza un argomento colore per il dispatch: le UDT RGBA (Dictionary
    /// Red/Green/Blue/Alpha) diventano 0x40000000|RGB; numerici/double[] restano invariati.</summary>
    private static object? NormalizeColorArg(object? v)
    {
        if (v is null || v is double || v is int || v is long || v is float) return v;
        if (v is System.Collections.IDictionary) return RgbaToLineColor(v);
        return v;
    }

    private static string PrintFormatValueCore(object? value) => value switch
    {
        null => "",
        string s => s,
        double d => PrintFormatDouble(d),
        float f => (f >= 0.0f ? " " : "") + f.ToString("G9", System.Globalization.CultureInfo.InvariantCulture) + " ",
        bool b => b ? "-1 " : " 0 ",
        // Parità 4 backend: gli altri backend (PCode/VM-C/C99Native) rappresentano ogni numero come
        // double e lo stampano con G15 → un intero grande diventa scientifico (es. 1.7E+15).
        // IL, che ha un vero int64, stampava le cifre piene: allineato al formato double per
        // non divergere (stesso valore, stessa stringa).
        int i => PrintFormatDouble(i),
        long l => PrintFormatDouble(l),
        short s2 => PrintFormatDouble(s2),
        byte by => PrintFormatDouble(by),
        decimal dec => (dec >= 0.0m ? " " : "") + dec.ToString("G", System.Globalization.CultureInfo.InvariantCulture) + " ",
        System.Collections.IEnumerable en => "[" + string.Join(", ", en.Cast<object?>().Select(JsonValueToString)) + "]",
        // DATA/ORA: "dd/MM/yyyy HH:mm:ss" SENZA lo spazio finale del caso generico.
        // Le gambe C (gmb_dt_datetime_to_string) e la PCodeVM non aggiungono padding; prima
        // l'IL era l'unico a stampare "01/11/2026 18:43:38 " (divergenza trovata sul sample
        // Http/HttpRoutes.bas, che logga NOW()). Formato esplicito = indipendente dalla cultura.
        DateTime dt => dt.ToString("dd/MM/yyyy HH:mm:ss", System.Globalization.CultureInfo.InvariantCulture),
        _ => (value?.ToString() ?? "") + " "
    };
    private static string PrintFormatDouble(double d)
        => d == 0.0 ? " 0 " : (d >= 0.0 ? " " : "") + d.ToString("G15", System.Globalization.CultureInfo.InvariantCulture) + " ";

