    // --- Categoria 6: PORTFOLIO (ottimizzazioni -> CommonLib -> dict campi BASIC) ---
    private static double[,] ToMatrix(double[][] jagged)
    {
        if (jagged == null || jagged.Length == 0) return new double[0, 0];
        int cols = 0;
        foreach (var r in jagged) if (r != null) cols = Math.Max(cols, r.Length);
        var m = new double[jagged.Length, cols];
        for (int i = 0; i < jagged.Length; i++)
            if (jagged[i] != null)
                for (int j = 0; j < jagged[i].Length; j++) m[i, j] = jagged[i][j];
        return m;
    }

    private static Dictionary<string, object?> PortfolioResultDict(CommonLib.Trading.PortfolioResult r) => new()
    {
        ["ExpectedReturn"] = r.Return,
        ["Volatility"] = r.StDev,
        ["SharpeRatio"] = r.SharpeRatio,
        ["Weights"] = r.Weights
    };

    public static Dictionary<string, object?>? MaxSharpe(double[] returns, double[][] cov, double rf)
    {
        // Solver closed-form (parità VM/C gmb_port_max_sharpe): w = inv(cov)·(rets−rf),
        // normalizzato a somma 1. Il solver QLNet lanciava su input a 3 asset → null.
        return MaxSharpeDict(returns, cov, rf);
    }
    public static Dictionary<string, object?>? MinVolatility(double[][] cov)
    {
        var m = ToMatrix(cov);
        return PortfolioResultDict(CommonLib.Trading.Portfolio.OptimizeMeanVariance(new double[m.GetLength(0)], m, "MINVOLATILITY", 0, null));
    }

    /// <summary>Weights MAXSHARPE: w = inv(cov)·(rets−rf), normalizzato a somma 1
    /// (stessa formula di gmb_port_max_sharpe in gmb_math.c).</summary>
    private static Dictionary<string, object?> MaxSharpeDict(double[] rets, double[][] cov, double rf)
    {
        int n = rets.Length;
        if (n == 0 || cov.Length < n) return null;
        var inv = InvertMatrix(cov, n);
        var w = new double[n];
        if (inv != null)
        {
            double sum = 0;
            for (int i = 0; i < n; i++) { double row = 0; for (int j = 0; j < n; j++) row += inv[i][j] * (rets[j] - rf); w[i] = row; sum += row; }
            if (sum != 0) for (int i = 0; i < n; i++) w[i] /= sum;
            else for (int i = 0; i < n; i++) w[i] = 1.0 / n;
        }
        else for (int i = 0; i < n; i++) w[i] = 1.0 / n;
        double pr = 0; for (int i = 0; i < n; i++) pr += w[i] * rets[i];
        double pv = 0; for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) pv += w[i] * cov[i][j] * w[j];
        double sd = pv > 0 ? Math.Sqrt(pv) : 0;
        double sh = sd > 0 ? (pr - rf) / sd : 0;
        return new Dictionary<string, object?> { { "Weights", w }, { "ExpectedReturn", pr }, { "Volatility", sd }, { "SharpeRatio", sh } };
    }

    /// <summary>Inversa di una matrice n×n (Gauss-Jordan), null se singolare.</summary>
    private static double[][]? InvertMatrix(double[][] a, int n)
    {
        var m = new double[n][];
        for (int i = 0; i < n; i++) { m[i] = new double[2 * n]; for (int j = 0; j < n; j++) m[i][j] = a[i][j]; m[i][n + i] = 1.0; }
        for (int col = 0; col < n; col++)
        {
            int piv = col;
            for (int r = col + 1; r < n; r++) if (Math.Abs(m[r][col]) > Math.Abs(m[piv][col])) piv = r;
            if (Math.Abs(m[piv][col]) < 1e-15) return null;
            (m[col], m[piv]) = (m[piv], m[col]);
            double d = m[col][col];
            for (int j = 0; j < 2 * n; j++) m[col][j] /= d;
            for (int r = 0; r < n; r++) if (r != col)
            {
                double f = m[r][col];
                for (int j = 0; j < 2 * n; j++) m[r][j] -= f * m[col][j];
            }
        }
        var inv = new double[n][];
        for (int i = 0; i < n; i++) { inv[i] = new double[n]; for (int j = 0; j < n; j++) inv[i][j] = m[i][n + j]; }
        return inv;
    }

    public static Dictionary<string, object?>? MeanVariance(double[] returns, double[][] cov)
    {
        // Parità VM/C: kind 4 (mean_variance) usa lo stesso solver con rf=0.
        return MaxSharpeDict(returns, cov, 0);
    }

