    /// <summary>RGB(r,g,b,a) → RgbaColor (campi nominati, canone StdLib RgbaColorType):
    /// {Red, Green, Blue, Alpha}. Stessa rappresentazione di VM/C (gmb_rgb) e C99.</summary>
    public static System.Collections.Generic.Dictionary<string, object?> Rgb(double r, double g, double b, double a)
        => new System.Collections.Generic.Dictionary<string, object?>
        {
            ["Red"] = Math.Clamp(r, 0, 255), ["Green"] = Math.Clamp(g, 0, 255),
            ["Blue"] = Math.Clamp(b, 0, 255), ["Alpha"] = Math.Clamp(a, 0, 255)
        };

    /// <summary>Converte un array RGBA (double[4]: [r,g,b,a]) nel colore int 0xRRGGBBAA
    /// usato da GraphicsManager (r<<24 | g<<16 | b<<8 | a). Per contesti che si aspettano
    /// un int colore (COLOR/PSET con un argomento RGBA).</summary>
    /// <summary>Componenti RGBA da un RgbaColor dict ({Red,Green,Blue,Alpha}) o, in fallback,
    /// da una sequenza numerica [r,g,b,a]. Default Alpha=255.</summary>
    private static double[] RgbaComponents(object? rgba)
    {
        var v = new double[4] { 0, 0, 0, 255 };
        if (rgba is System.Collections.IDictionary d)
        {
            double Cv(object? o) => o is null ? 0.0 : Convert.ToDouble(o);
            v[0] = Cv(d.Contains("Red") ? d["Red"] : null);
            v[1] = Cv(d.Contains("Green") ? d["Green"] : null);
            v[2] = Cv(d.Contains("Blue") ? d["Blue"] : null);
            v[3] = d.Contains("Alpha") ? Cv(d["Alpha"]) : 255.0;
            return v;
        }
        if (rgba is System.Collections.IEnumerable en)
        {
            int i = 0;
            foreach (var item in en) { if (i >= 4) break; v[i++] = Convert.ToDouble(item); }
        }
        return v;
    }

    public static int RgbaToColorInt(object? rgba)
    {
        var v = RgbaComponents(rgba);
        return ((int)Math.Clamp(v[0], 0, 255) << 24)
             | ((int)Math.Clamp(v[1], 0, 255) << 16)
             | ((int)Math.Clamp(v[2], 0, 255) << 8)
             | (int)Math.Clamp(v[3], 0, 255);
    }

    /// <summary>Colore RGBA per LINE/riempimento: 0x40000000 | (R<<16)|(G<<8)|B — formato
    /// letto da GraphicsManager.GetColor (flag separato dai byte colore, a differenza di
    /// RgbaToColorInt che usa 0xRRGGBBAA per altri usi).</summary>
    public static int RgbaToLineColor(object? rgba)
    {
        var v = RgbaComponents(rgba);
        return 0x40000000
             | ((int)Math.Clamp(v[0], 0, 255) << 16)
             | ((int)Math.Clamp(v[1], 0, 255) << 8)
             | (int)Math.Clamp(v[2], 0, 255);
    }

    /// <summary>Conversione generica object → stringa (per CPrint/PRINT grafico).</summary>
    public static string ObjToStr(object? value) => value?.ToString() ?? "";

    /// <summary>Legge un array nativo BASIC (double[]/int[]/IEnumerable) in double[].</summary>
    public static double[] ReadDoubleArray(object? arr)
    {
        switch (arr)
        {
            case double[] da: return da;
            case int[] ia: return Array.ConvertAll(ia, v => (double)v);
            case System.Collections.IEnumerable en:
                var list = new System.Collections.Generic.List<double>();
                foreach (var item in en)
                {
                    if (item is double d) list.Add(d);
                    else if (item is int i) list.Add(i);
                    else list.Add(Convert.ToDouble(item));
                }
                return list.ToArray();
            default: return Array.Empty<double>();
        }
    }

    /// <summary>Legge un array nativo BASIC (double[]/int[]) e lo converte in int[].</summary>
    public static int[] ReadIntArray(object? arr)
    {
        var result = new System.Collections.Generic.List<int>();
        switch (arr)
        {
            case int[] ia: return ia;
            case double[] da: foreach (var v in da) result.Add((int)v); break;
            case System.Collections.IEnumerable en:
                foreach (var item in en)
                {
                    if (item is double d) result.Add((int)d);
                    else if (item is int i) result.Add(i);
                    else result.Add(0);
                }
                break;
        }
        return result.ToArray();
    }

    /// <summary>Copia gli id texture (int[]) negli slot di un array BASIC già allocato
    /// (long[]/int[]/double[]/short[]). Usato da LOAD TEXTURE … CELL INTO arr.</summary>
    public static void CopyIntIdsIntoArray(object? dest, object? ids)
    {
        if (dest is not Array da || ids is not int[] src || da.Length == 0 || src.Length == 0)
            return;
        var n = Math.Min(da.Length, src.Length);
        var et = da.GetType().GetElementType();
        for (var i = 0; i < n; i++)
        {
            var id = src[i];
            if (et == typeof(double)) da.SetValue((double)id, i);
            else if (et == typeof(long)) da.SetValue((long)id, i);
            else if (et == typeof(short)) da.SetValue((short)id, i);
            else if (et == typeof(int)) da.SetValue(id, i);
            else da.SetValue(id, i);
        }
    }

