    public static void MatrixSetTransformMatrix(long matrixId) { _ = matrixId; }

    /// <summary>TaskYield() — AWAIT TaskYield(): cede al cooperatore. IL sincrono → no-op.</summary>
    public static void TaskYield() { }

    /// <summary>Legge un elemento di tupla (object[] da FUNCTION AS (...)) per indice.</summary>
    public static object? TupleElement(object tuple, double index)
    {
        if (tuple is not System.Collections.IEnumerable en) return null;
        var i = 0;
        foreach (var item in en)
        {
            if (i == (int)index) return item;
            i++;
        }
        return null;
    }

    /// <summary>Slice di un array: arr[start..end] inclusivo (end = -1 → fino alla fine).
    /// Ritorna una COPIA (il P-Code ARRAY_SLICE restituisce un nuovo array).</summary>
    public static double[] ArraySlice(double[] arr, int start, int end)
    {
        if (arr is null) return Array.Empty<double>();
        if (start < 0) start = 0;
        if (start >= arr.Length) return Array.Empty<double>();
        // Semantica canonica (ArraysDim.bas §3): start INCLUSIVO, end ESCLUSIVO.
        var stop = end < 0 ? arr.Length : Math.Min(end, arr.Length);
        if (stop <= start) return Array.Empty<double>();
        var result = new double[stop - start];
        Array.Copy(arr, start, result, 0, result.Length);
        return result;
    }

    /// <summary>Slice di una LISTA — `arr[a:b]` quando il valore base è una List&lt;T&gt; e non
    /// un double[]: nuovo List&lt;T&gt; con gli elementi [start, end) (start inclusivo, end
    /// esclusivo — semantica canonica di ArraysDim.bas §3); la sorgente resta invariata.
    /// Stessa semantica di <see cref="ArraySlice"/> (parità PCodeVM/VM-C).</summary>
    public static List<T> ArraySliceList<T>(List<T> src, int start, int end)
    {
        var result = new List<T>();
        if (src is null) return result;
        if (start < 0) start = 0;
        if (start >= src.Count) return result;
        var stop = end < 0 ? src.Count : Math.Min(end, src.Count);
        if (stop <= start) return result;
        result.Capacity = stop - start;
        for (var i = start; i < stop; i++) result.Add(src[i]);
        return result;
    }

    /// <summary>DIRECTCAST(expr, Type): estrae un valore boxed. "STRING" → stringa;
    /// altrimenti restituisce l'oggetto così com'è (cast reference).</summary>
    public static object? DirectCast(object? value, string typeName)
    {
        if (typeName == "STRING") return value is string s ? s : value?.ToString() ?? "";
        return value;
    }

