    // --- ON SPRITE COLLISION(S) ---
    // Capture sul main (callback SYNC); dispatch nel worker. Gli handler sono Proc_*
    // non-park: Invoke dal worker è lecito (gmo hijacka l'IP del task).
    private static Action<double, double>? _spriteCollisionSingular;
    private static Action<object>? _spriteCollisionPlural;
    private static SpriteCollisionHit[] _pendingSpriteCollisions = [];
    // Thread-safe: le variabili GLOBAL possono essere scritte da thread in background
    // (callback WebSocket/HTTP, receive loop) e lette dal thread principale in un loop di
    // attesa (DO WHILE NOT flag ... LOOP). Un Dictionary semplice NON garantisce la
    // visibilità tra thread (il loop poteva non vedere mai la scrittura — bug ricorrente).
    private static readonly System.Collections.Concurrent.ConcurrentDictionary<int, object?> ProgramGlobals = new();

    /// <summary>
    /// Azzera bag GLOBAL e handler sprite del programma IL appena caricato.
    /// Evita che un run precedente (stesso processo, altro .dll LoadFile) lasci stato.
    /// </summary>
    public static void ResetProgramState()
    {
        ProgramExitCode = 0;
        ProgramGlobals.Clear();
        DynamicScopeGlobals.Clear();
        DynamicVarReset();
        ResetStaticState();
        // Stato HTTP dichiarativo del programma precedente (route/middleware/WS/static +
        // eventuale listener ancora vivo): senza, i run successivi nello stesso processo si
        // contaminano (bug MiniTest-HTTP-Server-Stesso-Processo).
        HttpDeclarationReset();
        _spriteCollisionSingular = null;
        _spriteCollisionPlural = null;
        _pendingSpriteCollisions = [];
        AbortRequested = false;
        _tuiWindows = null;
        _gfxWindows = null;
        _windowSnapshots.Clear();
        _pixelWindowSnapshots.Clear();
        // GPM: pulizia del poller condiviso — i sample TIMEOUT/abbandonati in un harness a
        // processo condiviso lasciano scheduler stantii che il poller continuerebbe a svegliare
        // (contaminazione cross-sample). Chiamato a ogni reset (per-sample nello sweep).
        Basic.IlBackend.Gpm.IlGpmV2Driver.ResetSharedPoller();
        lock (InkeyQueueLock)
        {
            InkeyQueue.Clear();
        }
    }

    /// <summary>Legge una variabile GLOBAL condivisa tra stepper Main e Proc_* degli handler.</summary>
    /// <param name="symbolId">Id del simbolo GLOBAL nella SymbolTable.</param>
    /// <returns>Valore boxed, o null se mai scritto.</returns>
    public static object? LoadGlobal(int symbolId)
        => ActiveGlobals.TryGetValue(symbolId, out var value) ? value : null;

    /// <summary>Scrive una variabile GLOBAL condivisa tra stepper Main e Proc_* degli handler.</summary>
    /// <param name="symbolId">Id del simbolo GLOBAL nella SymbolTable.</param>
    /// <param name="value">Valore boxed da memorizzare.</param>
    public static void StoreGlobal(int symbolId, object? value) => ActiveGlobals[symbolId] = value;

    /// <summary>Restituisce il box (object) del global <paramref name="symbolId"/>, creandolo
    /// dal <paramref name="defaultValue"/> boxed se assente. Serve a prendere l'INDIRIZZO di un
    /// UDT globale (value type boxed) con una sequenza IL SENZA label — la versione con
    /// Brtrue/Brfalse definiva label che il GPM v2 stepper (splitting del corpo in stati) non
    /// riusciva a marcare ("Label N has not been marked").</summary>
    public static object GetOrCreateGlobalBox(int symbolId, object defaultValue)
    {
        if (ActiveGlobals.TryGetValue(symbolId, out var existing) && existing is not null) return existing;
        ActiveGlobals[symbolId] = defaultValue;
        return defaultValue;
    }

    /// <summary>Scope globale isolato per un'esecuzione ANNIdata in-process (una pagina BSP che
    /// gira DENTRO il server): la pagina ha una SymbolTable propria con symbolId che si
    /// sovrappongono a quelli del programma ospite — senza isolamento, il seed `REQ` della
    /// pagina sovrascriveva `pkgs` del server allo stesso symbolId (SendJSON riceveva un
    /// Dictionary invece della List → "Handler Error"). Lo scope è per-THREAD: mentre la pagina
    /// legge/scrive i propri globali nello scope, gli handler HTTP del server (altri thread)
    /// continuano a leggere la bag condivisa <see cref="ProgramGlobals"/>.</summary>
    [ThreadStatic] private static System.Collections.Concurrent.ConcurrentDictionary<int, object?>? _activeGlobalScope;
    // Pila degli scope ANNIDATI sul thread corrente: una pagina BSP (BeginGlobalScope) gira
    // DENTRO il thread del server, il cui Main() ha già aperto il PROPRIO scope (vedi
    // BeginProgramScope). EndGlobalScope deve ripristinare lo scope ESTERNO (quello del
    // server), non azzerarlo a null — altrimenti, dopo la prima pagina servita, il server
    // "perde" i propri globali (ricade su ProgramGlobals, ormai vuoto/estraneo).
    [ThreadStatic] private static Stack<System.Collections.Concurrent.ConcurrentDictionary<int, object?>>? _globalScopeStack;

    public static void BeginGlobalScope(System.Collections.Concurrent.ConcurrentDictionary<int, object?> scope)
    {
        (_globalScopeStack ??= new()).Push(scope);
        _activeGlobalScope = scope;
    }

    public static void EndGlobalScope()
    {
        var stack = _globalScopeStack;
        if (stack is { Count: > 0 }) stack.Pop();
        _activeGlobalScope = stack is { Count: > 0 } ? stack.Peek() : null;
    }

    /// <summary>Scope attivo sul thread CORRENTE (null se nessuno) — letto dal coordinatore
    /// GPM v2 prima di avviare i worker thread, per propagarlo (vedi <see cref="BeginGlobalScope"/>
    /// sopra): i worker sono Thread NUOVI, il ThreadStatic non li eredita da solo.</summary>
    public static System.Collections.Concurrent.ConcurrentDictionary<int, object?>? CurrentGlobalScope => _activeGlobalScope;

    /// <summary>Apre uno scope globale isolato per QUESTA esecuzione di programma (chiamato
    /// dal prologo di ogni entry point compilato, prima di Proc_&lt;Main&gt;/RunV2Entry): senza
    /// questo, due programmi compilati diversi in esecuzione CONTEMPORANEA nello stesso processo
    /// (es. più test xUnit/harness che compilano ed eseguono sample IL diversi in parallelo, o
    /// anche lo stesso sample più volte) condividerebbero l'unico <see cref="ProgramGlobals"/>
    /// statico — il ResetProgramState() di uno svuota i globali impliciti dell'altro a metà
    /// esecuzione (sintomo: LinAlgMatrixHandle(null) su una variabile globale scritta poco
    /// prima, letta null perché nel frattempo un altro Main() concorrente ha fatto reset).
    /// Ogni esecuzione riparte da un dictionary VUOTO proprio, mai condiviso.
    /// <see cref="ProgramGlobalScope"/> (cross-thread) espone lo stesso scope ai thread di rete
    /// (HttpService/pool) così gli handler HTTP/WS/middleware/BSP leggono i globali del programma.</summary>
    public static void BeginProgramScope()
    {
        var scope = new System.Collections.Concurrent.ConcurrentDictionary<int, object?>();
        BeginGlobalScope(scope);
        _programGlobalScope = scope;
    }

    /// <summary>Scope globale del programma CORRENTE (ultimo BeginProgramScope) — cross-thread:
    /// i dispatch degli handler HTTP/WS dal thread di rete lo applicano sul proprio thread
    /// (BeginGlobalScope/EndGlobalScope) per leggere i globali top-level del programma.</summary>
    private static System.Collections.Concurrent.ConcurrentDictionary<int, object?>? _programGlobalScope;
    public static System.Collections.Concurrent.ConcurrentDictionary<int, object?>? ProgramGlobalScope => _programGlobalScope;

    private static System.Collections.Concurrent.ConcurrentDictionary<int, object?> ActiveGlobals =>
        _activeGlobalScope ?? ProgramGlobals;

    // ── DYNAMIC SCOPE (variabili NON dichiarate per NOME, es. i globali keyword delle pagine
    // BSP: FORM/QUERY sono TokenKind.Form/SqlQuery, non dichiarabili con DIM) ─────────────
    // Il linker assegna loro DynamicScopeSymbolId (-3); l'accesso a indice (FORM("x"),
    // QUERY["name"]) risolve il valore qui per NOME. Iniettato dall'host (ServeBspPage) come
    // i globali tipizzati; azzerato da ResetProgramState.
    private static readonly System.Collections.Concurrent.ConcurrentDictionary<string, object?> DynamicScopeGlobals = new(StringComparer.OrdinalIgnoreCase);

    public static object? DynamicScopeGet(string name)
        => DynamicScopeGlobals.TryGetValue(name, out var v) ? v : null;

    public static void DynamicScopeSet(string name, object? value) => DynamicScopeGlobals[name] = value;

    /// <summary>QUERY["key"] / FORM["key"] (chiave STRINGA) su un globale dynamic-scope per NOME.</summary>
    public static object? DynamicScopeIndexGet(string name, string key)
        => JsonFieldGet(DynamicScopeGet(name), key);

    /// <summary>QUERY(i) / FORM(i) (indice NUMERICO) su un globale dynamic-scope per NOME.</summary>
    public static object? DynamicScopeIndexGetNum(string name, int index)
        => JsonIndexGet(DynamicScopeGet(name), index);

    /// <summary>Scrittura a indice su un globale dynamic-scope per NOME (FORM("x") = y).</summary>
    public static void DynamicScopeIndexSet(string name, object? key, object? value)
        => CollectionIndexSet(DynamicScopeGet(name), key, value);

    // ── DYNAMIC SCOPE STACK — variabili DYNAMIC dichiarate dall'utente (per NOME) ──────
    // A differenza di DynamicScopeGlobals (dict PIATTO per i globali keyword delle pagine
    // BSP, iniettati dall'host), qui c'è una PILA di frame, uno per ogni ingresso di
    // procedura che DICHIARA una DYNAMIC (spec VARIABLES §2.5). La ricerca è top-down
    // (shadowing): una lettura ritorna il valore del frame più interno che definisce il
    // nome; una scrittura colpisce quel frame. Il frame base (indice 0) esiste sempre ed è
    // dove finiscono le DYNAMIC dichiarate a livello modulo/Main. Per-thread: rispecchia il
    // modello TLS usato dal runtime C condiviso (gmb_dscope).
    [ThreadStatic] private static List<Dictionary<string, object?>>? _dynVarFrames;

    private static List<Dictionary<string, object?>> DynVarFrames
        => _dynVarFrames ??= new List<Dictionary<string, object?>> { new(StringComparer.OrdinalIgnoreCase) };

    /// <summary>Entra in un nuovo frame (a ogni chiamata di una procedura che dichiara DYNAMIC).</summary>
    public static void DynamicVarPush()
        => DynVarFrames.Add(new Dictionary<string, object?>(StringComparer.OrdinalIgnoreCase));

    /// <summary>Esce dal frame corrente (a ogni uscita della procedura che l'ha aperto).</summary>
    public static void DynamicVarPop()
    {
        var frames = DynVarFrames;
        if (frames.Count > 1) frames.RemoveAt(frames.Count - 1);
    }

    /// <summary>Azzera la pila (nuovo programma nello stesso processo).</summary>
    public static void DynamicVarReset() => _dynVarFrames = null;

    /// <summary>Dichiara una DYNAMIC nel frame corrente (endure lo shadowing di un omonimo esterno).</summary>
    public static void DynamicVarDeclare(string name, object? value)
        => DynVarFrames[^1][name] = value;

    /// <summary>Legge una DYNAMIC: cerca dal frame più interno verso l'esterno (shadowing).</summary>
    public static object? DynamicVarGet(string name)
    {
        var frames = DynVarFrames;
        for (var i = frames.Count - 1; i >= 0; i--)
            if (frames[i].TryGetValue(name, out var value)) return value;
        return null;
    }

    /// <summary>Lettura STRINGA (coercizione permissiva, parità C99 gmb_dscope_get_string).</summary>
    public static string DynamicVarGetString(string name) => DynamicVarGet(name) as string ?? string.Empty;

    /// <summary>Lettura NUMERICA (coercizione permissiva, parità C99 gmb_dscope_get_double).</summary>
    public static double DynamicVarGetDouble(string name)
    {
        var value = DynamicVarGet(name);
        return value switch
        {
            null => 0d,
            double d => d,
            string s => double.TryParse(s, System.Globalization.NumberStyles.Any,
                System.Globalization.CultureInfo.InvariantCulture, out var parsed) ? parsed : 0d,
            _ => Convert.ToDouble(value, System.Globalization.CultureInfo.InvariantCulture),
        };
    }

    /// <summary>Scrive una DYNAMIC: colpisce il frame più interno che la definisce; se nessuno
    /// la definisce, la dichiara nel frame corrente.</summary>
    public static void DynamicVarSet(string name, object? value)
    {
        var frames = DynVarFrames;
        for (var i = frames.Count - 1; i >= 0; i--)
            if (frames[i].ContainsKey(name))
            {
                frames[i][name] = value;
                return;
            }
        frames[^1][name] = value;
    }

    // ── STATIC (persistenza tra chiamate, spec VARIABLES #3) ─────────
    // Le variabili STATIC mantengono il valore tra chiamate successive della procedura.
    // Stesso modello del bag GLOBAL (LoadGlobal/StoreGlobal), ma con inizializzazione
    // UNA-SOLTA-VOLTA alla prima chiamata (StaticInitOnce).
    private static readonly Dictionary<int, object?> ProgramStatics = new();
    private static readonly HashSet<int> StaticInitialized = new();

    /// <summary>Crea un array MULTIDIM JAGGED (T[][], T[][][]...) di <paramref name="rank"/>
    /// dimensioni con le lunghezze date. Ogni sotto-array è ISTANZIATO FRESH (mai aliasato):
    /// indispensabile per elementi struct/UDT (mutazioni indipendenti per slot). Usato per
    /// gli array multi-dim con elemento TypeBuilder (CLASS/UDT), dove `newobj` sul costruttore
    /// rettangolare non è risolvibile in Reflection.Emit. La struttura jagged è quella già
    /// gestita da EmitLoadArrayRefAndIndices (ldelem.ref sugli assi intermedi).
    public static Array MakeJagged(Type elementType, int[] lengths) => MakeJaggedAt(elementType, lengths, 0);

    private static Array MakeJaggedAt(Type elementType, int[] lengths, int dim)
    {
        var len = lengths[dim] < 0 ? 0 : lengths[dim];
        if (dim == lengths.Length - 1)
            return Array.CreateInstance(elementType, len);
        var sub = elementType;
        for (var k = 0; k < lengths.Length - 1 - dim; k++) sub = sub.MakeArrayType();
        var outer = Array.CreateInstance(sub, len);
        for (var i = 0; i < outer.Length; i++)
            outer.SetValue(MakeJaggedAt(elementType, lengths, dim + 1), i);
        return outer;
    }

    public static object? LoadStatic(int symbolId)
        => ProgramStatics.TryGetValue(symbolId, out var value) ? value : null;

    public static void StoreStatic(int symbolId, object? value)
    {
        lock (ProgramStatics) ProgramStatics[symbolId] = value;
    }

    /// <summary>Inizializza una variabile STATIC alla PRIMA chiamata (le successive ignorano il valore).</summary>
    public static void StaticInitOnce(int symbolId, object? value)
    {
        lock (StaticInitialized)
        {
            if (!StaticInitialized.Contains(symbolId))
            {
                StaticInitialized.Add(symbolId);
                lock (ProgramStatics) ProgramStatics[symbolId] = value;
            }
        }
    }

    public static void ResetStaticState()
    {
        lock (StaticInitialized) { StaticInitialized.Clear(); }
        lock (ProgramStatics) { ProgramStatics.Clear(); }
    }

    public static void RegisterSpriteCollision(string handlerName, int plural)
    {
        _ = handlerName;
        _ = plural;
    }

    public static void RegisterSpriteCollisionSingular(Action<double, double>? handler)
        => _spriteCollisionSingular = handler;

    public static void RegisterSpriteCollisionPlural(Action<object>? handler)
        => _spriteCollisionPlural = handler;

    /// <summary>Registra ON SPRITE COLLISION/COLLISIONS per SymbolId. Evita ldftn in emit
    /// (firma del Proc_* spesso non è Action&lt;object&gt; — JIT InvalidProgram).
    /// Cerca prima nell'assembly chiamante (GeneratedProgram caricato con LoadFile).</summary>
    public static void RegisterSpriteCollisionBySymbol(int symbolId, int plural)
    {
        var method = FindProcedureMethodIn(Assembly.GetCallingAssembly(), symbolId, paramTypes: null);
        if (method is null)
            throw new InvalidOperationException(
                $"Backend IL: Proc_{symbolId} per ON SPRITE COLLISION(S) non trovato.");
        if (plural != 0)
        {
            _spriteCollisionPlural = ids => method.Invoke(null, [CoerceHandlerArg(method, ids)]);
        }
        else
        {
            _spriteCollisionSingular = (x, y) => InvokeSingularCollision(method, x, y);
        }
    }

    private static void InvokeSingularCollision(System.Reflection.MethodInfo method, double x, double y)
    {
        var ps = method.GetParameters();
        if (ps.Length == 2)
            method.Invoke(null, [CoerceScalar(ps[0].ParameterType, x), CoerceScalar(ps[1].ParameterType, y)]);
        else
            method.Invoke(null, [x, y]);
    }

    private static object CoerceScalar(Type want, double value)
    {
        if (want == typeof(double)) return value;
        if (want == typeof(float)) return (float)value;
        if (want == typeof(int)) return (int)value;
        if (want == typeof(long)) return (long)value;
        if (want == typeof(object)) return value;
        return Convert.ChangeType(value, want);
    }

    private static object? CoerceHandlerArg(System.Reflection.MethodInfo method, object? ids)
    {
        var ps = method.GetParameters();
        if (ps.Length != 1) return ids;
        var want = ps[0].ParameterType;
        if (want.IsInstanceOfType(ids)) return ids;
        if (want == typeof(object)) return ids;
        if (ids is Array arr && want.IsArray)
        {
            var elem = want.GetElementType()!;
            var copy = Array.CreateInstance(elem, arr.Length);
            for (var i = 0; i < arr.Length; i++)
                copy.SetValue(Convert.ChangeType(arr.GetValue(i), elem), i);
            return copy;
        }
        return ids;
    }

    /// <summary>Chiamato dalla callback SYNC sul main thread: salva le hit, non dispatcha.</summary>
    public static void CaptureSpriteCollisionsFromMainThread()
        => _pendingSpriteCollisions = Current.Graphics.TakeLastCollisions();

    /// <summary>SYNC fuori dallo stepper GPM (programma IL diretto): consegna le collisioni rilevate dal SYNC
    /// precedente, esegue il SYNC e preleva quelle del frame appena presentato (stessa semantica di TrySyncPark).</summary>
    public static void SyncWithCollisions()
    {
        DispatchPendingSpriteCollisions();
        if (Current.Graphics is Basic.Runtime.CGfxGraphicsService cg) cg.SyncBarrier(); else Current.Graphics.Sync();
        CaptureSpriteCollisionsFromMainThread();
    }

    /// <summary>Chiamato nel worker all'inizio di SYNC. Gmo alterna singolare/plurale
    /// perché può hijackare un solo IP; qui gli handler sono Proc_* non-park: si invocano
    /// entrambi sullo stesso set di hit (esplosione + SPRITE OFF nello stesso ciclo).</summary>
    public static void DispatchPendingSpriteCollisions()
    {
        var hits = _pendingSpriteCollisions;
        if (hits.Length == 0) return;
        _pendingSpriteCollisions = [];
        if (_spriteCollisionSingular is not null)
        {
            var h = hits[0];
            _spriteCollisionSingular(h.X, h.Y);
        }
        if (_spriteCollisionPlural is not null)
        {
            var ids = new double[hits.Length * 2];
            var n = 0;
            var seen = new HashSet<int>();
            foreach (var hit in hits)
            {
                if (hit.Id1 >= 0 && seen.Add(hit.Id1)) ids[n++] = hit.Id1;
                if (hit.Id2 >= 0 && seen.Add(hit.Id2)) ids[n++] = hit.Id2;
            }
            Array.Resize(ref ids, n);
            _spriteCollisionPlural(ids);
        }
    }

    // --- COLLIDE / COLLIDEBATCH (sprite AABB) — delega a IGraphicsService (mai reflection:
    //     il runner inietta l'implementazione SDL; headless → NullGraphicsService). ---
    public static double SpriteCollide(int id1, int id2) => Current.Graphics.SpriteCollide(id1, id2);

    public static object[] SpriteCollideAll(int id) => Current.Graphics.SpriteCollideAll(id);

    public static object[] SpriteCollideBatch(object xArr, object yArr, object w, object h)
    {
        var xs = ReadDoubleArray(xArr);
        var ys = ReadDoubleArray(yArr);
        /* AABB diretto sugli array (parità C99/VM-C). Prima delegava al servizio
         * grafico: headless (NullGraphics) ritornava SEMPRE vuoto → divergenza
         * con PCode e gambe C. Le posizioni sentinella (>=1e5, sprite morti) sono
         * ignorate come nel runtime C. */
        int n = Math.Min(xs.Length, ys.Length);
        double halfW = Math.Max(0.0, Convert.ToDouble(w)) / 2.0;
        double halfH = Math.Max(0.0, Convert.ToDouble(h)) / 2.0;
        var res = new System.Collections.Generic.List<object>();
        for (int i = 0; i < n; i++)
        {
            double ax = xs[i], ay = ys[i];
            if (!(ax > -1e5 && ax < 1e5 && ay > -1e5 && ay < 1e5)) continue;
            for (int j = i + 1; j < n; j++)
            {
                double bx = xs[j], by = ys[j];
                if (!(bx > -1e5 && bx < 1e5 && by > -1e5 && by < 1e5)) continue;
                if (ax + halfW >= bx - halfW && ax - halfW <= bx + halfW &&
                    ay + halfH >= by - halfH && ay - halfH <= by + halfH)
                { res.Add(i); res.Add(j); }
            }
        }
        return res.ToArray();
    }

    // --- Importato da GMBasic (SYSTEM, altra cat6) ---
    public static long VarPtr(object value) => CommonLib.UdtUtils.VarPtr(value);

    /// <summary>
    ///     Nomi BASIC dei tipi UDT emessi come CLR type (`Udt_&lt;SymbolId&gt;`), registrati dal
    ///     codegen. Serve a <see cref="TypeInfo"/> per ritornare il nome utente ("Person") invece
    ///     del nome CLR interno ("UDT_544") — parità con PCode/VM-C.
    ///     Chiave = <see cref="Type.FullName"/> e NON <see cref="Type"/>: l'assembly emesso viene
    ///     salvato e ricaricato (Assembly.LoadFile), quindi l'oggetto Type a runtime è distinto
    ///     da quello restituito da CreateType() in fase di emissione.
    /// </summary>
    private static readonly System.Collections.Concurrent.ConcurrentDictionary<string, string> UdtTypeNames = new();

    /// <summary>Numero di campi per nome BASIC del UDT (es. "Person" → 3). Popolato UNA VOLTA
    /// dal codegen alla registrazione del tipo (parità con C99Native, che emettono
    /// la costante). Serve a SYSTEM.UDTPACKED: lookup O(1), nessun conteggio/reflection a runtime.</summary>
    private static readonly System.Collections.Concurrent.ConcurrentDictionary<string, int> UdtFieldCounts = new();

    public static void RegisterUdtTypeName(Type udtType, string basicName, int fieldCount = -1)
    {
        if (udtType.FullName is { } fn) UdtTypeNames[fn] = basicName;
        if (fieldCount >= 0) UdtFieldCounts[basicName] = fieldCount;
    }

    public static string TypeInfo(object value)
    {
        switch (value)
        {
            case null: return "NIL";
            case string: return "STRING";
            case bool: return "BIT";
            case double: return "DOUBLE";
            case float: return "SINGLE";
            // INTEGER?/INTEGER boxati come interi a 16/32 bit: il runtime PCode/VM-C non li
            // distingue da un DOUBLE → parità "DOUBLE" (prima "INT16"/"LONG").
            case short: return "DOUBLE";
            /* INTERI a 32/64 bit: anche il runtime PCode/VM-C/C99 li rappresenta come DOUBLE e
             * TYPEINFO deve dire la stessa cosa (2026-11-04: IL rispondeva "LONG"/"QUAD" e
             * `system_typeinfo.bas` divergeva su 4 gambe). */
            case int: return "DOUBLE";
            case long: return "DOUBLE";
            case decimal: return "CURRENCY";
            case System.DateTime: return "DATETIME";
            case System.Collections.IDictionary dict:
                if (dict.Contains("__class__") && dict["__class__"] is System.Collections.IDictionary cd &&
                    cd.Contains("Name") && cd["Name"] is string name)
                    return name;
                return "DICT";
            case System.Collections.IList list:
                return list.Count == 0 ? "LIST OF ANY" : $"LIST OF {TypeInfo(list[0]!)}";
            default:
                return value.GetType().FullName is { } fn && UdtTypeNames.TryGetValue(fn, out var udtName)
                    ? udtName
                    : value.GetType().Name.ToUpperInvariant();
        }
    }
    public static double TypeInfoHas(object value) => value != null ? 1.0 : 0.0;
    public static double UdtPacked(object? value)
    {
        // UDT dict (PCode/VM-C): il descriptor __class__ porta Name/FieldNames → registro (O(1)).
        if (value is System.Collections.IDictionary ud)
        {
            if (ud.Contains("__class__") && ud["__class__"] is System.Collections.IDictionary cd)
            {
                if (cd.Contains("Name") && cd["Name"] is string cn && UdtFieldCounts.TryGetValue(cn, out var c)) return c;
                if (cd.Contains("FieldNames") && cd["FieldNames"] is System.Collections.IDictionary fn) return fn.Count;
            }
            return ud.Count;
        }
        // UDT struct (IL): registro per FullName popolato dal codegen → O(1), niente reflection.
        if (value is not null && UdtTypeNames.TryGetValue(value.GetType().FullName ?? "", out var bn)
            && UdtFieldCounts.TryGetValue(bn, out var sc))
            return sc;
        return 0.0;
    }
    public static double UdtAligned(object value)
    {
        try
        {
            var sizes = new List<int>();
            if (value is System.Collections.IList l)
            {
                foreach (var a in l) sizes.Add((int)Convert.ToDouble(a));
            }
            else sizes.Add((int)Convert.ToDouble(value));
            return CommonLib.UdtUtils.UdtAligned(sizes.ToArray());
        }
        catch { return 1.0; }
    }
    public static string MethodInfo(string typeName, string? memberName) => TypeInfoJson(typeName, memberName, isMethod: true);
    public static string PropertyInfo(string typeName, string? memberName) => TypeInfoJson(typeName, memberName, isMethod: false);

    private static string TypeInfoJson(string typeName, string? memberName, bool isMethod)
    {
        var type = FindTypeByName(typeName);
        if (type == null) return "{}";
        if (!Basic.TypeSchemaRegistry.TryGetValue(type, out var schema) || schema == null) return "{}";
        var map = isMethod ? schema.Methods : schema.Fields;
        if (memberName != null)
        {
            if (map.TryGetValue(memberName, out var dt))
                return "{\"" + memberName + "\":\"" + dt + "\"}";
            return "{}";
        }
        var sb = new System.Text.StringBuilder("{");
        var first = true;
        foreach (var kv in map)
        {
            if (!first) sb.Append(',');
            first = false;
            sb.Append('"').Append(kv.Key).Append('"' + ':' + '"').Append(kv.Value).Append('"');
        }
        sb.Append('}');
        return sb.ToString();
    }

    private static System.Type? FindTypeByName(string typeName)
    {
        if (string.IsNullOrWhiteSpace(typeName)) return null;
        foreach (var kv in Basic.TypeSchemaRegistry.Enumerate())
            if (kv.Key.Name.Equals(typeName, StringComparison.OrdinalIgnoreCase)) return kv.Key;
        foreach (var kv in Basic.TypeSchemaRegistry.Enumerate())
            if (kv.Key.Name.Equals(typeName + "Type", StringComparison.OrdinalIgnoreCase)) return kv.Key;
        return null;
    }

    /// <summary>Conversione DateTime → OADate double (CDOW/DOW/DTOC): wrapper nel mondo
    /// IlBackend — il MethodInfo di DateTime.ToOADate risolto dal runtime .NET e usato
    /// direttamente in Reflection.Emit causava SIGSEGV al JIT.</summary>
    public static double ToOADate(DateTime value) => value.ToOADate();

    /// <summary>Conversione double OADate → DateTime (ISLEAPYEAR(anno)/DAYSINMONTH(...)):
    /// Convert.ToDateTime(double) lancia InvalidCast su .NET Core → FromOADate.</summary>
    public static DateTime FromOADate(double oa) => DateTime.FromOADate(oa);

    /// <summary>Min()/Max() su una collection boxed (Tree/Bag/...) — minimo/massimo dei valori.</summary>
    public static double CollectionMin(object? collection)
    {
        var vals = ToDoubleEnumerable(collection).ToList();
        return vals.Count > 0 ? vals.Min() : 0.0;
    }
    public static double CollectionMax(object? collection)
    {
        var vals = ToDoubleEnumerable(collection).ToList();
        return vals.Count > 0 ? vals.Max() : 0.0;
    }
    private static IEnumerable<double> ToDoubleEnumerable(object? collection)
    {
        if (collection is not System.Collections.IEnumerable en) return Array.Empty<double>();
        var outList = new List<double>();
        foreach (var item in en)
        {
            // Dictionary/KeyValuePair (Tree/AVL/Bag...): usa il VALORE della coppia.
            var effective = item;
            var itemType = item?.GetType();
            if (itemType is not null && itemType.IsGenericType
                && itemType.GetGenericTypeDefinition() == typeof(KeyValuePair<,>))
            {
                effective = itemType.GetProperty("Value")?.GetValue(item);
            }
            if (effective is System.Collections.IEnumerable sub && effective is not string)
            {
                outList.AddRange(ToDoubleEnumerable(sub));
                continue;
            }
            try { outList.Add(Convert.ToDouble(effective, System.Globalization.CultureInfo.InvariantCulture)); }
            catch { /* elementi non numerici (es. stringhe): saltati */ }
        }
        return outList;
    }

    /// <summary>UniqueCount (Bag): numero di chiavi UNICHE — come la VM (IDictionary.Count).</summary>
    /// <summary>ZIP legacy (statement): sorgenti ';'-separate o lista → CreateZip — come la VM.</summary>
    public static double ZipLegacy(object? source, object? dest)
    {
        var destPath = dest?.ToString() ?? "";
        var sources = new List<string>();
        if (source is System.Collections.IList srcList)
        { foreach (var it in srcList) if (it != null) sources.Add(it.ToString() ?? ""); }
        else if (source is string srcStr)
        { foreach (var part in srcStr.Split(';')) if (!string.IsNullOrWhiteSpace(part)) sources.Add(part.Trim()); }
        try { CommonLib.CompressionUtils.CreateZip(destPath, sources); return -1.0; }
        catch { return 0.0; }
    }

    /// <summary>UNZIP legacy (statement): ExtractZip — come la VM.</summary>
    public static double UnzipLegacy(object? archive, object? dest)
    {
        var destDir = dest?.ToString() ?? "";
        try { CommonLib.CompressionUtils.ExtractZip(archive?.ToString() ?? "", destDir); return -1.0; }
        catch { return 0.0; }
    }

    /// <summary>SafeCast (AS?): converte il valore al tipo target (double/string/bool);
    /// ritorna NIL (null) se non convertibile — come la VM (BuiltInFunction.SAFECAST).</summary>
    public static object? SafeCastValue(object? value, string targetType)
    {
        var t = targetType.ToUpperInvariant();
        if (value is null) return null;
        try
        {
            if (t is "DOUBLE") return Convert.ToDouble(value, CultureInfo.InvariantCulture);
            if (t is "SINGLE") return Convert.ToSingle(value, CultureInfo.InvariantCulture);
            if (t is "CURRENCY") return Convert.ToDecimal(value, CultureInfo.InvariantCulture);
            if (t is "INTEGER") return Convert.ToInt16(value, CultureInfo.InvariantCulture);
            if (t is "LONG") return Convert.ToInt32(value, CultureInfo.InvariantCulture);
            if (t is "QUAD") return Convert.ToInt64(value, CultureInfo.InvariantCulture);
            if (t is "BIT" or "BOOLEAN" or "BOOL")
            {
                if (value is string text && !bool.TryParse(text, out _)
                    && !double.TryParse(text, NumberStyles.Any, CultureInfo.InvariantCulture, out _))
                    return null;
                return Convert.ToBoolean(value, CultureInfo.InvariantCulture);
            }
            if (t == "STRING")
                return value is string ? value
                    : value is IConvertible ? Convert.ToString(value, CultureInfo.InvariantCulture)
                    : null;
        }
        catch (FormatException) { return null; }
        catch (InvalidCastException) { return null; }
        catch (OverflowException) { return null; }
        return null;
    }

    /// <summary>
    /// Verifica se il valore appartiene a una famiglia generica CLR senza imporre gli
    /// argomenti di tipo, come richiesto da controlli BASIC quali <c>value IS LIST</c>.
    /// </summary>
    /// <param name="value">Valore runtime da controllare; un valore null restituisce false.</param>
    /// <param name="genericTypeDefinitionName">Nome completo della definizione generica CLR aperta.</param>
    /// <returns>True se il tipo concreto del valore è un'istanza della definizione indicata.</returns>
    public static bool IsRawGenericType(object? value, string genericTypeDefinitionName)
    {
        if (value is null) return false;
        var valueType = value.GetType();
        return valueType.IsGenericType
            && valueType.GetGenericTypeDefinition().FullName == genericTypeDefinitionName;
    }

    /// <summary>
    /// Verifica se un valore dinamico BASIC rappresenta un numero o una stringa numerica.
    /// </summary>
    /// <param name="value">Valore boxed da controllare; null non è numerico.</param>
    /// <returns>True quando il valore è numerico secondo le regole di CommonLib.</returns>
    public static bool IsNumericValue(object? value) => CommonLib.Numerics.IsNumeric(value);

    /// <summary>
    /// Applica l'operatore BASIC + a due valori dinamici, concatenando quando almeno un
    /// operando è stringa e sommando numericamente negli altri casi.
    /// </summary>
    /// <param name="left">Operando sinistro boxed.</param>
    /// <param name="right">Operando destro boxed.</param>
    /// <returns>La stringa concatenata oppure il risultato numerico boxed.</returns>
    public static object DynamicAdd(object? left, object? right) =>
        left is string || right is string
            ? string.Concat(left?.ToString() ?? string.Empty, right?.ToString() ?? string.Empty)
            : ToDouble(left) + ToDouble(right);

    /// <summary>Confronto di uguaglianza dinamico con semantica NIL (parità PCodeVM/Clipper):
    /// NIL==NIL è vero; NIL==qualsiasi altro valore è falso; altrimenti confronto numerico.
    /// Ritorna -1 (vero) / 0 (falso) come i booleani BASIC.</summary>
    public static double DynamicEquals(object? left, object? right)
    {
        if (left is null || right is null)
        {
            if (left is null && right is null) return -1.0;
            // NIL = "" e' VERO (parita' PCode/VM-C: un campo JSON assente `m = c.chiave_assente` si confronta uguale alla stringa vuota);
            // NIL = qualunque altro valore (compreso 0) resta falso (golden ClipperSyntax).
            return (left ?? right) is string emptyCand && emptyCand.Length == 0 ? -1.0 : 0.0;
        }
        // Stringhe (boxed da AnyType) → confronto TESTUALE case-insensitive: prima
        // ToDouble(l)==ToDouble(r) lanciava FormatException su valori non numerici.
        if (left is string lstr || right is string rstr)
        {
            var l = left.ToString();
            var r = right.ToString();
            // Case-SENSITIVE ordinale: canone gmb_val_equals/gmb_string_equals (strcmp) e
            // PCodeVM/VM-C. Prima OrdinalIgnoreCase rendeva `campoNudo = "ALICE"`
            // case-insensitive solo su IL (divergenza sui 4 backend).
            return string.Equals(l, r, System.StringComparison.Ordinal) ? -1.0 : 0.0;
        }
        return ToDouble(left) == ToDouble(right) ? -1.0 : 0.0;
    }

    /// <summary>Confronto ORDINATO dinamico (mirror di <c>gmb_val_compare</c>, runtime C condiviso):
    /// se uno dei due operandi è una stringa → confronto ordinale (case-sensitive) del testo,
    /// altrimenti confronto numerico. Ritorna -1/0/1. Usato dai confronti relazionali
    /// (&lt; &lt;= &gt; &gt;=) fra un operando dinamico (campo nudo RDD, val boxed) e un letterale:
    /// senza, il lato dinamico veniva coercito a double accanto a una stringa →
    /// <c>call string.CompareOrdinal(double, string)</c> = InvalidProgram.</summary>
    public static int DynamicCompare(object? left, object? right)
    {
        if (left is string || right is string)
        {
            var l = left?.ToString() ?? string.Empty;
            var r = right?.ToString() ?? string.Empty;
            return Math.Sign(string.CompareOrdinal(l, r));
        }
        var ld = ToDouble(left);
        var rd = ToDouble(right);
        return ld < rd ? -1 : (ld > rd ? 1 : 0);
    }

    /// <summary>TRIM/LTRIM/RTRIM null-safe (parità VM: TRIM(null) resta null — un
    /// campo UDT non inizializzato è null, e `null <> ""` è TRUE come in VM).</summary>
    public static string? StringTrim(string? s) => s?.Trim();
    public static string? StringTrimStart(string? s) => s?.TrimStart();
    public static string? StringTrimEnd(string? s) => s?.TrimEnd();

    /// <summary>ACHUNK: divide una lista/array in blocchi di size elementi — come la VM.</summary>
    public static object?[] Chunk(object? list, object? size)
    {
        if (list is not System.Collections.IList l) return Array.Empty<object?>();
        var cs = Convert.ToInt32(size ?? 0, System.Globalization.CultureInfo.InvariantCulture);
        if (cs <= 0) return Array.Empty<object?>();
        var result = new List<object?>();
        for (var ci = 0; ci < l.Count; ci += cs)
        {
            var chunk = new List<object?>();
            for (var cj = ci; cj < ci + cs && cj < l.Count; cj++) chunk.Add(l[cj]);
            result.Add(chunk.ToArray());
        }
        return result.ToArray();
    }

    /// <summary>AZIP: coppie (a1[i], a2[i]) fino alla lunghezza minima — come la VM.</summary>
    public static object?[] ZipArrays(object? a, object? b)
    {
        if (a is not System.Collections.IList z1 || b is not System.Collections.IList z2) return Array.Empty<object?>();
        var zipLen = System.Math.Min(z1.Count, z2.Count);
        var result = new List<object?>();
        for (var zi = 0; zi < zipLen; zi++)
            result.Add(new object?[] { z1[zi], z2[zi] });
        return result.ToArray();
    }

    /// <summary>FetchResult.SaveToFile(path): salva il BodyBytes su file — come il VM
    /// (PCodeFetchResult.SaveToFile).</summary>
    public static void FetchResultSaveToFile(object? fetchResult, string path)
    {
        if (fetchResult is CommonLib.Http.FetchResult fr && fr.BodyBytes is { Length: > 0 } bytes)
            File.WriteAllBytes(path, bytes);
    }

    /// <summary>Lower bound logici associati agli array (per la propagazione ai parametri
    /// delle procedure). Condivisi per RIFERIMENTO: passare l'array a una procedura porta
    /// con sé i limiti, senza cambiare la firma dei metodi (lambde/delegate compresi).
    /// La CWT non tiene vivo l'array (chiave debole).</summary>
    private static readonly System.Runtime.CompilerServices.ConditionalWeakTable<Array, int[]> ArrayLowerTable = new();

    public static void SetArrayLowerBounds(Array? arr, int[]? lowers)
    {
        if (arr is null || lowers is null) return;
        ArrayLowerTable.AddOrUpdate(arr, lowers);
    }

    public static int GetArrayLowerBound(Array? arr, int axis)
    {
        if (arr is not null && ArrayLowerTable.TryGetValue(arr, out var l)
            && axis >= 0 && axis < l.Length)
            return l[axis];
        return 0;
    }

    /// <summary>UBOUND/LBOUND con asse scelto a runtime: <paramref name="dim"/> è 1-based,
    /// <paramref name="lowers"/> contiene i lower bound logici per asse (compile-time nel
    /// backend IL). Gestisce sia gli array rettangolari (double[,], ecc.) sia quelli JAGGED
    /// usati per gli array di UDT/CLASS (T[][]): per un asse > 0 la riga è la prima
    /// dell'array esterno. Non usa GetMethod sul tipo (fallirebbe sui TypeBuilder).</summary>
    public static long ArrayBound(Array? arr, int dim, bool upper, int[]? lowers)
    {
        if (arr is null) return upper ? -1 : 0;
        if (dim < 1) dim = 1;
        var rank = lowers?.Length ?? 1;
        if (dim > rank)
            throw new IndexOutOfRangeException("Array does not have that many dimensions.");
        var axis = dim - 1;
        var target = arr;
        if (axis > 0 && arr.Rank == 1)
        {
            if (arr.Length == 0)
                return (upper ? -1 : 0) + (lowers is not null && axis < lowers.Length ? lowers[axis] : 0);
            target = (Array)arr.GetValue(0)!;
            axis = 0;
        }
        var b = upper ? target.GetUpperBound(axis) : target.GetLowerBound(axis);
        var lo = lowers is not null && dim - 1 < lowers.Length ? lowers[dim - 1] : 0;
        return b + lo;
    }

    /// <summary>Count di una collection/array boxed (AnyType) — per UBOUND/LBOUND dinamici.</summary>
    public static double CollectionCount(object? collection)
    {
        // BAG: Count() è la MOLTEPLICITÀ TOTALE, non il numero di chiavi (il codegen emette
        // CollectionCount per .Count(), quindi la correzione va qui e non nel dispatch).
        if (collection is IBagMultiset bag) return bag.TotalCount();
        // HLL: non implementa ICollection (non conserva gli elementi) — Count() è la STIMA
        // della cardinalità (parità gmb_coll_hll_count).
        if (collection is CommonLib.Collections.HyperLogLog hll) return hll.Count();
        if (collection is System.Collections.ICollection c) return c.Count;
        if (collection is System.Array a) return a.Length;
        if (collection is string s) return s.Length;
        /* Collezioni CommonLib con Count come PROPRIETÀ ma non ICollection (TRIE, e in
         * generale le strutture dedicate): senza, `.Count()` rispondeva 0 su IL mentre le
         * altre gambe davano il valore (CollectionsModern: Trie.Count 0 vs 4). */
        if (collection is not null)
        {
            var cntProp = collection.GetType().GetProperty("Count",
                System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance);
            if (cntProp is not null && cntProp.GetIndexParameters().Length == 0)
            {
                var cv = cntProp.GetValue(collection);
                if (cv is int ic) return ic;
                if (cv is long lc) return lc;
            }
        }
        return 0.0;
    }

    /// <summary>BAG = MULTISET. Il contratto non generico permette al dispatch runtime di
    /// riconoscerlo senza indovinare dal tipo dei valori (un DICTIONARY<K,LONG> utente NON è
    /// un bag). Semantica del runtime condiviso C: gmb_coll_bag_count / gmb_coll_bag_remove.</summary>
    public interface IBagMultiset
    {
        /// <summary>MOLTEPLICITÀ TOTALE (somma dei conteggi), non il numero di chiavi.</summary>
        double TotalCount();
        /// <summary>Rimuove UNA istanza (l'ultima); false se l'elemento non c'è.</summary>
        bool RemoveOne(object? item);
    }

    /// <summary>BAG&lt;T&gt; materializzato dal codegen IL: Dictionary&lt;T,long&gt;
    /// (elemento → molteplicità) + IBagMultiset.</summary>
    public sealed class BagMultiset<TKey> : Dictionary<TKey, long>, IBagMultiset where TKey : notnull
    {
        public double TotalCount()
        {
            long total = 0;
            foreach (var n in Values) total += n;
            return total;
        }

        public bool RemoveOne(object? item)
        {
            if (item is null) return false;
            TKey key;
            try { key = item is TKey tk ? tk : (TKey)Convert.ChangeType(item, typeof(TKey), System.Globalization.CultureInfo.InvariantCulture); }
            catch { return false; }
            if (!TryGetValue(key, out var n)) return false;
            if (n <= 1) Remove(key); else this[key] = n - 1;
            return true;
        }
    }

    /// <summary>HEAP/MAXHEAP → CommonLib.Collections.BinaryHeap&lt;object&gt; (Add/Extract/Peek
    /// con heapify), la struttura canonica del repo. Materializzare una List lasciava
    /// Peek/Extract sul primo inserito: l'ordine heap non veniva mai applicato.</summary>
    public static CommonLib.Collections.BinaryHeap<object> NewHeap(bool max)
        => new(new BasicHeapComparer(max));

    /// <summary>HEAP/MAXHEAP da letterale (`= [4,1,7,3]`): gli elementi sono ELEMENTI, non
    /// coppie; il letterale stesso produce una List e qui viene impilato con heapify.</summary>
    public static CommonLib.Collections.BinaryHeap<object> HeapFromItems(System.Collections.IEnumerable items, bool max)
    {
        var heap = NewHeap(max);
        foreach (var it in items) if (it is not null) heap.Add(it);
        return heap;
    }

    /// <summary>Ordinamento degli elementi di HEAP/MAXHEAP: numerico quando entrambi i valori
    /// sono numeri (in BASIC arrivano boxati come double), altrimenti ordinale sulla resa
    /// stringa. `max` INVERTE il confronto: stessa struttura con radice massima.</summary>
    private sealed class BasicHeapComparer(bool max) : System.Collections.Generic.IComparer<object>
    {
        public int Compare(object a, object b)
        {
            int c;
            if (a is null || b is null) c = a is null ? (b is null ? 0 : -1) : 1;
            else if (TryNum(a, out var na) && TryNum(b, out var nb)) c = na.CompareTo(nb);
            else c = string.CompareOrdinal(Convert.ToString(a, System.Globalization.CultureInfo.InvariantCulture),
                                           Convert.ToString(b, System.Globalization.CultureInfo.InvariantCulture));
            return max ? -c : c;
        }

        private static bool TryNum(object v, out double d)
            => double.TryParse(Convert.ToString(v, System.Globalization.CultureInfo.InvariantCulture),
                               System.Globalization.NumberStyles.Any,
                               System.Globalization.CultureInfo.InvariantCulture, out d);
    }

    /// <summary>TREE/AVL/REDBLACK (IDictionary ordinato): Min/Max/ExtractMin/ExtractMax →
    /// COPPIA [chiave, valore] della prima/ultima voce in ordine di chiave (Extract* la
    /// rimuove). Semantica del P-Code (OP_CALL_MEMBER: Min = prima voce, Max = ultima).
    /// L'IL passava da CollectionMin/Max, che lavora sui VALORI e torna un double.</summary>
    public static object? DictEdgePair(System.Collections.IDictionary d, bool max, bool extract)
    {
        if (d.Count == 0) return null;
        object? k = null, v = null;
        foreach (System.Collections.DictionaryEntry e in d)
        {
            k = e.Key; v = e.Value;
            if (!max) break;
        }
        if (extract && k is not null) d.Remove(k);
        return new object?[] { k, v };
    }

    /// <summary>TRYGETVALUE con out-param: predicato + valore (usato dal backend IL per
    /// propagare la variabile out; PCode/VM/C riscrivono in Get+ContainsKey).</summary>
    public static bool CollectionTryGetValueOut(object? instance, object? key, out object? value)
    {
        value = null;
        if (instance is null) return false;
        if (instance is CommonLib.Collections.IKeyValueIndexable kvi && kvi.TryGetValue(key, out var v))
        {
            value = v;
            return true;
        }
        if (instance is System.Collections.IDictionary d && key is not null && d.Contains(key))
        {
            value = d[key];
            return true;
        }
        return false;
    }

    /// <summary>Istanza di CommonLib.Collections.Timeline&lt;T&gt;?</summary>
    private static bool IsTimelineInstance(object? o)
        => o is not null
           && o.GetType().Name.StartsWith("Timeline", StringComparison.Ordinal)
           && o.GetType().Namespace?.StartsWith("CommonLib.Collections", StringComparison.Ordinal) == true;

    /// <summary>Istanza di CommonLib.Collections.Graph&lt;T&gt;?</summary>
    private static bool IsGraphInstance(object? o)
        => o is not null
           && o.GetType().Name.StartsWith("Graph", StringComparison.Ordinal)
           && o.GetType().Namespace?.StartsWith("CommonLib.Collections", StringComparison.Ordinal) == true;

    /// <summary>Data seriale BASIC (OADate) di una chiave temporale.</summary>
    private static double DateSerialOf(object? key) => key switch
    {
        DateTimeOffset dto => dto.DateTime.ToOADate(),
        DateTime dt => dt.ToOADate(),
        null => 0.0,
        _ => SafeDouble(key)
    };

    private static object? ReadKv(object? kv, string prop)
        => kv is null ? null : kv.GetType().GetProperty(prop)?.GetValue(kv);

    /// <summary>Prima/ultima voce di una Timeline come {"Key":&lt;seriale&gt;,"Value":...}.</summary>
    private static object? TimelineEdge(object timeline, bool last)
    {
        var mi = timeline.GetType().GetMethod(last ? "Last" : "First");
        if (mi is null) return null;
        object? kv;
        try { kv = mi.Invoke(timeline, null); }
        catch (System.Reflection.TargetInvocationException) { return null; }
        if (kv is null) return null;
        return new Dictionary<string, object?>(StringComparer.Ordinal)
        {
            ["Key"] = DateSerialOf(ReadKv(kv, "Key")),
            ["Value"] = ReadKv(kv, "Value")
        };
    }

    /// <summary>GetRange(lo,hi) di una Timeline: lista di {"Key":seriale,"Value":...}.</summary>
    private static object? TimelineRange(object timeline, object? lo, object? hi)
    {
        var mi = timeline.GetType().GetMethod("GetRange");
        if (mi is null) return null;
        var ptype = mi.GetParameters()[0].ParameterType;
        object ConvertArg(object? a)
        {
            /* L'argomento può arrivare già come DateTime (il compilatore converte DateSerial
             * per il parametro DateTimeOffset) oppure come numero seriale. */
            if (a is DateTime dtArg)
                return ptype == typeof(DateTimeOffset) ? new DateTimeOffset(dtArg) : dtArg;
            if (a is DateTimeOffset dtoArg)
                return ptype == typeof(DateTime) ? dtoArg.DateTime : dtoArg;
            var serial = Convert.ToDouble(a, System.Globalization.CultureInfo.InvariantCulture);
            if (ptype == typeof(DateTimeOffset)) return new DateTimeOffset(DateTime.FromOADate(serial));
            if (ptype == typeof(DateTime)) return DateTime.FromOADate(serial);
            return Convert.ChangeType(a, ptype, System.Globalization.CultureInfo.InvariantCulture)!;
        }
        object? res;
        try { res = mi.Invoke(timeline, [ConvertArg(lo), ConvertArg(hi)]); }
        catch (System.Reflection.TargetInvocationException) { return null; }
        var rows = new List<Dictionary<string, object?>>();
        if (res is System.Collections.IEnumerable en)
            foreach (var kv in en)
                rows.Add(new Dictionary<string, object?>(StringComparer.Ordinal)
                {
                    ["Key"] = DateSerialOf(ReadKv(kv, "Key")),
                    ["Value"] = ReadKv(kv, "Value")
                });
        return rows;
    }

    /// <summary>Dijkstra di un Graph&lt;T&gt; come lista di record {"node","dist"}
    /// (ordinata per nome nodo: forma canonica condivisa con il runtime C).</summary>
    private static object? GraphDijkstraRows(object graph, object? start)
    {
        var mi = graph.GetType().GetMethod("Dijkstra");
        if (mi is null || start is null) return null;
        var ptype = mi.GetParameters()[0].ParameterType;
        object arg;
        try { arg = Convert.ChangeType(start, ptype, System.Globalization.CultureInfo.InvariantCulture)!; }
        catch { arg = start; }
        object? res;
        try { res = mi.Invoke(graph, [arg]); }
        catch (System.Reflection.TargetInvocationException) { return null; }
        var rows = new List<Dictionary<string, object?>>();
        if (res is System.Collections.IDictionary dist)
            foreach (System.Collections.DictionaryEntry e in dist)
                rows.Add(new Dictionary<string, object?>(StringComparer.Ordinal)
                {
                    ["node"] = Convert.ToString(e.Key, System.Globalization.CultureInfo.InvariantCulture),
                    ["dist"] = SafeDouble(e.Value)
                });
        rows.Sort((a, b) => string.CompareOrdinal(
            Convert.ToString(a["node"], System.Globalization.CultureInfo.InvariantCulture),
            Convert.ToString(b["node"], System.Globalization.CultureInfo.InvariantCulture)));
        return rows;
    }

    /// <summary>F1: MaxPair/MinPair su IDictionary — chiave con valore max (true) o min
    /// (false). Confronto numerico se i valori sono numerici, stringa (ordinale) altrimenti.
    /// Parità semantica PCode/VMC (nessun backend la aveva prima).</summary>
    public static object? DictMaxMinPair(System.Collections.IDictionary d, bool max)
    {
        object? bestKey = null;
        double? bestNum = null;
        string? bestStr = null;
        bool numericMode = false;
        foreach (var key in d.Keys)
        {
            var v = d[key];
            var s = Convert.ToString(v, System.Globalization.CultureInfo.InvariantCulture) ?? "";
            if (double.TryParse(s, System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out var num))
            {
                if (!numericMode) { numericMode = true; bestKey = key; bestNum = num; bestStr = null; }
                else if ((max && num > bestNum) || (!max && num < bestNum)) { bestKey = key; bestNum = num; }
            }
            else if (!numericMode)
            {
                if (bestKey == null) { bestKey = key; bestStr = s; }
                else if ((max && string.CompareOrdinal(s, bestStr) > 0) || (!max && string.CompareOrdinal(s, bestStr) < 0)) { bestKey = key; bestStr = s; }
            }
        }
        return bestKey;
    }

    /// <summary>F1 Incongruenze (AGENTS §12, regola d'oro): dispatch runtime di un metodo
    /// di collection per CHIAVE CANONICA (int del TokenKind Coll*, emesso dal compilatore).
    /// Il lexeme legacy è risolto qui internamente via CollMembers — la CollectionInvoke
    /// per nome resta l'implementazione; la chiave di dispatch è il TokenKind.</summary>
    public static object? CollectionInvokeByKind(int tokenKind, object? instance, object?[]? args)
    {
        if (instance is null) return null;
        var kind = (TokenKind)tokenKind;
        var name = CollMembers.RuntimeName(kind)
            ?? throw new NotSupportedException(
                $"Backend IL: CollectionInvokeByKind su TokenKind '{kind}' non membro collection (dispatch deve usare il lexeme).");
        return CollectionInvoke(instance, name, args ?? []);
    }

    /// <summary>Dispatch runtime di un metodo su una collection boxed (AnyType): Remove/Add/
    /// Contains/First/Last... per nome, via riflessione sul tipo reale.</summary>
    public static object? CollectionInvoke(object? instance, string methodName, object?[] args)
    {
        if (instance is null) return null;
        /* HLL (HyperLogLog): metodi per nome — Add/Count/Merge/Error/Precision/Serialize/
         * Load/Clear. Il dispatcher condiviso evita la reflection e garantisce la stessa
         * semantica su IL e PCode (e il mirror del runtime C gmb_hll.c). */
        if (instance is CommonLib.Collections.HyperLogLog hll)
        {
            switch (methodName.ToUpperInvariant())
            {
                case "ADD": if (args.Length >= 1) hll.Add(args[0]); return null;
                case "COUNT" or "LENGTH": return hll.Count();
                case "ERROR": return hll.Error();
                case "PRECISION": return (double)hll.Precision();
                case "MERGE":
                    if (args.Length >= 1 && args[0] is CommonLib.Collections.HyperLogLog other)
                        hll.Merge(other);
                    return null;
                case "SERIALIZE": return hll.Serialize();
                case "LOAD":
                    if (args.Length >= 1 && args[0] is string blob) hll.Load(blob);
                    return null;
                case "CLEAR": hll.Clear(); return null;
                default: return null;
            }
        }
        // HTTPREQUEST seminata come dict (chiave "__httpRequest"): i metodi BASIC della
        // req (ParseForm/ParseMultipartForm) girano sull'istanza reale — UNICA logica shared
        // col PCodeVM (PCodeHttpRequestDictInvoke, §0bis). Come nel PCode, qualunque altro
        // nome su questa dict vale null.
        if (instance is System.Collections.IDictionary httpReqDict
            && Basic.IlBackend.PCode.PCodeProcessor.PCodeHttpRequestDictInvoke(httpReqDict, methodName, args.Length, out var hrRes))
            return hrRes;
        // Streaming (chunked) della risposta HTTP: stesse funzioni della gamba PCode
        // (PCodeHttpResponseStreamInvoke, §0bis). Senza questo il dispatch cadeva nella
        // reflection di CollectionInvoke, che cerca "StartStream"/"Flush" sul tipo CLR —
        // metodi che hanno altri nomi → NotSupportedException e risposta 204.
        if (instance is Basic.IlBackend.PCode.Http.PCodeHttpResponse httpResStream
            && Basic.IlBackend.PCode.PCodeProcessor.PCodeHttpResponseStreamInvoke(httpResStream, methodName, args, args.Length))
            return null;
        // Metodi "logici" BASIC su collection boxed: Min/Max/Keys/Count/UniqueCount/Contains/
        // Add/Remove — dispatch specializzato sul tipo reale (Dictionary per Tree/AVL/Bag/...).
        switch (methodName.ToUpperInvariant())
        {
            /* TIMELINE: First/Last/GetRange sono KeyValuePair<DateTimeOffset,T> nel CLR, che
             * il serializzatore rende come {"Key":{},...} / stringhe ISO (IL) o come lista
             * [k,v] (PCode): 4 forme diverse. Forma CANONICA unica (uguale a VM/C e C99):
             * {"Key":<data seriale>, "Value":<valore>} — la chiave è il numero OADate che
             * il BASIC usa in DateSerial. */
            case "FIRST" when args.Length == 0 && IsTimelineInstance(instance):
                return TimelineEdge(instance!, last: false);
            case "LAST" when args.Length == 0 && IsTimelineInstance(instance):
                return TimelineEdge(instance!, last: true);
            case "GETRANGE" when args.Length == 2 && IsTimelineInstance(instance):
                return TimelineRange(instance!, args[0], args[1]);
            /* GRAPH.Dijkstra: nel CLR torna Dictionary<nodo,dist> (IL stampava una mappa
             * {"A":0,...}, PCode una lista di KeyValuePair, VM/C e C99 una lista di record).
             * Forma CANONICA unica: lista di {"node","dist"} ordinata per nome nodo. */
            case "DIJKSTRA" when args.Length == 1 && IsGraphInstance(instance):
                return GraphDijkstraRows(instance!, args[0]);
            // TREE/AVL/REDBLACK (IDictionary ordinato): Min/Max = COPPIA [chiave,valore]
            // della prima/ultima voce, come il P-Code (OP_CALL_MEMBER). Prima finivano in
            // CollectionMin/Max, che lavora sui VALORI e torna un double: TREE<STRING,INTEGER>
            // .Min() dava 10 invece di ["a",10].
            case "MIN" when instance is System.Collections.IDictionary dmin:
                return DictEdgePair(dmin, max: false, extract: false);
            case "MAX" when instance is System.Collections.IDictionary dmax:
                return DictEdgePair(dmax, max: true, extract: false);
            case "MIN": return CollectionMin(instance);
            case "MAX": return CollectionMax(instance);
            // Sort()/Reverse() su LinkedList<T>: il CLR non espone i metodi (il backend IL li
            // emette come CollectionSort/CollectionReverse; il P-Code delega qui). Senza,
            // "metodo runtime 'Sort' non trovato su 'LinkedList`1'" (CollectionsLinked/DictLists).
            case "SORT" when args.Length == 0 && IsLinkedListInstance(instance):
                CollectionSort(instance); return null;
            case "REVERSE" when args.Length == 0 && IsLinkedListInstance(instance):
                CollectionReverse(instance); return null;
            // IndexOf(value): LinkedList/Doubly/Circular non hanno il metodo CLR —
            // scansione lineare con uguaglianza NUMERICA (parità con il ramo del backend IL).
            case "INDEXOF" when args.Length == 1:
                return CollectionIndexOf(instance, args[0]);
            // HEAP/MAXHEAP (BinaryHeap<T>): Count() = numero di elementi (non è ICollection,
            // quindi il COUNT generico sotto tornava 0).
            case "COUNT" when args.Length == 0 && instance is CommonLib.Collections.BinaryHeap<object> hbc:
                return (double)hbc.Count;
            // BAG.Count() = MOLTEPLICITÀ TOTALE (il COUNT generico sotto conta le CHIAVI:
            // ["a","b","a","c","a"].Count() dava 3 invece di 5).
            case "COUNT" when args.Length == 0 && instance is IBagMultiset bcnt:
                return bcnt.TotalCount();
            // TRIE: Count è una PROPRIETÀ CommonLib (non ICollection) → il Count generico
            // tornava 0 (CollectionsModern: "Trie.Count= 0" su IL, 4 sulle altre gambe).
            case "COUNT" or "LENGTH" when args.Length == 0 && instance is CommonLib.Collections.Trie trieCnt:
                return (double)trieCnt.Count;
            // BAG.Count(item): molteplicità dell'elemento (Dictionary<item,conteggio>).
            case "COUNT" when args.Length >= 1 && instance is System.Collections.IDictionary dcount:
                return dcount.Contains(args[0] ?? "") ? Convert.ToDouble(dcount[args[0] ?? ""]) : 0.0;
            case "COUNT": return CollectionCount(instance);
            // TOARRAY su collection boxed (RedBlack/Tree/AVL/... → IDictionary): array delle
            // coppie KeyValuePair boxed (parità VM per ToArray() su queste strutture).
            case "TOARRAY" when instance is System.Collections.IDictionary dta:
                return dta.Cast<object?>().ToArray();
            // TOARRAY generico (CircularQueue/RingBuffer/Timeline/... che implementano
            // IEnumerable ma non espongono ToArray come metodo di istanza).
            case "TOARRAY" when instance is System.Collections.IEnumerable dtgen:
                return dtgen.Cast<object?>().ToArray();
            // BIT (Fenwick) materializzato come IDictionary (chiave=indice, valore=numero):
            // Query(idx) somma prefissa [0..idx], QueryRange(a,b) somma l'intervallo,
            // Update(idx,delta) somma un delta al valore esistente.
            /* BITREE (BinaryIndexedTree<T> CommonLib): Query/QueryRange/Update non sono
             * IDictionary → senza questi casi la riflessione non trovava nulla e si
             * stampava 0 (CollectionsModern §10: IL 0/0/10 vs 6/9/19 delle altre gambe). */
            case "QUERY" when args.Length == 1 && instance is CommonLib.Collections.BinaryIndexedTree<double> bitQ:
                return bitQ.Query(Convert.ToInt32(args[0] ?? 0));
            case "QUERYRANGE" when args.Length == 2 && instance is CommonLib.Collections.BinaryIndexedTree<double> bitQR:
                return bitQR.QueryRange(Convert.ToInt32(args[0] ?? 0), Convert.ToInt32(args[1] ?? 0));
            case "UPDATE" when args.Length == 2 && instance is CommonLib.Collections.BinaryIndexedTree<double> bitU:
                bitU.Update(Convert.ToInt32(args[0] ?? 0), SafeDouble(args[1]));
                return null;
            case "QUERY" when args.Length == 1 && instance is System.Collections.IDictionary qry:
                return BitQuery(qry, 0.0, Convert.ToDouble(args[0]));
            case "QUERYRANGE" when args.Length == 2 && instance is System.Collections.IDictionary qrg:
                return BitQuery(qrg, Convert.ToDouble(args[0]), Convert.ToDouble(args[1]));
            case "UPDATE" when args.Length == 2 && instance is System.Collections.IDictionary upd:
            {
                var ukey = upd[args[0] ?? ""];
                var uval = Convert.ToDouble(ukey ?? 0) + Convert.ToDouble(args[1]);
                upd[args[0] ?? ""] = uval;
                return uval;
            }
            // TRIE: FindAll(prefix) → FindAllWordsWithPrefix (la classe espone il nome lungo);
            // StartsWith/Add/Contains sono metodi reali del Trie (dispatch generico sotto).
            case "FINDALL" when instance is CommonLib.Collections.Trie ft && args.Length >= 1:
                return ft.FindAllWordsWithPrefix(Convert.ToString(args[0], System.Globalization.CultureInfo.InvariantCulture) ?? "").Cast<object?>().ToArray();
            // EXTRACTMIN/EXTRACTMAX (AVL/RedBlack/BPlus materializzati come IDictionary):
            // rimuove e restituisce la COPPIA [chiave,valore] della voce minima/massima
            // (come il P-Code: prima l'IL tornava il solo VALORE).
            case "EXTRACTMIN" when instance is System.Collections.IDictionary emin:
                return DictEdgePair(emin, max: false, extract: true);
            case "EXTRACTMAX" when instance is System.Collections.IDictionary emax:
                return DictEdgePair(emax, max: true, extract: true);
            // HEAP/MAXHEAP (BinaryHeap<T> canonico): Peek/Extract/Count reali della
            // struttura (prima, materializzata come List, Peek dava il PRIMO INSERITO).
            case "PEEK" when instance is CommonLib.Collections.BinaryHeap<object> hbp:
                return hbp.Count > 0 ? hbp.Peek() : null;
            case "EXTRACT" when instance is CommonLib.Collections.BinaryHeap<object> hbx:
                return hbx.Count > 0 ? hbx.Extract() : null;
            // HEAP (PriorityQueue boxed): Extract() = Dequeue, Peek() = Peek.
            case "EXTRACT" when instance is System.Collections.Generic.PriorityQueue<object, object> pq:
                return pq.Dequeue();
            case "PEEK" when instance is System.Collections.Generic.PriorityQueue<object, object> pqp:
                return pqp.Peek();
            // HEAP/MAXHEAP materializzati come List/array (letterale): Peek() = testa,
            // Extract() = testa rimossa (parità pragmatica; l'ordine heap reale non è
            // preservato dal letterale, ma il sample non ne dipende per il valore esatto).
            case "PEEK" when instance is System.Collections.IList pil && pil.Count > 0:
                return pil[0];
            case "EXTRACT" when instance is System.Collections.IList eil:
                if (eil.Count == 0) return null;
                var eilHead = eil[0];
                eil.RemoveAt(0);
                return eilHead;
            case "UNIQUECOUNT": return UniqueCount(instance);
            // GRAPH.GetNeighbors(node): lista di record {node, weight} — parità col runtime
            // condiviso C (gmb_graph_neighbors_val) e con VM/C/C99/C99Native. Prima il
            // dispatch riflessivo rendeva l'IEnumerable<KeyValuePair> come dict ({B:10,C:20}).
            case "GETNEIGHBORS" when args.Length >= 1:
            {
                var gn = instance.GetType().GetMethod("GetNeighbors");
                if (gn is null) return null;
                var lres = new System.Collections.Generic.List<object?>();
                if (gn.Invoke(instance, new[] { args[0] }) is System.Collections.IEnumerable gne)
                    foreach (var kv in gne)
                    {
                        var kt = kv!.GetType();
                        lres.Add(new Dictionary<string, object?>
                        {
                            ["node"] = kt.GetProperty("Key")!.GetValue(kv),
                            ["weight"] = kt.GetProperty("Value")!.GetValue(kv),
                        });
                    }
                return lres.ToArray();
            }
            case "KEYS" when instance is System.Collections.IDictionary dk:
                return dk.Keys.Cast<object?>().ToArray();
            case "VALUES" when instance is System.Collections.IDictionary dv:
                return dv.Values.Cast<object?>().ToArray();
            case "CONTAINS" when args.Length == 1 && instance is System.Collections.IDictionary dc:
                return dc.Contains(args[0] ?? "") ? 1.0 : 0.0;
            // BAG.Remove(item): toglie UNA istanza (molteplicità -1, chiave rimossa a 0),
            // non l'intera chiave: ["a","b","a","c","a"].Remove("a") → "a" resta con 2.
            case "REMOVE" when args.Length >= 1 && instance is IBagMultiset brem:
                brem.RemoveOne(args[0]); return 1.0;
            case "REMOVE" when args.Length >= 1 && instance is System.Collections.IDictionary dr:
            {
                /* BAG (Dictionary<elemento,long> = multiset): toglie UNA istanza —
                 * decrementa la molteplicità e rimuove la chiave solo a 0 (semantica del
                 * ramo P-Code e del runtime C). Prima cadeva nel Remove di dizionario e
                 * cancellava TUTTE le istanze ("a" spariva da ToJson/UniqueItems:
                 * Minitest collections/typed_containers_parity, gamba PCode). */
                var gt = dr.GetType();
                if (gt.IsGenericType && gt.GetGenericArguments().Length == 2
                    && gt.GetGenericArguments()[1] == typeof(long)
                    && dr.Contains(args[0] ?? ""))
                {
                    var cur = dr[args[0] ?? ""];
                    long mult = cur is long cl ? cl : (long)Convert.ToDouble(cur);
                    if (mult <= 1) dr.Remove(args[0] ?? "");
                    else dr[args[0] ?? ""] = mult - 1;
                    return -1.0;
                }
                /* Predicato BASIC: -1 se la chiave esisteva (rimossa), 0 se assente. Prima
                 * tornava SEMPRE 1.0: `WHILE d.Remove(k)` non terminava mai e `PRINT
                 * d.Remove(k)` stampava 1 sia per presente sia per assente (Minitest
                 * collections/dict_remove_if, gamba PCode: exit 142/hang). Parità
                 * IL/VM/C/C99Native. `IDictionary.Remove` (non generico) ritorna void →
                 * l'esito si ricava da Contains. */
                var had = dr.Contains(args[0] ?? "");
                if (had) dr.Remove(args[0] ?? "");
                return had ? -1.0 : 0.0;
            }
            case "ADD" when args.Length >= 2 && instance is System.Collections.IDictionary da:
                da[args[0] ?? ""] = args[1]; return 0.0;
            // F1e: SET/SETKEYVALUE su map-like boxed — semantica "set" (sovrascrive),
            // identica ad Add(k,v) boxed (parity VM/C dict path Set + C99Native). Su un
            // dict TIPIZZATO (es. Dictionary<string,short>) il valore BASIC arriva boxato
            // come double (letterale senza suffisso): Convert.ChangeType al tipo del valore
            // del dict (il CLR Add generico non coerzerebbe: ArgumentException).
            case "SET" or "SETKEYVALUE" when args.Length >= 2 && instance is System.Collections.IDictionary ds:
            {
                var vSet = args[1];
                var vArgs = ds.GetType().IsGenericType ? ds.GetType().GetGenericArguments()[1] : null;
                if (vArgs != null && vArgs.IsValueType && vSet != null && !vArgs.IsInstanceOfType(vSet))
                    vSet = System.Convert.ChangeType(vSet, vArgs, System.Globalization.CultureInfo.InvariantCulture);
                ds[args[0] ?? ""] = vSet;
                return 0.0;
            }
            // F1: membri LIST parity VM/C — AddUnique (HashSet-like, duplicato ignorato),
            // AddAfter/AddBefore (inserimento per indice 0-based), IsEmpty.
            case "ADDUNIQUE" when args.Length >= 1 && instance is System.Collections.IList iu:
                if (!iu.Contains(args[0])) iu.Add(args[0]);
                return null;
            case "ADDAFTER" or "ADDBEFORE" when args.Length >= 2 && instance is System.Collections.IList iab:
            {
                var idx = Convert.ToInt32(Convert.ToDouble(args[0] ?? 0));
                if (methodName.Equals("AddAfter", StringComparison.OrdinalIgnoreCase)) idx += 1;
                if (idx < 0) idx = 0;
                while (idx > iab.Count) iab.Add(null);
                iab.Insert(Math.Min(idx, iab.Count), args[1]);
                return null;
            }
            // F1: IsEmpty/Front/Back — parity VM/C (IsEmpty: count==0 → 1; Front/Back: peek
            // della testa, stesso valore per entrambe come gmb_coll_peek della VM/C).
            // F1: IsEmpty/Front/Back — parity VM/C/PCode: Front = testa (prossimo da
            // Dequeue), Back = coda (ultimo elemento); IsEmpty → 1/0.
            case "ISEMPTY" when args.Length == 0 && instance is System.Collections.ICollection ie:
                return ie.Count == 0;
            case "FRONT" or "BACK" when args.Length == 0 && instance is System.Collections.IList ifb && ifb.Count > 0:
                return methodName.Equals("Front", StringComparison.OrdinalIgnoreCase)
                    ? ifb[0] : ifb[ifb.Count - 1];
            // Queue TIPIZZATA (Queue<string>/Queue<int> — non solo Queue<object?>): il C#
            // della VM materializza QUEUE OF T come generico chiuso, NON come Queue<object?>.
            case "FRONT" or "BACK" when args.Length == 0 && instance is System.Collections.ICollection qcol
                && qcol.Count > 0 && instance is not System.Collections.IList
                && instance is not System.Collections.IDictionary
                && instance.GetType().GetGenericTypeDefinition() == typeof(System.Collections.Generic.Queue<>):
            {
                object? first = null, last = null;
                foreach (var it in (System.Collections.IEnumerable)instance) { first ??= it; last = it; }
                return methodName.Equals("Front", StringComparison.OrdinalIgnoreCase) ? first : last;
            }
            // F1: MaxPair/MinPair su map-like — la CHIAVE della voce con valore massimo/
            // minimo (numeri per valore, stringhe in ordine alfabetico). Parità del
            // dispatch runtime condiviso (nessun backend la aveva: gmb_members F1e nota).
            case "MAXPAIR" or "MINPAIR" when args.Length == 0 && instance is System.Collections.IDictionary dmp && dmp.Count > 0:
                return DictMaxMinPair(dmp, methodName.Equals("MaxPair", StringComparison.OrdinalIgnoreCase));
            // BAG (Dictionary<item,count>): Add(item) incrementa il conteggio (long).
            case "ADD" when args.Length == 1 && instance is System.Collections.IDictionary db:
                db[args[0] ?? ""] = (long)(Convert.ToDouble(db[args[0] ?? ""] ?? 0) + 1); return 0.0;
            // BAG.UniqueItems() / BAG.UniqueCount(): le chiavi del conteggio.
            case "UNIQUEITEMS" when instance is System.Collections.IDictionary du:
                return du.Keys.Cast<object?>().ToArray();
            // CACHE/collection chiave→valore (CommonLib IKeyValueIndexable): Keys/Values/
            // ContainsKey/Get via interfaccia non generica (niente reflection per nome).
            case "KEYS" when instance is CommonLib.Collections.IKeyValueIndexable kc:
                /* Ordine CANONICO per nome chiave (C99/VM/C ordinano; Cache ha un
                 * ConcurrentDictionary → ordine di hash instabile). */
                return kc.Entries().Select(kv => kv.Key)
                    .OrderBy(k => Convert.ToString(k, System.Globalization.CultureInfo.InvariantCulture),
                             StringComparer.Ordinal)
                    .ToArray();
            case "VALUES" when instance is CommonLib.Collections.IKeyValueIndexable vc:
                return vc.Entries().Select(kv => kv.Value).ToArray();
            case "CONTAINSKEY" when instance is CommonLib.Collections.IKeyValueIndexable ck && args.Length >= 1:
                /* Convenzione BASIC -1/0 (parità PCode/VM-C/C99: prima IL stampava 1). */
                return ck.TryGetValue(args[0], out _) ? -1.0 : 0.0;
            case "GET" when instance is CommonLib.Collections.IKeyValueIndexable gk && args.Length >= 1:
                return gk.TryGetValue(args[0], out var gkv) ? gkv : null;
            // GET(key) su IDictionary boxed (BPlusTree/RedBlack/...): lookup per chiave.
            case "GET" when args.Length >= 1 && instance is System.Collections.IDictionary dget:
                return dget.Contains(args[0] ?? "") ? dget[args[0] ?? ""] : null;
            // GET(key) su JsonObject (NON implementa System.Collections.IDictionary → il caso
            // sopra non matcha): `FetchResult.Headers.Get("k")` / `HttpRequest.Headers.Get("k")`.
            // Valore JsonNode → object (JsonValue stringa → string, altrimenti ToJsonString);
            // chiave assente → null (a valle coerced a "" come PCodeVM/VM/C/C99; bug
            // Headers-Get-Divergenza-Backend).
            case "GET" when args.Length >= 1 && instance is System.Text.Json.Nodes.JsonObject joGet:
            {
                if (!joGet.TryGetPropertyValue(args[0]?.ToString() ?? "", out var jnGet) || jnGet is null)
                    return null;
                return jnGet is System.Text.Json.Nodes.JsonValue jvGet
                    && jvGet.TryGetValue<string>(out var jsGet) ? jsGet : jnGet.ToJsonString();
            }
            // F1: alias GRAPH — la classe CommonLib espone TryGetEdgeWeight (out), non
            // GetEdgeWeight; la VM/C lo chiama gmb_graph_get_edge_weight. Peso 0 se assente.
            case "GETEDGEWEIGHT" when args.Length >= 2 && instance is not null
                && instance.GetType().Name.StartsWith("Graph", StringComparison.Ordinal):
            {
                var tm = instance.GetType().GetMethod("TryGetEdgeWeight", System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance)
                    ?? throw new NotSupportedException($"Backend IL: GetEdgeWeight richiede Graph.TryGetEdgeWeight, assente su '{instance.GetType().Name}'.");
                var tmArgs = new object?[3] { args[0]!, args[1]!, 0.0 };
                var ok = (bool)tm.Invoke(instance, tmArgs)!;
                return ok ? Convert.ToDouble(tmArgs[2]) : 0.0;
            }
            // F1: AddNodeConsistent — idempotente (add se assente), -1 se il nodo esiste
            // dopo la chiamata, 0 su errore (parity gmb_graph_add_node_consistent del
            // runtime C condiviso).
            case "ADDNODECONSISTENT" when args.Length >= 1 && instance is not null
                && instance.GetType().Name.StartsWith("Graph", StringComparison.Ordinal):
            {
                var an = instance.GetType().GetMethod("AddNode", System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance)
                    ?? throw new NotSupportedException($"Backend IL: AddNodeConsistent richiede Graph.AddNode, assente su '{instance.GetType().Name}'.");
                an.Invoke(instance, new[] { args[0] });
                var hn = instance.GetType().GetMethod("HasNode", System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance)
                    ?? throw new NotSupportedException($"Backend IL: AddNodeConsistent richiede Graph.HasNode, assente su '{instance.GetType().Name}'.");
                return (bool)hn.Invoke(instance, new[] { args[0] })!;
            }
        }
        /* FIRST/LAST su collezioni enumerabili NON-map: l'ELEMENTO di testa/coda — PRIMA del
         * fallback-property. LinkedList<T> espone le PROPRIETÀ First/Last che ritornano un
         * LinkedListNode<T>: il fallback le trovava e restituiva il NODO, che poi finiva in
         * WritePrinter come stringa → AccessViolationException (sample CollectionsDictLists
         * §7/§8, CollectionsLinked). Per i dizionari resta il comportamento a valle. */
        if (args.Length == 0 && instance is System.Collections.IEnumerable seqFL
            && instance is not System.Collections.IDictionary && instance is not string)
        {
            var wantLast = methodName.Equals("Last", StringComparison.OrdinalIgnoreCase)
                        || methodName.Equals("Back", StringComparison.OrdinalIgnoreCase);
            var isFL = methodName.Equals("First", StringComparison.OrdinalIgnoreCase)
                    || methodName.Equals("Front", StringComparison.OrdinalIgnoreCase) || wantLast;
            if (isFL)
            {
                object? first = null, last = null;
                var any = false;
                foreach (var it in seqFL) { if (!any) { first = it; any = true; } last = it; }
                return any ? (wantLast ? last : first) : null;
            }
        }
        var t = instance.GetType();
        System.Reflection.PropertyInfo? gProp = null;
        if (args.Length == 0)
        {
            try
            {
                gProp = t.GetProperty(methodName, System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.IgnoreCase);
            }
            catch (System.Reflection.AmbiguousMatchException)
            {
                /* Più property con lo stesso nome a meno del case: prendi la prima
                 * senza indicizzatore (le indexer hanno parametri e non sono "letture"). */
                gProp = t.GetProperties(System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance)
                    .FirstOrDefault(pp => pp.GetIndexParameters().Length == 0
                        && pp.Name.Equals(methodName, StringComparison.OrdinalIgnoreCase)
                        && pp.CanRead);
            }
        }
        if (gProp != null && args.Length == 0)
        {
            var gPropGet = gProp.GetGetMethod();
            if (gPropGet != null) return gPropGet.Invoke(instance, null);
        }
        /* Selezione DETERMINISTICA dell'overload. `Type.GetMethod(nome, flags)` lancia
         * AmbiguousMatchException quando il tipo ha PIÙ overload con lo stesso nome a meno
         * del case, anche se la chiamata BASIC ha arità non ambigua: `t.Sort()` su
         * List<object> trovava `Sort()` e `Sort(Comparison<object>)` → [P-CODE ERROR]
         * "Ambiguous match found" (minitest collections/list_methods_parity). Si filtra per
         * ARITÀ (più i parametri opzionali) come fa il dispatcher PCode, preferendo
         * l'overload con il minor numero di parametri compatibile. */
        var m = t.GetMethods(System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance)
            .Where(mm => mm.Name.Equals(methodName, StringComparison.OrdinalIgnoreCase)
                         && !mm.IsSpecialName
                         && mm.GetParameters().Length >= args.Length
                         && (mm.GetParameters().Length == args.Length
                             || mm.GetParameters().Skip(args.Length).All(pp => pp.IsOptional)))
            .OrderBy(mm => mm.GetParameters().Length)
            .FirstOrDefault()
            ?? throw new NotSupportedException($"Backend IL: metodo runtime '{methodName}' non trovato su '{t.Name}'.");
        try
        {
            // Coercizione argomenti BASIC (double/string) al tipo dei parametri C#. Senza,
            // reflection fallisce (es. SparseSet.Add(double) su Add(int), o Cache.Set(key,
            // value, ttl) dove il TTL numerico va convertito in TimeSpan DA SECONDI).
            var ps = m.GetParameters();
            for (var ai = 0; ai < args.Length && ai < ps.Length; ai++)
            {
                if (args[ai] == null || ps[ai].ParameterType.IsInstanceOfType(args[ai])) continue;
                var pt = ps[ai].ParameterType;
                if (pt == typeof(int)) args[ai] = (int)Convert.ToDouble(args[ai]);
                else if (pt == typeof(long)) args[ai] = (long)Convert.ToDouble(args[ai]);
                else if (pt == typeof(short)) args[ai] = (short)Convert.ToDouble(args[ai]);
                else if (pt == typeof(byte)) args[ai] = (byte)Convert.ToDouble(args[ai]);
                else if (pt == typeof(float)) args[ai] = (float)Convert.ToDouble(args[ai]);
                else if (pt == typeof(double)) args[ai] = Convert.ToDouble(args[ai]);
                else if (pt == typeof(bool)) args[ai] = Convert.ToDouble(args[ai]) != 0;
                else if (pt == typeof(string)) args[ai] = args[ai]?.ToString() ?? "";
                else if (pt == typeof(DateTime)) args[ai] = DateTime.FromOADate(Convert.ToDouble(args[ai]));
                else if (pt == typeof(DateTimeOffset))
                    args[ai] = args[ai] is DateTime dt0
                        ? new DateTimeOffset(dt0)
                        : new DateTimeOffset(DateTime.FromOADate(Convert.ToDouble(args[ai])));
                else if (pt == typeof(TimeSpan))
                    args[ai] = System.TimeSpan.FromSeconds(Convert.ToDouble(args[ai]));
                else if (pt == typeof(TimeSpan?))
                    args[ai] = System.TimeSpan.FromSeconds(Convert.ToDouble(args[ai]));
            }
            // Reflection NON applica i parametri opzionali (C# default) a Invoke: riempie
            // i mancanti (es. Cache.Set(key, value) → Set(TKey,TValue,TimeSpan?) con il
            // TTL a null), altrimenti TargetParameterCountException.
            if (args.Length < ps.Length)
            {
                var full = new object?[ps.Length];
                Array.Copy(args, full, args.Length);
                for (var ai = args.Length; ai < ps.Length; ai++)
                    full[ai] = ps[ai].HasDefaultValue
                        ? ps[ai].DefaultValue
                        : (ps[ai].ParameterType.IsValueType ? Activator.CreateInstance(ps[ai].ParameterType) : null);
                args = full;
            }
            return m.Invoke(instance, args);
        }
        catch (System.Reflection.TargetInvocationException tie) { throw tie.InnerException ?? tie; }    }

    /// <summary>ToDict(dict): copia IDictionary in un nuovo Dictionary<object,object?> —
    /// stessa semantica del VM (case BuiltInFunction.TODICT).</summary>
    public static object? ToDict(object? source)
    {
        if (source is not System.Collections.IDictionary d) return null;
        var nd = new Dictionary<object, object?>();
        foreach (System.Collections.DictionaryEntry de in d) nd[de.Key] = de.Value;
        return nd;
    }

    /// <summary>MyList.Join(sep): unisce gli elementi della collezione (IEnumerable) con il
    /// separatore — equivalente BASIC del JOIN su collection, non String.Join dei CLR.</summary>
    public static string CollectionJoin(object? collection, object? separator)
    {
        if (collection is not System.Collections.IEnumerable en) return string.Empty;
        var sep = separator?.ToString() ?? string.Empty;
        return string.Join(sep, en.Cast<object?>().Select(v => v?.ToString() ?? string.Empty));
    }

    /// <summary>IIF(cond, a, b): ritorna a se cond è vera (nonzero), altrimenti b — stessa
    /// semantica del VM (case BuiltInFunction.IIF).</summary>
    public static object? Iif(double condition, object? a, object? b) => condition != 0 ? a : b;

    /// <summary>CHOOSE(index, values...): 1-based index nella lista valori (ParamArray).</summary>
    public static object? Choose(double index, object?[] values)
        => index >= 1 && index <= values.Length ? values[(int)index - 1] : null;

    /// <summary>VALTYPE(value): lettera del tipo Clipper (C/N/L/D/U...) — delega a ClipperStrings.</summary>
    public static string ValType(object? value) => value switch
    {
        null => CommonLib.Consoles.Tui.NativeValtype.Letter(CommonLib.Consoles.Tui.NativeValtype.NIL),
        string or char => CommonLib.Consoles.Tui.NativeValtype.Letter(CommonLib.Consoles.Tui.NativeValtype.STRING),
        bool => CommonLib.Consoles.Tui.NativeValtype.Letter(CommonLib.Consoles.Tui.NativeValtype.BOOL),
        DateTime => CommonLib.Consoles.Tui.NativeValtype.Letter(CommonLib.Consoles.Tui.NativeValtype.DATETIME),
        byte or short or int or long => CommonLib.Consoles.Tui.NativeValtype.Letter(CommonLib.Consoles.Tui.NativeValtype.INT),
        float or double or decimal => CommonLib.Consoles.Tui.NativeValtype.Letter(CommonLib.Consoles.Tui.NativeValtype.DOUBLE),
        System.Collections.IDictionary d when d.Contains("__class__")
            => CommonLib.Consoles.Tui.NativeValtype.Letter(CommonLib.Consoles.Tui.NativeValtype.OBJECT),
        System.Collections.ICollection
            => CommonLib.Consoles.Tui.NativeValtype.Letter(CommonLib.Consoles.Tui.NativeValtype.ARRAY),
        _ => CommonLib.Consoles.Tui.NativeValtype.Letter(CommonLib.Consoles.Tui.NativeValtype.OBJECT),
    };

    /// <summary>CTYPE generico (value, "TYPE") — coercizione runtime (parità
    /// PCodeProcessor.CTYPE: STRING→ToString, INTEGER/INT/LONG→(long), DOUBLE/SINGLE/FLOAT→double,
    /// BOOLEAN/BIT→-1/0; fallback = valore invariato).</summary>
    public static object? CTypeGeneric(object? value, string? typeName)
    {
        switch ((typeName ?? "").ToUpperInvariant())
        {
            case "STRING": return value?.ToString() ?? "";
            case "INTEGER": case "INT": case "LONG": return (double)(long)Convert.ToDouble(value ?? 0.0);
            case "DOUBLE": case "SINGLE": case "FLOAT": return Convert.ToDouble(value ?? 0.0);
            case "BOOLEAN": case "BIT": return Convert.ToDouble(value ?? 0.0) != 0.0 ? -1.0 : 0.0;
            default: return value;
        }
    }

    /// <summary>CONFIRM(msg [, default]) — in headless conferma sempre (ritorna TRUE),
    /// stessa convenzione del VM quando non c'è UI.</summary>
    /// <summary>Mappa un indice palette (VGA256) a CellColor, per i parametri fg/bg dei dialog.</summary>
    private static CommonLib.Screens.CellColor? IndexToCellColor(int idx)
    {
        if (idx < 0) return null;
        try
        {
            var pal = CommonLib.Screens.PaletteManager.GetPalette("VGA256");
            if (idx < pal.Length)
            {
                var c = pal[idx];
                return c.Length >= 3 ? new CommonLib.Screens.CellColor { R = c[0], G = c[1], B = c[2] } : null;
            }
        }
        catch { }
        return null;
    }

    /// <summary>CONFIRM("msg"[, width[, align[, fg[, bg[, border[, buttons]]]]]]) → indice
    /// pulsante (1-based) o 0 se chiusa. Runtime comune con la PCodeVM: usa AlertBox con le
    /// etichette dei pulsanti (costanti %OKCANCEL=101/%YESNO=102/...), stessa logica del case
    /// BuiltInFunction.CONFIRM del PCode.</summary>
    public static double Confirm(string? message, double width = 0, double align = 1, double fg = -1,
        double bg = -1, double border = 1, double buttons = 0)
    {
        try
        {
            // Headless: nessuna finestra modale (parità PCode/VM-C/C99Native,
            // niente render a schermo) → 0.
            if (Current.Console is Basic.Runtime.Services.HeadlessConsoleService) return 0.0;
            var msg = message ?? "";
            var alignI = (int)align;
            var fgI = (int)fg;
            var bgI = (int)bg;
            var borderI = (int)border;
            var buttonsI = (int)buttons;
            /* Via UNICA C (AlertBox): nessuna proprietà persa (pulsanti/align/width/border/colori). */
            int alC = alignI switch { 0 => 0, 2 => 2, _ => 1 };           /* 0=Left 1=Center 2=Right */
            int brdC = borderI switch { 0 => 3, 2 => 1, 3 => 2, _ => 0 };  /* GMB_PB_* */
            var fgc = fgI >= 0 ? IndexToCellColor(fgI) : null;
            var bgc = bgI >= 0 ? IndexToCellColor(bgI) : null;
            string? l0 = null, l1 = null, l2 = null;
            if (buttonsI > 100)
            {
                var labels = buttonsI switch
                {
                    101 => new[] { "OK", "Cancel" },
                    102 => new[] { "Yes", "No" },
                    103 => new[] { "Yes", "No", "Cancel" },
                    104 => new[] { "Abort", "Retry", "Ignore" },
                    105 => new[] { "Retry", "Cancel" },
                    _ => new[] { "OK", "Cancel" },
                };
                if (labels.Length > 0) l0 = labels[0];
                if (labels.Length > 1) l1 = labels[1];
                if (labels.Length > 2) l2 = labels[2];
            }
            int r = Basic.Runtime.Services.NativeTui.AlertEx(msg, l0, l1, l2, alC,
                width > 0 ? (int)width : 0, brdC,
                fgc != null ? 1 : 0, fgc?.R ?? 0, fgc?.G ?? 0, fgc?.B ?? 0,
                bgc != null ? 1 : 0, bgc?.R ?? 0, bgc?.G ?? 0, bgc?.B ?? 0);
            return (double)r;
        }
        catch { return 1.0; }
    }

    /// <summary>STRINGIFY(value) = JsonSerializer.Serialize — stessa semantica del VM
    /// (case BuiltInFunction.STRINGIFY).</summary>
    public static string Stringify(object? value)
        => System.Text.Json.JsonSerializer.Serialize(NormalizeForJson(value));

    /// <summary>Normalizza un valore per la serializzazione JSON: le struct UDT dell'IL
    /// (campi public, JsonSerializer li ignora di default → "{}") vengono mappate su un
    /// Dictionary dai campi; dict/list ricorsivi vengono copiati per uniformità. Parità
    /// VM/PCode (dove gli UDT sono già dict).</summary>
    /* internal: usato anche da PCodeHttpResponse.SendJson (stesso assembly) per serializzare la
     * risposta HTTP con la STESSA normalizzazione di JSON.STRINGIFY (prima SendJson usava
     * SerializeToUtf8Bytes crudo -> un DateTime usciva "" invece dell'ISO). */
    internal static object? NormalizeForJson(object? value)
    {
        if (value == null) return null;
        // Canone data/ora (NOW/TODAY/DATETIME): in JSON un datetime e' una stringa ISO-8601.
        // Senza questo, il DateTime (value-type non primitivo, nessun campo pubblico) finiva nel
        // ramo struct-dict sotto -> "{}" (HttpSession: timestamp {} su IL/PCode vs seriale su C).
        if (value is DateTime dtVal)
            return dtVal.ToString("yyyy-MM-ddTHH:mm:ss", System.Globalization.CultureInfo.InvariantCulture);
        if (value is TimeSpan tsVal)
            return tsVal.ToString("c", System.Globalization.CultureInfo.InvariantCulture);
        // PCode: le date/ore sono DateValue (OADate). Stessa resa ISO-8601 del DateTime (il
        // PCodeDateValueJsonConverter faceva "o" con offset/frazione -> ora formato unico).
        if (value is Basic.IlBackend.PCode.PCodeProcessor.DateValue dvVal)
            return DateTime.SpecifyKind(DateTime.FromOADate(dvVal.OADate), DateTimeKind.Local)
                .ToString("yyyy-MM-ddTHH:mm:ss", System.Globalization.CultureInfo.InvariantCulture);
        var t = value.GetType();
        // KeyValuePair<K,V> (coppie di ToArray() su TREE/AVL/REDBLACK, Min/Max/Extract*):
        // Key/Value sono PROPRIETÀ su campi privati, quindi il ramo struct sotto ("campi
        // pubblici") non trovava nulla e il JSON usciva "{},{},{}". Forma canonica del canone
        // P-Code/VM-C: {"Key":…,"Value":…}.
        if (t.IsGenericType && t.GetGenericTypeDefinition() == typeof(KeyValuePair<,>))
        {
            var kvp = new Dictionary<string, object?>
            {
                ["Key"] = NormalizeForJson(t.GetProperty("Key")!.GetValue(value)),
                ["Value"] = NormalizeForJson(t.GetProperty("Value")!.GetValue(value)),
            };
            return kvp;
        }
        if (t.IsValueType && !t.IsPrimitive && !t.IsEnum)
        {
            var dict = new Dictionary<string, object?>();
            foreach (var fi in t.GetFields(System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance))
                dict[fi.Name] = NormalizeForJson(fi.GetValue(value));
            return dict;
        }
        if (value is System.Collections.IDictionary d)
        {
            // Istanza UDT/CLASS: il dict porta un descriptor "__class__" (e talvolta
            // "__closure__") di bookkeeping — va ESCLUSO dal JSON utente, come fanno i backend
            // C (layout UDT → solo i campi). Senza questo, JSON.ToJson(udt) emetteva il
            // descriptor della classe (FieldOffsets/SourceToken/...) insieme ai campi.
            bool isUdt = d.Contains("__class__");
            var dict = new Dictionary<string, object?>();
            foreach (System.Collections.DictionaryEntry kv in d)
            {
                var k = kv.Key?.ToString() ?? "";
                if (isUdt && (k == "__class__" || k == "__closure__")) continue;
                dict[k] = NormalizeForJson(kv.Value);
            }
            return dict;
        }
        if (value is System.Collections.IList list)
        {
            var arr = new object?[list.Count];
            for (int i = 0; i < list.Count; i++) arr[i] = NormalizeForJson(list[i]);
            return arr;
        }
        return value;
    }
    public static string CharToString(char c) => c.ToString();

    /// <summary>INKEY/INKEY$ — legge un tasto (intercept) e restituisce il char.</summary>
    /// <summary>Bridge col KeyboardService headless dell'host (HeadlessRuntimeHost.QueueKey /
    /// HeadlessKeyboardService.QueueInputString): i runner test console (`test_ilrun`) iniettano
    /// i tasti QUI, NON nella coda statica InkeyQueue — senza questo poll INKEY/WAITKEY/GET
    /// restavano in TIMEOUT (IlRuntime-InkeyQueue-KeyboardService-Bug). Solo headless: il
    /// servizio console reale continua col fallback System.Console.ReadKey.</summary>
    private static string? TryPollHeadlessKeyboard()
    {
        try
        {
            if (Current.Keyboard is HeadlessKeyboardService hs && hs.TryReadKey() is { } tki && tki.KeyChar != '\0')
                return tki.KeyChar.ToString();
        }
        catch { }
        return null;
    }

    /// <summary>INPUT/LINE INPUT: legge una riga dal KeyboardService dell'host — parità PCodeVM
    /// (SysCall.INPUT → _runtime.Keyboard.ReadLine). Così QueueLine/QueueInputString headless
    /// raggiungono INPUT (prima: System.Console.ReadLine diretto → i runner test restavano in
    /// attesa/blocco). Fallback su System.Console.ReadLine quando nessuna riga è iniettata o
    /// l'host non è impostato.</summary>
    public static string ReadLine()
    {
        try
        {
            if (Current.Keyboard is { } kb)
            {
                var line = kb.ReadLine(null);
                if (line != null) return line;
            }
        }
        catch { }
        // FONTE UNICA: quando IlConsoleKeyFeeder è attivo, la console è drenata dal feeder
        // nella coda InkeyQueue (ReadKey intercept su stdin). System.Console.ReadLine QUI
        // competerebbe col feeder (i caratteri digitati finirebbero nella coda, non nella
        // riga) — invece si ricostruisce la riga dai tasti della coda (Enter=\r, Backspace=\b),
        // stesso contratto di INPUT/LINE INPUT quando l'host fornisce il KeyboardService.
        if (IlConsoleKeyFeeder.IsActive)
        {
            var sb = new System.Text.StringBuilder();
            while (true)
            {
                ThrowIfAborted();
                if (!TryDequeueInkey(out var k)) { Thread.Sleep(5); continue; }
                if (k == "\r" || k == "\n") break;
                if (k == "\b")
                {
                    if (sb.Length > 0) sb.Length--;
                    continue;
                }
                sb.Append(k);
            }
            return sb.ToString();
        }
        return System.Console.ReadLine() ?? string.Empty;
    }

    public static string Inkey()
    {
        ThrowIfAborted();
        if (TryDequeueInkey(out var key)) return key;
        var hostKey = TryPollHeadlessKeyboard();
        if (hostKey != null)
        {
            DispatchKeyEvent(hostKey);
            ProcessKeyForActiveWindow(hostKey);
            return hostKey;
        }
        // INKEY SEMPRE NON-BLOCCANTE (semantica Clipper INKEY()=""): un poll sincrono di
        // Console.KeyAvailable qui nel percorso lineare bloccherebbe e — peggio — se
        // chiamato dal worker GPM congelerebbe l'intero scheduler. La console reale per
        // IL è coperta dai metodi BLOCCANTI (WAITKEY/GET → ReadKey, Inkey(timeout)).
        return "";
    }

    /// <summary>INKEY/WAITKEY: attiva gli ON KEY registrati (EventDispatcher, lo stesso
    /// dispatcher della PCodeVM) per il tasto letto — parità col case VM che chiamava
    /// DispatchKeyEvent dopo la lettura. Ignora i modifier (come RegisterKeyHandler che
    /// registra con mods=0).</summary>
    private static void DispatchKeyEvent(string key)
    {
        try
        {
            if (string.IsNullOrEmpty(key)) return;
            CommonLib.App.EventDispatcher.Instance.DispatchKey(
                new CommonLib.Keyboard.KeyCombination((ConsoleKey)key[0], 0));
        }
        catch { }
    }

    /// <summary>Se la finestra attiva è editable, il tasto letto (INKEY/WAITKEY) viene
    /// processato dal WindowManager (editing/clipboard) sul buffer della finestra.</summary>
    private static void ProcessKeyForActiveWindow(string key)
    {
        try
        {
            if (string.IsNullOrEmpty(key)) return;
            var c = key[0];
            var keyCode = c switch
            {
                '\r' => ClipperLib.Clipper.KeyConstants.K_ENTER,
                '\b' => ClipperLib.Clipper.KeyConstants.K_BS,
                '\t' => ClipperLib.Clipper.KeyConstants.K_TAB,
                '\x1b' => ClipperLib.Clipper.KeyConstants.K_ESC,
                _ => (int)c,
            };
            var mods = ClipperLib.Clipper.KeyModifiers.None;
            if (c == '\x03') mods = ClipperLib.Clipper.KeyModifiers.Control;

            // Finestra PIXEL attiva → editing diretto sul buffer pixel.
            if (ActivePixelWindow() is { } pw && pw.Editable)
            {
                ProcessEditKeyPixel(pw, keyCode);
                RenderPixelWindows();
                return;
            }

            var aw = ActiveWindowObj();
            if (aw is null || !aw.Editable) return;
            var wm = TuiWindows;
            wm.ProcessKeyOnActive(keyCode, mods);
            RenderTuiWindows();
        }
        catch { }
    }

    /// <summary>Editing da tastiera sul buffer di una finestra PIXEL (frecce, Enter,
    /// Backspace, caratteri stampabili, Home/End). Replica la semantica di
    /// WindowManager.HandleEditKey ma sul PixelWindow.</summary>
    private static void ProcessEditKeyPixel(CommonGraphics.Graphics.PixelWindow pw, int key)
    {
        var cr = pw.ClientRect;
        var rows = Math.Max(1, cr.h / Math.Max(1, CommonGraphics.Graphics.GfxWindowManager.CharHeight()));
        var cols = Math.Max(1, cr.w / Math.Max(1, CommonGraphics.Graphics.GfxWindowManager.CharWidth()));
        switch (key)
        {
            case ClipperLib.Clipper.KeyConstants.K_UP:
                if (pw.CursorLine > 0) pw.CursorLine--;
                if (pw.CursorLine < pw.ScrollOffset) pw.ScrollOffset = pw.CursorLine;
                break;
            case ClipperLib.Clipper.KeyConstants.K_DOWN:
                if (pw.CursorLine < pw.Lines.Count - 1) pw.CursorLine++;
                if (pw.CursorLine >= pw.ScrollOffset + rows) pw.ScrollOffset = pw.CursorLine - rows + 1;
                break;
            case ClipperLib.Clipper.KeyConstants.K_LEFT:
                if (pw.CursorCol > 0) pw.CursorCol--;
                break;
            case ClipperLib.Clipper.KeyConstants.K_RIGHT:
                if (pw.Lines.Count > 0 && pw.CursorLine < pw.Lines.Count && pw.CursorCol < pw.Lines[pw.CursorLine].Length)
                    pw.CursorCol++;
                break;
            case ClipperLib.Clipper.KeyConstants.K_ENTER:
                if (pw.Lines.Count == 0) pw.Lines.Add("");
                var rest = pw.Lines[pw.CursorLine][pw.CursorCol..];
                pw.Lines[pw.CursorLine] = pw.Lines[pw.CursorLine][..pw.CursorCol];
                pw.Lines.Insert(pw.CursorLine + 1, rest);
                pw.CursorLine++;
                pw.CursorCol = 0;
                if (pw.CursorLine >= pw.ScrollOffset + rows) pw.ScrollOffset = pw.CursorLine - rows + 1;
                break;
            case ClipperLib.Clipper.KeyConstants.K_BS:
                if (pw.Lines.Count == 0) break;
                if (pw.CursorCol > 0)
                {
                    pw.Lines[pw.CursorLine] = pw.Lines[pw.CursorLine].Remove(pw.CursorCol - 1, 1);
                    pw.CursorCol--;
                }
                else if (pw.CursorLine > 0)
                {
                    var prevLen = pw.Lines[pw.CursorLine - 1].Length;
                    pw.Lines[pw.CursorLine - 1] += pw.Lines[pw.CursorLine];
                    pw.Lines.RemoveAt(pw.CursorLine);
                    pw.CursorLine--;
                    pw.CursorCol = prevLen;
                }
                break;
            case ClipperLib.Clipper.KeyConstants.K_HOME: pw.CursorCol = 0; break;
            case ClipperLib.Clipper.KeyConstants.K_END:
                if (pw.Lines.Count > 0 && pw.CursorLine < pw.Lines.Count) pw.CursorCol = pw.Lines[pw.CursorLine].Length;
                break;
            default:
                if (key is >= 32 and <= 126)
                {
                    if (pw.Lines.Count == 0) pw.Lines.Add("");
                    var line = pw.Lines[pw.CursorLine];
                    if (line.Length < cols)
                    {
                        pw.Lines[pw.CursorLine] = line.Insert(pw.CursorCol, ((char)key).ToString());
                        pw.CursorCol++;
                    }
                }
                break;
        }
    }

    private static readonly object InkeyQueueLock = new();
    private static readonly System.Collections.Generic.Queue<string> InkeyQueue = new();

    /// <summary>Task GPM parcheggiati su WAITKEY (§bug ILBackend-Gpm-Stepper-For-FrameChain-Hang):
    /// prima di questo fix, WAITKEY chiamava <see cref="ReadKey"/> direttamente anche dentro
    /// uno stepper, bloccando SINCRONAMENTE il thread del driver GPM (spin-wait con
    /// Thread.Sleep) invece di parcheggiare cooperativamente il task — congelando l'INTERO
    /// scheduler (nessun altro task può avanzare, incluso il pump grafico se gira sullo
    /// stesso thread) finché non arriva un tasto. Questa lista fa da "waiter registry" (stesso
    /// pattern di RegisterWaiter in GpmCore.cs/ChannelInfo): IlGpmRuntime.TryWaitKeyPark
    /// registra qui il task se la coda è vuota, QueueInkey sveglia (Task.Wake) tutti i
    /// waiter registrati quando arriva un nuovo tasto -- ognuno ri-controlla la coda al
    /// prossimo tick (TryDequeueInkey), niente valore "riservato" per task specifico (chi
    /// arriva prima consuma, gli altri ri-parcheggiano se la coda è di nuovo vuota).</summary>
    private static readonly System.Collections.Generic.List<PCodeTask> InkeyWaiters = new();

    /// <summary>Dequeue non bloccante di un tasto, se disponibile. Usato sia da
    /// <see cref="ReadKey"/> (percorso lineare) sia da
    /// <see cref="IlGpmRuntime.TryWaitKeyPark"/> (che parcheggia cooperativamente).</summary>
    internal static bool TryDequeueInkey(out string key)
    {
        lock (InkeyQueueLock)
        {
            if (InkeyQueue.Count > 0)
            {
                key = InkeyQueue.Dequeue();
                DispatchKeyEvent(key);
                ProcessKeyForActiveWindow(key);
                return true;
            }
        }
        key = "";
        return false;
    }

    /// <summary>Registra un task GPM come in attesa di un tasto (WAITKEY parcheggiato,
    /// coda vuota al momento del check). Vedi <see cref="InkeyWaiters"/>.</summary>
    internal static void RegisterInkeyWaiter(PCodeTask task)
    {
        lock (InkeyQueueLock)
        {
            if (!InkeyWaiters.Contains(task)) InkeyWaiters.Add(task);
        }
    }

    /// <summary>Test headless: accoda un tasto letto da INKEY$. Thread-safe. Sveglia anche
    /// ogni task GPM parcheggiato su WAITKEY (<see cref="InkeyWaiters"/>) -- senza questo, un
    /// task Blocked non viene MAI ri-schedulato dal driver (nessun riaccodo automatico, vedi
    /// IlGpm.ExecuteTaskTick), restando bloccato per sempre anche se un tasto arriva davvero.</summary>
    /// <summary>Input scriptato dai test/CI (stessa variabile delle gambe C99/VM-C):
    /// ogni carattere diventa un tasto in coda; '\n' → INVIO.</summary>
    public static void InjectScriptFromEnv()
    {
        var script = Basic.Providers.GmbEnv.Get("GMB_TUI_SCRIPT");
        if (string.IsNullOrEmpty(script)) return;
        foreach (var ch in script) QueueInkey(ch == '\n' ? "\r" : ch.ToString());
    }

    public static void QueueInkey(string key)
    {
        System.Collections.Generic.List<PCodeTask>? toWake = null;
        lock (InkeyQueueLock)
        {
            InkeyQueue.Enqueue(key);
            if (InkeyWaiters.Count > 0)
            {
                toWake = new System.Collections.Generic.List<PCodeTask>(InkeyWaiters);
                InkeyWaiters.Clear();
            }
        }
        if (toWake is not null)
            foreach (var t in toWake) t.Wake();
    }

    /// <summary>Poll NON-BLOCCANTE della console di sistema: se c'è un tasto pronto lo
    /// legge (intercept) e lo instrada al WindowManager TUI (evento UiKey con focus/
    /// editing/clipboard/TAB) e a ON KEY. <c>true</c> = c'è un tasto DA CONSEGNARE al
    /// programma (il WM non l'ha consumato); <c>false</c> = nessun tasto in attesa,
    /// oppure il tasto é stato consumato dal window manager (focus/TAB/editing/m/n/del:
    /// WAITKEY/INKEY devono RESTARE in attesa), oppure la console non è disponibile
    /// (stdin rediretto/pipe).</summary>
    /// <summary>Event-loop "finestra attiva" per la TASTIERA console (parità col pattern
    /// della grafica: IlSdlInput → coda → TryDequeueInkey, e parità col PCodeVM:
    /// GmBasicInputSource.Read → UiKey → wm.HandleEvent). Instrada il tasto al
    /// WindowManager TUI via <see cref="ClipperLib.Controls.WindowManager.HandleEvent"/>
    /// così TAB/F6 cambiano focus, Escape/n/m/Del agiscono sulle finestre e la
    /// clipboard/editing funzionano — NON solo HandleEditKey di ProcessKeyOnActive.
    /// Vedi regressione "WindowTurboVision: nessun event-loop mentre WAITKEY attende".
    /// <c>true</c> = tasto consumato dal WM: il chiamante NON lo consegna al programma.</summary>
    private static bool ProcessKeyForActiveWindow(ConsoleKeyInfo cki)
    {
        try
        {
            if (_tuiWindows is not { } wm || wm.WindowCount == 0) return false;
            var keyCode = ClipperLib.App.GmBasicInputSource.ToInternalKey(cki);
            var mods = ClipperLib.Clipper.KeyModifiers.None;
            if (cki.Modifiers.HasFlag(ConsoleModifiers.Shift)) mods |= ClipperLib.Clipper.KeyModifiers.Shift;
            if (cki.Modifiers.HasFlag(ConsoleModifiers.Alt)) mods |= ClipperLib.Clipper.KeyModifiers.Alt;
            if (cki.Modifiers.HasFlag(ConsoleModifiers.Control)) mods |= ClipperLib.Clipper.KeyModifiers.Control;
            var consumed = wm.HandleEvent(new ClipperLib.Clipper.UiKey(keyCode, mods));
            if (consumed) RenderTuiWindows();
            return consumed;
        }
        catch { return false; }
    }

    /// <summary>GET/WAITKEY: come la PCodeVM di GMBasic (Keyboard.ReadKey bloccante).
    /// Con grafica reale (SdlGraphicsService, anche dummy) attende la coda INKEY
    /// alimentata da SDL o da <c>--key</c>. NullGraphicsService → no-op (test senza runner).</summary>
    public static string ReadKey()
    {
        bool graphicsAttached;
        try { graphicsAttached = Current.Graphics.IsAvailable; }
        catch { graphicsAttached = false; }
        if (!graphicsAttached)
        {
            // WAITKEY senza grafica: attesa LINEARE (percorso non-GPM: il thread corrente
            // è quello del programma, nessuno scheduler da congelare). Poll non bloccante
            // della coda + Console.KeyAvailable — MAI fuori da qui: questo metodo non è
            // mai chiamato dal worker GPM (lì esiste TryWaitKeyPark, park cooperativo).
            while (true)
            {
                ThrowIfAborted();
                if (TryDequeueInkey(out var key)) return key;
                var hostKey = TryPollHeadlessKeyboard();
                if (hostKey != null)
                {
                    DispatchKeyEvent(hostKey);
                    ProcessKeyForActiveWindow(hostKey);
                    return hostKey;
                }
                // FONTE UNICA: feeder attivo → la console è già drenata nella coda (il poll
                // TryDequeueInkey sopra la consuma); il fallback System.Console competerebbe.
                if (!IlConsoleKeyFeeder.IsActive)
                {
                    try
                    {
                        if (System.Console.KeyAvailable)
                        {
                            var ks = System.Console.ReadKey(true);
                            ProcessKeyForActiveWindow(ks);
                            return ks.KeyChar.ToString();
                        }
                    }
                    catch { return ""; }
                }
                Thread.Sleep(10);
            }
        }
        while (true)
        {
            ThrowIfAborted();
            if (TryDequeueInkey(out var key)) return key;
            var hostKey = TryPollHeadlessKeyboard();
            if (hostKey != null)
            {
                ProcessKeyForActiveWindow(hostKey);
                return hostKey;
            }
            Thread.Sleep(20);
        }
    }

    /// <summary>SET PRINTER/DEVICE: instrada il testo PRINT alla stampante virtuale Clipper.</summary>
    private static int _ilPrintColumn;
    public static void WritePrinter(string text, bool newLine)
    {
        // SOLO se la stampante virtuale è attiva, cioè se un comando grafico/stampante ha già
        // creato il servizio (`SET PRINTER` passa da `Current.Graphics` e lo crea). Leggere la
        // proprietà pigra qui la creava a OGNI PRINT → caricava libgmb_gfx + SDL (~8 MB).
        var g = (Current as Runtime.HeadlessRuntimeHost)?.CreatedGraphics;
        try { g?.ClipperPrinterWrite(text ?? "", newLine); } catch { }
        lock (_ilPrintSync) { if (newLine) _ilPrintColumn = 0; else _ilPrintColumn += (text?.Length ?? 0); }
    }
    private static readonly object _ilPrintSync = new();
    // Parità VM (OP_PRINT_TAB_ZONE): la virgola di PRINT allinea alla zona di 14
    // caratteri successiva — padding '14 - (col % 14)' con colonna tracciata.
    // Ritorna SOLO la stringa di spazi; la scrittura (printer + colonna + console)
    // la fa il pattern PRINT standard (WritePrinter/ConsolePrint) nel chiamante.
    public static string PrintTabZone()
    {
        var padding = 14 - (_ilPrintColumn % 14);
        if (padding <= 0) padding = 14;
        return new string(' ', padding);
    }
    /// <summary>SET legacy Clipper dall'IL: applica lo stato Clipper (subCode 6-16).</summary>
    public static void SetClipperCmd(int subCode, string value)
    {
        try
        {
            switch (subCode)
            {
                case 6: Current.Graphics.ClipperSetWrap(IsOn(value)); break;
                case 7: Current.Graphics.ClipperSetEscape(IsOn(value)); break;
                case 8: Current.Graphics.ClipperSetDelimiters(value); break;
                case 9: if (int.TryParse(value, out var ta)) Current.Graphics.ClipperSetTypeahead(ta); break;
                case 10: Current.Graphics.ClipperSetIntensity(IsOn(value)); break;
                case 11: if (int.TryParse(value, out var ep)) Current.Graphics.ClipperSetEpoch(ep); break;
                case 12: if (int.TryParse(value, out var dc)) Current.Graphics.ClipperSetDecimals(dc); break;
                case 13: Current.Graphics.ClipperSetFixed(IsOn(value)); break;
                case 14: Current.Graphics.ClipperSetPrinter(IsOn(value)); break;
                case 15: Current.Graphics.ClipperSetDevice(value.Trim().ToUpperInvariant()); break;
                case 16: if (int.TryParse(value, out var mr)) Current.Graphics.ClipperSetMessage(mr); break;
            }
        }
        catch { }
    }
    private static bool IsOn(string v) => v.Equals("TRUE", StringComparison.OrdinalIgnoreCase) || v == "1";

    /// <summary>True se SET DEVICE TO PRINTER (output SOLO stampante, nessun video).</summary>
    public static bool PrinterOnly()
    {
        // Come WritePrinter: "solo stampante" può essere vero solo se il servizio esiste già
        // (SET DEVICE TO PRINTER lo crea). Non si crea il motore grafico per chiederlo.
        var g = (Current as Runtime.HeadlessRuntimeHost)?.CreatedGraphics;
        try { return g?.ClipperPrinterOnly() == true; } catch { return false; }
    }

    /// <summary>INKEY con timeout in millisecondi: attende fino a timeoutMs (polling non
    /// bloccante); scaduto → "" (semantica Clipper INKEY()=""). timeoutMs &lt;= 0 → bloccante.</summary>
    public static string Inkey(int timeoutMs)
    {
        if (timeoutMs <= 0) return Inkey();
        var sw = System.Diagnostics.Stopwatch.StartNew();
        while (true)
        {
            ThrowIfAborted();
            if (TryDequeueInkey(out var key)) return key;
            var hostKey = TryPollHeadlessKeyboard();
            if (hostKey != null)
            {
                DispatchKeyEvent(hostKey);
                ProcessKeyForActiveWindow(hostKey);
                return hostKey;
            }
            if (sw.ElapsedMilliseconds >= timeoutMs) return "";
            bool graphicsAttached;
            try { graphicsAttached = Current.Graphics.IsAvailable; }
            catch { graphicsAttached = false; }
            if (graphicsAttached)
            {
                Thread.Sleep(10);
                continue;
            }
            // Console reale: attesa LINEARE (percorso non-GPM) con poll non bloccante —
            // solo in questo metodo, mai nel worker GPM (lì TryWaitKeyPark parcheggia).
            // FONTE UNICA: feeder attivo → la console è già drenata nella coda (TryDequeueInkey
            // sopra); il fallback System.Console competerebbe.
            if (!IlConsoleKeyFeeder.IsActive)
            {
                try
                {
                    if (System.Console.KeyAvailable)
                    {
                        var ks = System.Console.ReadKey(true);
                        ProcessKeyForActiveWindow(ks);
                        return ks.KeyChar.ToString();
                    }
                }
                catch { return ""; }
            }
            Thread.Sleep(10);
        }
    }

    // ── JSON I/O ──────────────────────────────────────────────────────
    public static void JsonSave(object source, string filePath)
    {
        var json = System.Text.Json.JsonSerializer.Serialize(source);
        File.WriteAllText(filePath, json, Encoding.UTF8);
    }

    public static void JsonWriteValue(string key, object value, string? section)
    {
        // Scrive key=value in app.settings.json (formato INI, compatibile con ReadValue).
        var file = Path.Combine(Directory.GetCurrentDirectory(), "app.settings.json");
        CommonLib.FileReadWriteUtils.WriteValue(file, section ?? "", key, Convert.ToString(value, CultureInfo.InvariantCulture) ?? "");
    }

    public static void JsonWriteSection(object source, string? section)
    {
        // Scrive i campi di source (DICT/UDT) come sezione in app.settings.json.
        var file = Path.Combine(Directory.GetCurrentDirectory(), "app.settings.json");
        var values = new System.Collections.Generic.Dictionary<string, object?>();
        if (source is System.Collections.IDictionary d)
        {
            foreach (System.Collections.DictionaryEntry e in d)
                values[Convert.ToString(e.Key, CultureInfo.InvariantCulture) ?? ""] = e.Value;
        }
        else
        {
            // UDT: estrae i campi pubblici (l'UDT è un struct con campi, non property).
            var t = source?.GetType();
            if (t != null)
            {
                foreach (var f in t.GetFields(System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance))
                    values[f.Name] = f.GetValue(source);
                if (values.Count == 0)
                    foreach (var p in t.GetProperties(System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance))
                    {
                        if (p.CanRead) values[p.Name] = p.GetValue(source);
                    }
            }
        }
        CommonLib.FileReadWriteUtils.WriteSection(file, section ?? "", values);
    }

    // ── TUI Drawing ──────────────────────────────────────────────────
    private static readonly object _tuiLock = new();

    public static void DrawBox(int top, int left, int bottom, int right, string? border)
    {
        // Finestra attiva → box nel buffer della finestra (coordinate relative alla viewport).
        if (ActivePixelWindow() is { } pw)
        {
            try { pw.BoxAt(top, left, bottom, right, border); RenderPixelWindows(); } catch { }
            return;
        }
        if (ActiveWindowObj() is { } aw)
        {
            try { aw.BoxAt(top, left, bottom, right, border); RenderTuiWindows(); } catch { }
            return;
        }
        var b = (border ?? "single") switch { "double" => "╔═╗║║╚═╝", "none" => "", _ => "┌─┐││└─┘" };
        if (b.Length < 8) return;
        lock (_tuiLock)
        {
            for (int x = left; x <= right; x++)
            {
                Console.SetCursorPosition(x, top); Console.Write(b[1]);
                Console.SetCursorPosition(x, bottom); Console.Write(b[6]);
            }
            for (int y = top; y <= bottom; y++)
            {
                Console.SetCursorPosition(left, y); Console.Write(b[3]);
                Console.SetCursorPosition(right, y); Console.Write(b[4]);
            }
            Console.SetCursorPosition(left, top); Console.Write(b[0]);
            Console.SetCursorPosition(right, top); Console.Write(b[2]);
            Console.SetCursorPosition(left, bottom); Console.Write(b[5]);
            Console.SetCursorPosition(right, bottom); Console.Write(b[7]);
        }
    }

    /// <summary>Legge un array nativo BASIC di punti poligono (double[]: [x1,y1,x2,y2,...])
    /// e lo appiattisce in float[] per IGraphicsService.Polygon. Valori non numerici → 0.</summary>
    public static float[] ReadPolygonPoints(object? points)
    {
        var result = new System.Collections.Generic.List<float>();
        switch (points)
        {
            case double[] da: foreach (var v in da) result.Add((float)v); break;
            case int[] ia: foreach (var v in ia) result.Add(v); break;
            case System.Collections.IEnumerable en:
                foreach (var item in en)
                {
                    if (item is double d) result.Add((float)d);
                    else if (item is int i) result.Add(i);
                    else if (item is float f) result.Add(f);
                    else if (item is System.IConvertible cv) { try { result.Add(cv.ToSingle(System.Globalization.CultureInfo.InvariantCulture)); } catch { result.Add(0f); } }
                    else if (item.GetType().IsValueType)
                    {
                        // Array di TYPE (es. Point2D[] con campi X/Y): POLYGON punti_udt(), colore
                        // — prima leggeva 0 per ogni struct (nessun campo letto) → poligono mai
                        // disegnato. Parità GMO: legge i campi X e Y della struct.
                        var t = item.GetType();
                        var fx = t.GetField("X");
                        var fy = t.GetField("Y");
                        if (fx != null && fy != null)
                        {
                            try
                            {
                                result.Add(Convert.ToSingle(fx.GetValue(item), System.Globalization.CultureInfo.InvariantCulture));
                                result.Add(Convert.ToSingle(fy.GetValue(item), System.Globalization.CultureInfo.InvariantCulture));
                            }
                            catch { result.Add(0f); }
                        }
                        else result.Add(0f);
                    }
                    else result.Add(0f);
                }
                break;
        }
        return result.ToArray();
    }

    /// <summary>Converte un array BASIC (int[]/double[]/IEnumerable) in double[] per il
    /// runtime chart (CHART.PLOT) — schema PCodeVM CHART_PLOT.</summary>
    public static double[] ArrayToDoubleArray(object? value) => RuntimeFlatten.ToDoubles(value);

    public static double[] EmptyDoubleArray() => Array.Empty<double>();

    /// <summary>Converte un array BASIC in int[] (per TILEMAP LOAD, schema PCodeVM).</summary>
    public static int[] ArrayToIntArray(object? value)
    {
        if (value is int[] ia) return ia;
        if (value is short[] sa) return sa.Select(x => (int)x).ToArray();
        if (value is double[] da) return da.Select(x => (int)x).ToArray();
        if (value is System.Collections.IEnumerable en)
            return en.Cast<object?>().Select(v => (int)ToDouble(v)).ToArray();
        return Array.Empty<int>();
    }

    // ─── TICK / END TICK (frame pacing, schema PCodeVM TICK loop) ───
    private static int _tickStartMs;
    private static int _tickRate;

    public static void TickBegin(int rate)
    {
        _tickStartMs = Environment.TickCount;
        _tickRate = Math.Max(1, rate);
    }

    public static void TickEnd(int rate)
    {
        int target = Math.Max(1, 1000 / Math.Max(1, rate));
        int elapsed = Environment.TickCount - _tickStartMs;
        int wait = target - elapsed;
        if (wait > 0) System.Threading.Thread.Sleep(wait);
    }

    /// <summary>Copia un int[] in un array target (limite = lunghezza minore; converte il
    /// tipo elemento, es. int → short/double). Usato da SPRITE GETPIXELS e IMAGEGET.</summary>
    public static void CopyIntArrayTo(int[] src, Array dst)
    {
        if (src is null || dst is null) return;
        int n = Math.Min(src.Length, dst.Length);
        var elemType = dst.GetType().GetElementType();
        for (int i = 0; i < n; i++)
        {
            int v = src[i];
            if (elemType == typeof(short)) dst.SetValue(checked((short)v), i);
            else if (elemType == typeof(double)) dst.SetValue((double)v, i);
            else if (elemType == typeof(float)) dst.SetValue((float)v, i);
            else if (elemType == typeof(long)) dst.SetValue((long)v, i);
            else if (elemType == typeof(byte)) dst.SetValue(checked((byte)v), i);
            else if (elemType == typeof(bool)) dst.SetValue(v != 0, i);
            else dst.SetValue(v, i);
        }
    }

    public static void ClearRect(int x1, int y1, int x2, int y2)
    {
        var space = new string(' ', x2 - x1 + 1);
        lock (_tuiLock) { for (int y = y1; y <= y2; y++) { Console.SetCursorPosition(x1, y); Console.Write(space); } }
    }

    public static void DrawText(int row, int col, string text)
    {
        lock (_tuiLock) { Console.SetCursorPosition(col, row); Console.Write(text); }
    }

    /// <summary>@ SAY row, col, text — con finestra attiva scrive nel buffer della finestra
    /// (coordinate relative alla viewport); altrimenti posiziona il cursore console e stampa.</summary>
    public static void AtSayDispatch(int row, int col, string text)
    {
        if (ActivePixelWindow() is { } pw)
        {
            try { pw.SayAt(Math.Max(0, row - 1), Math.Max(0, col - 1), text ?? ""); RenderPixelWindows(); } catch { }
            return;
        }
        if (ActiveWindowObj() is { } aw)
        {
            try { aw.SayAt(Math.Max(0, row - 1), Math.Max(0, col - 1), text ?? ""); RenderTuiWindows(); } catch { }
            return;
        }
        // Via UNICA: il controllo C (Label) si rende su TUI/SDLConsole/grafica secondo il
        // contesto attivo. Niente SetCursorPosition/PrintLine (rendering proprio).
        Basic.Runtime.Services.NativeTui.AtSay(row, col, text ?? "");
    }

    public static string AtGet(int row, int col)
    {        // Finestra attiva → legge la riga relativa della viewport (da colonna in poi).
        if (ActivePixelWindow() is { } pw)
        {
            try
            {
                var absRow = pw.ScrollOffset + row;
                if (absRow < pw.Lines.Count)
                {
                    var line = pw.Lines[absRow];
                    return col < line.Length ? line[col..] : "";
                }
            }
            catch { }
            return "";
        }
        if (ActiveWindowObj() is { } aw)
        {
            try
            {
                var absRow = aw.ScrollOffset + row;
                if (absRow < aw.Lines.Count)
                {
                    var line = aw.Lines[absRow];
                    return col < line.Length ? line[col..] : "";
                }
            }
            catch { }
            return "";
        }
        lock (_tuiLock) { Console.SetCursorPosition(col, row); }
        // FONTE UNICA: ReadLine() gestisce il feeder attivo (ricostruisce la riga dalla coda
        // InkeyQueue); System.Console.ReadLine diretto qui competerebbe col feeder.
        return ReadLine();
    }

    public static void StatusBar(string text)
    {
        // Finestra attiva → riga in fondo alla viewport della finestra.
        if (ActivePixelWindow() is { } pw)
        {
            try
            {
                var cr = pw.ClientRect;
                var rows = Math.Max(1, cr.h / Math.Max(1, CommonGraphics.Graphics.GfxWindowManager.CharHeight()));
                pw.SayAt(Math.Max(0, rows - 1), 0, text ?? "");
                RenderPixelWindows();
            }
            catch { }
            return;
        }
        if (ActiveWindowObj() is { } aw)
        {
            try { aw.SayAt(Math.Max(0, aw.ContentRect.H - 1), 0, text ?? ""); RenderTuiWindows(); } catch { }
            return;
        }
        // Base screen: prima scriveva SEMPRE direttamente su System.Console, bypassando
        // GraphicsManager/ClipperLib.Controls.WindowManager per intero — in modalità
        // SDLConsole o grafica pura non produceva ALCUN output visibile (quei rendering non
        // passano dal vero stdout del terminale). Ora usa lo stesso canale condiviso con la
        // taskbar (SetStatusBar), scelto in base a quale schermo è realmente attivo.
        if (IsGraphicScreenOn && _gfxWindows is { } gpStatus)
        {
            try { gpStatus.SetStatusBar(text ?? ""); RenderPixelWindows(); return; } catch { }
        }
        try { TuiWindows.SetStatusBar(text ?? ""); RenderTuiWindows(); return; } catch { }
        lock (_tuiLock) { Console.SetCursorPosition(0, Console.WindowHeight - 1); Console.Write((text ?? "").PadRight(Console.WindowWidth)); }
    }

    // ═══ TUI WIDGET — backend IL (parità PCodeVM e VM/C) ═══
    // I controlli TUI (CHECKBOX/LISTBOX/COMBOBOX/TOGGLE/RADIOGROUP/SLIDER/TAB/GRID/
    // DATEPICKER/COLORPICKER/TREEVIEW/MENU/FILEDIALOG/PRINTERDIALOG/TBROWSE) sono registrati
    // nel runtime C (UiAdd*) e resi non-bloccanti dal frame/drain C. I vecchi loop modali C#
    // (ClipperForm/Control/Menu/FileDialog/PrinterDialog/TBrowse su ModalHost) sono stati
    // rimossi perché morti — vedi repo GMBasic-Deprecated.

    private static bool? PopBool(IReadOnlyList<object?> args, int idx, bool? dflt = null)
        => idx < args.Count && args[idx] is double db ? db != 0 : idx < args.Count && args[idx] is bool bb ? bb : dflt;
    private static int PopInt(IReadOnlyList<object?> args, int idx, int dflt = 0)
        => idx < args.Count && args[idx] is double d2 ? (int)d2 : dflt;
    private static string PopStr(IReadOnlyList<object?> args, int idx, string dflt = "")
        => idx < args.Count ? args[idx]?.ToString() ?? dflt : dflt;
    private static List<string> PopStrArr(IReadOnlyList<object?> args, int idx)
    {
        var list = new List<string>();
        if (idx >= args.Count || args[idx] is not System.Collections.IEnumerable en) return list;
        foreach (var o in en) list.Add(o?.ToString() ?? "");
        return list;
    }

