    public static double TuiTBrowse(IReadOnlyList<object?> args)
    {
        // ordine AST TBROWSE: row, col, width, height, columns, data, options
        var row = PopInt(args, 0); var col = PopInt(args, 1);
        var w = PopInt(args, 2, 40); var h = PopInt(args, 3, 6);
        var rowsList = BrowseRows(args, 5);
        // colsCsv: "header:width:type:align" per colonna → il runtime C conserva tipo/allineamento
        // (parità col backend che dalla tupla imposta DataType/Align).
        var colsCsv = string.Join("|", BrowseColumns(args, 4));
        var dataCsv = string.Join(";", rowsList.ConvertAll(r => string.Join("|", r)));
        UiAddTbrowse(row, col, w, h, colsCsv, dataCsv); // runtime C, non-bloccante
        return -1.0;
    }

    /// <summary>Costruisce le colonne TBROWSE dall'array BASIC come celle CSV
    /// "header:width:type:align" (coerente con PCodeProcessor.Tui.TuiTBrowse).</summary>
    private static List<string> BrowseColumns(IReadOnlyList<object?> args, int idx)
    {
        var columns = new List<string>();
        if (idx >= args.Count || args[idx] is not System.Collections.IList cl) goto dflt;
        foreach (var c in cl)
        {
            if (c is not System.Collections.IList cd || cd.Count < 2) continue;
            var header = cd[0]?.ToString() ?? "";
            var width = Convert.ToInt32(cd[1] is double dw ? dw : 10);
            var typeChar = (cd.Count >= 3 ? cd[2]?.ToString()?.ToUpperInvariant() : null) switch
            {
                "N" or "I" => "N",
                "F" => "F",
                "L" or "B" => "L",
                "D" => "D",
                "X" => "X",
                _ => "T"
            };
            var alignChar = (cd.Count >= 4 ? cd[3]?.ToString()?.ToUpperInvariant() : null) switch
            {
                "R" => "R",
                "C" => "C",
                _ => "L"
            };
            columns.Add(header + ":" + width + ":" + typeChar + ":" + alignChar);
        }
        if (columns.Count > 0) return columns;
    dflt:
        columns.Add("Field:10:T:L");
        return columns;
    }

    /// <summary>Costruisce le righe (lista di liste di stringhe) dell'array BASIC data.</summary>
    private static List<List<string>> BrowseRows(IReadOnlyList<object?> args, int idx)
    {
        var rows = new List<List<string>>();
        if (idx < args.Count && args[idx] is System.Collections.IList dl)
            foreach (var r in dl)
            {
                var rd = new List<string>();
                if (r is System.Collections.IList rl)
                    foreach (var cell in rl) rd.Add(cell?.ToString() ?? "");
                rows.Add(rd);
            }
        return rows;
    }

    // ═══ fine TUI WIDGET ═══

    public static void ScrollRegion(int top, int left, int bottom, int right, int count)
    {
        // Finestra attiva → scroll della finestra.
        if (ActivePixelWindow() is { } pw)
        {
            try
            {
                var cr = pw.ClientRect;
                var rows = Math.Max(1, cr.h / Math.Max(1, CommonGraphics.Graphics.GfxWindowManager.CharHeight()));
                var max = Math.Max(0, pw.Lines.Count - rows);
                pw.ScrollOffset = Math.Clamp(pw.ScrollOffset + count, 0, max);
                RenderPixelWindows();
            }
            catch { }
            return;
        }
        if (ActiveWindowObj() is { } aw)
        {
            try { aw.ScrollBy(count); RenderTuiWindows(); } catch { }
            return;
        }
        SetScrollRegion(top, bottom);
    }

    public static void SetScrollRegion(int top, int bottom)
    {
        if (top >= 0 && bottom >= top)
        {
            try { Current.Console.SetScrollRegion(top, bottom); } catch { }
        }
    }

    public static void CursorVisible(bool visible)
    {
        try { Console.CursorVisible = visible; } catch { }
        try { ClipperLib.Clipper.ClipperOutput.SetCursor(visible); } catch { }
        try { Current.Graphics.CursorState(visible); } catch { }
    }

    public static void CursorShape(int shape)
    {
        if (OperatingSystem.IsWindows()) { try { Console.CursorSize = Math.Clamp(shape, 1, 100); } catch { } }
        try { Current.Graphics.CursorShape(shape); } catch { }
    }

    public static void ConsoleSendKeys(string keys)
    {
        // Parità PCode (CONSOLE_SENDKEY → KeyboardService.SendKey): inietta nella coda
        // InkeyQueue che ReadKey/TryDequeueInkey consumano (via QueueInkey: enqueue + wake
        // dei waiter GPM). Prima no-op ("richiede Win32 API") → SENDKEY+GET/INKEY/WAITKEY
        // inaffidabili su gamba IL. Un tasto per char (come PCode SendKey(keys[0]) in loop).
        if (string.IsNullOrEmpty(keys)) return;
        foreach (var ch in keys) QueueInkey(ch.ToString());
    }

    public static void SetScreenMode(int mode)
    {
        try { if (mode == 0) Console.Clear(); } catch { }
    }

    // SAVE SCREEN/RESTORE SCREEN in IL: allineati al P-Code VM GAI
    // (PCodeProcessor.Syscalls.cs case SAVE_SCREEN/RESTORE_SCREEN) che usa l'alternate
    // Snapshot nominati dei buffer schermo (SAVESCREEN/RESTORESCREEN): finestre, pixel,
    // grafica, oppure — headless/test — griglia console reale via Get/PutScreen
    // (parità PCode _consoleScreens; niente escape su stdout in harness).
    private static readonly System.Collections.Generic.Dictionary<string, ClipperLib.Controls.ManagedWindow> _windowSnapshots = new();
    private static readonly System.Collections.Generic.Dictionary<string, CommonGraphics.Graphics.PixelWindow> _pixelWindowSnapshots = new();
    private static readonly System.Collections.Generic.Dictionary<string, CommonLib.Screens.ScreenCell[,]> _consoleScreens = new(System.StringComparer.OrdinalIgnoreCase);

    public static void SaveScreenBuffer(string name)
    {
        // Finestra attiva → snapshot del buffer finestra (SAVESCREEN viewport).
        if (ActivePixelWindow() is { } pw)
        {
            try { _pixelWindowSnapshots[name ?? ""] = pw.Snapshot(); } catch { }
            return;
        }
        if (ActiveWindowObj() is { } aw)
        {
            try { _windowSnapshots[name ?? ""] = aw.Snapshot(); } catch { }
            return;
        }
        var g = Current.Graphics;
        try { if (g.IsAvailable) { g.SaveScreen(name); return; } } catch { }
        // Headless/harness: cattura reale della griglia console (niente escape su stdout).
        try
        {
            if (Current.Console is Basic.Runtime.Services.HeadlessConsoleService)
            {
                var cells = Current.Console.GetScreen(new CommonLib.Consoles.ScreenRect(0, 0, 80, 25));
                _consoleScreens[name ?? ""] = cells ?? new CommonLib.Screens.ScreenCell[25, 80];
                return;
            }
        } catch { }
        try { Current.Console.Print("\x1b[?47h"); } catch { }
    }

    public static void RestoreScreenBuffer(string name)
    {
        // Finestra attiva → ripristina lo snapshot del buffer finestra (RESTORESCREEN viewport).
        if (ActivePixelWindow() is { } pw)
        {
            try
            {
                if (_pixelWindowSnapshots.TryGetValue(name ?? "", out var snap))
                {
                    pw.RestoreFrom(snap);
                    RenderPixelWindows();
                }
            }
            catch { }
            return;
        }
        if (ActiveWindowObj() is { } aw)
        {
            try
            {
                if (_windowSnapshots.TryGetValue(name ?? "", out var snap))
                {
                    aw.RestoreFrom(snap);
                    RenderTuiWindows();
                }
            }
            catch { }
            return;
        }
        var g = Current.Graphics;
        try { if (g.IsAvailable) { g.RestoreScreen(name); return; } } catch { }
        // Headless/harness: ripristino reale dalla griglia catturata (niente escape su stdout).
        try
        {
            if (Current.Console is Basic.Runtime.Services.HeadlessConsoleService
                && _consoleScreens.TryGetValue(name ?? "", out var cells) && cells.Length > 0)
            {
                Current.Console.PutScreen(0, 0, cells);
                return;
            }
        } catch { }
        try { Current.Console.Print("\x1b[?47l"); } catch { }
    }

    // PALETTE polimorfico (come CLS/PRINT/LOCATE): schermo grafico attivo → SetPaletteColor
    // (PALETTE_GPM aggiorna _colorPalette); altrimenti console. Prima andava SEMPRE alla
    // console → la palette grafica non veniva mai ridefinita (bug: PALETTE 5,r,g,b no-op).
    public static void PaletteDispatch(int index, int r, int g, int b)
    {
        var gr = Current.Graphics;
        bool gfx;
        try { gfx = gr.IsAvailable; } catch { gfx = false; }
        if (gfx) { gr.SetPaletteColor(index, r, g, b); return; }
        Current.Console.SetPaletteColor(index, r, g, b);
    }

    public static void SetWindowRegion(bool screen, int x1, int y1, int x2, int y2)
    {
        // WINDOW (x1,y1)-(x2,y2) [SCREEN]: finestra di coordinate logiche. Con grafica
        // attiva delega a IGraphicsService.Window (viewport grafico, come la PCodeVM);
        // altrimenti applica la regione di scroll sulla console attiva.
        var g = Current.Graphics;
        bool gfx;
        try { gfx = g.IsAvailable; } catch { gfx = false; }
        if (gfx) { g.Window(x1, y1, x2, y2); return; }
        try { Current.Console.SetScrollRegion(y1, y2); } catch { }
    }

    public static void SetConsoleAttribute(string attribute, string state)
    {
        // Parità PCodeVM (SysCall.SET_ATTRIBUTE): SET BOLD/UNDERLINE/INVERSE ON/OFF via
        // codici ANSI sulla console attiva. Era un no-op silenzioso (SET BOLD ON non faceva nulla).
        var attr = attribute.ToUpperInvariant();
        var on = string.Equals(state, "ON", StringComparison.OrdinalIgnoreCase)
                 || string.Equals(state, "1", StringComparison.Ordinal);
        try
        {
            lock (_ilPrintSync)
            {
                if (attr == "BOLD") Current.Console.Print(on ? "\x1b[1m" : "\x1b[22m");
                else if (attr == "UNDERLINE") Current.Console.Print(on ? "\x1b[4m" : "\x1b[24m");
                else if (attr == "INVERSE") Current.Console.Print(on ? "\x1b[7m" : "\x1b[27m");
            }
        }
        catch { }
    }

