    // ── MOUSE POLIMORFICO (TUI / screen grafico / SDLConsole) ──
    // Le funzioni MOUSE.X()/Y() ecc. seguono il pattern di PRINT/CLS/LOCATE: lo screen
    // attivo decide il percorso. In TUI/SDLConsole le coordinate sono CELLE (ClipperMouse →
    // ClipperGlobal.State); in uno screen grafico (SCREEN VGA/SVGA/...) sono PIXEL SDL.
    // Gli eventi SDL alimentano _guiMouse* (pixel) e ClipperGlobal.State (booleani + celle)
    // via SubscribeGuiMouseEvents; le funzioni scelgono il ramo in base a IsScreenOn.

    private static int _guiMouseX;
    private static int _guiMouseY;
    private static bool[] _guiMouseDown = new bool[3];
    private static bool _guiMousePresent;
    private static int _guiMouseWheel;
    private static bool _guiMouseSubscribed;

    private static bool IsGraphicScreenOn
    {
        get
        {
            // Host headless (NullGraphicsService, es. test_ilrun): mai vero, senza nemmeno
            // toccare GraphicsManager.Instance — leggere quel singleton di processo lo
            // inizializza (SDL reale) al primo accesso, indipendentemente dall'host corrente.
            // Vedi il commento in SetCurrent per l'hang che questo causava.
            try { if (Current.Graphics is NullGraphicsService) return false; } catch { return false; }
            // Motore C (F2): lo screen grafico vive in gmb_graphics, non nel GraphicsManager C#.
            try { if (Current.Graphics is Basic.Runtime.CGfxGraphicsService) return Basic.Runtime.CGfxGraphicsService.IsScreenOnC; } catch { }
            try { return CommonGraphics.Graphics.GraphicsManager.Instance.IsScreenOn; }
            catch { return false; }
        }
    }

    /// <summary>Sottoscrive una sola volta gli eventi mouse SDL: aggiorna lo stato GUI
    /// (_guiMouse* in pixel + ClipperGlobal.State per i booleani/ON MOUSE). Chiamata dal
    /// primo uso di una funzione MOUSE o da ON MOUSE (best-effort).</summary>
    private static void SubscribeGuiMouseEvents()
    {
        if (_guiMouseSubscribed) return;
        _guiMouseSubscribed = true;
        try
        {
            var mgr = CommonGraphics.Consoles.SdlManager.Instance;
            mgr.MouseButtonEvent += e => ApplyGuiMouseButton(
                e.type == SDL2.SDL.SDL_EventType.SDL_MOUSEBUTTONDOWN, e.button.button, e.button.x, e.button.y);
            mgr.MouseMotionEvent += e => ApplyGuiMouseMotion(e.motion.x, e.motion.y);
            mgr.MouseWheelEvent += e => ApplyGuiMouseWheel(e.wheel.y);
        }
        catch { /* niente SDL: solo TUI */ }
    }

    /// <summary>Applica un evento bottone mouse (unica sorgente per SDL C#, motore C e test).
    /// sdlButton = numero SDL (1=L, 2=M, 3=R). Aggiorna _guiMouse* (pixel), ClipperGlobal.State
    /// (ON MOUSE/MOUSE.LEFT in TUI), EventDispatcher e i WindowManager.</summary>
    private static void ApplyGuiMouseButton(bool down, int sdlButton, int x, int y)
    {
        _guiMousePresent = true;
        _guiMouseX = x;
        _guiMouseY = y;
        int b = sdlButton switch { 2 => 1, 3 => 2, _ => 0 };
        if (b >= 0 && b < 3) _guiMouseDown[b] = down;
        // Stato mouse Clipper → runtime C (`gmb_clipper_mouse_update_simple`): kind GMB_MA_*
        // (0=CLICK, 2=RIGHTCLICK, 3=MIDDLECLICK, 9=RELEASE).
        try { Current.Graphics.ClipperMouseUpdateEvent(down ? (sdlButton == 2 ? 2 : sdlButton == 3 ? 3 : 0) : 9, x, y); } catch { }
        CommonLib.App.EventDispatcher.Instance.DispatchMouse(down ? 2 : 3, x, y);
        // Controlli C (form pixel + registri TUI): l host drena la coda, quindi
        // l evento va consegnato esplicitamente al layer controlli C.
        try { Current.Graphics.FormDispatchMouse(down ? 2 : 3, x, y, sdlButton, 0); } catch { }
        // Instrada il click anche ai WindowManager (TUI cell-based e PIXEL):
        // focus/raise, titlebar (close/min/max), drag/resize sulle finestre.
        RouteGuiMouse(down ? 0 : 1, x, y);
    }

    /// <summary>Applica un movimento mouse (pixel schermo).</summary>
    private static void ApplyGuiMouseMotion(int x, int y)
    {
        _guiMouseX = x;
        _guiMouseY = y;
        _guiMousePresent = true;
        // Movimento → runtime C (kind 11 = GMB_MA_MOVE).
        try { Current.Graphics.ClipperMouseUpdateEvent(11, x, y); } catch { }
        CommonLib.App.EventDispatcher.Instance.DispatchMouse(4, x, y);
        try { Current.Graphics.FormDispatchMouse(1, x, y, 0, 0); } catch { }
        // Drag/resize in corso (solo mentre un pulsante è premuto).
        if (_guiMouseDown[0]) RouteGuiMouse(2, x, y);
    }

    /// <summary>Applica un evento rotella (y SDL: >0 su, &lt;0 giù).</summary>
    private static void ApplyGuiMouseWheel(int wheelY)
    {
        try { _guiMouseWheel = wheelY > 0 ? 1 : -1; } catch { }
        try
        {
            // Rotella → runtime C (5=GMB_MA_SCROLLUP, 6=GMB_MA_SCROLLDOWN).
            Current.Graphics.ClipperMouseUpdateEvent(_guiMouseWheel > 0 ? 5 : 6, (int)_guiMouseX, (int)_guiMouseY);
            CommonLib.App.EventDispatcher.Instance.DispatchMouse(_guiMouseWheel > 0 ? 5 : 6, (int)_guiMouseX, (int)_guiMouseY);
            try { Current.Graphics.FormDispatchMouse(4, (int)_guiMouseX, (int)_guiMouseY, 0, _guiMouseWheel); } catch { }
        }
        catch { }
    }

    /// <summary>Evento mouse dal motore C (drain di CGfxInputService, main thread).
    /// type: 1=move, 2=down, 3=up, 4=wheel (parità GMB_GFX_MOUSE_*).</summary>
    public static void OnCGfxMouseEvent(int type, int x, int y, int sdlButton, int wheel)
    {
        switch (type)
        {
            case 1: ApplyGuiMouseMotion(x, y); break;
            case 2: ApplyGuiMouseButton(true, sdlButton, x, y); break;
            case 3: ApplyGuiMouseButton(false, sdlButton, x, y); break;
            case 4: ApplyGuiMouseWheel(wheel); break;
        }
    }

    /// <summary>Collega il drain input alla pump del motore C (chiamare una volta in
    /// modalità C): CGfxGraphicsService.MainThreadTick invocherà DrainCGfxInput.</summary>
    public static void BindCGfxInput()
    {
        try { Basic.Runtime.CGfxGraphicsService.InputDrain = DrainCGfxInput; } catch { }
    }

    /// <summary>Drena l'input del motore C (SOLO main thread, dopo la pump grafica):
    /// tasti → QueueInkey (park/wake/ON KEY invariati), mouse → stato+dispatch,
    /// Ctrl+C → tasto se intercettato, altrimenti abort (parità IlSdlInput).</summary>
    public static void DrainCGfxInput()
    {
        try
        {
            while (Basic.Runtime.CGfxInputService.TryPollKey(out var k))
            {
                QueueInkey(k);
                foreach (var ch in k) try { Current.Graphics.FormDispatchKey(ch.ToString()); } catch { }
            }
            while (Basic.Runtime.CGfxInputService.TryPollMouse(out var t, out var x, out var y, out var b, out var w))
                OnCGfxMouseEvent(t, x, y, b, w);
            if (Basic.Runtime.CGfxInputService.TakeCtrlC())
            {
                if (IsCtrlCIntercepted()) QueueInkey("\x03");
                else { QueueInkey("\x1b"); RequestAbort(); }
            }
        }
        catch { }
    }

    /// <summary>True se il mouse deve usare coordinate PIXEL (screen grafico attivo).</summary>
    private static bool MouseUsesPixels => IsGraphicScreenOn;

    /// <summary>Instrada un evento mouse alle finestre gestite (TUI cell-based e PIXEL).
    /// kind: 0=down, 1=up, 2=drag/move. x,y = coordinate PIXEL dello schermo grafico.
    /// Per le finestre TUI (coordinate in celle) converte con la cella font corrente;
    /// per le finestre PIXEL usa le coordinate pixel dirette. Chiamato SOLO dal thread
    /// di polling SDL (gli handler del WindowManager non fanno lavoro pesante).</summary>
    private static void RouteGuiMouse(int kind, int x, int y)
    {
        try
        {
            // Finestre PIXEL (solo se lo schermo grafico è attivo e ce ne sono).
            if (_gfxWindows is { } gp && gp.Windows.Count > 0 && IsGraphicScreenOn)
            {
                gp.HandleMouse(kind, x, y);
                // Il mouse può aver cambiato geometria (drag/resize) → ridisegna.
                RenderPixelWindows();
            }
        }
        catch { }
        try
        {
            // Finestre TUI (WindowManager cell-based): converte pixel → cella.
            if (_tuiWindows is not { } wm || wm.WindowCount == 0) return;
            var g = Current.Graphics;
            bool gfx;
            try { gfx = g.IsAvailable; } catch { gfx = false; }
            int cellW, cellH;
            if (gfx)
            {
                try
                {
                    var gm = CommonGraphics.Graphics.GraphicsManager.Instance;
                    cellW = Math.Max(1, gm.CharCellWidth);
                    cellH = Math.Max(1, gm.CharCellHeight);
                }
                catch { cellW = 8; cellH = 16; }
            }
            else { cellW = 1; cellH = 1; }
            var cx = x / cellW;
            var cy = y / cellH;
            ClipperLib.Clipper.MouseAction ma = kind switch
            {
                0 => ClipperLib.Clipper.MouseAction.Click(cx, cy),
                1 => ClipperLib.Clipper.MouseAction.Release(cx, cy),
                _ => ClipperLib.Clipper.MouseAction.Drag(cx, cy),
            };
            wm.HandleEvent(new ClipperLib.Clipper.UiMouse(ma));
            RenderTuiWindows();
        }
        catch { }
    }

