    /// <summary>Larghezza cella font corrente (fallback 8x16 sotto test).</summary>
    private static int GraphCellW()
    {
        try { var m = CommonGraphics.Graphics.GraphicsManager.Instance; return Math.Max(1, m.CharCellWidth); } catch { return 8; }
    }

    /// <summary>Altezza cella font corrente (fallback 8x16 sotto test).</summary>
