    // ── Printing ──────────────────────────────────────────────────────
    public static void PrinterDialog(object printerVar, object copiesVar, object duplexVar, string? title) { }

    // ── READ unificato (C#): loop sui campi @GET (text-input CONTROLS) ──
    // Modello: campo = text-input; WHEN skip (non-blocking), VALID re-focus, apply al var C#.
    private sealed class ReadField
    {
        public int Row, Col, Width;
        public string Value = "";
        public Func<bool>? When;
        public Func<string, bool>? Valid;
        public Action<string>? Apply;
    }
    private static readonly System.Collections.Generic.List<ReadField> _readFields = new();

    public static int ReadAddField(int row, int col, int width, string initial, Action<string>? apply = null)
    {
        _readFields.Add(new ReadField { Row = row, Col = col, Width = width <= 0 ? 10 : width, Value = initial ?? "", Apply = apply });
        return _readFields.Count - 1;
    }
    public static void ReadSetWhen(int idx, Func<bool>? when) { if (idx >= 0 && idx < _readFields.Count) _readFields[idx].When = when; }
    public static void ReadSetValid(int idx, Func<string, bool>? valid) { if (idx >= 0 && idx < _readFields.Count) _readFields[idx].Valid = valid; }

    // ─── READ PCodeVM — park per-tasto (il syscall CLIPPER_READ viene RI-ESEGUITO) ────────
    // Parità col modello C/IL: il campo è reso ad ogni tasto e il task parcheggia finché non
    // arriva un tasto. La PCodeVM non ri-esegue i syscall; CLIPPER_READ fa il rewind di Ip
    // prima di ParkAsync (stesso pattern di OP_SEND/OP_RECV/OP_LOAD_GLOBAL), così al risveglio
    // ri-entra qui con lo stato (campo corrente + buffer) conservato.

    private sealed class PCodeReadState { public int Idx; public bool Started; public readonly System.Text.StringBuilder Buffer = new(); }
    private static readonly System.Collections.Generic.Dictionary<PCodeTask, PCodeReadState> _pcodeReadStates = new();
    private static readonly object _pcodeReadLock = new();

    /// <summary>Un passo del READ per la PCodeVM: rende il campo corrente e ritorna true se
    /// serve un tasto (il chiamante ri-esegue il syscall), false quando tutti i campi sono
    /// confermati (WHEN saltato). Parità col loop park dei backend C/IL.</summary>
    public static bool ReadPCodeStep(PCodeTask task)
    {
        PCodeReadState st;
        lock (_pcodeReadLock)
        {
            if (!_pcodeReadStates.TryGetValue(task, out st!)) { st = new PCodeReadState(); _pcodeReadStates[task] = st; }
        }
        while (st.Idx < _readFields.Count)
        {
            var f = _readFields[st.Idx];
            if (f.When != null && !f.When()) { st.Idx++; st.Started = false; continue; }
            if (!st.Started)
            {
                st.Buffer.Clear(); st.Buffer.Append(f.Value ?? "");
                if (f.Width > 0 && st.Buffer.Length > f.Width) st.Buffer.Length = f.Width;
                st.Started = true;
            }
            ReadRenderField(f.Row, f.Col, f.Width, st.Buffer.ToString());
            return true;
        }
        lock (_pcodeReadLock) _pcodeReadStates.Remove(task);
        ReadClear();
        return false;
    }

    /// <summary>Applica un tasto al campo READ corrente (continuation del park, al resume):
    /// Enter conferma (applica al target), VALID .F. rifà il campo, ESC annulla come Enter.</summary>
    public static void ReadPCodeApplyKey(PCodeTask task, string? key)
    {
        PCodeReadState? st;
        lock (_pcodeReadLock) _pcodeReadStates.TryGetValue(task, out st);
        if (st == null || st.Idx >= _readFields.Count) return;
        var f = _readFields[st.Idx];
        foreach (var ch in key ?? "")
        {
            if (ch == '\r' || ch == '\n' || ch == '\x1b')
            {
                f.Value = st.Buffer.ToString();
                st.Started = false;
                if (f.Valid != null && !f.Valid(f.Value)) return;   // VALID .F. → rifà il campo
                f.Apply?.Invoke(f.Value);
                st.Idx++;
                return;
            }
            if (ch == '\b') { if (st.Buffer.Length > 0) st.Buffer.Length--; }
            else if (ch >= ' ') { if (f.Width <= 0 || st.Buffer.Length < f.Width) st.Buffer.Append(ch); }
        }
    }

    /// <summary>Render del campo @GET attivo durante READ sul window attivo (pixel/TUI).
    /// Parità col render_hook di `gmb_read_run`: mostra il valore corrente del campo.
    /// `RenderPixelWindows`/`RenderTuiWindows` accodano sul main thread (GPM). Headless: no-op.
    /// Usato dal path IL (inline, via MethodInfo) e dalla PCodeVM (ReadPCodeStep).</summary>
    public static void ReadRenderField(int row, int col, int width, string? value)
    {
        if (width <= 0) width = 10;
        var text = value ?? "";
        if (text.Length < width) text = text.PadRight(width);
        else if (text.Length > width) text = text.Substring(0, width);
        if (ActivePixelWindow() is { } pw)
        {
            try { pw.SayAt(Math.Max(0, row - 1), Math.Max(0, col - 1), text); RenderPixelWindows(); } catch { }
            return;
        }
        if (ActiveWindowObj() is { } aw)
        {
            try { aw.SayAt(Math.Max(0, row - 1), Math.Max(0, col - 1), text); RenderTuiWindows(); } catch { }
        }
    }

    private static void RenderReadField(ReadField f) => ReadRenderField(f.Row, f.Col, f.Width, f.Value);
    public static string ReadGetValue(int idx) => (idx >= 0 && idx < _readFields.Count) ? _readFields[idx].Value : "";
    public static void ReadClear() { _readFields.Clear(); }

    // ── Window Events ─────────────────────────────────────────────────
    /// <summary>WindowManager TUI del backend IL (lazy, per-run — azzerato in
    /// ResetProgramState). Stessa implementazione del PCode VM (ClipperLib.Controls.
    /// WindowManager): finestre multiple con z-order, focus, snap/tile, drag/resize.
    /// <summary>WindowManager delle finestre PIXEL (Fase W-Pixel). Solo con schermo grafico
    /// attivo. Work area = risoluzione logica dello schermo corrente.</summary>
    private static CommonGraphics.Graphics.GfxWindowManager? _gfxWindows;

    private static CommonGraphics.Graphics.GfxWindowManager PixelWindows
    {
        get
        {
            if (_gfxWindows == null)
            {
                _gfxWindows = new CommonGraphics.Graphics.GfxWindowManager();
                try
                {
                    var gm = CommonGraphics.Graphics.GraphicsManager.Instance;
                    _gfxWindows.ScreenW = gm.ScreenWidth;
                    _gfxWindows.ScreenH = gm.ScreenHeight;
                }
                catch { }
            }
            return _gfxWindows;
        }
    }

    /// <summary>Renderizza le finestre pixel sul buffer della pagina grafica. Il render
    /// DEVE girare sul main thread SDL: accoda via GPM (come RenderTui).</summary>
    private static void RenderPixelWindows()
    {
        try
        {
            var gm = CommonGraphics.Graphics.GraphicsManager.Instance;
            if (gm is not CommonGraphics.Graphics.GraphicsManager) return;
            var mgr = _gfxWindows;
            // NON saltare il render quando Windows.Count è 0: è esattamente il caso in cui
            // serve un render (l'ultima finestra è appena stata chiusa) per ripristinare lo
            // sfondo — saltarlo lasciava i vecchi pixel della finestra chiusa impressi per
            // sempre (nessun altro trigger li avrebbe mai ripuliti).
            if (mgr is null) return;
            gm.EnqueueGpmOperation(() => { try { mgr.Render(); } catch { } return null; }, (_r, _e) => { });
        }
        catch { }
    }

    /// <summary>Gli eventi finestra dispatchano al EventDispatcher unificato (ON WINDOW).</summary>
    private static ClipperLib.Controls.WindowManager? _tuiWindows;
    private static bool _tuiWindowEventsSubscribed;

    private static ClipperLib.Controls.WindowManager TuiWindows
    {
        get
        {
            if (_tuiWindows == null)
            {
                _tuiWindows = new ClipperLib.Controls.WindowManager(new ClipperLib.Clipper.ScreenRect(0, 0, 80, 24));
                try { _tuiWindows.ClipboardService = Current.Clipboard; } catch { }
                if (!_tuiWindowEventsSubscribed)
                {
                    _tuiWindowEventsSubscribed = true;
                    try
                    {
                        _tuiWindows.WindowOpened += (_, e) => CommonLib.App.EventDispatcher.Instance.DispatchWindow(7, e.Id);
                        _tuiWindows.WindowClosed += (_, e) => CommonLib.App.EventDispatcher.Instance.DispatchWindow(0, e.Id);
                        _tuiWindows.WindowMoved += (_, e) => CommonLib.App.EventDispatcher.Instance.DispatchWindow(3, e.Id);
                        _tuiWindows.WindowResized += (_, e) => CommonLib.App.EventDispatcher.Instance.DispatchWindow(1, e.Id);
                        _tuiWindows.WindowFocused += (_, e) => CommonLib.App.EventDispatcher.Instance.DispatchWindow(4, e.Id);
                        _tuiWindows.WindowMinimized += (_, e) => CommonLib.App.EventDispatcher.Instance.DispatchWindow(5, e.Id);
                        _tuiWindows.WindowRestored += (_, e) => CommonLib.App.EventDispatcher.Instance.DispatchWindow(6, e.Id);
                    }
                    catch { }
                }
            }
            return _tuiWindows;
        }
    }

    public static void DefineWindow(string name, int top, int left, int bottom, int right, string? title, bool doubleBorder, bool shadow, bool pixel, int frameStyle, int desktop)
    {
        // WINDOW DEFINE name FROM top,left TO bottom,right [TITLE "t"] [DOUBLE] [SHADOW] [PIXEL] [DESKTOP n].
        // Senza PIXEL → finestra TUI cell-based (WindowManager). Con PIXEL → finestra
        // pixel-based (GfxWindowManager, solo schermo grafico): coordinate e dimensioni
        // in PIXEL LOGICI dello schermo (top,left) e (bottom,right) = angoli opposti.
        try
        {
            if (pixel)
            {
                var g = PixelWindows;
                var id = g.AddWindow(name, string.IsNullOrEmpty(title) ? name : title,
                    left, top, right - left, bottom - top, shadow);
                if (desktop > 0 && g.Get(id) is { } pw) pw.Desktop = desktop;
                RenderPixelWindows();
                return;
            }
            var wm = TuiWindows;
            // Re-DEFINE dello stesso nome BASIC: aggiorna la finestra esistente (come il
            // runtime C e C99Native) e non innalza un secondo OPEN.
            if (wm.FindByName(name) is int existingId && wm.Get(existingId) is { } existingWin)
            {
                existingWin.Rect = new ClipperLib.Clipper.ScreenRect(left, top,
                    Math.Max(1, right - left), Math.Max(1, bottom - top));
                existingWin.Title = string.IsNullOrEmpty(title) ? name : title;
                RenderTuiWindows();
                return;
            }
            var id2 = wm.AddWindow(string.IsNullOrEmpty(title) ? name : title,
                new ClipperLib.Clipper.ScreenRect(left, top, Math.Max(1, right - left), Math.Max(1, bottom - top)));
            if (id2 >= 0 && wm.Get(id2) is { } win)
            {
                win.Name = name;
                win.Border = doubleBorder ? ClipperLib.Controls.PanelBorder.Double : ClipperLib.Controls.PanelBorder.Single;
                win.FrameStyle = (ClipperLib.Controls.FrameStyle)frameStyle;
                win.Shadow = shadow;
                if (desktop > 0) win.Desktop = desktop;
                win.Draggable = true;
                win.Closable = true;
            }
            RenderTuiWindows();
        }
        catch { }
    }

    public static void DefineWindow(string name, int top, int left, int bottom, int right, string? title, bool doubleBorder, bool shadow, bool pixel) =>
        DefineWindow(name, top, left, bottom, right, title, doubleBorder, shadow, pixel, doubleBorder ? 1 : 0, 1);

    public static void WindowTheme(string themeName) => SetTheme(themeName);

    public static void WindowDesktop(int desktop)
    {
        try
        {
            // Desktop virtuali: entrambi i compositor (TUI e pixel — parità, come
            // richiesto dalla regola coordinate pixel/celle). Il stato è per-manager:
            // WINDOW DESKTOP vale per entrambe le modalità.
            TuiWindows.SwitchDesktop(desktop);
            RenderTuiWindows();
        }
        catch { }
        try
        {
            if (_gfxWindows is { } gp) gp.SwitchDesktop(desktop);
            RenderPixelWindows();
        }
        catch { }
    }

    public static void WindowMoveDesktop(string name, int desktop)
    {
        try
        {
            TuiWindows.MoveWindowToDesktop(name, desktop);
            RenderTuiWindows();
        }
        catch { }
        try
        {
            if (_gfxWindows is { } gp && gp.Find(name) is { } pw)
            {
                gp.MoveWindowToDesktop(pw.Id, desktop);
                RenderPixelWindows();
            }
        }
        catch { }
    }

    public static void WindowFrame(string? name, int frameStyle)
    {
        try
        {
            var fs = (ClipperLib.Controls.FrameStyle)frameStyle;
            if (!string.IsNullOrEmpty(name))
            {
                if (WindowByName(name) is { } w) w.FrameStyle = fs;
            }
            else
            {
                if (TuiWindows.Focused is int fid && TuiWindows.Get(fid) is { } fw) fw.FrameStyle = fs;
            }
            RenderTuiWindows();
        }
        catch { }
    }

    public static void WindowShadow(string? name, bool enable)
    {
        try
        {
            if (!string.IsNullOrEmpty(name))
            {
                if (WindowByName(name) is { } w) w.Shadow = enable;
            }
            else
            {
                if (TuiWindows.Focused is int fid && TuiWindows.Get(fid) is { } fw) fw.Shadow = enable;
            }
            RenderTuiWindows();
        }
        catch { }
    }

    public static double GetCurrentDesktop() => TuiWindows.CurrentDesktop;

    /// <summary>WINDOW SHOW/HIDE — visibilita' della finestra dello screen grafico.</summary>
    public static void WindowSetVisible(bool visible)
    {
        try { Current.Graphics?.WindowVisible(visible); } catch { }
    }

    public static void WindowAction(string name, string action)
    {
        // WINDOW name ACTIVATE|DEACTIVATE|RELEASE|CLOSE|MINIMIZE|RESTORE
        try
        {
            // Prima prova la finestra pixel (se lo schermo grafico è attivo e ne esiste una).
            if (_gfxWindows is { } gp && gp.Find(name) is { } pw)
            {
                switch (action.ToUpperInvariant())
                {
                    case "ACTIVATE": gp.Raise(pw.Id); break;
                    case "DEACTIVATE": gp.Select(null); break;
                    case "CLOSE": gp.Close(pw.Id); break;
                    case "MINIMIZE": gp.Minimize(pw.Id); break;
                    case "RESTORE": gp.Restore(pw.Id); break;
                    case "RELEASE": gp.Close(pw.Id); break;
                }
                RenderPixelWindows();
                return;
            }
            var wm = TuiWindows;
            var id = wm.FindByTitle(name);
            if (!id.HasValue)
            {
                // Fallback: se il nome non è un titolo, prova come nome registrato (il
                // DEFINE usa name come titolo quando TITLE assente — idem).
                id = wm.FindByTitle(name);
                if (!id.HasValue) return;
            }
            switch (action.ToUpperInvariant())
            {
                case "ACTIVATE": wm.Raise(id.Value); break;
                case "DEACTIVATE": wm.Deactivate(id.Value); break;
                case "CLOSE": wm.Close(id.Value); break;
                case "MINIMIZE": wm.Minimize(id.Value); break;
                case "RESTORE": wm.Restore(id.Value); break;
                case "RELEASE": wm.RemoveWindow(id.Value); break;
            }
            RenderTuiWindows();
        }
        catch { }
    }

    /// <summary>WINDOW SET TITLE "titolo" — imposta il titolo della finestra focalizzata.</summary>
    public static void WindowSetTitle(string title)
    {
        try
        {
            if (_gfxWindows is { } gp && gp.ActiveId is int gid && gp.Get(gid) is { } gpw)
            {
                gpw.Title = title ?? "";
                RenderPixelWindows();
                return;
            }
            var wm = TuiWindows;
            wm.SetFocusedTitle(title ?? "");
            RenderTuiWindows();
        }
        catch { }
    }

    // ── Contenuto finestre (buffer/scroll/editing) ──
    private static ClipperLib.Controls.ManagedWindow? WindowByName(string name)
    {
        if (string.IsNullOrEmpty(name)) return null;
        var wm = TuiWindows;
        var id = wm.FindByTitle(name);
        if (!id.HasValue) id = wm.FindByTitle(name);
        return id.HasValue ? wm.Get(id.Value) : null;
    }

    /// <summary>Finestra pixel per nome, o null. Solo se lo schermo grafico è attivo.</summary>
    private static CommonGraphics.Graphics.PixelWindow? PixelWindowByName(string name)
    {
        if (string.IsNullOrEmpty(name)) return null;
        return _gfxWindows?.Find(name);
    }

    public static void WindowAppendLine(string name, string text)
    {
        try
        {
            if (PixelWindowByName(name) is { } pw) { pw.AppendLine(text ?? ""); RenderPixelWindows(); return; }
            if (WindowByName(name) is { } w) { w.AppendLine(text ?? ""); RenderTuiWindows(); }
        }
        catch { }
    }

    public static void WindowSetContent(string name, object? lines)
    {
        try
        {
            if (PixelWindowByName(name) is { } pw)
            {
                var list = ToStringList(lines);
                pw.Lines = list;
                pw.ScrollOffset = 0;
                RenderPixelWindows();
                return;
            }
            if (WindowByName(name) is not { } w) return;
            w.SetLines(ToStringList(lines));
            RenderTuiWindows();
        }
        catch { }
    }

    private static List<string> ToStringList(object? lines)
    {
        var list = new List<string>();
        switch (lines)
        {
            case string[] sa: list.AddRange(sa); break;
            case IEnumerable<string> en: list.AddRange(en); break;
            case System.Collections.IEnumerable e: foreach (var o in e) list.Add(o?.ToString() ?? ""); break;
        }
        return list;
    }

    public static void WindowClear(string name)
    {
        try
        {
            if (PixelWindowByName(name) is { } pw) { pw.Lines.Clear(); pw.ScrollOffset = 0; RenderPixelWindows(); return; }
            if (WindowByName(name) is { } w) { w.Lines.Clear(); w.ScrollOffset = 0; RenderTuiWindows(); }
        }
        catch { }
    }

    public static void WindowScroll(string name, double delta)
    {
        try
        {
            if (PixelWindowByName(name) is { } pw)
            {
                var cr = pw.ClientRect;
                var maxRows = Math.Max(1, cr.h / 16);
                var max = Math.Max(0, pw.Lines.Count - maxRows);
                pw.ScrollOffset = Math.Clamp(pw.ScrollOffset + (int)delta, 0, max);
                RenderPixelWindows();
                return;
            }
            if (WindowByName(name) is { } w) { w.ScrollBy((int)delta); RenderTuiWindows(); }
        }
        catch { }
    }

    public static void WindowEdit(string name, bool enable)
    {
        try
        {
            if (PixelWindowByName(name) is { } pw) { pw.Editable = enable; RenderPixelWindows(); return; }
            if (WindowByName(name) is { } w) { w.Editable = enable; RenderTuiWindows(); }
        }
        catch { }
    }

    // ── Finestra attiva (viewport corrente di output) ──
    /// <summary>Id della finestra attiva, o null se lo schermo base. I comandi polimorfici
    /// (PRINT/LOCATE/CLS/@SAY/@GET/BOX/...) scrivono nella finestra attiva con coordinate
    /// relative alla sua viewport. Con schermo grafico attivo la finestra attiva può essere
    /// pixel (GfxWindowManager); altrimenti TUI (WindowManager).</summary>
    public static int? ActiveWindow
    {
        get
        {
            try
            {
                if (IsPixelWindowActive()) return _gfxWindows?.ActiveId;
                return _tuiWindows?.ActiveWindowId;
            }
            catch { return null; }
        }
    }

    private static bool IsPixelWindowActive()
    {
        try
        {
            // Un ActiveId non-null esiste SOLO se WINDOW DEFINE ... PIXEL è stato chiamato
            // esplicitamente: è già prova sufficiente che una finestra pixel esista. Un
            // controllo aggiuntivo "schermo davvero acceso" (sia via IRuntimeHost.Graphics,
            // sempre NullGraphicsService nell'eseguibile standalone -m dato che nessuno
            // imposta HeadlessRuntimeHost.DefaultGraphics lì, sia via
            // GraphicsManager.Instance.IsScreenOn, che nello stepper GPM risulta falso anche
            // a finestra pixel già visibile e funzionante — verificato con log diretto)
            // rendeva WINDOWS.X()/COLOR su finestra PIXEL SEMPRE "non attivi" fuori dai
            // runner di test che impostano DefaultGraphics a mano.
            return _gfxWindows is { ActiveId: not null };
        }
        catch { return false; }
    }

    /// <summary>WINDOW SELECT target — imposta la finestra attiva. target: 0/numero → schermo
    /// base; stringa → nome finestra. Con schermo grafico attivo seleziona la finestra pixel
    /// se il nome esiste lì, altrimenti la TUI.</summary>
    public static void WindowSelect(object? target)
    {
        try
        {
            // Finestra pixel attiva? Selezione nel GfxWindowManager.
            var g = _gfxWindows;
            switch (target)
            {
                case string s when string.IsNullOrWhiteSpace(s) || s == "0":
                    if (g is not null) g.Select(null);
                    TuiWindows.Select((int?)null);
                    break;
                case string s:
                    if (g is not null && g.Find(s) is not null) g.Select(g.Find(s)!.Id);
                    else TuiWindows.Select(s);
                    break;
                case double d when d == 0:
                    if (g is not null) g.Select(null);
                    TuiWindows.Select((int?)null);
                    break;
                case double d:
                    if (g is not null && g.Get((int)d) is not null) g.Select((int)d);
                    else TuiWindows.Select((int)d);
                    break;
                default:
                    if (g is not null) g.Select(null);
                    TuiWindows.Select((int?)null);
                    break;
            }
            // Parita' C/VM-C (gmb_window_manager_select): SELECT porta la finestra in primo
            // piano. Il solo Select() imposta il viewport di output ma NON cambia lo z-order,
            // quindi la finestra selezionata restava sotto le altre (z-order stantio).
            try { if (TuiWindows.ActiveWindowId is int aid) TuiWindows.Raise(aid); } catch { }
            if (g is not null) RenderPixelWindows();
            RenderTuiWindows();
        }
        catch { }
    }

    /// <summary>Ritorna la finestra attiva (ManagedWindow) o null se lo schermo base.</summary>
    private static ClipperLib.Controls.ManagedWindow? ActiveWindowObj()
    {
        try
        {
            var id = _tuiWindows?.ActiveWindowId;
            return id is int nid ? _tuiWindows?.Get(nid) : null;
        }
        catch { return null; }
    }

    /// <summary>Ritorna la finestra PIXEL attiva (viewport corrente su schermo grafico),
    /// o null se nessuna finestra pixel è selezionata / lo schermo grafico non è attivo.</summary>
    private static CommonGraphics.Graphics.PixelWindow? ActivePixelWindow()
    {
        try
        {
            if (!IsPixelWindowActive()) return null;
            var id = _gfxWindows?.ActiveId;
            return id is int nid ? _gfxWindows?.Get(nid) : null;
        }
        catch { return null; }
    }

    /// <summary>Disegna le finestre TUI (WindowManager). Con schermo grafico attivo
    /// delega al servizio grafico (RenderTui → SDL, Fase W3); altrimenti scrive ANSI
    /// via ConsoleRenderer sulla console. In headless (HeadlessConsoleService) il
    /// rendering resta in un buffer a griglia senza output — no-op visivo ma coerente.</summary>
    private static void RenderTuiWindows()
    {
        try
        {
            // Saltare SOLO se non c'è nulla da mostrare (nessuna finestra E nessun testo
            // STATUSBAR): WINDOW SELECT chiama sempre RenderTuiWindows() incondizionatamente,
            // anche per le finestre PIXEL — senza questo secondo controllo un "vero" salto
            // solo su WindowCount==0 avrebbe fatto comparire un desktop TUI vuoto (i puntini
            // decorativi di RenderDesktop) sopra lo schermo grafico ad ogni WINDOW SELECT,
            // anche in programmi che non usano MAI finestre TUI. Serve però renderizzare
            // quando c'è solo testo STATUSBAR e zero finestre (stesso bug già corretto in
            // RenderPixelWindows).
            if (_tuiWindows is null || (_tuiWindows.WindowCount == 0 && !_tuiWindows.HasStatusText)) return;
            var g = Current.Graphics;
            bool gfx;
            try { gfx = g.IsAvailable; } catch { gfx = false; }
            // Buffer 80x24 su grafica (parità texture SDL); su console usa le dimensioni
            // REALI del terminale, altrimenti il desktop blu copre solo 80x24 celle e il
            // resto della console resta col colore di default ("sfondo parzialmente colorato").
            int bufW = 80, bufH = 24;
            if (!gfx)
            {
                try { bufW = Math.Max(1, Console.WindowWidth); bufH = Math.Max(1, Console.WindowHeight); }
                catch { /* headless: restano 80x24 */ }
            }
            var buf = new CommonLib.Consoles.Tui.ScreenBuffer(bufW, bufH);
            var theme = ClipperLib.Controls.ControlStyle.ActiveTheme;
            _tuiWindows.SyncWorkArea(bufW, bufH);
            _tuiWindows.RenderWm(buf, theme, "", "");
            if (gfx)
            {
                // Fase W3: disegna le celle TUI sulla pagina grafica (SDL).
                var cells = new Basic.Runtime.TuiCell[80 * 24];
                for (var row = 0; row < 24; row++)
                {
                    for (var col = 0; col < 80; col++)
                    {
                        var cell = buf.Cells[row, col];
                        cells[row * 80 + col] = new Basic.Runtime.TuiCell(
                            cell.Character == '\0' ? ' ' : cell.Character,
                            ToArgbRgba(cell.ForegroundRgb),
                            ToArgbRgba(cell.BackgroundRgb));
                    }
                }
                g.RenderTui(cells, 80, 24);
                return;
            }
            CommonLib.Consoles.Tui.ConsoleRenderer.Write(buf);
        }
        catch { }
    }

    private static uint ToArgbRgba(CommonLib.Screens.CellColor? c)
    {
        if (c is null || c.Value.IsDefault) return 0xFF000000;
        return 0xFF000000u | ((uint)c.Value.R << 16) | ((uint)c.Value.G << 8) | c.Value.B;
    }

    // ── ON KEY / ON MOUSE / ON WINDOW ────────────────────────────────
    // Porting da GMBasic (commit 5485907e). Riusa CommonLib.App.EventDispatcher.Instance —
    // LO STESSO dispatcher unificato usato dal P-Code VM (RegisterKey/RegisterMouse/
    // RegisterWindow + DispatchKey/DispatchMouse/DispatchWindow, già chiamati dai punti di
    // lettura input condivisi tra i due backend) — quindi qui basta registrare l'handler, il
    // dispatch a runtime è già cablato. Solo l'azione CALL è supportata: GOTO/GOSUB
    // richiederebbero di saltare a un'etichetta arbitraria da un thread di dispatch
    // indipendente, e in un metodo IL compilato le etichette sono jump target INTERNI al corpo
    // del metodo (non punti di ingresso invocabili dall'esterno) — a differenza della P-Code
    // VM, dove ogni "task" è liberamente spawnabile a un IP arbitrario.
    public static void RegisterKeyHandler(int keyCode, Action handler) =>
        CommonLib.App.EventDispatcher.Instance.RegisterKey(new CommonLib.Keyboard.KeyCombination((ConsoleKey)keyCode, 0), handler);
    public static void UnregisterKeyHandler(int keyCode) =>
        CommonLib.App.EventDispatcher.Instance.UnregisterKey(new CommonLib.Keyboard.KeyCombination((ConsoleKey)keyCode, 0));

    /// <summary>ON KEY ... GOSUB &lt;handler&gt;: risolve Proc_&lt;symbolId&gt; a RUNTIME (il
    /// MethodBuilder non è CreateType quando il codegen emette ldftn → InvalidProgramException
    /// sull'intero stepper GPM, stesso schema di RegisterSpriteCollisionBySymbol) e registra
    /// un handler che DISPATCHA COME TASK GPM (SpawnGoSub) — la SUB gira in-context su un
    /// worker, mai invocata in diretta sul thread del dispatcher (TerminalReader/GUI/SDL =
    /// iniezione esterna nel GPM, stessa classe della race WS). Se la procedura non esiste,
    /// registra un no-op (label di riga/modulo).</summary>
    public static void RegisterKeyHandlerBySymbol(int keyCode, int symbolId)
    {
        var method = FindProcedureMethodIn(Assembly.GetCallingAssembly(), symbolId, paramTypes: null);
        Action handler = method is null
            ? NoopHandler
            : () => DispatchHandlerAsGpmOrDirect(symbolId, method, null);
        CommonLib.App.EventDispatcher.Instance.RegisterKey(new CommonLib.Keyboard.KeyCombination((ConsoleKey)keyCode, 0), handler);
    }
    /// <summary>KEY.MAKE(key, modifiers) → int compatibile con ON KEY (parità headless):
    /// RegisterKeyHandler decodifica il codice come (ConsoleKey)keyCode, quindi qui si
    /// restituisce il tasto base; i modifier sono accettati ma non combinati (stub).</summary>
    public static double KeyMake(double key, double modifiers) => (int)key;
    public static void RegisterMouseHandler(int kind, Action handler) =>
        CommonLib.App.EventDispatcher.Instance.RegisterMouse(kind, (_, _) => handler());
    public static void UnregisterMouseHandler(int kind) =>
        CommonLib.App.EventDispatcher.Instance.UnregisterMouse(kind);
    /// <summary>ON WINDOW ... STOP: rimuove l'handler per (evento, finestra); handle = -1 →
    /// qualunque finestra (forma senza OF).</summary>
    public static void UnregisterWindowHandler(int kind, int handle) =>
        CommonLib.App.EventDispatcher.Instance.UnregisterWindow(kind, handle);

    /// <summary>ON MOUSE ... GOSUB &lt;handler&gt;: come RegisterKeyHandlerBySymbol — la SUB
    /// gira come TASK GPM (SpawnGoSub), mai sul thread del dispatcher esterno.</summary>
    public static void RegisterMouseHandlerBySymbol(int kind, int symbolId)
    {
        var method = FindProcedureMethodIn(Assembly.GetCallingAssembly(), symbolId, paramTypes: null);
        Action handler = method is null
            ? NoopHandler
            : () => DispatchHandlerAsGpmOrDirect(symbolId, method, null);
        CommonLib.App.EventDispatcher.Instance.RegisterMouse(kind, (_, _) => handler());
    }

    /// <summary>ON WINDOW <ev> OF <handle> ... GOSUB/CALL: la registrazione vale solo per la
    /// finestra indicata (handle = -1 → qualunque finestra). Il dispatch è un TASK GPM.</summary>
    public static void RegisterWindowHandlerBySymbol(int kind, int handle, int symbolId)
    {
        var method = FindProcedureMethodIn(Assembly.GetCallingAssembly(), symbolId, paramTypes: null);
        Action handler = method is null
            ? NoopHandler
            : () => DispatchHandlerAsGpmOrDirect(symbolId, method, null);
        CommonLib.App.EventDispatcher.Instance.RegisterWindow(kind, handle, handler);
    }

    /// <summary>Dispatch di un handler di evento (ON KEY/MOUSE/WINDOW) come TASK GPM quando
    /// lo scheduler del programma è attivo; fallback deterministico (invocazione diretta)
    /// solo quando il run non è GPM. La SUB NON viene mai eseguita sul thread del dispatcher
    /// esterno quando c'è un GPM: niente iniezione esterna nel GPM (parità PCodeVM Fire*Event).</summary>
    public static void DispatchHandlerAsGpmOrDirect(int symbolId, System.Reflection.MethodInfo method, object?[]? args)
    {
        var scheduler = IlGpmRuntime.CurrentScheduler;
        if (scheduler != null)
        {
            IlGpmRuntime.SpawnGoSub(scheduler, symbolId, args ?? [], null);
            return;
        }
        // Thread ESTERNO alla GPM (ricezione MESSAGE/WS, watcher IO): il task non c'è, ma il
        // CONTESTO va applicato esplicitamente (§0ter) — lo scope globale è [ThreadStatic],
        // quindi senza questo le variabili di modulo scritte dall'handler finiscono nello scope
        // di QUESTO thread e il programma non le vede mai (misurato: handler stampa g=1, Main
        // legge g=0). Stesso pattern di InvokeBasicProcedureGpm (BeginGlobalScope/End).
        var scope = ProgramGlobalScope;
        if (scope != null) BeginGlobalScope(scope);
        try { method.Invoke(null, args); } catch { }
        finally { if (scope != null) EndGlobalScope(); }
    }

    /// <summary>Handler finestra no-op: usato quando ON WINDOW ... GOSUB punta a una
    /// label di riga/modulo (nessuna procedura da ldftn). L'evento non scatta mai in
    /// esecuzione headless/sequenziale, quindi non fa nulla.</summary>
    public static void NoopHandler() { }


    // ── IO Watch ──────────────────────────────────────────────────────
    private static readonly ConcurrentDictionary<string, FileSystemWatcher> _watchers = new(StringComparer.OrdinalIgnoreCase);

    public static void IoWatch(string path, int eventsMask, string callbackName = "")
    {
        if (_watchers.ContainsKey(path)) return;
        var watcher = new FileSystemWatcher(Path.GetDirectoryName(path) ?? ".", Path.GetFileName(path))
        {
            NotifyFilter = NotifyFilters.LastWrite | NotifyFilters.FileName | NotifyFilters.Size
        };
        if (!string.IsNullOrWhiteSpace(callbackName))
        {
            // Dispatch della SUB come task GPM (§0ter): mai invocarla sul thread del watcher.
            watcher.Changed += (_, _) => { try { InvokeBasicProcedureGpm(callbackName, ""); } catch { /* watcher dismesso */ } };
        }
        watcher.EnableRaisingEvents = true;
        _watchers.TryAdd(path, watcher);
    }

    public static void IoUnwatch(string path)
    {
        if (_watchers.TryRemove(path, out var watcher))
        {
            watcher.EnableRaisingEvents = false;
            watcher.Dispose();
        }
    }

