    public static void SetTheme(string themeName)
    {
        // Tema: applica al runtime C (widget C) + allo stato colore C; il C# ControlStyle
        // resta per la WindowManager C#. Parità PCodeVM (SET THEME / WINDOW THEME).
        var theme = ClipperLib.Controls.Theme.Named(themeName);
        try
        {
            ClipperLib.Controls.ControlStyle.SetTheme(theme);
            Current.Graphics.ClipperSetThemeName(themeName);
            Current.Graphics.ClipperSetFgBg(theme.Text, theme.DesktopBg);
            RenderTuiWindows();
        }
        catch { /* TUI non inizializzata: best-effort */ }
    }

