    // ── Handle store helper ───────────────────────────────────────────
    private static long _nextHandle = 1000;
    private static readonly ConcurrentDictionary<long, IDisposable> _disposableHandles = new();

    private static long StoreHandle(IDisposable obj)
    {
        var handle = Interlocked.Increment(ref _nextHandle);
        _disposableHandles.TryAdd(handle, obj);
        return handle;
    }

