    // ── TEAM RUN asincrono + WAIT (item 3): lancia il team su Task.Run (non blocca il worker)
    // e ritorna un handle; TEAMWAIT recupera il risultato. Registry per-handle, thread-safe.
    private static readonly System.Collections.Concurrent.ConcurrentDictionary<string, System.Threading.Tasks.Task<string>> _teamAsync = new();
    private static int _teamAsyncSeq;

    /// <summary>Lancia il run del team su un thread pool (non blocca) e ritorna un handle string.</summary>
    public static string TeamRunStart(string team, string task)
    {
        var record = Basic.Agents.TeamServer.Instance.Get(team);
        if (record is null) return $"ERROR: Team '{team}' non trovato (usa TEAM CREATE prima).";
        var handle = "team_" + System.Threading.Interlocked.Increment(ref _teamAsyncSeq);
        _teamAsync[handle] = System.Threading.Tasks.Task.Run(() => Basic.Agents.TeamOrchestrator.Run(record, task));
        return handle;
    }

    /// <summary>Attende il risultato del team avviato con TeamRunStart. Bloccante: chiamarlo fuori
    /// da un task GPM concorrente (stesso modello del TEAM RUN sincrono esistente) o con WAITKEY-park.
    /// Se il task è fallito ritorna "Error: ...".</summary>
    public static string TeamRunWait(string handle)
    {
        if (!_teamAsync.TryGetValue(handle, out var t))
            return $"Error: handle team sconosciuto '{handle}' (TeamRunStart non chiamato o già consumato)";
        try
        {
            var r = t.GetAwaiter().GetResult();
            _teamAsync.TryRemove(handle, out _);
            return r;
        }
        catch (System.Exception ex) { _teamAsync.TryRemove(handle, out _); return "Error: " + ex.Message; }
    }

    // ── Team streaming callback (item 1): registra una SUB BASIC per nome che riceve ogni
    // member-completed (membro, testo). Il dispatch usa InvokeBasicProcedureGpm (gestisce la GPM),
    // MAI eseguito sul thread del dispatcher. Sub idempotente per nome. ──
    private static readonly object _teamStreamLock = new();
    private static readonly System.Collections.Generic.HashSet<string> _teamStreamSubs = new();
    private static bool _teamStreamHooked;
    public static double TeamOnStream(string subName)
    {
        if (string.IsNullOrWhiteSpace(subName)) return 0.0;
        lock (_teamStreamLock)
        {
            if (_teamStreamSubs.Add(subName) && !_teamStreamHooked)
            {
                _teamStreamHooked = true;
                Basic.Agents.TeamOrchestrator.MemberCompleted += (tm, member, text) =>
                {
                    string[] subs;
                    lock (_teamStreamLock) subs = _teamStreamSubs.ToArray();
                    foreach (var s in subs)
                    {
                        try
                        {
                            var args = System.Text.Json.JsonSerializer.Serialize(new[] { member, text });
                            InvokeBasicProcedureGpm(s, args);
                        }
                        catch { /* il consumer non deve far fallire lo stream del team */ }
                    }
                };
            }
            return 1.0;
        }
    }

