    // ── AI VERIFY ... REQUIRE (2026-09-09, decisione (b)) ──
    // Comando verifier/retry: ogni tentativo esegue `action`; se produce un errore si ritenta;
    // altrimenti `require` (espressione BASIC valutata con le LOCALI del chiamante + RESULT$ =
    // risultato del tentativo) deve dare true. Dopo maxRetries (default 3) fallimento ESPLICITO.
    // Azioni v1: "COMPILE <path>" (deterministico, host C#, via CodeGenTools→Orchestrator).
    // Mai stub silenziosi (AGENTS §0bis): azione non riconosciuta = errore esplicito.
    public static string AiVerify(string action, string require, double maxRetries,
        string[]? localNames, object?[]? localValues)
    {
        int mr = maxRetries < 1 ? 1 : (int)System.Math.Min(maxRetries, 100);
        string feedback = "";
        for (int attempt = 1; attempt <= mr; attempt++)
        {
            var (result, error) = RunVerifyAttempt(action);
            if (!string.IsNullOrEmpty(error))
            {
                feedback = $"Tentativo {attempt} fallito: {error}";
                continue;
            }
            if (VerifyRequireHolds(require, result, localNames, localValues))
                return result;
            feedback = $"Tentativo {attempt}: il risultato non soddisfa il REQUIRE.\nRisultato:\n{result}";
        }
        throw new InvalidOperationException(
            $"AI VERIFY fallito dopo {mr} tentativi: {(string.IsNullOrEmpty(feedback) ? action : feedback)}");
    }

    private static (string result, string error) RunVerifyAttempt(string action)
    {
        var t = string.IsNullOrEmpty(action) ? "" : action.Trim();
        if (t.StartsWith("COMPILE ", System.StringComparison.OrdinalIgnoreCase))
        {
            var path = t.Substring("COMPILE ".Length).Trim();
            if (string.IsNullOrEmpty(path)) return ("", "COMPILE: path mancante");
            var (ok, diag) = Basic.Agents.CodeGenTools.ToolCompile(path);
            return ok ? ("Compile OK", "") : ("", diag);
        }
        throw new InvalidOperationException(
            $"AI VERIFY: azione non supportata '{action}' (v1 supporta solo 'COMPILE <path>')");
    }

    private static bool VerifyRequireHolds(string require, string result,
        string[]? localNames, object?[]? localValues)
    {
        if (string.IsNullOrWhiteSpace(require)) return true;
        // Valuta il REQUIRE con le locali del chiamante + RESULT$ (nome esatto: il codice del
        // macro fa match OrdinalIgnoreCase sul testo grezzo — NON normalizzare il suffisso $).
        var names = AiVerifyExtendNames(localNames);
        var values = AiVerifyExtendValues(localValues, result);
        try
        {
            var v = MacroEvalExprWithLocals(require, names, values);
            return AiVerifyTruthy(v);
        }
        catch (System.Exception ex)
        {
            throw new InvalidOperationException($"AI VERIFY: REQUIRE non valutabile: {ex.Message}", ex);
        }
    }

    private static string[] AiVerifyExtendNames(string[]? localNames)
    {
        int n = localNames?.Length ?? 0;
        var r = new string[n + 2];
        if (localNames != null) for (int i = 0; i < n; i++) r[i] = localNames[i];
        // Doppio alias: il compilatore del macro può interrogare il nome col suffisso grezzo
        // (RESULT$) o normalizzato senza suffisso (RESULT) — match OrdinalIgnoreCase su entrambi.
        r[n] = "RESULT$";
        r[n + 1] = "RESULT";
        return r;
    }

    private static object?[] AiVerifyExtendValues(object?[]? localValues, string result)
    {
        int n = localValues?.Length ?? 0;
        var r = new object?[n + 2];
        if (localValues != null) for (int i = 0; i < n; i++) r[i] = localValues[i];
        r[n] = result;
        r[n + 1] = result;
        return r;
    }

    private static bool AiVerifyTruthy(object? v)
    {
        switch (v)
        {
            case bool b: return b;
            case double d: return d != 0.0;
            case float f: return f != 0.0f;
            case int i: return i != 0;
            case long l: return l != 0;
            case string s: return s.Length > 0 && !s.Equals("0") && !s.Equals("false", System.StringComparison.OrdinalIgnoreCase);
            default: return false;
        }
    }

