    // ── AI DECIDE <state>, "<NOUL|SCORE|CHOICE>" [INTO target] (JEV/SystemOne, v0 JSON) ──
    // Provider deterministico Rules (nessun modello): restituisce lo stesso JSON del runtime C
    // (gmb_ai_decide_run_json), così le 4 gambe sono confrontabili. La superficie tipizzata
    // DECISION<T> e il provider locale MLX (ABI v8 CAP_DECIDE) sono il passo successivo.
    public static string AiDecide(string state, string kind) => AiDecide(state, kind, "");

    /// <summary>Risolve il nome di provider di `AI DECIDE` nel kind effettivo. Vuoto → provider
    /// `%DECIDE` attivo; un alias registrato col ruolo `%DECIDE` (`USING "jev"`) → il suo kind; il
    /// nome `verbalizer` → il `%DECIDE` attivo se è di quel kind. Per il kind `verbalizer` ritorna
    /// anche il profilo (decide/decideTemplate/decideCalibration) preso dalla config di QUEL provider,
    /// così lo stesso modello può avere più decisori con template/calibrazione diversi.</summary>
    private static string ResolveDecideProvider(string? provider, out string? decideName,
        out Basic.Decision.DecideProfile? profile)
    {
        var server = Basic.Providers.ProviderServer.Instance;
        decideName = null;
        profile = null;
        var requested = (provider ?? "").Trim();
        var p = requested.ToLowerInvariant();
        if (p.Length == 0)
        {
            decideName = server.GetActiveName(Basic.Providers.ProviderRole.Decide);
        }
        else if (p == "verbalizer")
        {
            var active = server.GetActiveName(Basic.Providers.ProviderRole.Decide);
            if (!string.IsNullOrWhiteSpace(active)
                && string.Equals(server.GetKind(active), "verbalizer", StringComparison.OrdinalIgnoreCase))
                decideName = active;
        }
        else if (p is not ("rules" or "mock" or "local" or "typesafe" or "clm" or "adapter" or "llm")
                 && string.Equals(server.GetRole(requested), Basic.Providers.ProviderRole.Decide,
                     StringComparison.Ordinal))
        {
            decideName = requested;
        }
        if (!string.IsNullOrWhiteSpace(decideName))
        {
            var decideKind = server.GetKind(decideName);
            if (!string.IsNullOrWhiteSpace(decideKind))
                p = decideKind.Trim().ToLowerInvariant();
        }
        if (p == "verbalizer")
        {
            var cfg = string.IsNullOrWhiteSpace(decideName)
                ? new Dictionary<string, string>()
                : server.GetConfigMap(decideName);
            profile = Basic.Decision.DecideProfile.FromConfig(cfg);
            // Il verbalizer è un decisore esplicito: modalità `on` salvo `decide` nella sua config.
            profile = profile with { Mode = profile.Mode ?? "on" };
        }
        return p;
    }

    public static string AiDecide(string state, string kind, string provider)
    {
        try
        {
            var raw = (kind ?? "").Trim();
            var k = raw.ToUpperInvariant();
            var kindName = k.StartsWith("CHOICE", StringComparison.Ordinal) ? "CHOICE" : k;
            if (k.StartsWith("RANK:", StringComparison.Ordinal))
            {
                // RANK ("RANK:c1|c2|…"): best-of-N su candidati liberi, solo col provider clm; lo esegue il C.
                var rankProvider = ResolveDecideProvider(provider, out var rankName, out _);
                if (rankProvider != "clm") return "{\"error\":\"RANK richiede il provider clm\"}";
                rankName ??= Basic.Providers.ProviderServer.Instance.GetActiveName(Basic.Providers.ProviderRole.Decide);
                if (string.IsNullOrWhiteSpace(rankName))
                    return "{\"error\":\"clm: nessun provider %DECIDE attivo con config (baseUrl)\"}";
                return Basic.Decision.NativeClm.Run(state ?? "", raw,
                    Basic.Providers.ProviderServer.Instance.GetConfigMap(rankName));
            }
            Basic.Decision.DecisionRequest request;
            if (kindName == "CHOICE" && raw.Length > 6 && raw[6] == ':')
            {
                var labels = raw[7..].Split('|', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
                request = labels.Length > 0
                    ? Basic.Decision.DecisionSlots.CreateChoice(state ?? "", labels)
                    : new Basic.Decision.DecisionRequest(state ?? "",
                        Basic.Decision.DecisionKind.Choice, Basic.Decision.DecisionSlots.Choice);
            }
            else if (kindName.StartsWith("SCORE:", StringComparison.Ordinal))
            {
                // Rubrica esplicita `SCORE:lo:hi` (oggi 0..5 canonica e 0..10 linguistica).
                var parts = raw.Split(':');
                if (parts.Length != 3
                    || !int.TryParse(parts[1], System.Globalization.NumberStyles.Integer,
                        System.Globalization.CultureInfo.InvariantCulture, out var lo)
                    || !int.TryParse(parts[2], System.Globalization.NumberStyles.Integer,
                        System.Globalization.CultureInfo.InvariantCulture, out var hi))
                    throw new ArgumentException($"kind '{kind}' non valido (SCORE:lo:hi).");
                request = Basic.Decision.DecisionSlots.CreateScoreRange(state ?? "", lo, hi);
            }
            else
            {
                request = kindName switch
                {
                    "NOUL" => Basic.Decision.DecisionSlots.CreateNoul(state ?? ""),
                    "SCORE" => Basic.Decision.DecisionSlots.CreateScore(state ?? ""),
                    "CHOICE" => new Basic.Decision.DecisionRequest(state ?? "",
                        Basic.Decision.DecisionKind.Choice, Basic.Decision.DecisionSlots.Choice),
                    _ => throw new ArgumentException($"kind '{kind}' non valido (NOUL/SCORE/CHOICE[:labels])"),
                };
            }
            // Ruolo %DECIDE (AI REGISTER alias, %DECIDE, kind; AI SET ACTIVE %DECIDE, alias) oppure alias
            // %DECIDE esplicito (USING "alias"); kind `verbalizer` porta con sé il profilo di decisione.
            var p = ResolveDecideProvider(provider, out var decideName, out var decideProfile);
            using var decideProfileScope = Basic.Decision.DecideProfile.Push(decideProfile);
            Basic.Decision.DecisionResult result;
            if (p == "typesafe")
            {
                // Provider remoto: config dal provider %DECIDE attivo (kind "typesafe").
                decideName ??= Basic.Providers.ProviderServer.Instance.GetActiveName(
                    Basic.Providers.ProviderRole.Decide);
                if (string.IsNullOrWhiteSpace(decideName))
                    throw new Basic.Decision.DecisionProviderException(
                        "typesafe: nessun provider %DECIDE attivo con config baseUrl.");
                var cfg = Basic.Providers.ProviderServer.Instance.GetConfigMap(decideName);
                cfg.TryGetValue("baseUrl", out var baseUrl);
                cfg.TryGetValue("apiKey", out var apiKey);
                cfg.TryGetValue("model", out var model);
                var timeout = TimeSpan.FromSeconds(30);
                if (cfg.TryGetValue("timeoutMs", out var timeoutText)
                    && int.TryParse(timeoutText, out var timeoutMs) && timeoutMs > 0)
                    timeout = TimeSpan.FromMilliseconds(timeoutMs);
                result = new Basic.Decision.TypesafeDecisionProvider(baseUrl ?? "", apiKey, model, timeout)
                    .Evaluate(request)[0];
            }
            else if (p == "clm")
            {
                // Provider CLM (contratto SystemOne): il C# CONSUMA il runtime C via P/Invoke (libgmb_clm);
                // la config del %DECIDE attivo si passa in JSON. Risposta già nella forma di AI DECIDE.
                decideName ??= Basic.Providers.ProviderServer.Instance.GetActiveName(
                    Basic.Providers.ProviderRole.Decide);
                if (string.IsNullOrWhiteSpace(decideName))
                    return "{\"error\":\"clm: nessun provider %DECIDE attivo con config (baseUrl)\"}";
                return Basic.Decision.NativeClm.Run(state ?? "", raw,
                    Basic.Providers.ProviderServer.Instance.GetConfigMap(decideName));
            }
            else if (p is "adapter" or "llm")
            {
                // P6: adapter generativo sul completer ATTIVO (locale o remoto). Serve ai
                // modelli/endpoint che non espongono logprob; la probabilità è 1/0 sull'opzione
                // riconosciuta e nessun match è un errore esplicito.
                Basic.AI.Rag.ILlmCompleter? adapterCompleter = null;
                try { adapterCompleter = Basic.Providers.ProviderServer.Instance.GetActiveCompletion(); }
                catch { /* sotto → errore esplicito */ }
                if (adapterCompleter is null)
                    return "{\"error\":\"adapter: nessun provider di completion attivo\"}";
                result = new Basic.Decision.AdapterDecisionProvider(adapterCompleter).Evaluate(request)[0];
            }
            else if (p is "local" or "verbalizer")
            {
                // Provider locale MLX: richiede un completer attivo che implementi
                // IDecisionCompleter (MlxLlmCompleter). Senza modello attivo → errore JSON
                // esplicito, identico al runtime C (che non ha il provider locale).
                Basic.AI.Rag.ILlmCompleter? completer = null;
                try { completer = Basic.Providers.ProviderServer.Instance.GetActiveCompletion(); }
                catch { /* nessun provider attivo: sotto → errore esplicito */ }
                if (completer is not Basic.Decision.IDecisionCompleter decisionCompleter)
                    return "{\"error\":\"local: local provider non disponibile: nessun modello MLX attivo (AI REGISTER con path o \\\"mlx\\\"+modelDir + AI SET ACTIVE)\"}";
                var localResults = decisionCompleter.Decide(request);
                if (localResults.Count == 0)
                    return "{\"error\":\"local: local provider: nessun risultato\"}";
                result = localResults.OrderByDescending(r => r.Probability).First();
            }
            else
            {
                Basic.Decision.ISystemOneProvider decisionProvider = p switch
                {
                    "" or "rules" => new Basic.Decision.RuleDecisionProvider(),
                    "mock" => new Basic.Decision.MockDecisionProvider(),
                    _ => throw new ArgumentException($"provider '{provider}' non valido (rules/mock/local)"),
                };
                result = decisionProvider.Evaluate(request)[0];
            }
            var value = result.Value switch
            {
                bool b => b ? "true" : "false",
                double d => d.ToString("0.#####", System.Globalization.CultureInfo.InvariantCulture),
                null => "",
                _ => result.Value.ToString() ?? "",
            };
            static string Esc(string? s) => (s ?? "").Replace("\\", "\\\\").Replace("\"", "\\\"");
            static string Num(double? v) => v.HasValue
                ? v.Value.ToString("0.000000", System.Globalization.CultureInfo.InvariantCulture)
                : "null";
            return $"{{\"kind\":\"{kindName}\",\"option\":\"{Esc(result.OptionId)}\",\"value\":\"{Esc(value)}\",\"probability\":{result.Probability.ToString("0.000000", System.Globalization.CultureInfo.InvariantCulture)},\"confidence\":{Num(result.Confidence)},\"calibrated\":{Num(result.Calibrated)}}}";
        }
        catch (Exception ex)
        {
            return $"{{\"error\":\"{ex.Message.Replace("\"", "'")}\"}}";
        }
    }

    /// <summary>Catena di fallback esplicita: prova il provider primario e poi ogni nome in
    /// `fallback` (CSV `|`). Il primo risultato NON-errore vince; se tutti falliscono ritorna un
    /// JSON `{"error":"tutti i provider falliti: …"}` con il motivo di ciascuno. Nessun
    /// fallback implicito: la catena esiste solo se il programma la scrive.</summary>
    public static string AiDecide(string state, string kind, string provider, string fallback)
    {
        var chain = new List<string>();
        if (!string.IsNullOrWhiteSpace(provider)) chain.Add(provider.Trim());
        if (!string.IsNullOrWhiteSpace(fallback))
            chain.AddRange(fallback.Split('|', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries));
        if (chain.Count == 0) chain.Add("rules");

        var errors = new List<string>();
        foreach (var name in chain)
        {
            var result = AiDecide(state, kind, name);
            if (!result.StartsWith("{\"error\"", StringComparison.Ordinal))
                return result;
            errors.Add($"{name}: {AiDecideErrorText(result)}");
        }
        var detail = string.Join(" | ", errors);
        detail = detail.Replace("\\", "\\\\").Replace("\"", "\\\"");
        return $"{{\"error\":\"tutti i provider falliti: {detail}\"}}";
    }

    /// <summary>Testo dell'errore da un JSON `{"error":"..."}` (o il JSON stesso se non lo è).</summary>
    private static string AiDecideErrorText(string json)
    {
        const string prefix = "{\"error\":\"";
        if (json.StartsWith(prefix, StringComparison.Ordinal) && json.EndsWith("\"}", StringComparison.Ordinal))
            return json[prefix.Length..^2].Replace("\\\"", "\"");
        return json;
    }

    [ThreadStatic] private static string? _lastDecideGroupKey;
    [ThreadStatic] private static string? _lastDecideGroupResult;

    private static string[] ParseGroupArray(string? json)
    {
        if (string.IsNullOrWhiteSpace(json)) return [];
        try
        {
            return System.Text.Json.JsonSerializer.Deserialize<string[]>(json) ?? [];
        }
        catch { return []; }
    }

    /// <summary>Forma batch interna: N domande sullo stesso stato, una sola entry point.
    /// Ritorna un oggetto JSON `{nome:"&lt;json risultato&gt;"}` (i valori sono STRINGHE col
    /// JSON della singola decisione, così `JSON.EXTRACT` restituisce il testo originale).
    /// Se il provider è `local` e implementa `IDecisionGroupCompleter`, usa il percorso
    /// group-aware (prefill/KV condiviso); altrimenti valuta le domande in sequenza con la
    /// stessa semantica (fallback incluso).</summary>
    public static string AiDecideGroup(string state, string namesCsv, string kindsCsv,
        string provider, string fallback)
    {
        var names = ParseGroupArray(namesCsv);
        var kinds = ParseGroupArray(kindsCsv);
        // La desugar del batch riusa lo stesso nodo per N estrazioni: la prima chiamata
        // calcola il gruppo, le successive (stessi argomenti, stesso thread) leggono la cache.
        var cacheKey = (state ?? "") + "\u0001" + (namesCsv ?? "") + "\u0001" + (kindsCsv ?? "")
                     + "\u0001" + (provider ?? "") + "\u0001" + (fallback ?? "");
        if (cacheKey == _lastDecideGroupKey && _lastDecideGroupResult is not null)
            return _lastDecideGroupResult;
        var obj = new System.Text.Json.Nodes.JsonObject();
        if (names.Length == 0)
            return "{\"error\":\"AiDecideGroup: nessuna domanda\"}";
        if (names.Length != kinds.Length)
        {
            for (var i = 0; i < names.Length; i++)
                obj[names[i]] = "{\"error\":\"AiDecideGroup: names/kinds disallineati\"}";
            return obj.ToJsonString();
        }

        var p = ResolveDecideProvider(provider, out _, out var groupProfile);
        using var groupProfileScope = Basic.Decision.DecideProfile.Push(groupProfile);

        var canGroup = p is "local" or "verbalizer" && string.IsNullOrWhiteSpace(fallback);
        if (canGroup)
        {
            Basic.AI.Rag.ILlmCompleter? completer = null;
            try { completer = Basic.Providers.ProviderServer.Instance.GetActiveCompletion(); }
            catch { /* sotto: percorso sequenziale */ }
            if (completer is Basic.Decision.IDecisionGroupCompleter groupCompleter)
            {
                var requests = kinds.Select(k => BuildDecisionRequest(state, k)).ToList();
                var results = groupCompleter.DecideGroup(requests);
                if (results.Count == requests.Count)
                {
                    for (var i = 0; i < names.Length; i++)
                    {
                        var kindName = KindName(kinds[i]);
                        obj[names[i]] = FormatDecisionJson(kindName, results[i]);
                    }
                    _lastDecideGroupKey = cacheKey; _lastDecideGroupResult = obj.ToJsonString();
                    return _lastDecideGroupResult;
                }
                /* numero inatteso: sotto si ricade sul percorso sequenziale */
            }
        }

        for (var i = 0; i < names.Length; i++)
            obj[names[i]] = AiDecide(state, kinds[i], provider, fallback);
        _lastDecideGroupKey = cacheKey; _lastDecideGroupResult = obj.ToJsonString();
        return _lastDecideGroupResult;
    }

    /// <summary>Diagnostica `AI DECIDE VERIFY`: esegue la stessa richiesta su più provider
    /// (default `rules|mock`) e riporta accordo/drift. Non altera lo stato.</summary>
    public static string AiDecideVerify(string state, string kind, string providersCsv)
        => AiDecideVerify(state, kind, providersCsv, "", "", "");

    public static string AiDecideVerify(string state, string kind, string providersCsv,
        string unused1, string unused2, string unused3)
    {
        _ = unused1; _ = unused2; _ = unused3;
        var providers = (providersCsv ?? "").Split('|',
            StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
        if (providers.Length == 0) providers = ["rules", "mock"];
        var results = new System.Text.Json.Nodes.JsonArray();
        var options = new List<string>();
        var probabilities = new List<double>();
        var ok = true;
        foreach (var provider in providers)
        {
            Basic.Decision.NativeClm.StatsReset();
            var raw = AiDecide(state, kind, provider);
            System.Text.Json.Nodes.JsonNode? node;
            try { node = System.Text.Json.Nodes.JsonNode.Parse(raw); }
            catch { node = null; }
            var entry = new System.Text.Json.Nodes.JsonObject
            {
                ["provider"] = provider,
                ["result"] = node,
            };
            // Misure del provider clm (tempi encoder/head/rete, embedding, margine), prese dal runtime C.
            if (Basic.Decision.NativeClm.StatsJson() is { } clmStats)
                entry["clm"] = System.Text.Json.Nodes.JsonNode.Parse(clmStats);
            results.Add(entry);
            if (node is System.Text.Json.Nodes.JsonObject obj && obj["error"] is null)
            {
                var option = obj["option"]?.GetValue<string>();
                if (!string.IsNullOrEmpty(option)) options.Add(option!);
                if (double.TryParse(obj["probability"]?.ToJsonString(),
                        System.Globalization.NumberStyles.Float,
                        System.Globalization.CultureInfo.InvariantCulture, out var prob))
                    probabilities.Add(prob);
            }
            else ok = false;
        }
        var distinct = options.Distinct(StringComparer.OrdinalIgnoreCase).Count();
        var agreement = distinct <= 1;
        var drift = options.Count == 0 ? 0 : distinct - 1;
        var spread = probabilities.Count == 0 ? 0.0 : probabilities.Max() - probabilities.Min();
        var report = new System.Text.Json.Nodes.JsonObject
        {
            ["ok"] = ok,
            ["agreement"] = agreement,
            ["argmaxDrift"] = drift,
            ["probabilitySpread"] = spread,
            ["results"] = results,
        };
        return report.ToJsonString();
    }

    private static Basic.Decision.DecisionRequest BuildDecisionRequest(string state, string kind)
    {
        var raw = (kind ?? "").Trim();
        var k = raw.ToUpperInvariant();
        if (k.StartsWith("CHOICE", StringComparison.Ordinal) && raw.Length > 6 && raw[6] == ':')
        {
            var labels = raw[7..].Split('|', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
            return labels.Length > 0
                ? Basic.Decision.DecisionSlots.CreateChoice(state ?? "", labels)
                : new Basic.Decision.DecisionRequest(state ?? "",
                    Basic.Decision.DecisionKind.Choice, Basic.Decision.DecisionSlots.Choice);
        }
        if (k.StartsWith("SCORE:", StringComparison.Ordinal))
        {
            var parts = raw.Split(':');
            if (parts.Length == 3
                && int.TryParse(parts[1], System.Globalization.NumberStyles.Integer,
                    System.Globalization.CultureInfo.InvariantCulture, out var lo)
                && int.TryParse(parts[2], System.Globalization.NumberStyles.Integer,
                    System.Globalization.CultureInfo.InvariantCulture, out var hi))
                return Basic.Decision.DecisionSlots.CreateScoreRange(state ?? "", lo, hi);
            throw new ArgumentException($"kind '{kind}' non valido (SCORE:lo:hi).");
        }
        return k switch
        {
            "NOUL" => Basic.Decision.DecisionSlots.CreateNoul(state ?? ""),
            "SCORE" => Basic.Decision.DecisionSlots.CreateScore(state ?? ""),
            "CHOICE" => new Basic.Decision.DecisionRequest(state ?? "",
                Basic.Decision.DecisionKind.Choice, Basic.Decision.DecisionSlots.Choice),
            _ => throw new ArgumentException($"kind '{kind}' non valido (NOUL/SCORE/CHOICE[:labels])"),
        };
    }

    private static string KindName(string kind)
    {
        var k = (kind ?? "").Trim().ToUpperInvariant();
        return k.StartsWith("CHOICE", StringComparison.Ordinal) ? "CHOICE" : k;
    }

    private static string FormatDecisionJson(string kindName, Basic.Decision.DecisionResult result)
    {
        var value = result.Value switch
        {
            bool b => b ? "true" : "false",
            double d => d.ToString("0.#####", System.Globalization.CultureInfo.InvariantCulture),
            null => "",
            _ => result.Value.ToString() ?? "",
        };
        static string Esc(string? s) => (s ?? "").Replace("\\", "\\\\").Replace("\"", "\\\"");
        static string Num(double? v) => v.HasValue
            ? v.Value.ToString("0.000000", System.Globalization.CultureInfo.InvariantCulture)
            : "null";
        return $"{{\"kind\":\"{kindName}\",\"option\":\"{Esc(result.OptionId)}\",\"value\":\"{Esc(value)}\",\"probability\":{result.Probability.ToString("0.000000", System.Globalization.CultureInfo.InvariantCulture)},\"confidence\":{Num(result.Confidence)},\"calibrated\":{Num(result.Calibrated)}}}";
    }

    // ── AI ASKCHAIN (T1.2, 2026-09-09): anello di ragionamento concatenato via Blackboard ──
    public static string AiAskChain(string name, string prompt, string prefix)
    {
        try { return Basic.Agents.AgentServer.Instance.AskChainedStep(name, prompt, prefix); }
        catch (Exception ex) { return $"ERROR: {ex.Message}"; }
    }

    /// <summary>AI.AGENTSWARM — Fase 1 reale: lancia N agenti (prefix+0..n-1, creati se mancano) che
    /// eseguono ognuno AgentServer.Ask(task) con concorrenza BOUNDED (<= maxConcurrency) via AgentBatch
    /// (SemaphoreSlim cap). NON un thread per agente. Ritorna i risultati (uno per riga, errore per-agente
    /// gestito — mai abortisce lo swarm). 0 = nessun agente.</summary>
    public static string AiAgentSwarm(double n, string agentPrefix, string task, double maxConcurrency)
    {
        int count = (int)n;
        if (count < 0) count = 0;
        if (count == 0) return "";
        if (string.IsNullOrWhiteSpace(agentPrefix)) return "Error: agentPrefix mancante";
        if (string.IsNullOrWhiteSpace(task)) return "Error: task mancante";
        var server = Basic.Agents.AgentServer.Instance;
        int cap = (int)maxConcurrency; if (cap < 1) cap = 8;
        var names = new string[count];
        for (int i = 0; i < count; i++) { names[i] = agentPrefix + i; if (!server.List().Any(a => a.Name.Equals(names[i], System.StringComparison.OrdinalIgnoreCase))) server.Create(names[i]); }
        var results = new string[count];
        var r = Basic.Agents.AgentBatch.Run(count, i =>
        {
            try { return server.Ask(names[i], task); }
            catch (System.Exception ex) { return $"[{names[i]} errore: {ex.Message}]"; }
        }, cap);
        for (int i = 0; i < count; i++) results[i] = r.Results[i];
        return string.Join("\n", results);
    }

    /// <summary>MESSAGE(text?) — getter (null) o setter+rendering del messaggio (riga SET MESSAGE).</summary>
    public static string MessageCmd(string? value)
    {
        try
        {
            var st = ClipperLib.Clipper.ClipperGlobal.State;
            if (value != null)
            {
                st.MessageText = value;
                if (st.MessageRow.HasValue)
                {
                    ClipperLib.Clipper.ClipperScrn.Prompt(st.MessageRow.Value, 0, value);
                    st.RenderHook?.Invoke(st.Buffer);
                }
                return value;
            }
            return st.MessageText;
        }
        catch { return ""; }
    }
