    public static void WorkflowStep(string name, string action, int retry, int timeout) => Basic.Workflow.WorkflowServer.Instance.AddStep(name, action, retry, timeout);
    public static void WorkflowEnd() => Basic.Workflow.WorkflowServer.Instance.EndDefinition();
