    public static string DocExtractEngine(string path)
    {
        // Classificazione senza fare OCR: conta le pagine con text-layer vs senza
        // (placeholder PDFOxide "OCR REQUIRED"). Ritorna PDFOXIDE / OCR / HYBRID.
        var h = NativeDocPdf.Open(path);
        if (h == 0) return "";
        int pages = NativeDocPdf.PageCount(h);
        if (pages < 1) pages = 1;
        int text = 0, ocr = 0;
        for (int p = 0; p < pages; p++)
        {
            var md = NativeDocPdf.Markdown(h, p);
            if (md.Trim().Length >= 20 && !md.Contains("OCR REQUIRED")) text++;
            else ocr++;
        }
        NativeDocPdf.Close(h);
        return ocr == 0 ? "PDFOXIDE" : text == 0 ? "OCR" : "HYBRID";
    }

