    public static double ConvertExtractTo(string src, string dest)
    {
        var text = DocExtract(src);
        System.IO.File.WriteAllText(dest, text);
        return 1.0;
    }

    public static double ConvertRenderTo(string src, string dest)
    {
        var h = NativeDocPdf.Open(src);
        if (h == 0) return -1.0;
        int rc = NativeDocPdf.RenderPng(h, 0, 150, dest);
        NativeDocPdf.Close(h);
        return rc == 0 ? 1.0 : -1.0;
    }

    public static string DocExtract(string path)
    {
        // ROUTING HYBRID per pagina: text-layer via PDFOxide dove presente; sulle pagine
        // senza text-layer (placeholder PDFOxide "OCR REQUIRED" / vuote) → OCR locale
        // (immagine embedded dello scan; fallback render 150dpi downscalato a 1280).
        var h = NativeDocPdf.Open(path);
        if (h == 0) return "";
        // FAST PATH (parità col C): documento a solo text-layer → to_markdown_all grezzo,
        // identico a gmb_doc_pdf_convert (nessun trim del newline finale). Il placeholder
        // "OCR REQUIRED" segnala pagine scansionate → altrimenti loop hybrid sotto.
        var all = NativeDocPdf.Markdown(h, -1);
        if (!all.Contains("OCR REQUIRED") && all.Trim().Length >= 20)
        {
            NativeDocPdf.Close(h);
            return all;
        }
        var sb = new System.Text.StringBuilder();
        int pages = NativeDocPdf.PageCount(h);
        if (pages < 1) pages = 1;
        var tmpDir = System.IO.Path.Combine(System.IO.Path.GetTempPath(), "gmb-extract-" + System.Guid.NewGuid().ToString("N"));
        int ocrPages = 0;
        for (int p = 0; p < pages; p++)
        {
            var md = NativeDocPdf.Markdown(h, p);
            bool hasText = md.Trim().Length >= 20 && !md.Contains("OCR REQUIRED");
            if (hasText)
            {
                if (sb.Length > 0) sb.Append('\n');
                sb.Append(md.Trim());
                continue;
            }
            // pagina scanned → OCR
            var emb = NativeDocPdf.ExtractFirstImage(h, p, tmpDir);
            string ocr;
            if (!string.IsNullOrEmpty(emb) && System.IO.File.Exists(emb))
                ocr = AiOcr(emb);
            else
            {
                var tmpPng = System.IO.Path.Combine(tmpDir, "p" + p + ".png");
                NativeDocPdf.RenderPngMaxWidth(h, p, 150, tmpPng, 1280);
                ocr = AiOcr(tmpPng);
            }
            if (!string.IsNullOrWhiteSpace(ocr) && !ocr.Contains("OCR REQUIRED"))
            {
                if (sb.Length > 0) sb.Append('\n');
                sb.Append(ocr.Trim());
            }
            ocrPages++;
        }
        NativeDocPdf.Close(h);
        try { System.IO.Directory.Delete(tmpDir, true); } catch { }
        return sb.ToString();
    }

    public static string AiOcr(string path) => AiOcrFull(path, "Extract all text from this image.");
    public static string AiOcrFull(string path, string prompt) => AiOcrFull(path, prompt, 0);
    public static string AiOcrFull(string path, string prompt, double redact)
    {
        if (!File.Exists(path)) return "[AI OCR: file not found]";
        try
        {
            var server = Basic.Providers.ProviderServer.Instance;
            var name = server.GetActiveName("ocr");
            if (string.IsNullOrEmpty(name)) return "[AI OCR: no active OCR provider — AI SET ACTIVE %OCR, alias first]";
            var instance = server.GetActiveCompletion("ocr");
            if (instance is not Basic.AI.Rag.IVisionCompleter vision)
                return $"[AI OCR: provider '{name}' does not support vision]";
            var imageBytes = File.ReadAllBytes(path);
            var format = Path.GetExtension(path).TrimStart('.').ToLowerInvariant();
            if (format == "jpg") format = "jpeg";
            var text = vision.DescribeImage(imageBytes, format, prompt);
            return redact != 0 ? Basic.AI.PiiRedactor.Redact(text) : text;
        }
        catch (Exception ex) { return $"[AI OCR ERROR: {ex.Message}]"; }
    }
    public static string AiStub() => "OK";

    public static string AiTranscribe(string path)
    {
        if (!File.Exists(path)) return "[AI Transcribe: file not found]";
        try
        {
            var server = Basic.Providers.ProviderServer.Instance;
            var name = server.GetActiveName("audio");
            if (string.IsNullOrEmpty(name)) return "[AI Transcribe: no active audio provider — AI SET ACTIVE %AUDIO, alias first]";
            var instance = server.GetActiveCompletion("audio");
            if (instance is not Basic.AI.Rag.IAudioCompleter audio)
                return $"[AI Transcribe: provider '{name}' does not support audio]";
            var audioBytes = File.ReadAllBytes(path);
            var format = Path.GetExtension(path).TrimStart('.').ToLowerInvariant();
            return audio.TranscribeAudio(audioBytes, format);
        }
        catch (Exception ex) { return $"[AI Transcribe ERROR: {ex.Message}]"; }
    }
    // F3 multimodale (2026-09-11): primitive immagini PNG su CommonLib.ImageUtils (stessa
    // semantica del runtime C gmb_image.c — solo PNG, errori espliciti, mai stub).
    /// <summary>Coercizione numerica tollerante (parità PCode SafeDouble): stringhe non
    /// numeriche → 0 invece di eccezione. Usata dal codegen IL per gli argomenti-dimensione
    /// (IlConversion.EmitConvert lascia le stringhe sullo stack → InvalidProgram).</summary>
    public static double SafeDouble(object? v)
    {
        if (v is null) return 0.0;
        if (v is double d) return d;
        if (v is float f) return f;
        if (v is decimal m) return (double)m;
        if (v is int i) return i;
        if (v is long l) return l;
        if (v is short s) return s;
        if (v is byte b) return b;
        if (v is string str && double.TryParse(str, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out var parsed))
            return parsed;
        if (v is string) return 0.0;
        try { return Convert.ToDouble(v, System.Globalization.CultureInfo.InvariantCulture); }
        catch { return 0.0; }
    }
    public static string AiImageInfo(string path)
    {
        if (!CommonLib.ImageUtils.TryReadPng(path, out int w, out int h, out _, out string err)) return err;
        return $"{w},{h},png";
    }
    public static long AiImageResize(string input, string output, double width, double height)
    {
        int w = (int)width, h = (int)height;
        if (w <= 0 || h <= 0 || w > CommonLib.ImageUtils.MaxDim || h > CommonLib.ImageUtils.MaxDim) return 0;
        if (string.IsNullOrEmpty(output) || !CommonLib.ImageUtils.HasPngExt(output)) return 0;
        if (!CommonLib.ImageUtils.TryReadPng(input, out int sw, out int sh, out var rgba, out _)) return 0;
        var dst = CommonLib.ImageUtils.ResizeNearest(rgba, sw, sh, w, h);
        return CommonLib.ImageUtils.TryWritePng(output, dst, w, h, out _) ? 1 : 0;
    }
    public static long AiImageCrop(string input, string output, double x, double y, double width, double height)
    {
        int ix = (int)x, iy = (int)y, w = (int)width, h = (int)height;
        if (w <= 0 || h <= 0 || w > CommonLib.ImageUtils.MaxDim || h > CommonLib.ImageUtils.MaxDim) return 0;
        if (string.IsNullOrEmpty(output) || !CommonLib.ImageUtils.HasPngExt(output)) return 0;
        if (!CommonLib.ImageUtils.TryReadPng(input, out int sw, out int sh, out var rgba, out _)) return 0;
        if (!CommonLib.ImageUtils.TryCrop(rgba, sw, sh, ix, iy, w, h, out var dst, out int cw, out int ch)) return 0;
        return CommonLib.ImageUtils.TryWritePng(output, dst, cw, ch, out _) ? 1 : 0;
    }
    public static long AiImageConvert(string input, string output)
    {
        if (string.IsNullOrEmpty(output) || !CommonLib.ImageUtils.HasPngExt(output)) return 0;
        if (!CommonLib.ImageUtils.TryReadPng(input, out int w, out int h, out var rgba, out _)) return 0;
        return CommonLib.ImageUtils.TryWritePng(output, rgba, w, h, out _) ? 1 : 0;
    }
    // F5 multimodale (2026-09-11): embedding percettivo + compare (modello-free, deterministici,
    // parità col runtime C gmb_image.c) + detect/classify via provider vision.
    public static double[] AiImageEmbed(string path)
    {
        if (!CommonLib.ImageUtils.TryReadPng(path, out int w, out int h, out var rgba, out _))
            return Array.Empty<double>();
        return CommonLib.ImageUtils.PerceptualEmbed(rgba, w, h);
    }
    public static long AiImageCompare(string p1, string p2)
    {
        if (!CommonLib.ImageUtils.TryReadPng(p1, out int w1, out int h1, out var a, out _)) return -1;
        if (!CommonLib.ImageUtils.TryReadPng(p2, out int w2, out int h2, out var b, out _)) return -1;
        var e1 = CommonLib.ImageUtils.PerceptualEmbed(a, w1, h1);
        var e2 = CommonLib.ImageUtils.PerceptualEmbed(b, w2, h2);
        double dot = 0.0;
        for (int i = 0; i < e1.Length; i++) dot += e1[i] * e2[i];
        long pct = (long)(dot * 100.0 + 0.5);
        if (pct < 0) pct = 0;
        if (pct > 100) pct = 100;
        return pct;
    }
