    // F2 multimodale (2026-09-11): estrazione strutturata documenti → JSON (stessa
    // semantica del runtime C gmb_docfields.c: euristiche IT offline + schema via LLM).
    private static string DocFieldsText(string path, out bool missing)
    {
        missing = false;
        if (string.IsNullOrEmpty(path) || !File.Exists(path)) { missing = true; return ""; }
        // Testuali prima (stesso ordine del runtime C): testo raw identico su ogni backend.
        var ext = Path.GetExtension(path).ToLowerInvariant();
        if (ext is ".txt" or ".md" or ".csv" or ".log")
        {
            try { return File.ReadAllText(path); } catch { return ""; }
        }
        try { return DocExtract(path); } catch { return ""; }
    }
    private static string DocFieldsJsonEscape(string s) =>
        s.Replace("\\", "\\\\").Replace("\"", "\\\"").Replace("\n", "\\n").Replace("\r", "\\r").Replace("\t", "\\t");
    private static string DocFieldsNormTotal(string raw)
    {
        var t = new string(raw.Where(c => c != ' ' && c != '\'').ToArray());
        if (!t.Contains(',')) return t;
        return new string(t.Where(c => c != '.').ToArray()).Replace(',', '.');
    }
    public static string AiDocFields(string path)
    {
        var text = DocFieldsText(path, out bool missing);
        if (missing) return "{\"error\":\"file not found\"}";
        string? number = null, date = null, total = null, vat = null;
        var m = System.Text.RegularExpressions.Regex.Match(text,
            @"fattura[^0-9\n]{0,12}([A-Za-z0-9][A-Za-z0-9\/\-.]*\d[A-Za-z0-9\/\-.]*)",
            System.Text.RegularExpressions.RegexOptions.IgnoreCase);
        if (m.Success) number = m.Groups[1].Value;
        m = System.Text.RegularExpressions.Regex.Match(text, @"(\d{1,2})[\/\.-](\d{1,2})[\/\.-](\d{2,4})");
        if (m.Success) date = $"{int.Parse(m.Groups[1].Value):00}/{int.Parse(m.Groups[2].Value):00}/{m.Groups[3].Value}";
        m = System.Text.RegularExpressions.Regex.Match(text,
            @"(?:totale(?:\s+(?:documento|fattura|complessivo|ivato))?|importo\s+totale)\s*[:€]?\s*€?\s*([0-9][\d.]*,\d{2}|\d[\d.,]*)",
            System.Text.RegularExpressions.RegexOptions.IgnoreCase);
        if (m.Success) total = DocFieldsNormTotal(m.Groups[1].Value);
        m = System.Text.RegularExpressions.Regex.Match(text,
            @"(?:p\.?\s*iva|partita\s+iva)[^.0-9]{0,10}(\d{11})",
            System.Text.RegularExpressions.RegexOptions.IgnoreCase);
        if (m.Success) vat = m.Groups[1].Value;
        string Q(string? v) => v is null ? "null" : $"\"{DocFieldsJsonEscape(v)}\"";
        string T() => total is null ? "null" : (decimal.TryParse(total, System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out _) ? total : $"\"{DocFieldsJsonEscape(total)}\"");
        return $"{{\"number\":{Q(number)},\"date\":{Q(date)},\"total\":{T()},\"vat\":{Q(vat)}}}";
    }
    public static string AiDocExtract(string path, string schema)
    {
        var text = DocFieldsText(path, out bool missing);
        if (missing) return "{\"error\":\"file not found\"}";
        if (string.IsNullOrEmpty(text)) return "{\"error\":\"testo non estraibile\"}";
        var completer = Basic.AI.Rag.LlmCompleterResolver.Default;
        if (completer is null) return "{\"error\":\"nessun provider LLM configurato (AI SET ACTIVE)\"}";
        if (text.Length > 12000) text = text.Substring(0, 12000);
        string sys = "Estrai dal documento i campi dello schema JSON: "
            + (string.IsNullOrEmpty(schema) ? "{\"text\":\"string\"}" : schema)
            + ". Rispondi SOLO con un oggetto JSON valido (niente markdown, niente spiegazioni); "
            + "valori assenti = null; numeri con punto decimale.";
        string ans;
        try { ans = completer.Complete(sys, text).Trim(); }
        catch (Exception ex) { return "{\"error\":\"" + DocFieldsJsonEscape(ex.Message) + "\"}"; }
        if (ans.StartsWith("```"))
        {
            int nl = ans.IndexOf('\n');
            ans = (nl >= 0 ? ans.Substring(nl + 1) : ans.Substring(3)).Trim();
            int end = ans.LastIndexOf("```");
            if (end >= 0) ans = ans.Substring(0, end).Trim();
        }
        return ans;
    }
    // F4 multimodale (2026-09-11): AI.SYNTHESIZE — sintesi vocale (TTS) via motore di sistema.
    // Scrive un WAV in `output` e ritorna 1 (ok) / 0 (errore: testo/output vuoti, motore
    // assente). Il testo passa da un file temporaneo e Process.Start usa argv (nessuna shell).
    public static long AiSynthesize(string text, string output)
    {
        if (string.IsNullOrEmpty(text) || string.IsNullOrEmpty(output)) return 0;
        var full = Path.GetFullPath(output);
        var dir = Path.GetDirectoryName(full);
        if (!string.IsNullOrEmpty(dir)) { try { Directory.CreateDirectory(dir); } catch { return 0; } }
        var tmp = Path.Combine(Path.GetTempPath(), "gmb_tts_" + Guid.NewGuid().ToString("N") + ".txt");
        try
        {
            File.WriteAllText(tmp, text);
            string exe;
            var args = new System.Collections.Generic.List<string>();
            if (OperatingSystem.IsMacOS())
            {
                exe = "/usr/bin/say";
                args.AddRange(["-f", tmp, "-o", full, "--data-format=LEI16@22050"]);
            }
            else if (OperatingSystem.IsWindows())
            {
                exe = "powershell";
                string Q(string s) => s.Replace("'", "''");
                args.AddRange(["-NoProfile", "-Command",
                    "Add-Type -AssemblyName System.Speech; $s=New-Object System.Speech.Synthesis.SpeechSynthesizer; " +
                    $"$s.SetOutputToWaveFile('{Q(full)}'); $s.Speak([IO.File]::ReadAllText('{Q(tmp)}')); $s.Dispose()"]);
            }
            else
            {
                exe = File.Exists("/usr/bin/espeak-ng") ? "/usr/bin/espeak-ng" : "espeak";
                args.AddRange(["-f", tmp, "-w", full]);
            }
            var psi = new System.Diagnostics.ProcessStartInfo(exe)
            { UseShellExecute = false, RedirectStandardError = true, RedirectStandardOutput = true };
            foreach (var a in args) psi.ArgumentList.Add(a);
            using var p = System.Diagnostics.Process.Start(psi);
            if (p is null) return 0;
            p.WaitForExit(30000);
            return p.HasExited && p.ExitCode == 0 && File.Exists(full) ? 1 : 0;
        }
        catch { return 0; }
        finally { try { File.Delete(tmp); } catch { } }
    }
    /// <summary>AI.PROVIDERS(): il file LOCALE (stato utente) vince; se manca si usa il SEED
    /// condiviso del compilatore (`shared/settings/providers.json`, che il bundle copia accanto
    /// all'eseguibile in `config/providers.json`). Prima faceva `File.ReadAllText` diretto: su un
    /// checkout pulito (o in un programma distribuito senza il file) lanciava
    /// FileNotFoundException invece di rispondere — e le due gambe divergevano (il C rispondeva
    /// col registry serializzato ad array). Ora entrambe rispondono con lo stesso seed.</summary>
    public static string AiProviders()
    {
        if (File.Exists(GmbiPaths.ProvidersFile)) return File.ReadAllText(GmbiPaths.ProvidersFile);
        var seed = Path.Combine(GmbiPaths.SharedConfigDir, "providers.json");
        if (File.Exists(seed)) return File.ReadAllText(seed);
        return "{\"providers\":[]}";
    }
    // AI SET KEY/MODEL: deve FONDERE la config del provider esistente (via Configure/AiSetOrGet),
    // non Register() con un descriptor nuovo solo-apiKey/model che SOVRASCRIVEVA baseUrl/kind —
    // bug: dopo `AI REGISTER <url> ... ; AI SET KEY` il provider perdeva 'model'/'baseUrl'
    // ("Provider 'x' requires config key 'model'"). Parità col runtime C (gmb_ai_set_config fonde).
    public static string AiSetKey(string name, string key)
        => AiSetOrGet(name, "apiKey", key);
    public static string AiSetModel(string name, string model)
        => AiSetOrGet(name, "model", model);
    public static string AiGetModel(string name)
        => AiSetOrGet(name, "model", null);

    /// <summary>
    /// Layer config AI reale (2026-08-19, sostituisce gli stub): SET/GET temperature, base URL,
    /// API key, modello, info, save/load, default, enable/disable — agiscono su ProviderServer
    /// e persistono via ProviderConfig (providers.json). Firma: (name [, value]).
    /// </summary>
    private static string ActiveCompletionName() =>
        Basic.Providers.ProviderServer.Instance.GetActiveName("completion") ?? "";

    private static string AiSetOrGet(string name, string key, string? value)
    {
        var server = Basic.Providers.ProviderServer.Instance;
        var target = string.IsNullOrWhiteSpace(name) ? ActiveCompletionName() : name;
        if (string.IsNullOrEmpty(target))
            return "ERROR: no active completion provider";
        // Parità runtime C (gmb_ai_set_config/gmb_ai_get_config, gmb_ai.c:793): SET su un
        // provider NON registrato = no-op silenzioso (find_provider → 0), GET = "".
        // Prima: Configure lanciava KeyNotFoundException — divergenza IL trovata dallo
        // sweep P2 (AiProviders.bas: `AI SET KEY "openrouter"` non registrato → rc=6 IL
        // vs no-op PCode/VM-C/C99). Save() anche nel no-op: nessuno stato da persistere.
        if (value != null)
        {
            if (!server.IsRegistered(target)) return "OK";
            server.Configure(target, key, value);
            Basic.Providers.ProviderConfig.Save();
            return "OK";
        }
        return server.GetConfig(target, key) ?? "";
    }

    public static string AiSetTemp(string name, string value)
        => AiSetOrGet(name, "temperature", value);
    public static string AiGetTemp(string name)
        => AiSetOrGet(name, "temperature", null);
    public static string AiSetBase(string name, string value)
        => AiSetOrGet(name, "baseUrl", value);
    public static string AiGetBase(string name)
        => AiSetOrGet(name, "baseUrl", null);
    public static string AiGetKey(string name)
        => AiSetOrGet(name, "apiKey", null);

    public static string AiInfo(string name)
    {
        var server = Basic.Providers.ProviderServer.Instance;
        var target = string.IsNullOrWhiteSpace(name) ? ActiveCompletionName() : name;
        var cfg = server.GetConfigMap(target);
        return $"Provider '{target}': {string.Join(", ", cfg.Select(kv => $"{kv.Key}={kv.Value}"))}";
    }

