    /// <summary>LOAD (JSON): legge un file JSON e lo converte in oggetto dinamico —
    /// come la VM (BuiltInFunction.LOAD, errore → Dictionary vuoto).</summary>
    public static object? JsonLoadFile(string path)
    {
        try
        {
            var text = File.ReadAllText(path);
            return JsonParse(text);
        }
        catch { return new Dictionary<string, object?>(); }
    }

    public static object? JsonParse(string text)
    {
        using var doc = System.Text.Json.JsonDocument.Parse(text);
        return JsonElementToObject(doc.RootElement);
    }

    /// <summary>JSON.LOAD(path): legge un file JSON e lo converte in oggetto dinamico —
    /// come la VM (File.ReadAllText + JsonElementToObject).</summary>
    public static object? JsonLoad(string path)
        => string.IsNullOrEmpty(path) || !File.Exists(path)
            ? null
            : JsonParse(File.ReadAllText(path));

    private static object? JsonElementToObject(System.Text.Json.JsonElement element)
    {
        switch (element.ValueKind)
        {
            case System.Text.Json.JsonValueKind.Object:
                var obj = new Dictionary<string, object?>(StringComparer.OrdinalIgnoreCase);
                foreach (var prop in element.EnumerateObject())
                    obj[prop.Name] = JsonElementToObject(prop.Value);
                return obj;
            case System.Text.Json.JsonValueKind.Array:
                var list = new List<object?>();
                foreach (var item in element.EnumerateArray())
                    list.Add(JsonElementToObject(item));
                return list;
            case System.Text.Json.JsonValueKind.String:
                return element.GetString();
            case System.Text.Json.JsonValueKind.Number:
                return element.GetDouble();
            // BOOLEANO: si conserva il TIPO (bool CLR), non -1/0. E' la stessa
            // rappresentazione dell'assegnazione `o("k") = TRUE` (bool_assign.bas) e
            // l'unica che permette al round-trip parse -> stringify di restituire
            // true/false: con -1.0/0.0 il JSON cambiava TIPO (non solo valore). In
            // contesto numerico il runtime coercizza bool -> -1/0 (PRINT, confronti,
            // assegnazione a LONG), quindi la semantica BASIC TRUE=-1 non cambia.
            // Vedi Bugs/(open) - JSON-Parse-Booleani-RoundTrip.md.
            case System.Text.Json.JsonValueKind.True:
                return true;
            case System.Text.Json.JsonValueKind.False:
                return false;
            default:
                return null;
        }
    }

    /// <summary>
    /// Accesso a campo dinamico su un valore JSON (Dictionary&lt;string,object?&gt; dopo
    /// <see cref="JsonParse"/>) — usato dal backend IL per `jsonObj.campo`, stesso concetto
    /// del case IDictionary generico di OP_LOAD_FIELD nel p-code VM (PCodeProcessor.cs).
    /// </summary>
    /// <summary>`g[k]` con chiave dinamica (object): stringa -> accesso per nome (JsonFieldGet); numero -> per indice (JsonIndexGet).</summary>
    public static object? JsonIndexGetDynamic(object? instance, object? key)
        => key is string ks ? JsonFieldGet(instance, ks) : JsonIndexGet(instance, (int)ToDouble(key));

    public static object? JsonFieldGet(object? instance, string fieldName)
    {
        if (instance is System.Collections.IDictionary dict && dict.Contains(fieldName))
            return dict[fieldName];
        // JSON serializzato come stringa (es. risultato di JSON.ToJson su un UDT): parsa e
        // leggi il campo — parità VM (OBJECTTOJSON → stringa, il campo si legge comunque).
        if (instance is string jsonStr)
        {
            try
            {
                using var doc = System.Text.Json.JsonDocument.Parse(jsonStr);
                if (doc.RootElement.ValueKind == System.Text.Json.JsonValueKind.Object &&
                    doc.RootElement.TryGetProperty(fieldName, out var prop))
                    return JsonElementToObject(prop);
            }
            catch { }
            return null;
        }
        // Classe CLR reale (es. FetchResult: StatusCode/Body/Headers — il mapper ora le
        // mappa alla classe, non a object): legge la proprietà via reflection.
        if (instance is not null)
        {
            var prop = instance.GetType().GetProperty(fieldName,
                System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance);
            if (prop is not null) return prop.GetValue(instance);
        }
        return null;
    }

    /// <summary>FETCH come FUNZIONE (DIM res AS FETCHRESULT = FETCH(url[, opts])): richiesta
    /// sincrona → FetchResult (StatusCode/Body/Headers). Opzioni (HttpOptions dict) passate
    /// se presenti; errore di rete → FetchResult con StatusCode 0 (ON ERROR lo gestisce).</summary>
    // Jar cookie GLOBALE condiviso per l'intero processo (canone HttpOptions: CookieJar null ->
    // "usa il jar globale condiviso"). Prima ogni FETCH creava un HttpClientHelper NUOVO: la
    // CookieContainer era vuota ad ogni chiamata -> i cookie NON persistevano (HttpSession:
    // sessionId "" su IL vs popolato su PCode, che usa l'helper condiviso dell'host).
    internal static readonly CommonLib.Http.HttpClientHelper SharedHttpClient = new();

    public static CommonLib.Http.FetchResult FetchFunction(object? url, object? options = null)
    {
        var urlStr = url?.ToString() ?? "";
        try
        {
            var helper = SharedHttpClient;
            var opts = BuildHttpOptions(options);
            var prevCtx = System.Threading.SynchronizationContext.Current;
            System.Threading.SynchronizationContext.SetSynchronizationContext(null);
            try
            {
                return helper.PerformRequestAsync(urlStr, opts).GetAwaiter().GetResult();
            }
            finally { System.Threading.SynchronizationContext.SetSynchronizationContext(prevCtx); }
        }
        catch (System.Exception)
        {
            return new CommonLib.Http.FetchResult();
        }
    }

    /// <summary>HTTP.GET(url) → body (string). Client via HttpClientHelper (canone condiviso).</summary>
    public static string HttpGet(string url) => HttpRequest(url, "GET", null, null);

    /// <summary>HTTP.POST(url [, body [, contentType]]) → body (string).</summary>
    public static string HttpPost(string url, string? body = null, string? contentType = null)
        => HttpRequest(url, "POST", body, contentType);

    /// <summary>HTTP.PUT(url [, body [, contentType]]) → body (string).</summary>
    public static string HttpPut(string url, string? body = null, string? contentType = null)
        => HttpRequest(url, "PUT", body, contentType);

    /// <summary>HTTP.DELETE(url) → body (string).</summary>
    public static string HttpDelete(string url) => HttpRequest(url, "DELETE", null, null);

    private static string HttpRequest(string url, string method, string? body, string? contentType)
    {
        try
        {
            var helper = SharedHttpClient;
            var opts = new CommonLib.Http.HttpOptions
            {
                Method = method,
                Body = body ?? ""
            };
            if (!string.IsNullOrEmpty(contentType))
                opts.Headers.ContentType = contentType;
            var result = helper.PerformRequestAsync(url, opts).GetAwaiter().GetResult();
            return result.Body ?? "";
        }
        catch { return ""; }
    }

    /// <summary>FETCH asincrono con CALLBACK (FETCH url[, opts] INTO Sub): la richiesta parte
    /// in background, il chiamante non si blocca; al completamento invoca
    /// <c>Sub(response$, error$)</c> — stesso contratto del PCodeVM: response$ = Body se
    /// successo altrimenti "", error$ = messaggio d'errore. La callback è dispatchata come
    /// TASK GPM (mai in diretta sul thread di Task.Run — iniezione esterna nel GPM).</summary>
    public static void HttpFetchAsync(string url, object? options, int callbackSymbolId)
    {
        var method = FindProcedureMethod(callbackSymbolId, [typeof(string), typeof(string)]);
        Action<string, string> callback = method is null
            ? (_, _) => { }
            : (resp, err) => DispatchHandlerAsGpmOrDirect(callbackSymbolId, method, [resp, err]);
        _ = Task.Run(() =>
        {
            CommonLib.Http.FetchResult result;
            try
            {
                var helper = SharedHttpClient;
                result = helper.PerformRequestAsync(url, BuildHttpOptions(options)).GetAwaiter().GetResult();
            }
            catch (Exception ex)
            {
                result = new CommonLib.Http.FetchResult { StatusCode = 0, ErrorMessage = ex.Message };
            }
            var response = string.IsNullOrEmpty(result.ErrorMessage) ? result.Body : "";
            callback(response, result.ErrorMessage ?? "");
        });
    }

    // ── WebSocket (client + server) ─────────────────────────────────────────────────────
    /// <summary>WEBSOCKET CONNECT (client): handshake RFC 6455 REALE via ClientWebSocket (prima
    /// apriva solo un socket TCP nudo senza upgrade né framing). Ritorna un <see cref="IlWebSocketHandle"/>
    /// già connesso e col loop di ricezione avviato, o null su errore (connessione rifiutata/
    /// timeout). Bloccante sul thread chiamante con timeout, come il VM (ExecuteWebSocketConnect).</summary>
    public static object? WsConnect(string host, int port, string? path, object? timeout)
    {
        var wsPath = string.IsNullOrEmpty(path) ? "/" : (path.StartsWith('/') ? path : "/" + path);
        var timeoutMs = timeout switch { double d when d > 0 => (int)d, int i when i > 0 => i, _ => 30000 };
        var client = new System.Net.WebSockets.ClientWebSocket();
        try
        {
            using var cts = new CancellationTokenSource(timeoutMs);
            client.ConnectAsync(new Uri($"ws://{host}:{port}{wsPath}"), cts.Token).GetAwaiter().GetResult();
        }
        catch { try { client.Dispose(); } catch { } return null; }
        var handle = new IlWebSocketHandle { Socket = client };
        handle.StartReceiveLoop();
        return handle;
    }

    /// <summary>Collega la SUB (symbolId risolto a COMPILE-TIME, stesso pattern di HTTP ROUTE/USE)
    /// all'evento WebSocket. Il nome di procedura non è risolvibile a runtime nel modello IL
    /// (i metodi generati sono Proc_&lt;symbolId&gt; senza il nome BASIC), quindi EmitFieldAssignment
    /// per `ws.OnMessage = "Nome"` risolve il nome qui e passa il symbolId. Il MethodInfo viene
    /// RISOLTO E CACHATO SUBITO (dall'assembly del programma appena caricato, vedi
    /// <see cref="LatestGeneratedAssembly"/>): risolverlo a runtime (al messaggio, da un thread in
    /// background) con FindProcedureMethod(symbolId, null) restituirebbe la PRIMA Proc_&lt;symbolId&gt;
    /// fra TUTTI gli assembly caricati nel processo (es. quelli di un programma precedente con lo
    /// stesso symbolId) — bug reale osservato in suite quando un altro test aveva caricato decine
    /// di GeneratedProgram prima del programma WebSocket.</summary>
    public static void WsSetHandler(object? handle, string property, int symbolId)
    {
        if (handle is IlWebSocketHandle ws)
        {
            var method = FindProcedureMethodIn(LatestGeneratedAssembly(), symbolId, null)
                ?? FindProcedureMethod(symbolId, null);
            if (property.Equals("OnMessage", StringComparison.OrdinalIgnoreCase))
            {
                ws.OnMessageSymbolId = symbolId;
                ws.OnMessageMethod = method;
            }
            else if (property.Equals("OnClose", StringComparison.OrdinalIgnoreCase))
            {
                ws.OnCloseSymbolId = symbolId;
                ws.OnCloseMethod = method;
            }
            else if (property.Equals("OnError", StringComparison.OrdinalIgnoreCase))
            {
                ws.OnErrorSymbolId = symbolId;
                ws.OnErrorMethod = method;
            }
        }
    }

    /// <summary>Assembly del programma IL generato CARICATO PER ULTIMO (quello dell'esecuzione in
    /// corso): AppDomain.GetAssemblies() restituisce in ordine di caricamento, quindi l'ultimo
    /// assembly che espone il tipo GeneratedProgram è il programma corrente. Usato per risolvere i
    /// Proc_&lt;symbolId&gt; col contesto giusto anche quando nel processo sono stati caricati altri
    /// programmi (es. test/Executor) con symbolId coincidenti.</summary>
    private static System.Reflection.Assembly? LatestGeneratedAssembly()
    {
        System.Reflection.Assembly? latest = null;
        foreach (var asm in AppDomain.CurrentDomain.GetAssemblies())
            if (asm.GetType("GeneratedProgram") is not null)
                latest = asm;
        return latest;
    }

    /// <summary>Dispatch del loop di ricezione (client e server): messaggio di testo → SUB OnMessage,
    /// chiusura remota → SUB OnClose. I messaggi binari non hanno un handler dedicato (come il VM).</summary>
    public static void DispatchWsMessage(object? handle, string? text, System.Net.WebSockets.WebSocketMessageType type)
    {
        if (handle is not IlWebSocketHandle ws) return;
        if (type == System.Net.WebSockets.WebSocketMessageType.Close) { DispatchWsEvent(ws, ws.OnCloseSymbolId, ws); return; }
        if (type != System.Net.WebSockets.WebSocketMessageType.Text || text is null) return;
        DispatchWsEvent(ws, ws.OnMessageSymbolId, ws, text);
    }

    /// <summary>Dispatch di un errore di lettura → SUB OnError(ws, messaggio).</summary>
    public static void DispatchWsError(object? handle, Exception ex)
    {
        if (handle is IlWebSocketHandle ws) DispatchWsEvent(ws, ws.OnErrorSymbolId, ws, ex.Message);
    }

    private static void DispatchWsEvent(IlWebSocketHandle ws, int symbolId, params object?[] args)
    {
        if (symbolId < 0) return;
        // §0ter (REGOLA INDEROGABILE): la SUB OnMessage/OnClose/OnError va dispatchata come
        // TASK GPM (SpawnGoSub su ws.Scheduler — contesto ESPLICITO), MAI invocata sul thread
        // del loop di ricezione. Due benefici: (1) rispetta la GPM; (2) SpawnGoSub risolve il
        // symbolId nel PROGRAMMA del scheduler (non la prima Proc_<symbolId> fra tutti gli
        // assembly) → niente collisione fra programmi omonimi nello stesso processo (era la
        // causa di `1,2,1,3` su IL: messageCount mutato su due copie del programma).
        var task = DispatchGpmHandler(symbolId, args, 30000, ws.Scheduler);
        if (task?.PendingException is { } ex)
            Console.Error.WriteLine($"[WebSocket handler] {ex.Message}");
    }

    public static Dictionary<string, object?> NewHttpOptionsDict()
    {
        // Default di NEW HTTPOPTIONS: identici alla P-CODE VM (typeCode 22) per parità
        // backend. La chiave "Headers" è già presente come dict annidato così le scritture
        // BASIC `opts.Headers.Authorization = ...` trovano l'oggetto da popolare.
        return new Dictionary<string, object?>(StringComparer.OrdinalIgnoreCase)
        {
            ["Method"] = "GET",
            ["Headers"] = new Dictionary<string, object?>(StringComparer.OrdinalIgnoreCase),
            ["Body"] = null,
            ["Timeout"] = 30000.0,
            ["UseCookies"] = true,
            ["Username"] = null,
            ["Password"] = null,
            ["BearerToken"] = null,
            ["ProxyUrl"] = null,
            ["ProxyUsername"] = null,
            ["ProxyPassword"] = null,
            ["ClientCertificatePath"] = null,
            ["ClientCertificatePassword"] = null,
            ["AllowRedirects"] = true,
            ["MaxRedirects"] = 10.0,
            ["AllowInsecureSSL"] = false,
            ["BrowserPreset"] = null,
            ["PinnedCertificateSha256"] = null,
        };
    }

    public static Dictionary<string, object?> NewHttpConfigDict()
    {
        // Default di NEW HTTPCONFIG: delegate a PCodeProcessor.NewHttpConfigDefaults — unica
        // sorgente managed condivisa con la P-CODE VM (parità backend).
        return Basic.IlBackend.PCode.PCodeProcessor.NewHttpConfigDefaults();
    }

    internal static CommonLib.Http.HttpOptions BuildHttpOptions(object? options)
    {
        var opts = new CommonLib.Http.HttpOptions();
        if (options is System.Collections.IDictionary od)
        {
            if (od.Contains("Timeout") || od.Contains("timeout"))
                opts.Timeout = Convert.ToInt32((od.Contains("Timeout") ? od["Timeout"] : od["timeout"]) ?? 30000, System.Globalization.CultureInfo.InvariantCulture);
            if (od.Contains("Method") || od.Contains("method"))
                opts.Method = (od.Contains("Method") ? od["Method"] : od["method"])?.ToString() ?? "GET";
            if (od.Contains("Headers"))
            {
                var headersValue = od["Headers"];
                if (headersValue is System.Collections.IDictionary hd)
                {
                    foreach (System.Collections.DictionaryEntry hkv in hd)
                        opts.Headers.SetHeader(Basic.IlBackend.PCode.PCodeProcessor.CanonicalHttpRequestHeaderName(hkv.Key?.ToString() ?? ""), hkv.Value?.ToString() ?? "");
                }
                else if (headersValue is CommonLib.Http.HttpHeaders httpHeaders)
                {
                    foreach (var kv in httpHeaders.GetAll())
                        opts.Headers.SetHeader(kv.Key, kv.Value);
                }
            }
            if (od.Contains("Body") || od.Contains("body"))
                opts.Body = od.Contains("Body") ? od["Body"] : od["body"];
            if (od.Contains("CookieJar") && od["CookieJar"] is CommonLib.Http.CookieJar jar)
                opts.CookieJar = jar;
            if ((od.Contains("AllowInsecureSSL") && od["AllowInsecureSSL"] is bool ins))
                opts.AllowInsecureSSL = ins;
            // Campi opzione mancanti (bug (solved) HttpFetch-Options-Headers-Non-Propagati): BearerToken
            // e compagni scritti con `opts.BearerToken = ...` finivano in chiavi dict MAI lette.
            if (od.Contains("BearerToken"))
                opts.BearerToken = od["BearerToken"]?.ToString();
            if (od.Contains("Username"))
                opts.Username = od["Username"]?.ToString();
            if (od.Contains("Password"))
                opts.Password = od["Password"]?.ToString();
            if (od.Contains("ProxyUrl"))
                opts.ProxyUrl = od["ProxyUrl"]?.ToString();
            if (od.Contains("ProxyUsername"))
                opts.ProxyUsername = od["ProxyUsername"]?.ToString();
            if (od.Contains("ProxyPassword"))
                opts.ProxyPassword = od["ProxyPassword"]?.ToString();
            if (od.Contains("ClientCertificatePath"))
                opts.ClientCertificatePath = od["ClientCertificatePath"]?.ToString();
            if (od.Contains("ClientCertificatePassword"))
                opts.ClientCertificatePassword = od["ClientCertificatePassword"]?.ToString();
            if (od.Contains("AllowRedirects") && od["AllowRedirects"] is bool ard)
                opts.AllowRedirects = ard;
            if (od.Contains("MaxRedirects"))
                opts.MaxRedirects = Convert.ToInt32(od["MaxRedirects"] ?? 10, System.Globalization.CultureInfo.InvariantCulture);
            if (od.Contains("UseCookies") && od["UseCookies"] is bool uc)
                opts.UseCookies = uc;
            if (od.Contains("BrowserPreset"))
                opts.BrowserPreset = od["BrowserPreset"]?.ToString();
            if (od.Contains("PinnedCertificateSha256"))
                opts.PinnedCertificateSha256 = od["PinnedCertificateSha256"]?.ToString();
        }
        return opts;
    }

    /// <summary>Get-or-create del sub-oggetto per un field-set ANNIDATO su oggetto dinamico
    /// (`opts.Headers.Authorization = ...` con HTTPOPTIONS = Dictionary vuoto): la chiave
    /// "Headers" non esiste finché nessuno la scrive, quindi JsonFieldGet ritornava null e
    /// il JsonFieldSet sul null era un NO-OP silenzioso (bug headers FETCH non propagati).
    /// Qui il sub-dict viene creato e salvato nel padre, poi il set scrive su di esso.</summary>
    public static object? JsonNestedFieldEnsure(object? instance, string fieldName)
    {
        if (instance is System.Collections.IDictionary dict)
        {
            if (dict.Contains(fieldName) && dict[fieldName] is System.Collections.IDictionary existing)
                return existing;
            var sub = new Dictionary<string, object?>(StringComparer.OrdinalIgnoreCase);
            dict[fieldName] = sub;
            return sub;
        }
        return instance;
    }

    /// <summary>Scrittura di un campo dinamico JSON (risposta.status = "ok"): il valore va
    /// boxed e inserito nel Dictionary. Il caso NON trovato è un'estensione (il VM lo
    /// permetteva solo se il campo esisteva già); qui crea la chiave, coerente con l'uso
    /// JSON come oggetto mutabile dal BASIC.</summary>
    public static void JsonFieldSet(object? instance, string fieldName, object? value)
    {
        if (instance is System.Collections.IDictionary dict)
        {
            dict[fieldName] = value;
            return;
        }
        if (instance is not null)
        {
            var prop = instance.GetType().GetProperty(fieldName,
                System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance);
            if (prop is not null && prop.CanWrite)
            {
                try { prop.SetValue(instance, value); } catch { /* proprietà init-only: ignora */ }
            }
        }
    }

    /// <summary>Scrittura di un membro su un oggetto "dinamico": superset di JsonFieldSet.
    /// JsonFieldSet copriva solo i dict (o una proprietà pubblicamente scrivibile): sui tipi
    /// HTTP del runtime la risposta NON è un dict ma un oggetto CLR (PCodeHttpResponse) e
    /// `StatusCode` ha setter PRIVATO ⇒ CanWrite=false ⇒ la scrittura spariva in SILENZIO
    /// (la risposta tornava 200 invece del 404 richiesto dal controller MVC). Ordine:
    /// 1) IDictionary → chiave (identico a JsonFieldSet); 2) property/field scrivibile anche
    /// non pubblico; 3) metodo <c>Set&lt;Membro&gt;(value)</c> — l'idioma del runtime HTTP
    /// (<c>HTTPRESPONSE.SetStatus(code)</c>), che è l'unico modo per i membri con setter
    /// privato + guardia di concorrenza.</summary>
    public static void DynamicMemberSet(object? instance, string memberName, object? value)
    {
        if (instance is null) return;
        if (instance is System.Collections.IDictionary dict)
        {
            dict[memberName] = value;
            return;
        }
        var type = instance.GetType();
        const System.Reflection.BindingFlags BF =
            System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance;
        var prop = type.GetProperty(memberName, BF);
        if (prop is not null && prop.CanWrite)
        {
            try { prop.SetValue(instance, value); return; } catch { /* init-only o tipo incompatibile: si prosegue */ }
        }
        var fld = type.GetField(memberName, BF);
        if (fld is not null)
        {
            try { fld.SetValue(instance, value); return; } catch { /* readonly: si prosegue */ }
        }
        var setter = type.GetMethods(BF).FirstOrDefault(m =>
            m.Name.Equals("Set" + memberName, StringComparison.OrdinalIgnoreCase)
            && m.GetParameters().Length == 1);
        if (setter is not null)
        {
            try { setter.Invoke(instance, [value]); } catch { /* firma non compatibile: no-op (mai crash) */ }
        }
    }

    /// <summary>
    /// Accesso per indice su un valore JSON (List&lt;object?&gt; dopo <see cref="JsonParse"/>)
    /// — usato dal backend IL per `jsonArr[i]`/`.campo[i]`.
    /// </summary>
    public static object? JsonIndexGet(object? instance, int index)
    {
        if (instance is System.Collections.IList list && index >= 0 && index < list.Count)
            return list[index];
        return null;
    }

    /// <summary>
    /// PRINT/CSTR su un valore JSON: il tipo statico è sempre object (vedi DataTypeMapper,
    /// JsonType → System.Object — un JSON è dinamico, forma nota solo a runtime), quindi
    /// IlConversion.EmitToString non può scegliere la conversione a compile-time come fa per
    /// gli scalari — delega qui, dispatch sul tipo REALE del valore boxed. Stessa formattazione
    /// (invariant, non locale) già usata altrove per Double/altri scalari.
    /// </summary>
    public static string JsonValueToString(object? value) => value switch
    {
        null => "",
        double d => d.ToString("G15", System.Globalization.CultureInfo.InvariantCulture),
        string s => s,
        bool b => b ? "-1" : "0",
        // Scalari dinamici (CURRENCY/decimal, int, …): sempre INVARIANT — con la cultura
        // locale un Saldo 170.75 diventava "170,75" in `+ Saldo` (divergenza da VM/C).
        System.IFormattable f => f.ToString(null, System.Globalization.CultureInfo.InvariantCulture) ?? "",
        _ => value.ToString() ?? ""
    };

    /// <summary>JSON.ToObject: parità VM (SysCall.JSON_TO_OBJECT) — il valore (stringa JSON
    /// o oggetto boxed) → ToString → JsonDocument.Parse → Dictionary/List; parse fallito → { }.</summary>
    public static object? JsonToObject(object? value)
    {
        // Se è già un dict/list JSON materializzato, pass-through (es. il risultato di
        // JSON.ToJson su un UDT, che l'IL rappresenta come Dictionary — ToString() sarebbe spazzatura).
        if (value is System.Collections.IDictionary || value is System.Collections.IList) return value;
        var jsonStr = value?.ToString() ?? "{}";
        try { using var doc = System.Text.Json.JsonDocument.Parse(jsonStr); return JsonElementToObject(doc.RootElement); }
        catch { return new Dictionary<string, object?>(); }
    }

    /// <summary>JSON.ToObject(TipoUDT, json) → istanza UDT MATERIALIZZATA (parità del linguaggio:
    /// il sample si aspetta NewUdt.Timeout / NewUdt.Ports(0) su una vera UDT). PRIMA il backend
    /// IL ritornava un Dictionary generico e il codice lo usava come classe UDT (stloc + ldfld su
    /// un dict) → riferimento corrotto → AccessViolation (JsonFullTests.bas). I campi delle classi
    /// UDT generate sono Public coi nomi originali (IlProgramCompiler.Host.cs), quindi la
    /// materializzazione via reflection mappa il dict sui campi, array inclusi.</summary>
    /// <summary>Valore raw di un campo JSON da un dict (nessuna reflection su classi CLR).</summary>
    public static object? JsonFieldRaw(object? dict, string name)
    {
        if (dict is System.Collections.IDictionary d && d.Contains(name)) return d[name];
        return null;
    }

    public static object? JsonConvertField(object? raw, Type fieldType)
    {
        if (raw == null)
        {
            /* campo assente dal dict: unbox.any su null lancia NRE — usa il default del tipo
             * (0 per i value type, null per i reference/array) */
            if (fieldType.IsValueType) return Activator.CreateInstance(fieldType);
            return null;
        }
        if (fieldType.IsArray)
        {
            if (raw is not System.Collections.IList list) return Array.CreateInstance(fieldType.GetElementType()!, 0);
            var elem = fieldType.GetElementType()!;
            var arr = Array.CreateInstance(elem, list.Count);
            for (int i = 0; i < list.Count; i++)
            {
                var item = list[i];
                if (item != null)
                    arr.SetValue(Convert.ChangeType(item, elem), i);
            }
            return arr;
        }
        if (fieldType == typeof(string)) return raw.ToString();
        if (fieldType.IsValueType) return Convert.ChangeType(raw, Nullable.GetUnderlyingType(fieldType) ?? fieldType);
        // LIST OF <ElemUDT> (List<T>): materializza ogni elemento UDT dal dict JSON.
        if (fieldType.IsGenericType && fieldType.GetGenericTypeDefinition() == typeof(System.Collections.Generic.List<>))
        {
            var elem = fieldType.GetGenericArguments()[0];
            var list = (System.Collections.IList)Activator.CreateInstance(fieldType)!;
            if (raw is System.Collections.IList src)
                for (int i = 0; i < src.Count; i++) list.Add(MaterializeUdt(src[i], elem));
            return list;
        }
        // UDT/CLASS (reference non primitivo) con dict JSON: materializza campo per campo.
        if (!fieldType.IsPrimitive && !fieldType.IsEnum && raw is System.Collections.IDictionary)
            return MaterializeUdt(raw, fieldType);
        return raw;
    }

    /// <summary>Materializza un'istanza UDT/CLASS (tipo CLR generato) dai campi di un dict JSON:
    /// usata per i campi LIST OF <ElemUDT> e UDT annidati di JSON.ToObject (parità C99/VM-C).</summary>
    private static object? MaterializeUdt(object? raw, Type type)
    {
        if (raw is not System.Collections.IDictionary d)
            return type.IsValueType ? Activator.CreateInstance(type) : null;
        var obj = Activator.CreateInstance(type);
        foreach (var fi in type.GetFields(System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance))
        {
            var rv = d.Contains(fi.Name) ? d[fi.Name] : null;
            fi.SetValue(obj, JsonConvertField(rv, fi.FieldType));
        }
        return obj;
    }

    /// <summary>READVALUE/READSECTION (INI): parità VM (FileReadWriteUtils).</summary>
    public static string ReadValue(string file, string section, string key, string def)
        => CommonLib.FileReadWriteUtils.ReadValue(file, section, key, def);
    /// <summary>READSECTION come OGGETTO sezione (Dictionary chiave→valore), parità canone VM/C:
    /// supporta sia accesso campo `.Campo` (valore) sia `.Count` (numero chiavi).</summary>
    public static object ReadSection(string file, string section)
        => CommonLib.FileReadWriteUtils.ReadSectionObject(file, section);

    /// <summary>READVALUE(key) con file implicito app.settings.json in CWD — la forma usata dai
    /// sample (JSON.ReadValue("ApiKey")).</summary>
    public static string ReadValue(string key)
        => CommonLib.FileReadWriteUtils.ReadValue(Path.Combine(Directory.GetCurrentDirectory(), "app.settings.json"), "", key, "");

    /// <summary>READSECTION(section) con file implicito app.settings.json in CWD (oggetto sezione).</summary>
    public static object ReadSection(string section)
        => CommonLib.FileReadWriteUtils.ReadSectionObject(Path.Combine(Directory.GetCurrentDirectory(), "app.settings.json"), section);

    /// <summary>EXTRACT(json, key): parità VM — stringa JSON (JsonDocument.Parse +
    /// TryGetProperty) oppure IDictionary (dict[key]); il caso IList (coda) resta VM-only.</summary>
    public static object? Extract(object? json, string key)
    {
        if (json is string jsonStr)
        {
            try
            {
                using var doc = System.Text.Json.JsonDocument.Parse(jsonStr);
                return ExtractFromElement(doc.RootElement, key);
            }
            catch { return ""; }
        }
        return ExtractFromObject(json, key);
    }

    /// <summary>Naviga un path su un oggetto PARSEATO (Dictionary/List/array): "status",
    /// "hits[0]", "hits[0].sourceId".</summary>
    private static object? ExtractFromObject(object? obj, string path)
    {
        if (obj is null || string.IsNullOrEmpty(path)) return null;
        var remaining = path;
        object? current = obj;
        while (remaining.Length > 0 && current != null)
        {
            int dot = remaining.IndexOf('.');
            int bracket = remaining.IndexOf('[');
            var segEnd = (dot >= 0 && (bracket < 0 || dot < bracket)) ? dot : (bracket >= 0 ? bracket : remaining.Length);
            var seg = remaining[..segEnd];
            if (seg.Length > 0)
            {
                if (current is System.Collections.IDictionary d)
                {
                    if (!d.Contains(seg)) return null;
                    current = d[seg];
                }
                else if (current is System.Text.Json.JsonElement el)
                {
                    if (!el.TryGetProperty(seg, out var elv)) return null;
                    current = elv;
                }
                else return null;
            }
            if (bracket >= 0 && bracket < (dot >= 0 ? dot : int.MaxValue))
            {
                int close = remaining.IndexOf(']', bracket);
                if (close < 0) return null;
                var idxStr = remaining[(bracket + 1)..close];
                if (!int.TryParse(idxStr, System.Globalization.NumberStyles.Integer,
                        System.Globalization.CultureInfo.InvariantCulture, out var idx) || idx < 0)
                    return null;
                current = IndexAt(current, idx);
                if (current is null) return null;
                remaining = close + 1 < remaining.Length ? remaining[(close + 1)..] : "";
                if (remaining.StartsWith('.')) remaining = remaining[1..];
                continue;
            }
            remaining = segEnd < remaining.Length ? remaining[(segEnd + 1)..] : "";
        }
        return BoxScalar(current);
    }

    private static object? IndexAt(object? container, int idx)
    {
        if (container is System.Collections.IList list)
            return idx >= 0 && idx < list.Count ? list[idx] : null;
        if (container is System.Text.Json.JsonElement el)
        {
            if (el.ValueKind != System.Text.Json.JsonValueKind.Array || idx < 0 || idx >= el.GetArrayLength())
                return null;
            return el[idx];
        }
        return null;
    }

    private static object? BoxScalar(object? value)
    {
        if (value is System.Text.Json.JsonElement el)
        {
            return el.ValueKind switch
            {
                System.Text.Json.JsonValueKind.String => el.GetString(),
                System.Text.Json.JsonValueKind.Number => el.GetDouble(),
                System.Text.Json.JsonValueKind.True => -1.0,
                System.Text.Json.JsonValueKind.False => 0.0,
                System.Text.Json.JsonValueKind.Null => null,
                _ => el.GetRawText()
            };
        }
        return value;
    }

    /// <summary>Naviga un path JSON: "status", "hits[0]", "hits[0].sourceId", "a.b[1].c".</summary>
    private static object? ExtractFromElement(System.Text.Json.JsonElement el, string path)
    {
        if (string.IsNullOrEmpty(path)) return null;
        var remaining = path;
        var current = el;
        while (remaining.Length > 0)
        {
            int dot = remaining.IndexOf('.');
            int bracket = remaining.IndexOf('[');
            var segEnd = (dot >= 0 && (bracket < 0 || dot < bracket)) ? dot : (bracket >= 0 ? bracket : remaining.Length);
            var seg = remaining[..segEnd];
            if (seg.Length > 0)
            {
                if (!current.TryGetProperty(seg, out current)) return null;
            }
            if (bracket >= 0 && bracket < (dot >= 0 ? dot : int.MaxValue))
            {
                int close = remaining.IndexOf(']', bracket);
                if (close < 0) return null;
                var idxStr = remaining[(bracket + 1)..close];
                if (!int.TryParse(idxStr, System.Globalization.NumberStyles.Integer,
                        System.Globalization.CultureInfo.InvariantCulture, out var idx) || idx < 0)
                    return null;
                if (current.ValueKind != System.Text.Json.JsonValueKind.Array || idx >= current.GetArrayLength())
                    return null;
                current = current[idx];
                remaining = close + 1 < remaining.Length ? remaining[(close + 1)..] : "";
                if (remaining.StartsWith('.')) remaining = remaining[1..];
                continue;
            }
            remaining = segEnd < remaining.Length ? remaining[(segEnd + 1)..] : "";
        }
        return current.ValueKind switch
        {
            System.Text.Json.JsonValueKind.String => current.GetString(),
            System.Text.Json.JsonValueKind.Number => current.GetDouble(),
            System.Text.Json.JsonValueKind.True => -1.0,
            System.Text.Json.JsonValueKind.False => 0.0,
            System.Text.Json.JsonValueKind.Null => null,
            _ => current.GetRawText()
        };
    }

    /// <summary>KEYS() su un valore JSON/AnyType (Dictionary<string,object?> boxed): le
    /// chiavi come string[] — parità VM (DICT_KEYS su IDictionary).</summary>
    public static string[]? JsonKeys(object? value)
        => value is System.Collections.IDictionary d
            ? d.Keys.Cast<object?>().Select(k => k?.ToString() ?? "").ToArray()
            : null;

    /// <summary>PRINT di una collezione (LIST/DICT/HASHSET/...): "[a, b, c]" / "{k: v, ...}"
    /// — prima EmitToString lanciava (ListType non mappato) per un PRINT diretto.</summary>
    public static string CollectionToString(object? value)
    {
        if (value is null) return "";
        if (value is string) return (string)value;
        if (value is System.Collections.IDictionary dict)
            return "{" + string.Join(", ", dict.Keys.Cast<object?>().Select(k => JsonValueToString(k) + ": " + JsonValueToString(dict[k!]))) + "}";
        if (value is System.Collections.IEnumerable en && value is not byte[])
            return "[" + string.Join(", ", en.Cast<object?>().Select(JsonValueToString)) + "]";
        return JsonValueToString(value);
    }
}
